import React, { useState } from 'react';
import { BookingSlot, ViewMode, Project } from '../types';
import { ShieldBan, Check, Lock, X } from 'lucide-react';
import { getProjectLineColor } from '../utils';

interface ScheduleBoardProps {
  bookings: BookingSlot[];
  projects: Project[];
  mode: ViewMode;
  onUpdateBookings: (bookings: BookingSlot[]) => void;
  currentClientId?: string;
  currentClientName?: string;
}

const ScheduleBoard: React.FC<ScheduleBoardProps> = ({ 
  bookings, 
  projects, 
  mode, 
  onUpdateBookings,
  currentClientId,
  currentClientName 
}) => {
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [bookingNote, setBookingNote] = useState('');
  const [viewDetailsDate, setViewDetailsDate] = useState<string | null>(null);

  // Helper to get local YYYY-MM-DD string to avoid UTC shifts
  const getLocalYYYYMMDD = (d: Date) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Generate next 21 days
  const getDays = () => {
    const days = [];
    const today = new Date();
    for (let i = 0; i < 21; i++) {
      const d = new Date(today);
      d.setDate(today.getDate() + i);
      days.push(getLocalYYYYMMDD(d));
    }
    return days;
  };

  const days = getDays();
  const getSlot = (date: string) => bookings.find(b => b.date === date);

  // Get all active projects that overlap with this date
  const getProjectsOnDate = (dateStr: string) => {
    const targetDate = new Date(dateStr + 'T00:00:00'); 

    const activeProjects = projects.filter(p => {
       if (p.status === 'completed') return false;

       // Filter based on View Mode
       if (mode === 'client' && p.targetClientId !== currentClientId) return false;

       const start = new Date(p.startDate);
       const end = new Date(p.deadline);

       // Normalize start/end to start-of-day for inclusive comparison
       const startDay = new Date(start.getFullYear(), start.getMonth(), start.getDate());
       const endDay = new Date(end.getFullYear(), end.getMonth(), end.getDate());

       return targetDate >= startDay && targetDate <= endDay;
    });

    // Sort by start date to keep visual consistency (lines don't jump around)
    return activeProjects.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  // Helper: Check if the slot belongs to the current viewer (Client mode)
  const isMySlot = (clientId?: string, bookedBy?: string) => {
    if (mode === 'artist') return true; // Artist owns everything

    // Check ID match (Strong check)
    if (currentClientId && clientId === currentClientId) return true;

    // Check manual booking name (Legacy check)
    if (bookedBy && currentClientName && bookedBy.toLowerCase() === currentClientName.toLowerCase()) return true;

    return false;
  };

  const handleDayClick = (date: string) => {
    const slot = getSlot(date);

    if (mode === 'artist') {
      // Prioritize showing details if actualHours exist
      if (slot?.actualHours && slot.actualHours.length > 0) {
          setViewDetailsDate(date);
          return;
      }

      const newBookings = [...bookings];
      const index = newBookings.findIndex(b => b.date === date);

      if (index >= 0) {
        // Toggle off existing manual slot
        if (newBookings[index].status === 'blocked') {
          newBookings.splice(index, 1);
        } else {
          if(confirm("该日期已有预约，确定要清除吗？")) {
             newBookings.splice(index, 1);
          }
        }
      } else {
        newBookings.push({ date, status: 'blocked' });
      }
      onUpdateBookings(newBookings);
    } else {
      // Client Mode
      if (slot?.status === 'blocked' || slot?.status === 'booked') return;
      setSelectedDate(date);
      setBookingNote('');
    }
  };

  const handleClientBook = () => {
    if (!selectedDate) return;

    const newBookings = [...bookings, {
      date: selectedDate,
      status: 'booked' as const,
      bookedBy: currentClientName || 'Client',
      clientId: currentClientId, // Store ID
      note: bookingNote
    }];

    onUpdateBookings(newBookings);
    setSelectedDate(null);
    alert('预约申请已提交！');
  };

  const renderDetailsModal = () => {
      if (!viewDetailsDate) return null;
      const slot = getSlot(viewDetailsDate);
      if (!slot || !slot.actualHours) return null;

      // Logic to merge capsules for display
      const sortedHours = [...slot.actualHours].sort((a, b) => {
          const [hA, mA] = a.replace('h-', '').split('-').map(Number);
          const [hB, mB] = b.replace('h-', '').split('-').map(Number);
          return (hA * 60 + mA) - (hB * 60 + mB);
      });

      const mergedCapsules: { start: string, end: string, label: string, type: 'morning' | 'afternoon' | 'evening' }[] = [];
      let currentStartMinutes = -1;
      let currentEndMinutes = -1;

      const formatTime = (totalMinutes: number) => {
          const h = Math.floor(totalMinutes / 60);
          const m = totalMinutes % 60;
          const displayH = h >= 24 ? h - 24 : h;
          const label = `${displayH.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
          return h >= 24 ? `次日 ${label}` : label;
      };

      const getTimeType = (totalMinutes: number) => {
          const h = Math.floor(totalMinutes / 60);
          if (h >= 9 && h <= 12) return 'morning';
          if (h >= 13 && h <= 17) return 'afternoon';
          return 'evening';
      };

      sortedHours.forEach((s) => {
           const [h, m] = s.replace('h-', '').split('-').map(Number);
           const startMin = h * 60 + (m === 0 ? 0 : 30);
           const endMin = startMin + 30;

           if (currentStartMinutes === -1) {
               currentStartMinutes = startMin;
               currentEndMinutes = endMin;
           } else {
               if (startMin === currentEndMinutes) {
                   currentEndMinutes = endMin;
               } else {
                   mergedCapsules.push({
                       start: formatTime(currentStartMinutes),
                       end: formatTime(currentEndMinutes),
                       label: `${formatTime(currentStartMinutes)} - ${formatTime(currentEndMinutes)}`,
                       type: getTimeType(currentStartMinutes) as any
                   });
                   currentStartMinutes = startMin;
                   currentEndMinutes = endMin;
               }
           }
      });
      if (currentStartMinutes !== -1) {
          mergedCapsules.push({
              start: formatTime(currentStartMinutes),
              end: formatTime(currentEndMinutes),
              label: `${formatTime(currentStartMinutes)} - ${formatTime(currentEndMinutes)}`,
              type: getTimeType(currentStartMinutes) as any
          });
      }

      return (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4 animate-fade-in">
              <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl p-6 relative animate-slide-up">
                  <button onClick={() => setViewDetailsDate(null)} className="absolute right-4 top-4 p-2 bg-slate-100 rounded-full hover:bg-slate-200">
                      <X size={20} className="text-slate-500" />
                  </button>

                  <div className="mb-6">
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">实际工时记录</span>
                      <h3 className="text-2xl font-black text-slate-800 mt-1">{viewDetailsDate}</h3>
                  </div>

                  <div className="flex flex-wrap gap-2 mb-6">
                      {mergedCapsules.map((cap, idx) => {
                          let bgClass = '';
                          if (cap.type === 'morning') bgClass = 'bg-orange-100 text-orange-700';
                          else if (cap.type === 'afternoon') bgClass = 'bg-sky-100 text-sky-700';
                          else bgClass = 'bg-indigo-100 text-indigo-700';

                          return (
                              <div key={idx} className={`${bgClass} px-3 py-1.5 rounded-full text-xs font-bold shadow-sm`}>
                                  {cap.label}
                              </div>
                          );
                      })}
                  </div>

                  <div className="pt-4 border-t border-slate-100 flex justify-between items-center">
                      <span className="text-slate-500 font-medium text-xs">总专注时长</span>
                      <span className="text-xl font-bold text-indigo-600">{slot.actualHours.length * 0.5} Hours</span>
                  </div>
              </div>
          </div>
      );
  };

  return (
    <div className="p-5">
      {renderDetailsModal()}

      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
            {mode === 'artist' ? '排期管理' : '预约排期'}
          </h2>
          <p className="text-xs text-slate-400 mt-0.5">
            {mode === 'artist' ? '彩色线条代表排单工期，单击日期即可下架（不可用），辅助规划将自动跳过。' : '灰色为不可选，白色为可选'}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-1.5 mb-2">
        {['日', '一', '二', '三', '四', '五', '六'].map(d => (
            <div key={d} className="text-center text-[10px] font-bold text-slate-300 uppercase tracking-wide py-1">{d}</div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1.5">
        {days.map(date => {
          const slot = getSlot(date);
          const projectsOnDay = getProjectsOnDate(date);

          let status = slot?.status;
          let clientId = slot?.clientId;
          let bookedBy = slot?.bookedBy;
          const hasActualHours = slot?.actualHours && slot.actualHours.length > 0;

          const dateObj = new Date(date + 'T00:00:00');
          const dayNum = dateObj.getDate();
          const isToday = getLocalYYYYMMDD(new Date()) === date;
          const isMine = isMySlot(clientId, bookedBy);

          let bgClass = 'bg-white border-slate-100 text-slate-700'; // Available
          let contentIcon = null;

          if (status === 'blocked') {
             if (mode === 'client' && !isMine) {
                bgClass = 'bg-slate-100 border-slate-100 text-slate-300';
                contentIcon = <Lock size={12} className="opacity-30 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />; 
             } else {
                bgClass = 'bg-slate-100 border-slate-200 text-slate-400 shadow-inner';
                contentIcon = <ShieldBan size={12} className="opacity-40 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             }
          } else if (status === 'booked') {
             if (mode === 'client' && !isMine) {
                bgClass = 'bg-slate-100 border-slate-100 text-slate-300';
                contentIcon = <Lock size={12} className="opacity-30 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             } else {
                // Reverted to Stronger Style
                bgClass = 'bg-indigo-600 border-indigo-600 text-white shadow-md shadow-indigo-200';
                contentIcon = <Check size={16} strokeWidth={3} className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             }
          }

          if (hasActualHours && mode === 'artist') {
              // Special indicator for actual work logged
              bgClass = 'bg-emerald-50 border-emerald-200 text-emerald-800';
              contentIcon = null; // Clear icon to show number clearly, or add small dot
          }

          if (selectedDate === date) {
            // Stronger selection color
            bgClass = 'ring-2 ring-indigo-500 ring-offset-2 bg-indigo-500 text-white z-10';
          }

          return (
            <div 
              key={date}
              onClick={() => handleDayClick(date)}
              className={`aspect-[4/5] rounded-lg border flex flex-col relative transition-all duration-200 active:scale-95 overflow-hidden ${bgClass}`}
            >
              {/* Day Number (Top Left) */}
              <span className={`text-[10px] font-bold p-1 leading-none ${isToday && !selectedDate ? 'text-indigo-500' : ''}`}>
                {dayNum}
              </span>

              {/* Indicator for Actual Work Logged */}
              {hasActualHours && mode === 'artist' && (
                  <div className="absolute top-1.5 right-1.5 w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>
              )}

              {/* Status Icon (Centered if present) */}
              {contentIcon}

              {/* Project Lines (Bottom) - Only show if not fully blocked/booked or if artist wants to see overlap */}
              <div className="mt-auto px-1 pb-1 flex flex-col gap-0.5 w-full">
                 {projectsOnDay.slice(0, 3).map((p, idx) => (
                   <div 
                     key={p.id} 
                     className={`h-1 w-full rounded-full ${getProjectLineColor(p.startDate, p.deadline)}`}
                     title={p.clientName}
                   />
                 ))}
                 {projectsOnDay.length > 3 && (
                   <div className="h-0.5 w-full flex justify-center gap-0.5">
                      <div className="w-0.5 h-0.5 rounded-full bg-slate-300"></div>
                      <div className="w-0.5 h-0.5 rounded-full bg-slate-300"></div>
                      <div className="w-0.5 h-0.5 rounded-full bg-slate-300"></div>
                   </div>
                 )}
              </div>
            </div>
          );
        })}
      </div>

      {mode === 'client' && selectedDate && (
        <div className="mt-6 animate-slide-up bg-slate-50 p-4 rounded-2xl border border-slate-100">
          <div className="flex items-center gap-2 mb-3 text-sm font-bold text-slate-700">
            <div className="w-2 h-2 rounded-full bg-indigo-500"></div>
            预约: {selectedDate}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="备注 / 需求 (可选)"
              value={bookingNote}
              onChange={(e) => setBookingNote(e.target.value)}
              className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button 
              onClick={handleClientBook}
              className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-colors"
            >
              提交
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduleBoard;
