            {/* Floating FAB (Artist Only) - Now positioned absolutely above the tabs */}
            {viewMode === 'artist' && (
              <div className="absolute left-1/2 -translate-x-1/2 -top-6">
                <button 
                  onClick={() => setShowAddModal(true)}
                  className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center text-white shadow-xl shadow-slate-300 active:scale-90 transition-transform border-4 border-slate-50"
                >
                  <Plus size={24} strokeWidth={2.5} />
                </button>
              </div>
            )}
          </div>

          {/* Desktop Nav Fallback */}
          <div className="hidden md:flex justify-center gap-8 py-4 bg-white border-t border-slate-200">
             <button 
              onClick={() => setActiveTab('projects')}
              className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              排单列表
            </button>
             <button 
              onClick={() => setActiveTab('schedule')}
              className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              排期日历
            </button>
             {viewMode === 'artist' && (
               <button 
                onClick={() => setActiveTab('planning')}
                className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                辅助规划
              </button>
             )}
          </div>
        </nav>
      )}

      {/* Add/Edit Project - Mobile Bottom Sheet / Desktop Modal */}
      {showAddModal && viewMode === 'artist' && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end md:justify-center md:items-center bg-slate-900/40 backdrop-blur-sm animate-fade-in">
          {/* Dismiss Area */}
          <div className="absolute inset-0" onClick={handleCloseModal}></div>

          <div className="relative bg-white w-full md:w-[400px] md:rounded-3xl rounded-t-3xl shadow-2xl animate-slide-up overflow-hidden flex flex-col max-h-[90vh]">

            {/* Handle for mobile feeling */}
            <div className="w-full flex justify-center pt-3 pb-1 md:hidden" onClick={handleCloseModal}>
              <div className="w-12 h-1.5 bg-slate-200 rounded-full"></div>
            </div>

            <div className="p-6 overflow-y-auto custom-scrollbar pb-10 safe-pb">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-slate-800">{editingProjectId ? '编辑排单' : '新建排单'}</h3>
                <button onClick={handleCloseModal} className="bg-slate-100 p-2 rounded-full text-slate-500 hover:bg-slate-200 transition-colors">
                  <X size={20} />
                </button>
              </div>

              <div className="space-y-5">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">单主名称 (备注)</label>
                  <input 
                    type="text" 
                    placeholder="例如: 老板A"
                    value={newProject.clientName}
                    onChange={e => setNewProject({...newProject, clientName: e.target.value})}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-indigo-600 uppercase mb-2">单主 ID (必填)</label>
                  <input 
                    type="text" 
                    placeholder="CLI-xxxx (单主需提供此ID)"
                    value={newProject.targetClientId}
                    onChange={e => setNewProject({...newProject, targetClientId: e.target.value})}
                    className="w-full bg-indigo-50 border border-indigo-200 rounded-xl px-4 py-3 text-sm font-bold text-indigo-900 outline-none focus:ring-2 focus:ring-indigo-500 transition-all placeholder-indigo-300"
                  />
                  <p className="text-[10px] text-slate-400 mt-1">只有持有该 ID 的单主才能看到此订单详情</p>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">约稿内容</label>
                  <textarea 
                    rows={3}
                    placeholder="描述约稿的具体要求..."
                    value={newProject.description}
                    onChange={e => setNewProject({...newProject, description: e.target.value})}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white resize-none transition-all"
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-2">开始时间</label>
                     <div className="relative">
                       <input 
                        type="datetime-local" 
                        value={newProject.startDate}
                        onChange={e => setNewProject({...newProject, startDate: e.target.value})}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                      />
                     </div>
                  </div>
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-2">截稿时间</label>
                     <div className="relative">
                       <input 
                        type="datetime-local" 
                        value={newProject.deadline}
                        onChange={e => setNewProject({...newProject, deadline: e.target.value})}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                      />
                     </div>
                  </div>
                </div>
              </div>

              <div className="flex gap-3 mt-8">
                <button 
                  onClick={handleSaveProject}
                  className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl shadow-xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                  {editingProjectId ? <><Save size={20}/> 保存修改</> : <><Plus size={20}/> 创建任务</>}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2 } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  // Session start date for non-synced projects
  const [sessionStartDate] = useState(new Date());

  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');

  // Sync State
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);

  // 'setup' = arranging, 'time-entry' = duration, 'finished' = summary, 'time-boxing' = daily planning, 
  // 'pre-comparison-confirm' = preview selection before done list, 'daily-comparison' = actual vs plan
  // 'summary' = final feedback
  const [planningStep, setPlanningStep] = useState<'setup' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  // Index of the stage currently being edited (starts from bottom)
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});

  // Time Boxing State
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);

  // Actual Execution State
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  // Local state for non-synced completed days tracking
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization: Load Sessions ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  // Save Sessions to LocalStorage
  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers for Planning Logic ---

  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      return bookings.some(b => b.date === dateStr && b.status === 'blocked');
  };

  // Calculate available days between start and end (inclusive), skipping blocked dates
  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    // Reset times to avoid partial day issues
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);

    // Safety break
    let loopCount = 0;
    while (curr <= end && loopCount < 365 * 5) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  // Get the date string for the Nth available working day (1-based index)
  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      // Reset time to ensure clean date iteration
      current.setHours(0,0,0,0);

      let validDaysFound = 0;
      let safetyCounter = 0;

      // Look ahead up to 2 years to find the day
      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }

          if (validDaysFound === dayIndex) {
              return dateStr;
          }

          // Advance one day
          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }

      return getYYYYMMDD(current);
  };

  // Check if a specific day index is completed (either in bookings or local state)
  const isDayCompleted = (dayIndex: number) => {
      const dateStr = getTargetDateStr(dayIndex);
      const hasBooking = bookings.some(b => b.date === dateStr && b.actualHours && b.actualHours.length > 0);
      return hasBooking || localCompletedDays.includes(dayIndex);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 0;
  // FIX: Use map(Number) to ensure strict number type for reduce accumulator
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const isOverBudget = syncedProject ? currentPlannedDays > totalAvailableDays : false;

  // Generate hours from 09:00 to 03:00 (+1 day)
  const generateTimeSlots = () => {
      const slots = [];
      for (let i = 9; i <= 27; i++) {
          const hour = i % 24;
          const label = `${hour.toString().padStart(2, '0')}:00`;
          const isNextDay = i >= 24;
          slots.push({ id: `h-${i}`, value: i, label, isNextDay, fullLabel: isNextDay ? `次日 ${label}` : label });
      }
      return slots;
  };
  const timeSlots = generateTimeSlots();

  // --- Actions ---

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setLocalCompletedDays([]);
      // Reset default stages
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);

      // Load Data
      setStages(session.stages);
      setEstimates(session.estimates);
      setLocalCompletedDays(session.completedDays || []);

      // Load Project Sync if exists
      if (session.projectId) {
          const project = projects.find(p => p.id === session.projectId);
          if (project) {
              setSyncedProject(project);
          }
      } else {
          setSyncedProject(null);
      }

      // Calculate next step
      // FIX: Use map(Number) to ensure strict number type for reduce accumulator
      const totalPlanned = Object.values(session.estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);

      // Find the first non-completed day
      let nextDay = 1;
      const completedSet = new Set(session.completedDays || []);

      // Check bookings based availability logic too, because user might have worked but not synced to session
      // But for resume logic, we rely mostly on session state + bookings check
      // We essentially want to jump to the first day that is NOT in completedDays

      // Simple scan
      for(let i=1; i<=Math.ceil(totalPlanned) + 5; i++) {
          if(!completedSet.has(i)) {
              nextDay = i;
              break;
          }
      }

      setCurrentComparisonDay(nextDay);
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const handleDragStart = (index: number) => {
    dragItem.current = index;
  };

  const handleDragEnter = (index: number) => {
    dragOverItem.current = index;
  };

  const handleDragEnd = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const copyListItems = [...stages];
    const dragItemContent = copyListItems[dragItem.current];
    copyListItems.splice(dragItem.current, 1);
    copyListItems.splice(dragOverItem.current, 0, dragItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setStages(copyListItems);
  };

  const handleConfirmAdd = () => {
    if (newStageTitle.trim()) {
        const newStage: PlannerStage = { 
            id: Date.now().toString(), 
            title: newStageTitle.trim(), 
            isDeletable: true 
        };
        setStages([newStage, ...stages]);
        setNewStageTitle('');
        setIsAdding(false);
    }
  };

  const deleteStage = (index: number) => {
      if(confirm('确定删除此阶段吗?')) {
          const newStages = [...stages];
          newStages.splice(index, 1);
          setStages(newStages);
      }
  };

  const handleSyncProject = () => {
      if(!syncId.trim()) return;
      const found = projects.find(p => p.id === syncId.trim());
      if(found) {
          setSyncedProject(found);
          setShowSyncInput(false);
          setSyncId('');
      } else {
          alert('未找到该 ID 对应的排单，请检查是否输入正确。');
      }
  };

  const startConfiguration = () => {
      setPlanningStep('time-entry');
      setActiveTimeIndex(stages.length - 1);
      setCurrentInputTime('');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;

      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });

      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime('');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) {
          setCurrentInputTime(val);
      }
  };

  const handleFinalize = () => {
      // Logic: Save Session here as it's the "Commit" point of the plan
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };

      const updatedSessions = [newSession, ...sessions];
      persistSessions(updatedSessions);
      setCurrentSessionId(newSession.id);

      // Find the first non-completed day to start Time Boxing
      let startDay = 1;
      const maxCheck = currentPlannedDays > 0 ? Math.ceil(currentPlannedDays) + 5 : 30;

      for (let i = 1; i <= maxCheck; i++) {
          if (!isDayCompleted(i)) {
              startDay = i;
              break;
          }
      }

      setCurrentComparisonDay(startDay); 
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const toggleTimeBox = (box: string) => {
      if (selectedTimeBoxes.includes(box)) {
          setSelectedTimeBoxes(selectedTimeBoxes.filter(b => b !== box));
      } else {
          setSelectedTimeBoxes([...selectedTimeBoxes, box]);
      }
  };

  const toggleActualHour = (uniqueId: string) => {
      // Prevent editing if day is completed
      if (isDayCompleted(currentComparisonDay)) return;

      if (selectedActualHours.includes(uniqueId)) {
          setSelectedActualHours(selectedActualHours.filter(h => h !== uniqueId));
      } else {
          setSelectedActualHours([...selectedActualHours, uniqueId]);
      }
  };

  const proceedToPreConfirmation = () => {
      if (selectedTimeBoxes.length === 0) {
          alert("请至少选择一个时间段作为今日规划");
          return;
      }
      setPlanningStep('pre-comparison-confirm');
  };

  const startComparison = () => {
      setPlanningStep('daily-comparison');
      // Initialize actual hours empty for the current session
      setSelectedActualHours([]);
  };

  const finishAll = () => {
      // 1. Sync to Bookings
      const dateStr = getTargetDateStr(currentComparisonDay);

      if (onUpdateBookings) {
          const newBookings = [...bookings];
          const existingIndex = newBookings.findIndex(b => b.date === dateStr);

          if (existingIndex >= 0) {
              newBookings[existingIndex] = {
                  ...newBookings[existingIndex],
                  actualHours: selectedActualHours
              };
          } else {
              newBookings.push({
                  date: dateStr,
                  status: 'booked', // Mark as booked if we have data
                  actualHours: selectedActualHours
              });
          }
          onUpdateBookings(newBookings);
      }

      // Update local state and Session Storage
      const newCompletedDays = [...localCompletedDays];
      if (!newCompletedDays.includes(currentComparisonDay)) {
          newCompletedDays.push(currentComparisonDay);
      }
      setLocalCompletedDays(newCompletedDays);

      if (currentSessionId) {
          const updatedSessions = sessions.map(s => 
              s.id === currentSessionId 
              ? { ...s, completedDays: newCompletedDays, lastUpdated: new Date().toISOString() }
              : s
          );
          persistSessions(updatedSessions);
      }

      setPlanningStep('summary');
  };

  const handleContinueToNextDay = () => {
      const nextDay = currentComparisonDay + 1;
      setCurrentComparisonDay(nextDay);
      setSelectedActualHours([]);
      setSelectedTimeBoxes([]); // Clear previous plan
      setPlanningStep('time-boxing'); // Go to Time Boxing for next day
  };

  // Helper to determine current stage based on day index
  const getCurrentStageForDay = (day: number) => {
      let cumulativeDays = 0;
      for (const stage of stages) {
          const duration = Number(estimates[stage.id] || 0);
          cumulativeDays += duration;
          if (day <= cumulativeDays) {
              return stage;
          }
      }
      return stages.length > 0 ? stages[stages.length - 1] : null;
  };

  // --- RENDER: DASHBOARD VIEW ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button 
                    onClick={onBack} 
                    className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"
                >
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>

             {/* Create New Button */}
             <button 
                onClick={handleCreateNew}
                className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900"
             >
                <div className="bg-white/20 p-3 rounded-full">
                    <Plus size={24} />
                </div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>

             {/* Ongoing Sessions List */}
             {sessions.length > 0 && (
                 <div className="space-y-4">
                     <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider ml-1">进行中 ({sessions.length})</h3>

                     {sessions.sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(session => {
                        // Calculate Progress
                        // FIX: Use map(Number) to ensure strict number type for reduce accumulator
                        const totalDays = Object.values(session.estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
                        const completedCount = session.completedDays.length;
                        const progress = totalDays > 0 ? (completedCount / totalDays) * 100 : 0;

                        return (
                            <div 
                                key={session.id}
                                onClick={() => handleResumeSession(session)}
                                className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative overflow-hidden"
                            >
                                <div className="flex justify-between items-start mb-3">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                                    </div>
                                    <div className="bg-fuchsia-50 text-fuchsia-600 p-2 rounded-xl">
                                        <LayoutGrid size={20} />
                                    </div>
                                </div>

                                <div className="flex items-center gap-2 mb-2">
                                    <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
                                        <div style={{width: `${progress}%`}} className="h-full bg-gradient-to-r from-fuchsia-500 to-indigo-500 rounded-full"></div>
                                    </div>
                                    <span className="text-xs font-bold text-slate-600 whitespace-nowrap">{completedCount} / {totalDays} 天</span>
                                </div>

                                {/* Delete Button (Visible on Hover/Touch) */}
                                <button 
                                    onClick={(e) => handleDeleteSession(session.id, e)}
                                    className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100 p-2"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        );
                     })}
                 </div>
             )}

             {sessions.length === 0 && (
                 <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                     <Sparkles size={24} className="text-slate-300 mx-auto mb-2" />
                     <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                 </div>
             )}
        </div>
    );
  }

  // --- RENDER: INTERMEDIATE STEP (PRE-COMPARISON) ---
  if (planningStep === 'pre-comparison-confirm') {
      const timeBoxConfig = [
          { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange' },
          { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky' },
          { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo' }
      ];

      const selectedConfigs = timeBoxConfig.filter(c => selectedTimeBoxes.includes(c.id));

      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20">
              <div className="text-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 mb-2">规划确认</h2>
                  <p className="text-slate-500 text-sm">今日专注目标</p>
              </div>

              {/* Selected Boxes Display */}
              <div className="w-full space-y-4 mb-8">
                  {selectedConfigs.map(item => {
                      const activeBg = item.id === 'morning' ? 'bg-orange-50 border-orange-100' :
                                       item.id === 'afternoon' ? 'bg-sky-50 border-sky-100' :
                                       'bg-indigo-50 border-indigo-100';
                      const activeText = item.id === 'morning' ? 'text-orange-600' :
                                         item.id === 'afternoon' ? 'text-sky-600' :
                                         'text-indigo-600';

                      return (
                          <div key={item.id} className={`flex items-center gap-4 p-4 rounded-2xl border ${activeBg} shadow-sm animate-slide-up`}>
                               <div className={`p-2 rounded-full bg-white/80 ${activeText}`}>
                                   <item.icon size={24} />
                               </div>
                               <span className={`text-lg font-bold ${activeText}`}>{item.label}</span>
                               <CheckCircle size={20} className={`ml-auto ${activeText}`} />
                          </div>
                      )
                  })}
              </div>

              {/* Guidance Text */}
              <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 mb-8 max-w-sm">
                  <div className="flex gap-3">
                      <div className="mt-1 text-fuchsia-500"><Sparkles size={20} /></div>
                      <div>
                          <p className="text-sm font-bold text-slate-700 mb-1">即将进入 Done List</p>
                          <p className="text-xs text-slate-500 leading-relaxed">
                              确认后，您将进入执行记录模式。<br/>
                              通过 <span className="font-bold text-slate-700">Done List (实际)</span> 与 <span className="font-bold text-slate-700">Time Box (计划)</span> 的对比，帮助您更直观地复盘今日状态。
                          </p>
                      </div>
                  </div>
              </div>

              {/* Action Buttons */}
              <div className="w-full space-y-3">
                  <button 
                    onClick={startComparison}
                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                      <PlayCircle size={20} />
                      开启 Done List
                  </button>
                  <button onClick={() => setPlanningStep('time-boxing')} className="text-slate-400 text-sm font-bold py-2">
                      返回调整
                  </button>
              </div>
          </div>
      );
  }

  // --- RENDER: TIME BOXING (Planning) ---
  if (planningStep === 'time-boxing') {
      const currentDay = currentComparisonDay;
      const currentStage = getCurrentStageForDay(currentDay) || stages[stages.length - 1];

      // Calculate day progress in current stage
      let daysBefore = 0;
      for (const s of stages) {
          if (s.id === currentStage.id) break;
          daysBefore += Number(estimates[s.id] || 0);
      }
      const dayInStage = currentDay - daysBefore;
      const stageDuration = Number(estimates[currentStage.id] || 0);
      const progressPercent = stageDuration > 0 ? (dayInStage / stageDuration) * 100 : 0;

      const displayDateObj = new Date(getTargetDateStr(currentDay));
      const displayDate = formatDate(displayDateObj.toISOString());

      return (
        <div className="animate-fade-in h-screen flex flex-col overflow-hidden bg-slate-50">

             {/* Nav Bar */}
             <div className="px-6 py-4 flex justify-between items-center shrink-0">
                <button 
                    onClick={() => setMode('dashboard')} 
                    className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"
                >
                    <ArrowLeft size={16} className="mr-1" /> 返回列表
                </button>
                <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-md">
                    Day {dayInStage} / {stageDuration}
                </span>
             </div>

             <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-40">

                 {/* Header Card */}
                 <div className="bg-white rounded-3xl p-6 shadow-xl shadow-fuchsia-100 border border-fuchsia-100 mb-8 relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-fuchsia-50 rounded-full -mr-10 -mt-10 blur-xl"></div>
                    <div className="relative z-10">
                        <div className="flex items-baseline justify-between mb-1">
                            <span className="text-3xl font-black text-slate-800 tracking-tight">{displayDate.split(' ')[0]}</span>
                            <span className="text-xs font-bold text-fuchsia-500 uppercase tracking-wider">当前阶段</span>
                        </div>
                        <h2 className="text-xl font-bold text-fuchsia-900 mb-2">{currentStage.title}</h2>
                        <div className="bg-slate-100 h-1.5 rounded-full w-full overflow-hidden flex">
                            <div style={{ width: `${progressPercent}%` }} className="bg-fuchsia-500 h-full"></div>
                        </div>
                    </div>
                 </div>

                 {/* Guidance */}
                 <div className="text-center mb-8">
                     <p className="text-sm font-medium text-slate-600 mb-1">选择今天的绘画时段</p>
                     <p className="text-xs text-slate-400 leading-relaxed max-w-xs mx-auto">
                         不做具体的时间刻度安排。<br/>
                         <span className="text-fuchsia-500 font-bold">早、中、晚</span>，你只需决定大致的创作范畴。
                     </p>
                 </div>

                 {/* Timeline & Boxes */}
                 <div className="relative pl-4 space-y-4">
                     {/* Vertical Line */}
                     <div className="absolute left-[27px] top-4 bottom-4 w-0.5 bg-gradient-to-b from-slate-200 via-fuchsia-200 to-slate-200"></div>

                     {/* Nodes */}
                     {[
                         { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange', ratio: 'h-24' },
                         { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky', ratio: 'h-48' },
                         { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo', ratio: 'h-36' }
                     ].map((item) => {
                         const isSelected = selectedTimeBoxes.includes(item.id);
                         const activeBg = item.id === 'morning' ? 'bg-gradient-to-r from-orange-50 to-white border-orange-100' :
                                          item.id === 'afternoon' ? 'bg-gradient-to-r from-sky-50 to-white border-sky-100' :
                                          'bg-gradient-to-r from-indigo-50 to-white border-indigo-100';

                         const activeIconBg = item.id === 'morning' ? 'bg-orange-100 text-orange-500' :
                                              item.id === 'afternoon' ? 'bg-sky-100 text-sky-500' :
                                              'bg-indigo-100 text-indigo-500';

                         const activeCheckColor = item.id === 'morning' ? 'text-orange-500' :
                                                  item.id === 'afternoon' ? 'text-sky-500' :
                                                  'text-indigo-500';

                         return (
                             <div 
                                key={item.id}
                                onClick={() => toggleTimeBox(item.id)}
                                className="relative flex items-stretch gap-3 group cursor-pointer transition-all hover:scale-102"
                             >
                                 <div className={`relative z-10 flex flex-col items-center justify-center ${item.id === 'morning' ? 'pt-9' : item.id === 'afternoon' ? 'pt-20' : 'pt-14'}`}>
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center bg-white transition-colors ${isSelected ? 'border-fuchsia-500 text-fuchsia-500' : 'border-slate-300 text-slate-300'}`}>
                                         <div className={`w-2 h-2 rounded-full ${isSelected ? 'bg-fuchsia-500' : 'bg-transparent'}`}></div>
                                    </div>
                                 </div>
                                 <div className={`flex-1 ${item.ratio} p-4 rounded-2xl border transition-all flex items-center ${isSelected ? activeBg + ' shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                                     <div className="flex items-center justify-between w-full">
                                         <div className="flex items-center gap-2">
                                             <div className={`p-1.5 rounded-full ${isSelected ? activeIconBg : 'bg-slate-50'}`}>
                                                 <item.icon size={16} />
                                             </div>
                                             <span className="text-lg font-bold">{item.label.split(' ')[0]}</span>
                                         </div>
                                         {isSelected && <Check size={16} className={activeCheckColor} />}
                                     </div>
                                 </div>
                             </div>
                         );
                     })}
                 </div>
             </div>

             {/* Bottom Action (Fixed Overlay) */}
             <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-10 pb-12 px-6 z-30 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button 
                        onClick={proceedToPreConfirmation}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 mb-safe"
                    >
                        确认今日规划
                        <ChevronRight size={20} />
                    </button>
                </div>
             </div>
        </div>
      );
  }

  // --- RENDER: DAILY COMPARISON (Done List Timeline) ---
  if (planningStep === 'daily-comparison') {
      const currentDay = currentComparisonDay;
      const currentStageForDay = getCurrentStageForDay(currentDay);
      const isCompleted = isDayCompleted(currentDay);

      // Define ranges
      const isMorning = (h: number) => h >= 9 && h <= 12;
      const isAfternoon = (h: number) => h >= 13 && h <= 17;
      const isEvening = (h: number) => h >= 18 && h <= 27;

      // Calculate date
      const displayingDateObj = new Date(getTargetDateStr(currentDay));
      const displayingDateStr = formatDate(displayingDateObj.toISOString()).split(' ')[0];

      // Check if plan matches
      const getPlanColor = (h: number) => {
          if (isMorning(h) && selectedTimeBoxes.includes('morning')) return 'bg-orange-50';
          if (isAfternoon(h) && selectedTimeBoxes.includes('afternoon')) return 'bg-sky-50';
          if (isEvening(h) && selectedTimeBoxes.includes('evening')) return 'bg-indigo-50';
          return 'bg-white';
      };

      // Populate hours if it's a completed day (view mode)
      const displayHours = isCompleted 
        ? (bookings.find(b => b.date === getTargetDateStr(currentDay))?.actualHours || [])
        : selectedActualHours;

      return (
          <div className="animate-fade-in h-screen flex flex-col bg-white">
               {/* Nav */}
               <div className="px-6 py-4 flex justify-between items-start bg-white border-b border-slate-50 shrink-0 z-20">
                   <div>
                       <div className="flex items-center gap-2">
                            <PenTool size={20} className="text-slate-800" />
                            <h2 className="text-xl font-serif font-bold text-slate-800 tracking-tight">Done List</h2>
                       </div>
                       <p className="text-[10px] text-slate-400 mt-1 ml-7">
                           {isCompleted ? '历史记录 (已存档)' : '点击时间轴，记录实际专注时段'}
                       </p>
                   </div>
                   <div className="flex flex-col items-end gap-1">
                       <span className={`text-xs font-mono font-medium px-3 py-1.5 rounded-full border ${isCompleted ? 'bg-slate-100 text-slate-500 border-slate-200' : 'text-emerald-600 bg-emerald-50 border-emerald-100'}`}>
                           {displayHours.length * 0.5}h
                       </span>
                       {currentStageForDay && (
                           <span className="text-[10px] font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-0.5 rounded-md border border-fuchsia-100/50">
                               {currentStageForDay.title}
                           </span>
                       )}
                   </div>
               </div>

               {/* Date Navigation */}
               <div className="px-6 py-2 bg-slate-50/50 border-b border-slate-100 flex items-center justify-between z-20">
                  <button 
                    onClick={() => {
                        const prev = Math.max(1, currentDay - 1);
                        setCurrentComparisonDay(prev);
                        setSelectedActualHours([]);
                    }}
                    className="p-1 rounded-full hover:bg-white text-slate-400 hover:text-slate-600 transition-colors"
                  >
                    <ArrowLeft size={16} />
                  </button>
                  <div className="flex flex-col items-center">
                    <span className="text-sm font-bold text-slate-800">Day {currentDay}</span>
                    <span className="text-[10px] text-slate-400 font-medium">{displayingDateStr}</span>
                  </div>
                  <button 
                    onClick={() => {
                        // Prevent going to future unreached days if strict logic needed, but allowing browsing planned/unplanned
                        setCurrentComparisonDay(currentDay + 1);
                        setSelectedActualHours([]);
                    }}
                    className="p-1 rounded-full hover:bg-white text-slate-400 hover:text-slate-600 transition-colors"
                  >
                    <ChevronRight size={16} />
                  </button>
               </div>

               {/* Timeline Container */}
               <div className="flex-1 overflow-y-auto custom-scrollbar pb-32 pt-4 px-6 relative">
                   <div className="max-w-lg mx-auto w-full relative">

                       {timeSlots.map((slot) => {
                           const bgClass = getPlanColor(slot.value);
                           const topId = `${slot.id}-00`; // Logic: Left (First 30m)
                           const botId = `${slot.id}-30`; // Logic: Right (Last 30m)
                           const isLeftDone = displayHours.includes(topId);
                           const isRightDone = displayHours.includes(botId);

                           return (
                               <div key={slot.id} className="flex items-center h-16 mb-2">
                                   {/* Time Label */}
                                   <div className="w-14 flex-shrink-0 text-right pr-3 pt-0">
                                       <span className="text-xs font-mono text-slate-400">
                                           {slot.label}
                                       </span>
                                       {slot.isNextDay && <div className="text-[8px] text-slate-300 leading-none">+1</div>}
                                   </div>

                                   {/* Capsule Container */}
                                   <div className={`flex-1 h-full rounded-2xl border border-slate-100 flex overflow-hidden ${bgClass} transition-colors ${isCompleted ? 'opacity-75 pointer-events-none grayscale-[0.3]' : ''}`}>

                                        {/* Left Half (00-30 min) */}
                                        <div 
                                            onClick={() => toggleActualHour(topId)}
                                            className={`flex-1 h-full border-r border-dashed border-slate-300/60 cursor-pointer transition-colors ${isLeftDone ? 'bg-[#a7d7c5]' : 'hover:bg-black/5'}`}
                                        ></div>

                                        {/* Right Half (30-60 min) */}
                                        <div 
                                            onClick={() => toggleActualHour(botId)}
                                            className={`flex-1 h-full cursor-pointer transition-colors ${isRightDone ? 'bg-[#a7d7c5]' : 'hover:bg-black/5'}`}
                                        ></div>
                                   </div>
                               </div>
                           );
                       })}

                        {/* Finish Button - Placed inside scrollable content but with extra margin */}
                       {!isCompleted && (
                           <div className="mt-8">
                                <button 
                                    onClick={finishAll}
                                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2"
                                >
                                    <CheckCircle2 size={20} />
                                    完成记录
                                </button>
                                <p className="text-center text-xs text-slate-400 mt-4">
                                    确认后将保存今日记录并同步至日历
                                </p>
                           </div>
                       )}
                       {isCompleted && (
                           <div className="mt-8 text-center text-slate-400 text-sm flex items-center justify-center gap-2">
                               <Lock size={16} /> 今日记录已存档
                           </div>
                       )}
                   </div>
               </div>
          </div>
      );
  }

  // --- RENDER: SUMMARY & FEEDBACK ---
  if (planningStep === 'summary') {
      const getFeedback = () => {
          const ranges = {
              morning: [9, 10, 11, 12],
              afternoon: [13, 14, 15, 16, 17],
              evening: Array.from({length: 10}, (_, i) => i + 18) // 18 to 27
          };

          let hasPlanned = false;
          let hasUnplanned = false;

          selectedActualHours.forEach(id => {
              const h = parseInt(id.split('-')[1].replace('h', ''));
              // Determine which box this hour belongs to
              let box = '';
              if (ranges.morning.includes(h)) box = 'morning';
              else if (ranges.afternoon.includes(h)) box = 'afternoon';
              else if (ranges.evening.includes(h)) box = 'evening';

              // Check if this box was selected
              if (box && selectedTimeBoxes.includes(box)) {
                  hasPlanned = true;
              } else {
                  hasUnplanned = true; 
              }
          });

          // Logic based on prompt
          if (hasPlanned && hasUnplanned) return { msg: "Way Ahead! But don't push your self too hard, take some rest!", emoji: "❤️", title: "超额完成！" };
          if (hasPlanned && !hasUnplanned) return { msg: "Well Done! Excellent Planning!", emoji: "👍", title: "计划达成！" };
          if (!hasPlanned && hasUnplanned) return { msg: "I see, a flexible runner, nice action.", emoji: "⚡", title: "灵活执行" };
          return { msg: "It's Ok, hope you take some water and enjoy your rest! After all, tomorrow is another day.", emoji: "🙂", title: "好好休息" };
      };

      const feedback = getFeedback();

      // Process Actual Hours for Capsule Display
      // 1. Sort hours
      const sortedHours = [...selectedActualHours].sort((a, b) => {
          const [hA, mA] = a.replace('h-', '').split('-').map(Number);
          const [hB, mB] = b.replace('h-', '').split('-').map(Number);
          return (hA * 60 + mA) - (hB * 60 + mB);
      });

      // 2. Merge adjacent slots and determine type/color
      const mergedCapsules: { start: string, end: string, label: string, type: 'morning' | 'afternoon' | 'evening' }[] = [];

      let currentStartMinutes = -1;
      let currentEndMinutes = -1;

      const formatTime = (totalMinutes: number) => {
          const h = Math.floor(totalMinutes / 60);
          const m = totalMinutes % 60;
          // Handle next day display > 24h
          const displayH = h >= 24 ? h - 24 : h;
          const label = `${displayH.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
          return h >= 24 ? `次日 ${label}` : label;
      };

      const getTimeType = (totalMinutes: number): 'morning' | 'afternoon' | 'evening' => {
          const h = Math.floor(totalMinutes / 60);
          if (h >= 9 && h <= 12) return 'morning';
          if (h >= 13 && h <= 17) return 'afternoon';
          return 'evening';
      };

      sortedHours.forEach((slot, index) => {
           const [h, m] = slot.replace('h-', '').split('-').map(Number);
           const startMin = h * 60 + (m === 0 ? 0 : 30);
           const endMin = startMin + 30;

           if (currentStartMinutes === -1) {
               currentStartMinutes = startMin;
               currentEndMinutes = endMin;
           } else {
               if (startMin === currentEndMinutes) {
                   // contiguous
                   currentEndMinutes = endMin;
               } else {
                   // break, push previous
                   mergedCapsules.push({
                       start: formatTime(currentStartMinutes),
                       end: formatTime(currentEndMinutes),
                       label: `${formatTime(currentStartMinutes)} - ${formatTime(currentEndMinutes)}`,
                       type: getTimeType(currentStartMinutes)
                   });
                   currentStartMinutes = startMin;
                   currentEndMinutes = endMin;
               }
           }
      });
      // Push last
      if (currentStartMinutes !== -1) {
          mergedCapsules.push({
              start: formatTime(currentStartMinutes),
              end: formatTime(currentEndMinutes),
              label: `${formatTime(currentStartMinutes)} - ${formatTime(currentEndMinutes)}`,
              type: getTimeType(currentStartMinutes)
          });
      }

      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20 text-center">

              {/* Emoji Badge */}
              <div className="w-24 h-24 bg-gradient-to-tr from-slate-100 to-white rounded-full flex items-center justify-center text-4xl shadow-xl shadow-slate-200 border border-slate-100 mb-6 animate-slide-up">
                  {feedback.emoji}
              </div>

              {/* Title & Feedback */}
              <h2 className="text-2xl font-black text-slate-800 mb-3">{feedback.title}</h2>
              <p className="text-slate-500 font-medium leading-relaxed max-w-xs mx-auto mb-6">
                  {feedback.msg}
              </p>

              <div className="bg-blue-50/50 text-blue-600 text-xs px-3 py-1 rounded-full mb-8 border border-blue-100">
                  已同步至排期日历，点击日历对应日期即可查看详情。
              </div>

              {/* Capsules Display */}
              {mergedCapsules.length > 0 && (
                  <div className="w-full max-w-sm bg-slate-50 rounded-3xl p-6 border border-slate-100 mb-10">
                      <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4 text-left">实际工作时间</h3>
                      <div className="flex flex-wrap gap-2">
                          {mergedCapsules.map((cap, idx) => {
                              // Use Morning/Noon/Evening specific colors
                              let bgClass = '';
                              if (cap.type === 'morning') bgClass = 'bg-orange-100 text-orange-700';
                              else if (cap.type === 'afternoon') bgClass = 'bg-sky-100 text-sky-700';
                              else bgClass = 'bg-indigo-100 text-indigo-700';

                              return (
                                  <div key={idx} className={`${bgClass} px-4 py-2 rounded-full text-sm font-bold shadow-sm`}>
                                      {cap.label}
                                  </div>
                              );
                          })}
                      </div>
                      <div className="mt-4 pt-4 border-t border-slate-200/50 flex justify-end">
                           <span className="text-xs font-bold text-slate-400">Total: {selectedActualHours.length * 0.5} Hours</span>
                      </div>
                  </div>
              )}

              {/* Next Day Button */}
              <button 
                onClick={handleContinueToNextDay}
                className="w-full max-w-xs bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all"
              >
                  进入下一天
              </button>

              <button 
                onClick={() => setMode('dashboard')}
                className="mt-4 text-sm font-bold text-slate-400 hover:text-slate-600"
              >
                  返回列表
              </button>

          </div>
      );
  }

  // --- RENDER: FINISHED SUMMARY (PLANNING PHASE) ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 shadow-lg shadow-emerald-200">
                  <Check size={40} strokeWidth={3} />
              </div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">规划已生成</h2>
              <p className="text-slate-500 mb-8">根据您的灵感流，我们计算出了所需天数。</p>

              <div className="w-full bg-white rounded-3xl p-6 shadow-xl shadow-slate-100 border border-slate-100 mb-8">
                  {syncedProject && (
                      <div className="mb-4 pb-4 border-b border-dashed border-slate-200 text-left">
                          <span className="text-[10px] uppercase font-bold text-slate-400">关联项目</span>
                          <div className="flex justify-between items-center mt-1">
                             <p className="font-bold text-slate-800">{syncedProject.clientName}</p>
                             <span className="text-xs bg-slate-100 px-2 py-1 rounded text-slate-600 font-medium">可用 {totalAvailableDays} 天</span>
                          </div>
                      </div>
                  )}
                  {stages.map((stage) => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                          <span className="font-medium text-slate-700">{stage.title}</span>
                          <span className="font-bold text-indigo-600">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between items-center font-bold text-lg">
                      <span>总计规划</span>
                      <span className={`${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} 天</span>
                  </div>
                  {isOverBudget && (
                      <p className="text-xs text-rose-500 mt-2 font-medium">注意：规划时间已超出可用工期！</p>
                  )}
              </div>

              <div className="w-full space-y-3">
                  <button 
                    onClick={handleFinalize} 
                    className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                      <Box size={20} />
                      时间盒子的规划法
                  </button>
                  <button onClick={() => setPlanningStep('time-entry')} className="text-slate-400 text-sm font-bold py-2">
                      返回修改
                  </button>
              </div>
          </div>
      );
  }

  // --- RENDER: SETUP WIZARD (Planner Mode) ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button 
                onClick={() => {
                    if (planningStep === 'time-entry') setPlanningStep('setup');
                    else setMode('dashboard');
                }} 
                className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"
            >
                <ArrowLeft size={16} className="mr-1" /> 返回
            </button>
            {planningStep === 'time-entry' && (
                <div className="flex items-center gap-3">
                    {syncedProject && (
                        <div className={`flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded-lg border ${isOverBudget ? 'bg-rose-50 border-rose-100 text-rose-600' : 'bg-emerald-50 border-emerald-100 text-emerald-600'}`}>
                            <Hourglass size={12} />
                            <span>{currentPlannedDays} / {totalAvailableDays} 天</span>
                        </div>
                    )}
                    <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1.5 rounded-lg">
                        逆向规划中...
                    </span>
                </div>
            )}
       </div>

       {planningStep === 'setup' && (
        <div className="mb-6 relative overflow-hidden bg-gradient-to-br from-fuchsia-50 to-rose-50 rounded-3xl border border-fuchsia-100 transition-all">

            {/* Header Content */}
            {!showSyncInput ? (
                <div className="p-6 relative">
                     <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
                        <Sparkles size={80} className="text-fuchsia-500" />
                    </div>
                    <div className="flex justify-between items-start">
                        <div className="flex-1 mr-2">
                            <h2 className="text-2xl font-bold text-fuchsia-900 flex items-center gap-2">
                                <Sparkles size={20} className="text-fuchsia-500" />
                                {syncedProject ? `规划: ${syncedProject.clientName}` : '灵感流 (P人模式)'}
                            </h2>
                            {syncedProject ? (
                                <div className="mt-3 bg-white/60 p-3 rounded-xl border border-fuchsia-100 backdrop-blur-sm shadow-sm">
                                    <div className="flex justify-between items-center mb-2 pb-2 border-b border-fuchsia-100/50">
                                         <span className="text-xs font-bold text-fuchsia-900/60 uppercase">工期预算</span>
                                         <span className="text-lg font-black text-fuchsia-600">{totalAvailableDays} 天</span>
                                    </div>
                                    <div className="flex gap-4">
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-fuchsia-400 font-bold">开始</span>
                                            <span className="text-xs font-bold text-fuchsia-800">{formatDate(syncedProject.startDate)}</span>
                                        </div>
                                        <div className="flex flex-col">
                                            <span className="text-[10px] text-fuchsia-400 font-bold">截止</span>
                                            <span className="text-xs font-bold text-fuchsia-800">{formatDate(syncedProject.deadline)}</span>
                                        </div>
                                    </div>
                                </div>
                            ) : (
                                <p className="text-xs text-fuchsia-800/60 mt-2 leading-relaxed">
                                    随意<b>拖拽</b>节点调整顺序。
                                </p>
                            )}
                        </div>

                        {!syncedProject && (
                            <button 
                                onClick={() => setShowSyncInput(true)}
                                className="flex items-center gap-1 bg-white/50 hover:bg-white text-fuchsia-700 px-3 py-2 rounded-xl backdrop-blur-sm transition-colors shadow-sm text-xs font-bold whitespace-nowrap"
                                title="同步排单"
                            >
                                <Link size={14} />
                                关联排单
                            </button>
                        )}
                    </div>
                </div>
            ) : (
                <div className="p-4 animate-fade-in">
                    <div className="flex items-center justify-between mb-2">
                         <span className="text-xs font-bold text-fuchsia-800 uppercase">输入排单 ID 同步</span>
                         <button onClick={() => setShowSyncInput(false)}><X size={16} className="text-fuchsia-400" /></button>
                    </div>
                    <div className="flex gap-2">
                        <input 
                            autoFocus
                            type="text" 
                            value={syncId}
                            onChange={(e) => setSyncId(e.target.value)}
                            placeholder="粘贴排单 ID"
                            className="flex-1 text-sm bg-white border border-fuchsia-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-fuchsia-500"
                        />
                        <button 
                            onClick={handleSyncProject}
                            className="bg-fuchsia-600 text-white px-3 py-2 rounded-xl font-bold text-sm"
                        >
                            同步
                        </button>
                    </div>
                </div>
            )}
        </div>
       )}

       <div className="space-y-4 relative">
          {/* Add Button (Hidden in time-entry) */}
          {planningStep === 'setup' && (
             !isAdding ? (
                <div 
                    onClick={() => setIsAdding(true)}
                    className="w-full h-20 border-2 border-dashed border-slate-300 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:bg-slate-50 hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all active:scale-95 group"
                >
                    <div className="flex flex-col items-center gap-1">
                        <Plus size={24} className="group-hover:scale-110 transition-transform" />
                        <span className="text-xs font-bold uppercase tracking-wider">添加新阶段</span>
                    </div>
                </div>
              ) : (
                <div className="w-full h-20 border-2 border-fuchsia-300 rounded-2xl flex items-center justify-between px-4 bg-white shadow-sm animate-fade-in">
                    <input 
                        autoFocus
                        type="text" 
                        placeholder="输入阶段名称..."
                        value={newStageTitle}
                        onChange={(e) => setNewStageTitle(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()}
                        className="flex-1 bg-transparent text-lg font-medium text-slate-800 outline-none placeholder-slate-300"
                    />
                    <div className="flex gap-2">
                        <button onClick={() => setIsAdding(false)} className="p-2 text-slate-400 hover:bg-slate-100 rounded-full">
                            <X size={20} />
                        </button>
                        <button onClick={handleConfirmAdd} className="p-2 bg-fuchsia-500 text-white rounded-full">
                            <Check size={20} />
                        </button>
                    </div>
                </div>
              )
          )}

          {/* Draggable List */}
          {stages.map((stage, index) => {
            const isActive = index === activeTimeIndex;
            // In setup mode: full width. In time-entry: 40% width and left aligned.
            const containerClass = planningStep === 'setup' 
                ? 'w-full h-24 px-6 border-slate-200 bg-white/50 hover:border-fuchsia-300' 
                : `w-[45%] h-16 px-4 transition-all duration-500 ${isActive ? 'border-fuchsia-500 bg-white shadow-lg scale-105 z-10' : 'border-slate-100 bg-slate-50 opacity-40 grayscale'}`;

            return (
                <div key={stage.id} className="relative flex items-center">
                    {/* The Stage Card */}
                    <div
                        draggable={planningStep === 'setup'}
                        onDragStart={() => handleDragStart(index)}
                        onDragEnter={() => handleDragEnter(index)}
                        onDragEnd={handleDragEnd}
                        onDragEndCapture={handleDragEnd}
                        onDragOver={(e) => e.preventDefault()}
                        onClick={() => {
                            if (planningStep === 'time-entry') {
                                setActiveTimeIndex(index);
                                setCurrentInputTime(estimates[stage.id] || '');
                            }
                        }}
                        className={`
                            relative border rounded-2xl flex items-center 
                            ${containerClass}
                            ${planningStep === 'setup' ? 'cursor-grab active:cursor-grabbing backdrop-blur-sm' : ''}
                            ${planningStep === 'time-entry' ? 'cursor-pointer hover:opacity-80 hover:scale-[1.02]' : ''}
                        `}
                    >
                        {/* Drag Handle (Only Setup) */}
                        {planningStep === 'setup' && (
                            <div className="text-slate-200 mr-4 cursor-grab">
                                <GripVertical size={24} />
                            </div>
                        )}

                        {/* Content */}
                        <div className="flex flex-col truncate">
                            <span className={`font-medium truncate ${planningStep === 'setup' ? 'text-lg text-slate-700' : 'text-sm text-slate-800'}`}>
                                {stage.title}
                            </span>
                            {planningStep === 'time-entry' && estimates[stage.id] && (
                                <span className="text-[10px] text-fuchsia-600 font-bold flex items-center gap-1">
                                    <Clock size={10} /> {estimates[stage.id]} 天
                                </span>
                            )}
                        </div>

                        {/* Delete Action (Only Setup) */}
                        {planningStep === 'setup' && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); deleteStage(index); }}
                                className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-200 hover:text-rose-400 p-2"
                            >
                                <X size={16} />
                            </button>
                        )}
                    </div>

                    {/* Time Input Area (Only for Active Item in Time Mode) */}
                    {planningStep === 'time-entry' && isActive && (
                        <div className="flex-1 ml-4 animate-slide-up flex items-center gap-3">
                            <div className="h-0.5 w-4 bg-fuchsia-300"></div>
                            <div className="flex-1">
                                <label className="block text-[10px] font-bold text-fuchsia-500 uppercase mb-1 tracking-wider">
                                    预期耗时 (天)
                                </label>
                                <div className="flex gap-2">
                                    <input 
                                        autoFocus
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="0.5"
                                        value={currentInputTime}
                                        onChange={handleTimeInput}
                                        onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()}
                                        className="w-20 bg-white border-2 border-fuchsia-200 rounded-xl px-3 py-2 text-lg font-bold text-slate-800 outline-none focus:border-fuchsia-500 focus:ring-4 focus:ring-fuchsia-100 transition-all"
                                    />
                                    <button 
                                        onClick={confirmTimeEntry}
                                        disabled={!currentInputTime}
                                        className="bg-slate-900 text-white px-4 rounded-xl disabled:opacity-50 disabled:cursor-not-allowed hover:scale-105 transition-transform flex items-center justify-center"
                                    >
                                        <ArrowUp size={20} />
                                    </button>
                                </div>
                                <p className="text-[10px] text-slate-400 mt-2 leading-tight">
                                    {isOverBudget ? (
                                        <span className="text-rose-500 font-bold">警告：已超出可用工期！</span>
                                    ) : (
                                        <span>当前可用预算: {Math.max(0, totalAvailableDays - currentPlannedDays)} 天</span>
                                    )}
                                </p>
                            </div>
                        </div>
                    )}
                </div>
            );
          })}
       </div>

       {/* Bottom Action Button */}
       {planningStep === 'setup' && (
           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button 
                     onClick={startConfiguration}
                     className="w-full bg-slate-900 text-white py-4 rounded-2xl shadow-xl shadow-slate-300 font-bold text-lg flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all"
                   >
                       <Check size={20} />
                       已完成配置
                   </button>
               </div>
           </div>
       )}
    </div>
  );
};

export default PTypePlanner;

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string; // New: To identify which client owns this project
  description: string;
  startDate: string; // ISO String
  deadline: string; // ISO String
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string; // YYYY-MM-DD
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string; // New: To identify who booked/owns this slot
  note?: string;
  actualHours?: string[]; // New: Stores the IDs of actual worked slots (e.g., 'h-9-00')
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>; // StageId -> Days
  blockedDates: string[]; // New: Dates user chose to rest (YYYY-MM-DD)
  createdAt: string;
  lastUpdated: string;
  completedDays: number[]; // Array of completed day indices (1, 2, 3...)
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  // Session start date for non-synced projects
  const [sessionStartDate] = useState(new Date());

  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');

  // Sync State
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);

  // 'setup' = stages, 'off-days' = rest calendar, 'time-entry' = duration, 'finished' = summary, 'time-boxing' = daily planning...
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  // Index of the stage currently being edited (starts from bottom)
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Time Boxing State
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);

  // Actual Execution State
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  // Local state for non-synced completed days tracking
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization: Load Sessions ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  // Save Sessions to LocalStorage
  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers for Planning Logic ---

  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Check if a date is blocked globally OR specifically in this session
  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings.some(b => b.date === dateStr && b.status === 'blocked');
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  // Calculate available days between start and end (inclusive), skipping blocked dates
  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 365 * 2) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  // Get the date string for the Nth available working day (1-based index)
  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      current.setHours(0,0,0,0);

      let validDaysFound = 0;
      let safetyCounter = 0;

      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }

          if (validDaysFound === dayIndex) {
              return dateStr;
          }

          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }
      return getYYYYMMDD(current);
  };

  const isDayCompleted = (dayIndex: number) => {
      const dateStr = getTargetDateStr(dayIndex);
      const hasBooking = bookings.some(b => b.date === dateStr && b.actualHours && b.actualHours.length > 0);
      return hasBooking || localCompletedDays.includes(dayIndex);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 0;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const isOverBudget = syncedProject ? currentPlannedDays > totalAvailableDays : false;

  const generateTimeSlots = () => {
      const slots = [];
      for (let i = 9; i <= 27; i++) {
          const hour = i % 24;
          const label = `${hour.toString().padStart(2, '0')}:00`;
          const isNextDay = i >= 24;
          slots.push({ id: `h-${i}`, value: i, label, isNextDay, fullLabel: isNextDay ? `次日 ${label}` : label });
      }
      return slots;
  };
  const timeSlots = generateTimeSlots();

  // --- Actions ---

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);

      if (session.projectId) {
          const project = projects.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else {
          setSyncedProject(null);
      }

      const totalPlanned = Object.values(session.estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
      let nextDay = 1;
      const completedSet = new Set(session.completedDays || []);
      for(let i=1; i<=Math.ceil(totalPlanned) + 30; i++) {
          if(!completedSet.has(i)) {
              nextDay = i;
              break;
          }
      }
      setCurrentComparisonDay(nextDay);
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const copyListItems = [...stages];
    const dragItemContent = copyListItems[dragItem.current];
    copyListItems.splice(dragItem.current, 1);
    copyListItems.splice(dragOverItem.current, 0, dragItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setStages(copyListItems);
  };

  const handleConfirmAdd = () => {
    if (newStageTitle.trim()) {
        const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
        setStages([newStage, ...stages]);
        setNewStageTitle('');
        setIsAdding(false);
    }
  };

  const deleteStage = (index: number) => {
      if(confirm('确定删除此阶段吗?')) {
          const newStages = [...stages];
          newStages.splice(index, 1);
          setStages(newStages);
      }
  };

  const handleSyncProject = () => {
      if(!syncId.trim()) return;
      const found = projects.find(p => p.id === syncId.trim());
      if(found) {
          setSyncedProject(found);
          setShowSyncInput(false);
          setSyncId('');
      } else {
          alert('未找到该 ID 对应的排单。');
      }
  };

  const startConfiguration = () => {
      setPlanningStep('off-days');
  };

  const toggleSessionBlockedDate = (dateStr: string) => {
      if (sessionBlockedDates.includes(dateStr)) {
          setSessionBlockedDates(sessionBlockedDates.filter(d => d !== dateStr));
      } else {
          setSessionBlockedDates([...sessionBlockedDates, dateStr]);
      }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });
      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime('');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      const updatedSessions = [newSession, ...sessions];
      persistSessions(updatedSessions);
      setCurrentSessionId(newSession.id);

      let startDay = 1;
      const maxCheck = currentPlannedDays > 0 ? Math.ceil(currentPlannedDays) + 30 : 60;
      for (let i = 1; i <= maxCheck; i++) {
          if (!isDayCompleted(i)) {
              startDay = i;
              break;
          }
      }
      setCurrentComparisonDay(startDay); 
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const toggleTimeBox = (box: string) => {
      if (selectedTimeBoxes.includes(box)) setSelectedTimeBoxes(selectedTimeBoxes.filter(b => b !== box));
      else setSelectedTimeBoxes([...selectedTimeBoxes, box]);
  };

  const toggleActualHour = (uniqueId: string) => {
      if (isDayCompleted(currentComparisonDay)) return;
      if (selectedActualHours.includes(uniqueId)) setSelectedActualHours(selectedActualHours.filter(h => h !== uniqueId));
      else setSelectedActualHours([...selectedActualHours, uniqueId]);
  };

  const proceedToPreConfirmation = () => {
      if (selectedTimeBoxes.length === 0) {
          alert("请至少选择一个时间段作为今日规划");
          return;
      }
      setPlanningStep('pre-comparison-confirm');
  };

  const finishAll = () => {
      const dateStr = getTargetDateStr(currentComparisonDay);
      if (onUpdateBookings) {
          const newBookings = [...bookings];
          const existingIndex = newBookings.findIndex(b => b.date === dateStr);
          if (existingIndex >= 0) newBookings[existingIndex] = { ...newBookings[existingIndex], actualHours: selectedActualHours };
          else newBookings.push({ date: dateStr, status: 'booked', actualHours: selectedActualHours });
          onUpdateBookings(newBookings);
      }
      const newCompletedDays = [...localCompletedDays];
      if (!newCompletedDays.includes(currentComparisonDay)) newCompletedDays.push(currentComparisonDay);
      setLocalCompletedDays(newCompletedDays);
      if (currentSessionId) {
          const updatedSessions = sessions.map(s => 
              s.id === currentSessionId ? { ...s, completedDays: newCompletedDays, lastUpdated: new Date().toISOString() } : s
          );
          persistSessions(updatedSessions);
      }
      setPlanningStep('summary');
  };

  const handleContinueToNextDay = () => {
      const nextDay = currentComparisonDay + 1;
      setCurrentComparisonDay(nextDay);
      setSelectedActualHours([]);
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const getCurrentStageForDay = (day: number) => {
      let cumulativeDays = 0;
      for (const stage of stages) {
          const duration = Number(estimates[stage.id] || 0);
          cumulativeDays += duration;
          if (day <= cumulativeDays) return stage;
      }
      return stages.length > 0 ? stages[stages.length - 1] : null;
  };

  // --- RENDER: DASHBOARD VIEW ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>

             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>

             {sessions.length > 0 && (
                 <div className="space-y-4">
                     <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider ml-1">进行中 ({sessions.length})</h3>
                     {sessions.sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(session => {
                        const totalDays = Object.values(session.estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
                        const completedCount = session.completedDays.length;
                        const progress = totalDays > 0 ? (completedCount / totalDays) * 100 : 0;
                        return (
                            <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative overflow-hidden">
                                <div className="flex justify-between items-start mb-3">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                                    </div>
                                    <div className="bg-fuchsia-50 text-fuchsia-600 p-2 rounded-xl"><LayoutGrid size={20} /></div>
                                </div>
                                <div className="flex items-center gap-2 mb-2">
                                    <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
                                        <div style={{width: `${progress}%`}} className="h-full bg-gradient-to-r from-fuchsia-500 to-indigo-500 rounded-full"></div>
                                    </div>
                                    <span className="text-xs font-bold text-slate-600 whitespace-nowrap">{completedCount} / {totalDays} 天</span>
                                </div>
                                <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100 p-2">
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        );
                     })}
                 </div>
             )}

             {sessions.length === 0 && (
                 <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                     <Sparkles size={24} className="text-slate-300 mx-auto mb-2" />
                     <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                 </div>
             )}
        </div>
    );
  }

  // --- RENDER: OFF-DAYS SELECTION ---
  if (planningStep === 'off-days') {
      const today = new Date();
      today.setHours(0,0,0,0);
      const calendarDays = [];
      const daysCount = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) + 30 : 35;

      const calendarStart = getStartDate();
      for (let i = 0; i < 42; i++) { // Show a 6-week grid
          const d = new Date(calendarStart);
          d.setDate(calendarStart.getDate() + i);
          calendarDays.push(getYYYYMMDD(d));
      }

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回设置
                </button>
              </div>

              <div className="mb-8">
                  <h2 className="text-2xl font-black text-slate-800">设置休息日</h2>
                  <p className="text-slate-400 text-sm mt-1">点击日期标记“X”，规划时将自动跳过这些日子。</p>
              </div>

              <div className="bg-white rounded-3xl p-5 shadow-xl shadow-slate-100 border border-slate-100">
                  <div className="grid grid-cols-7 gap-2 mb-4">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => (
                          <div key={d} className="text-center text-[10px] font-bold text-slate-300 uppercase">{d}</div>
                      ))}
                      {calendarDays.map(dateStr => {
                          const dateObj = new Date(dateStr + 'T00:00:00');
                          const isBlocked = sessionBlockedDates.includes(dateStr);
                          const isGlobalBlocked = bookings.some(b => b.date === dateStr && b.status === 'blocked');

                          return (
                              <div 
                                key={dateStr}
                                onClick={() => !isGlobalBlocked && toggleSessionBlockedDate(dateStr)}
                                className={`aspect-square rounded-xl border flex items-center justify-center relative transition-all active:scale-95 cursor-pointer
                                    ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}
                                    ${isGlobalBlocked ? 'bg-slate-100 text-slate-200 cursor-not-allowed opacity-50' : ''}
                                `}
                              >
                                  <span className="text-xs font-bold">{dateObj.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                                  {isGlobalBlocked && <Lock size={10} className="absolute bottom-1 right-1 opacity-20" />}
                              </div>
                          );
                      })}
                  </div>
                  <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl">
                      <div className="bg-white p-2 rounded-full text-rose-500 shadow-sm"><Coffee size={16} /></div>
                      <p className="text-xs text-slate-500 font-medium">休息是为了更好的创作，目前已选 <span className="text-rose-600 font-bold">{sessionBlockedDates.length}</span> 天休息。</p>
                  </div>
              </div>

              <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
                   <div className="max-w-lg mx-auto pointer-events-auto">
                       <button 
                         onClick={() => {
                            setPlanningStep('time-entry');
                            setActiveTimeIndex(stages.length - 1);
                            setCurrentInputTime('');
                         }}
                         className="w-full bg-slate-900 text-white py-4 rounded-2xl shadow-xl shadow-slate-300 font-bold text-lg flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all"
                       >
                           <Check size={20} />
                           进入工期分配
                       </button>
                   </div>
               </div>
          </div>
      );
  }

  // --- RENDER: INTERMEDIATE STEP (PRE-COMPARISON) ---
  if (planningStep === 'pre-comparison-confirm') {
      const timeBoxConfig = [
          { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange' },
          { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky' },
          { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo' }
      ];
      const selectedConfigs = timeBoxConfig.filter(c => selectedTimeBoxes.includes(c.id));
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20">
              <div className="text-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 mb-2">规划确认</h2>
                  <p className="text-slate-500 text-sm">今日专注目标</p>
              </div>
              <div className="w-full space-y-4 mb-8">
                  {selectedConfigs.map(item => (
                      <div key={item.id} className={`flex items-center gap-4 p-4 rounded-2xl border ${item.id === 'morning' ? 'bg-orange-50 border-orange-100 text-orange-600' : item.id === 'afternoon' ? 'bg-sky-50 border-sky-100 text-sky-600' : 'bg-indigo-50 border-indigo-100 text-indigo-600'} shadow-sm animate-slide-up`}>
                           <div className="p-2 rounded-full bg-white/80"><item.icon size={24} /></div>
                           <span className="text-lg font-bold">{item.label}</span>
                           <CheckCircle size={20} className="ml-auto" />
                      </div>
                  ))}
              </div>
              <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 mb-8 max-w-sm">
                  <div className="flex gap-3">
                      <div className="mt-1 text-fuchsia-500"><Sparkles size={20} /></div>
                      <div>
                          <p className="text-sm font-bold text-slate-700 mb-1">即将进入 Done List</p>
                          <p className="text-xs text-slate-500 leading-relaxed">确认后，您将进入执行记录模式。</p>
                      </div>
                  </div>
              </div>
              <div className="w-full space-y-3">
                  <button onClick={startComparison} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2">
                      <PlayCircle size={20} /> 开启 Done List
                  </button>
                  <button onClick={() => setPlanningStep('time-boxing')} className="text-slate-400 text-sm font-bold py-2">返回调整</button>
              </div>
          </div>
      );
  }

  // --- RENDER: TIME BOXING (Planning) ---
  if (planningStep === 'time-boxing') {
      const currentDay = currentComparisonDay;
      const currentStage = getCurrentStageForDay(currentDay) || stages[stages.length - 1];
      let daysBefore = 0;
      for (const s of stages) {
          if (s.id === currentStage.id) break;
          daysBefore += Number(estimates[s.id] || 0);
      }
      const dayInStage = currentDay - daysBefore;
      const stageDuration = Number(estimates[currentStage.id] || 0);
      const progressPercent = stageDuration > 0 ? (dayInStage / stageDuration) * 100 : 0;
      const displayDateObj = new Date(getTargetDateStr(currentDay));
      const displayDate = formatDate(displayDateObj.toISOString());

      return (
        <div className="animate-fade-in h-screen flex flex-col overflow-hidden bg-slate-50">
             <div className="px-6 py-4 flex justify-between items-center shrink-0">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回列表
                </button>
                <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-md">Day {dayInStage} / {stageDuration}</span>
             </div>
             <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-40">
                 <div className="bg-white rounded-3xl p-6 shadow-xl shadow-fuchsia-100 border border-fuchsia-100 mb-8 relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="flex items-baseline justify-between mb-1">
                            <span className="text-3xl font-black text-slate-800 tracking-tight">{displayDate.split(' ')[0]}</span>
                            <span className="text-xs font-bold text-fuchsia-500 uppercase tracking-wider">当前阶段</span>
                        </div>
                        <h2 className="text-xl font-bold text-fuchsia-900 mb-2">{currentStage.title}</h2>
                        <div className="bg-slate-100 h-1.5 rounded-full w-full overflow-hidden flex">
                            <div style={{ width: `${progressPercent}%` }} className="bg-fuchsia-500 h-full"></div>
                        </div>
                    </div>
                 </div>
                 <div className="text-center mb-8">
                     <p className="text-sm font-medium text-slate-600 mb-1">选择今天的绘画时段</p>
                 </div>
                 <div className="relative pl-4 space-y-4">
                     <div className="absolute left-[27px] top-4 bottom-4 w-0.5 bg-gradient-to-b from-slate-200 via-fuchsia-200 to-slate-200"></div>
                     {[
                         { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange', ratio: 'h-24' },
                         { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky', ratio: 'h-48' },
                         { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo', ratio: 'h-36' }
                     ].map((item) => {
                         const isSelected = selectedTimeBoxes.includes(item.id);
                         return (
                             <div key={item.id} onClick={() => toggleTimeBox(item.id)} className="relative flex items-stretch gap-3 group cursor-pointer transition-all hover:scale-102">
                                 <div className={`relative z-10 flex flex-col items-center justify-center ${item.id === 'morning' ? 'pt-9' : item.id === 'afternoon' ? 'pt-20' : 'pt-14'}`}>
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center bg-white transition-colors ${isSelected ? 'border-fuchsia-500 text-fuchsia-500' : 'border-slate-300 text-slate-300'}`}>
                                         <div className={`w-2 h-2 rounded-full ${isSelected ? 'bg-fuchsia-500' : 'bg-transparent'}`}></div>
                                    </div>
                                 </div>
                                 <div className={`flex-1 ${item.ratio} p-4 rounded-2xl border transition-all flex items-center ${isSelected ? (item.id === 'morning' ? 'bg-orange-50 border-orange-100' : item.id === 'afternoon' ? 'bg-sky-50 border-sky-100' : 'bg-indigo-50 border-indigo-100') + ' shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                                     <div className="flex items-center justify-between w-full">
                                         <div className="flex items-center gap-2">
                                             <div className={`p-1.5 rounded-full ${isSelected ? (item.id === 'morning' ? 'bg-orange-100 text-orange-500' : item.id === 'afternoon' ? 'bg-sky-100 text-sky-500' : 'bg-indigo-100 text-indigo-500') : 'bg-slate-50'}`}><item.icon size={16} /></div>
                                             <span className="text-lg font-bold">{item.label.split(' ')[0]}</span>
                                         </div>
                                         {isSelected && <Check size={16} />}
                                     </div>
                                 </div>
                             </div>
                         );
                     })}
                 </div>
             </div>
             <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-10 pb-12 px-6 z-30 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button onClick={proceedToPreConfirmation} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 mb-safe">
                        确认今日规划 <ChevronRight size={20} />
                    </button>
                </div>
             </div>
        </div>
      );
  }

  // --- RENDER: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const currentDay = currentComparisonDay;
      const currentStageForDay = getCurrentStageForDay(currentDay);
      const isCompleted = isDayCompleted(currentDay);
      const isMorning = (h: number) => h >= 9 && h <= 12;
      const isAfternoon = (h: number) => h >= 13 && h <= 17;
      const isEvening = (h: number) => h >= 18 && h <= 27;
      const displayingDateObj = new Date(getTargetDateStr(currentDay));
      const displayingDateStr = formatDate(displayingDateObj.toISOString()).split(' ')[0];
      const getPlanColor = (h: number) => {
          if (isMorning(h) && selectedTimeBoxes.includes('morning')) return 'bg-orange-50';
          if (isAfternoon(h) && selectedTimeBoxes.includes('afternoon')) return 'bg-sky-50';
          if (isEvening(h) && selectedTimeBoxes.includes('evening')) return 'bg-indigo-50';
          return 'bg-white';
      };
      const displayHours = isCompleted ? (bookings.find(b => b.date === getTargetDateStr(currentDay))?.actualHours || []) : selectedActualHours;

      return (
          <div className="animate-fade-in h-screen flex flex-col bg-white">
               <div className="px-6 py-4 flex justify-between items-start bg-white border-b border-slate-50 shrink-0 z-20">
                   <div>
                       <div className="flex items-center gap-2"><PenTool size={20} className="text-slate-800" /><h2 className="text-xl font-serif font-bold text-slate-800 tracking-tight">Done List</h2></div>
                       <p className="text-[10px] text-slate-400 mt-1 ml-7">{isCompleted ? '历史记录 (已存档)' : '点击时间轴，记录实际专注时段'}</p>
                   </div>
                   <div className="flex flex-col items-end gap-1">
                       <span className={`text-xs font-mono font-medium px-3 py-1.5 rounded-full border ${isCompleted ? 'bg-slate-100 text-slate-500 border-slate-200' : 'text-emerald-600 bg-emerald-50 border-emerald-100'}`}>{displayHours.length * 0.5}h</span>
                       {currentStageForDay && <span className="text-[10px] font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-0.5 rounded-md border border-fuchsia-100/50">{currentStageForDay.title}</span>}
                   </div>
               </div>
               <div className="px-6 py-2 bg-slate-50/50 border-b border-slate-100 flex items-center justify-between z-20">
                  <button onClick={() => { const prev = Math.max(1, currentDay - 1); setCurrentComparisonDay(prev); setSelectedActualHours([]); }} className="p-1 rounded-full hover:bg-white text-slate-400 hover:text-slate-600"><ArrowLeft size={16} /></button>
                  <div className="flex flex-col items-center"><span className="text-sm font-bold text-slate-800">Day {currentDay}</span><span className="text-[10px] text-slate-400 font-medium">{displayingDateStr}</span></div>
                  <button onClick={() => { setCurrentComparisonDay(currentDay + 1); setSelectedActualHours([]); }} className="p-1 rounded-full hover:bg-white text-slate-400 hover:text-slate-600"><ChevronRight size={16} /></button>
               </div>
               <div className="flex-1 overflow-y-auto custom-scrollbar pb-32 pt-4 px-6 relative">
                   <div className="max-w-lg mx-auto w-full relative">
                       {timeSlots.map((slot) => {
                           const bgClass = getPlanColor(slot.value);
                           const isLeftDone = displayHours.includes(`${slot.id}-00`);
                           const isRightDone = displayHours.includes(`${slot.id}-30`);
                           return (
                               <div key={slot.id} className="flex items-center h-16 mb-2">
                                   <div className="w-14 flex-shrink-0 text-right pr-3 pt-0"><span className="text-xs font-mono text-slate-400">{slot.label}</span></div>
                                   <div className={`flex-1 h-full rounded-2xl border border-slate-100 flex overflow-hidden ${bgClass} transition-colors ${isCompleted ? 'opacity-75 pointer-events-none grayscale-[0.3]' : ''}`}>
                                        <div onClick={() => toggleActualHour(`${slot.id}-00`)} className={`flex-1 h-full border-r border-dashed border-slate-300/60 cursor-pointer ${isLeftDone ? 'bg-[#a7d7c5]' : 'hover:bg-black/5'}`}></div>
                                        <div onClick={() => toggleActualHour(`${slot.id}-30`)} className={`flex-1 h-full cursor-pointer ${isRightDone ? 'bg-[#a7d7c5]' : 'hover:bg-black/5'}`}></div>
                                   </div>
                               </div>
                           );
                       })}
                       {!isCompleted && <button onClick={finishAll} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg mt-8 shadow-xl shadow-slate-200">完成记录</button>}
                   </div>
               </div>
          </div>
      );
  }

  // --- RENDER: SUMMARY & FEEDBACK ---
  if (planningStep === 'summary') {
      const getFeedback = () => {
          let hasPlanned = false, hasUnplanned = false;
          const ranges = { morning: [9,10,11,12], afternoon: [13,14,15,16,17], evening: Array.from({length:10},(_,i)=>i+18) };
          selectedActualHours.forEach(id => {
              const h = parseInt(id.split('-')[1].replace('h', ''));
              let box = '';
              if (ranges.morning.includes(h)) box = 'morning';
              else if (ranges.afternoon.includes(h)) box = 'afternoon';
              else if (ranges.evening.includes(h)) box = 'evening';
              if (box && selectedTimeBoxes.includes(box)) hasPlanned = true; else hasUnplanned = true;
          });
          if (hasPlanned && hasUnplanned) return { msg: "Way Ahead!", emoji: "❤️", title: "超额完成！" };
          return { msg: "Well Done!", emoji: "👍", title: "计划达成！" };
      };
      const feedback = getFeedback();
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20 text-center">
              <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center text-4xl mb-6">{feedback.emoji}</div>
              <h2 className="text-2xl font-black text-slate-800 mb-3">{feedback.title}</h2>
              <p className="text-slate-500 mb-10">{feedback.msg}</p>
              <button onClick={handleContinueToNextDay} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold">进入下一天</button>
              <button onClick={() => setMode('dashboard')} className="mt-4 text-sm font-bold text-slate-400">返回列表</button>
          </div>
      );
  }

  // --- RENDER: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6"><Check size={40} strokeWidth={3} /></div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">规划已生成</h2>
              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left">
                  {stages.map((stage) => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                          <span className="font-medium text-slate-700">{stage.title}</span><span className="font-bold text-indigo-600">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between font-bold text-lg"><span>总计规划</span><span className={`${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} 天</span></div>
              </div>
              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2"><Box size={20} />时间盒子的规划法</button>
          </div>
      );
  }

  // --- RENDER: SETUP WIZARD ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} className="mr-1" /> 返回</button>
       </div>
       <div className="mb-6 bg-gradient-to-br from-fuchsia-50 to-rose-50 rounded-3xl border border-fuchsia-100 p-6">
            <h2 className="text-2xl font-bold text-fuchsia-900 flex items-center gap-2"><Sparkles size={20} className="text-fuchsia-500" />{syncedProject ? `规划: ${syncedProject.clientName}` : '灵感流 (P人模式)'}</h2>
            {!syncedProject && <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-1 bg-white/50 px-3 py-2 rounded-xl text-xs font-bold text-fuchsia-700 shadow-sm"><Link size={14} /> 关联排单</button>}
            {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="排单 ID" className="flex-1 text-sm bg-white border border-fuchsia-200 rounded-xl px-3 py-2 outline-none" /><button onClick={handleSyncProject} className="bg-fuchsia-600 text-white px-3 py-2 rounded-xl text-sm font-bold">同步</button></div>}
       </div>
       <div className="space-y-4">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-20 border-2 border-dashed border-slate-300 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all"><Plus size={24} /><span className="text-xs font-bold uppercase ml-2">添加新阶段</span></div>
          ) : (
            <div className="w-full h-20 border-2 border-fuchsia-300 rounded-2xl flex items-center justify-between px-4 bg-white shadow-sm animate-fade-in"><input autoFocus type="text" placeholder="阶段名称..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-lg font-medium outline-none" /><div className="flex gap-2"><button onClick={() => setIsAdding(false)} className="p-2 text-slate-400"><X size={20} /></button><button onClick={handleConfirmAdd} className="p-2 bg-fuchsia-500 text-white rounded-full"><Check size={20} /></button></div></div>
          )}
          {stages.map((stage, index) => {
            const isActive = index === activeTimeIndex;
            const isEntry = planningStep === 'time-entry';
            return (
                <div key={stage.id} className="relative flex items-center">
                    <div draggable={!isEntry} onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} onClick={() => isEntry && setActiveTimeIndex(index)} className={`relative border rounded-2xl flex items-center transition-all ${isEntry ? (isActive ? 'w-[45%] h-16 border-fuchsia-500 bg-white shadow-lg scale-105 z-10' : 'w-[45%] h-16 border-slate-100 bg-slate-50 opacity-40 grayscale cursor-pointer') : 'w-full h-24 px-6 border-slate-200 bg-white/50 cursor-grab'}`}>
                        {!isEntry && <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>}
                        <div className="flex flex-col truncate"><span className={`font-medium truncate ${isEntry ? 'text-sm' : 'text-lg text-slate-700'}`}>{stage.title}</span>{isEntry && estimates[stage.id] && <span className="text-[10px] text-fuchsia-600 font-bold flex items-center gap-1"><Clock size={10} /> {estimates[stage.id]} 天</span>}</div>
                        {!isEntry && <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-4 text-slate-200 hover:text-rose-400"><X size={16} /></button>}
                    </div>
                    {isEntry && isActive && (
                        <div className="flex-1 ml-4 animate-slide-up">
                            <label className="block text-[10px] font-bold text-fuchsia-500 uppercase mb-1">预期耗时 (天)</label>
                            <div className="flex gap-2"><input autoFocus type="text" value={currentInputTime} onChange={handleTimeInput} onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} className="w-20 bg-white border-2 border-fuchsia-200 rounded-xl px-3 py-2 text-lg font-bold outline-none focus:border-fuchsia-500 shadow-sm" /><button onClick={confirmTimeEntry} disabled={!currentInputTime} className="bg-slate-900 text-white px-4 rounded-xl disabled:opacity-50"><ArrowUp size={20} /></button></div>
                        </div>
                    )}
                </div>
            );
          })}
       </div>
       {planningStep === 'setup' && (
           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button onClick={startConfiguration} className="w-full bg-slate-900 text-white py-4 rounded-2xl shadow-xl font-bold text-lg flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all"><Check size={20} />已完成阶段配置</button>
               </div>
           </div>
       )}
    </div>
  );
};

export default PTypePlanner;

import { GoogleGenAI } from "@google/genai";
import { Project, BookingSlot } from '../types';

/**
 * AI analysis service for schedule management.
 * Follows @google/genai guidelines for initialization and model selection.
 */
export const analyzeSchedule = async (
  projects: Project[],
  bookings: BookingSlot[],
  query: string
): Promise<string> => {
  // Initializing AI client with API key from environment variable.
  // Using direct process.env.API_KEY as per coding guidelines.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Filter relevant data to reduce token usage
  const activeProjects = projects.filter(p => p.status !== 'completed');
  const context = JSON.stringify({
    current_time: new Date().toISOString(),
    active_projects: activeProjects.map(p => ({
      client: p.clientName,
      deadline: p.deadline,
      desc: p.description
    })),
    blocked_dates: bookings.filter(b => b.status === 'blocked' || b.status === 'booked').map(b => b.date)
  });

  const prompt = `
    你是一个专业的画手私人助理。请根据以下目前的排单和日程情况回答用户的问题。
    保持回答简短、专业且不仅限于单纯的数据复述，要给出建议。

    数据上下文:
    ${context}

    用户问题:
    ${query}
  `;

  try {
    // Using recommended 'gemini-3-flash-preview' model for text tasks.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    // response.text is a property, not a method.
    return response.text || "无法生成回答。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "AI 服务暂时不可用，请稍后再试。";
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  // Session start date for non-synced projects
  const [sessionStartDate] = useState(new Date());

  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');

  // Sync State
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);

  // 'setup' = stages, 'off-days' = rest calendar, 'time-entry' = duration, 'finished' = summary, 'time-boxing' = daily planning...
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  // Index of the stage currently being edited (starts from bottom)
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Time Boxing State
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);

  // Actual Execution State
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  // Local state for non-synced completed days tracking
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization: Load Sessions ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  // Save Sessions to LocalStorage
  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers for Planning Logic ---

  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // Check if a date is blocked globally OR specifically in this session
  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings.some(b => b.date === dateStr && b.status === 'blocked');
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  // Calculate available days between start and end (inclusive), skipping blocked dates
  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 365 * 2) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  // Get the date string for the Nth available working day (1-based index)
  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      current.setHours(0,0,0,0);

      let validDaysFound = 0;
      let safetyCounter = 0;

      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }

          if (validDaysFound === dayIndex) {
              return dateStr;
          }

          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }
      return getYYYYMMDD(current);
  };

  const isDayCompleted = (dayIndex: number) => {
      const dateStr = getTargetDateStr(dayIndex);
      const hasBooking = bookings.some(b => b.date === dateStr && b.actualHours && b.actualHours.length > 0);
      return hasBooking || localCompletedDays.includes(dayIndex);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 0;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const isOverBudget = syncedProject ? currentPlannedDays > totalAvailableDays : false;

  const generateTimeSlots = () => {
      const slots = [];
      for (let i = 9; i <= 27; i++) {
          const hour = i % 24;
          const label = `${hour.toString().padStart(2, '0')}:00`;
          const isNextDay = i >= 24;
          slots.push({ id: `h-${i}`, value: i, label, isNextDay, fullLabel: isNextDay ? `次日 ${label}` : label });
      }
      return slots;
  };
  const timeSlots = generateTimeSlots();

  // --- Actions ---

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);

      if (session.projectId) {
          const project = projects.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else {
          setSyncedProject(null);
      }

      const totalPlanned = Object.values(session.estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
      let nextDay = 1;
      const completedSet = new Set(session.completedDays || []);
      for(let i=1; i<=Math.ceil(totalPlanned) + 30; i++) {
          if(!completedSet.has(i)) {
              nextDay = i;
              break;
          }
      }
      setCurrentComparisonDay(nextDay);
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const copyListItems = [...stages];
    const dragItemContent = copyListItems[dragItem.current];
    copyListItems.splice(dragItem.current, 1);
    copyListItems.splice(dragOverItem.current, 0, dragItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setStages(copyListItems);
  };

  const handleConfirmAdd = () => {
    if (newStageTitle.trim()) {
        const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
        setStages([newStage, ...stages]);
        setNewStageTitle('');
        setIsAdding(false);
    }
  };

  const deleteStage = (index: number) => {
      if(confirm('确定删除此阶段吗?')) {
          const newStages = [...stages];
          newStages.splice(index, 1);
          setStages(newStages);
      }
  };

  const handleSyncProject = () => {
      if(!syncId.trim()) return;
      const found = projects.find(p => p.id === syncId.trim());
      if(found) {
          setSyncedProject(found);
          setShowSyncInput(false);
          setSyncId('');
      } else {
          alert('未找到该 ID 对应的排单。');
      }
  };

  const startConfiguration = () => {
      setPlanningStep('off-days');
  };

  const toggleSessionBlockedDate = (dateStr: string) => {
      if (sessionBlockedDates.includes(dateStr)) {
          setSessionBlockedDates(sessionBlockedDates.filter(d => d !== dateStr));
      } else {
          setSessionBlockedDates([...sessionBlockedDates, dateStr]);
      }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });
      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime('');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      const updatedSessions = [newSession, ...sessions];
      persistSessions(updatedSessions);
      setCurrentSessionId(newSession.id);

      let startDay = 1;
      const maxCheck = currentPlannedDays > 0 ? Math.ceil(currentPlannedDays) + 30 : 60;
      for (let i = 1; i <= maxCheck; i++) {
          if (!isDayCompleted(i)) {
              startDay = i;
              break;
          }
      }
      setCurrentComparisonDay(startDay); 
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const toggleTimeBox = (box: string) => {
      if (selectedTimeBoxes.includes(box)) setSelectedTimeBoxes(selectedTimeBoxes.filter(b => b !== box));
      else setSelectedTimeBoxes([...selectedTimeBoxes, box]);
  };

  const toggleActualHour = (uniqueId: string) => {
      if (isDayCompleted(currentComparisonDay)) return;
      if (selectedActualHours.includes(uniqueId)) setSelectedActualHours(selectedActualHours.filter(h => h !== uniqueId));
      else setSelectedActualHours([...selectedActualHours, uniqueId]);
  };

  const proceedToPreConfirmation = () => {
      if (selectedTimeBoxes.length === 0) {
          alert("请至少选择一个时间段作为今日规划");
          return;
      }
      setPlanningStep('pre-comparison-confirm');
  };

  // Fix: Missing startComparison function that transitions to the daily comparison step.
  const startComparison = () => {
      setPlanningStep('daily-comparison');
  };

  const finishAll = () => {
      const dateStr = getTargetDateStr(currentComparisonDay);
      if (onUpdateBookings) {
          const newBookings = [...bookings];
          const existingIndex = newBookings.findIndex(b => b.date === dateStr);
          if (existingIndex >= 0) newBookings[existingIndex] = { ...newBookings[existingIndex], actualHours: selectedActualHours };
          else newBookings.push({ date: dateStr, status: 'booked', actualHours: selectedActualHours });
          onUpdateBookings(newBookings);
      }
      const newCompletedDays = [...localCompletedDays];
      if (!newCompletedDays.includes(currentComparisonDay)) newCompletedDays.push(currentComparisonDay);
      setLocalCompletedDays(newCompletedDays);
      if (currentSessionId) {
          const updatedSessions = sessions.map(s => 
              s.id === currentSessionId ? { ...s, completedDays: newCompletedDays, lastUpdated: new Date().toISOString() } : s
          );
          persistSessions(updatedSessions);
      }
      setPlanningStep('summary');
  };

  const handleContinueToNextDay = () => {
      const nextDay = currentComparisonDay + 1;
      setCurrentComparisonDay(nextDay);
      setSelectedActualHours([]);
      setSelectedTimeBoxes([]);
      setPlanningStep('time-boxing');
  };

  const getCurrentStageForDay = (day: number) => {
      let cumulativeDays = 0;
      for (const stage of stages) {
          const duration = Number(estimates[stage.id] || 0);
          cumulativeDays += duration;
          if (day <= cumulativeDays) return stage;
      }
      return stages.length > 0 ? stages[stages.length - 1] : null;
  };

  // --- RENDER: DASHBOARD VIEW ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>

             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>

             {sessions.length > 0 && (
                 <div className="space-y-4">
                     <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider ml-1">进行中 ({sessions.length})</h3>
                     {sessions.sort((a,b) => new Date(b.lastUpdated).getTime() - new Date(a.lastUpdated).getTime()).map(session => {
                        const totalDays = Object.values(session.estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
                        const completedCount = session.completedDays.length;
                        const progress = totalDays > 0 ? (completedCount / totalDays) * 100 : 0;
                        return (
                            <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative overflow-hidden">
                                <div className="flex justify-between items-start mb-3">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                                    </div>
                                    <div className="bg-fuchsia-50 text-fuchsia-600 p-2 rounded-xl"><LayoutGrid size={20} /></div>
                                </div>
                                <div className="flex items-center gap-2 mb-2">
                                    <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
                                        <div style={{width: `${progress}%`}} className="h-full bg-gradient-to-r from-fuchsia-500 to-indigo-500 rounded-full"></div>
                                    </div>
                                    <span className="text-xs font-bold text-slate-600 whitespace-nowrap">{completedCount} / {totalDays} 天</span>
                                </div>
                                <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 transition-colors opacity-0 group-hover:opacity-100 p-2">
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        );
                     })}
                 </div>
             )}

             {sessions.length === 0 && (
                 <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                     <Sparkles size={24} className="text-slate-300 mx-auto mb-2" />
                     <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                 </div>
             )}
        </div>
    );
  }

  // --- RENDER: OFF-DAYS SELECTION ---
  if (planningStep === 'off-days') {
      const today = new Date();
      today.setHours(0,0,0,0);
      const calendarDays = [];
      const daysCount = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) + 30 : 35;

      const calendarStart = getStartDate();
      for (let i = 0; i < 42; i++) { // Show a 6-week grid
          const d = new Date(calendarStart);
          d.setDate(calendarStart.getDate() + i);
          calendarDays.push(getYYYYMMDD(d));
      }

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回设置
                </button>
              </div>

              <div className="mb-8">
                  <h2 className="text-2xl font-black text-slate-800">设置休息日</h2>
                  <p className="text-slate-400 text-sm mt-1">点击日期标记“X”，规划时将自动跳过这些日子。</p>
              </div>

              <div className="bg-white rounded-3xl p-5 shadow-xl shadow-slate-100 border border-slate-100">
                  <div className="grid grid-cols-7 gap-2 mb-4">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => (
                          <div key={d} className="text-center text-[10px] font-bold text-slate-300 uppercase">{d}</div>
                      ))}
                      {calendarDays.map(dateStr => {
                          const dateObj = new Date(dateStr + 'T00:00:00');
                          const isBlocked = sessionBlockedDates.includes(dateStr);
                          const isGlobalBlocked = bookings.some(b => b.date === dateStr && b.status === 'blocked');

                          return (
                              <div 
                                key={dateStr}
                                onClick={() => !isGlobalBlocked && toggleSessionBlockedDate(dateStr)}
                                className={`aspect-square rounded-xl border flex items-center justify-center relative transition-all active:scale-95 cursor-pointer
                                    ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}
                                    ${isGlobalBlocked ? 'bg-slate-100 text-slate-200 cursor-not-allowed opacity-50' : ''}
                                `}
                              >
                                  <span className="text-xs font-bold">{dateObj.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                                  {isGlobalBlocked && <Lock size={10} className="absolute bottom-1 right-1 opacity-20" />}
                              </div>
                          );
                      })}
                  </div>
                  <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl">
                      <div className="bg-white p-2 rounded-full text-rose-500 shadow-sm"><Coffee size={16} /></div>
                      <p className="text-xs text-slate-500 font-medium">休息是为了更好的创作，目前已选 <span className="text-rose-600 font-bold">{sessionBlockedDates.length}</span> 天休息。</p>
                  </div>
              </div>

              <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
                   <div className="max-w-lg mx-auto pointer-events-auto">
                       <button 
                         onClick={() => {
                            setPlanningStep('time-entry');
                            setActiveTimeIndex(stages.length - 1);
                            setCurrentInputTime('');
                         }}
                         className="w-full bg-slate-900 text-white py-4 rounded-2xl shadow-xl shadow-slate-300 font-bold text-lg flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all"
                       >
                           <Check size={20} />
                           进入工期分配
                       </button>
                   </div>
               </div>
          </div>
      );
  }

  // --- RENDER: INTERMEDIATE STEP (PRE-COMPARISON) ---
  if (planningStep === 'pre-comparison-confirm') {
      const timeBoxConfig = [
          { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange' },
          { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky' },
          { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo' }
      ];
      const selectedConfigs = timeBoxConfig.filter(c => selectedTimeBoxes.includes(c.id));
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20">
              <div className="text-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 mb-2">规划确认</h2>
                  <p className="text-slate-500 text-sm">今日专注目标</p>
              </div>
              <div className="w-full space-y-4 mb-8">
                  {selectedConfigs.map(item => (
                      <div key={item.id} className={`flex items-center gap-4 p-4 rounded-2xl border ${item.id === 'morning' ? 'bg-orange-50 border-orange-100 text-orange-600' : item.id === 'afternoon' ? 'bg-sky-50 border-sky-100 text-sky-600' : 'bg-indigo-50 border-indigo-100 text-indigo-600'} shadow-sm animate-slide-up`}>
                           <div className="p-2 rounded-full bg-white/80"><item.icon size={24} /></div>
                           <span className="text-lg font-bold">{item.label}</span>
                           <CheckCircle size={20} className="ml-auto" />
                      </div>
                  ))}
              </div>
              <div className="bg-slate-50 p-5 rounded-2xl border border-slate-100 mb-8 max-w-sm">
                  <div className="flex gap-3">
                      <div className="mt-1 text-fuchsia-500"><Sparkles size={20} /></div>
                      <div>
                          <p className="text-sm font-bold text-slate-700 mb-1">即将进入 Done List</p>
                          <p className="text-xs text-slate-500 leading-relaxed">确认后，您将进入执行记录模式。</p>
                      </div>
                  </div>
              </div>
              <div className="w-full space-y-3">
                  <button onClick={startComparison} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2">
                      <PlayCircle size={20} /> 开启 Done List
                  </button>
                  <button onClick={() => setPlanningStep('time-boxing')} className="text-slate-400 text-sm font-bold py-2">返回调整</button>
              </div>
          </div>
      );
  }

  // --- RENDER: TIME BOXING (Planning) ---
  if (planningStep === 'time-boxing') {
      const currentDay = currentComparisonDay;
      const currentStage = getCurrentStageForDay(currentDay) || stages[stages.length - 1];
      let daysBefore = 0;
      for (const s of stages) {
          if (s.id === currentStage.id) break;
          daysBefore += Number(estimates[s.id] || 0);
      }
      const dayInStage = currentDay - daysBefore;
      const stageDuration = Number(estimates[currentStage.id] || 0);
      const progressPercent = stageDuration > 0 ? (dayInStage / stageDuration) * 100 : 0;
      const displayDateObj = new Date(getTargetDateStr(currentDay));
      const displayDate = formatDate(displayDateObj.toISOString());

      return (
        <div className="animate-fade-in h-screen flex flex-col overflow-hidden bg-slate-50">
             <div className="px-6 py-4 flex justify-between items-center shrink-0">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回列表
                </button>
                <span className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-md">Day {dayInStage} / {stageDuration}</span>
             </div>
             <div className="flex-1 overflow-y-auto custom-scrollbar px-6 pb-40">
                 <div className="bg-white rounded-3xl p-6 shadow-xl shadow-fuchsia-100 border border-fuchsia-100 mb-8 relative overflow-hidden">
                    <div className="relative z-10">
                        <div className="flex items-baseline justify-between mb-1">
                            <span className="text-3xl font-black text-slate-800 tracking-tight">{displayDate.split(' ')[0]}</span>
                            <span className="text-xs font-bold text-fuchsia-500 uppercase tracking-wider">当前阶段</span>
                        </div>
                        <h2 className="text-xl font-bold text-fuchsia-900 mb-2">{currentStage.title}</h2>
                        <div className="bg-slate-100 h-1.5 rounded-full w-full overflow-hidden flex">
                            <div style={{ width: `${progressPercent}%` }} className="bg-fuchsia-500 h-full"></div>
                        </div>
                    </div>
                 </div>
                 <div className="text-center mb-8">
                     <p className="text-sm font-medium text-slate-600 mb-1">选择今天的绘画时段</p>
                 </div>
                 <div className="relative pl-4 space-y-4">
                     <div className="absolute left-[27px] top-4 bottom-4 w-0.5 bg-gradient-to-b from-slate-200 via-fuchsia-200 to-slate-200"></div>
                     {[
                         { id: 'morning', label: '早 Morning', icon: Sunrise, color: 'orange', ratio: 'h-24' },
                         { id: 'afternoon', label: '中 Afternoon', icon: Sun, color: 'sky', ratio: 'h-48' },
                         { id: 'evening', label: '晚 Evening', icon: Moon, color: 'indigo', ratio: 'h-36' }
                     ].map((item) => {
                         const isSelected = selectedTimeBoxes.includes(item.id);
                         return (
                             <div key={item.id} onClick={() => toggleTimeBox(item.id)} className="relative flex items-stretch gap-3 group cursor-pointer transition-all hover:scale-102">
                                 <div className={`relative z-10 flex flex-col items-center justify-center ${item.id === 'morning' ? 'pt-9' : item.id === 'afternoon' ? 'pt-20' : 'pt-14'}`}>
                                    <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center bg-white transition-colors ${isSelected ? 'border-fuchsia-500 text-fuchsia-500' : 'border-slate-300 text-slate-300'}`}>
                                         <div className={`w-2 h-2 rounded-full ${isSelected ? 'bg-fuchsia-500' : 'bg-transparent'}`}></div>
                                    </div>
                                 </div>
                                 <div className={`flex-1 ${item.ratio} p-4 rounded-2xl border transition-all flex items-center ${isSelected ? (item.id === 'morning' ? 'bg-orange-50 border-orange-100' : item.id === 'afternoon' ? 'bg-sky-50 border-sky-100' : 'bg-indigo-50 border-indigo-100') + ' shadow-md' : 'bg-white border-slate-100 text-slate-400'}`}>
                                     <div className="flex items-center justify-between w-full">
                                         <div className="flex items-center gap-2">
                                             <div className={`p-1.5 rounded-full ${isSelected ? (item.id === 'morning' ? 'bg-orange-100 text-orange-500' : item.id === 'afternoon' ? 'bg-sky-100 text-sky-500' : 'bg-indigo-100 text-indigo-500') : 'bg-slate-50'}`}><item.icon size={16} /></div>
                                             <span className="text-lg font-bold">{item.label.split(' ')[0]}</span>
                                         </div>
                                         {isSelected && <Check size={16} />}
                                     </div>
                                 </div>
                             </div>
                         );
                     })}
                 </div>
             </div>
             <div className="fixed bottom-0 left-0 w-full bg-gradient-to-t from-white via-white to-transparent pt-10 pb-12 px-6 z-30 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button onClick={proceedToPreConfirmation} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 mb-safe">
                        确认今日规划 <ChevronRight size={20} />
                    </button>
                </div>
             </div>
        </div>
      );
  }

  // --- RENDER: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const currentDay = currentComparisonDay;
      const currentStageForDay = getCurrentStageForDay(currentDay);
      const isCompleted = isDayCompleted(currentDay);
      const isMorning = (h: number) => h >= 9 && h <= 12;
      const isAfternoon = (h: number) => h >= 13 && h <= 17;
      const isEvening = (h: number) => h >= 18 && h <= 27;
      const displayingDateObj = new Date(getTargetDateStr(currentDay));
      const displayingDateStr = formatDate(displayingDateObj.toISOString()).split(' ')[0];
      const getPlanColor = (h: number) => {
          if (isMorning(h) && selectedTimeBoxes.includes('morning')) return 'bg-orange-50';
          if (isAfternoon(h) && selectedTimeBoxes.includes('afternoon')) return 'bg-sky-50';
          if (isEvening(h) && selectedTimeBoxes.includes('evening')) return 'bg-indigo-50';
          return 'bg-white';
      };
      const displayHours = isCompleted ? (bookings.find(b => b.date === getTargetDateStr(currentDay))?.actualHours || []) : selectedActualHours;

      return (
          <div className="animate-fade-in h-screen flex flex-col bg-white">
               <div className="px-6 py-4 flex justify-between items-start bg-white border-b border-slate-50 shrink-0 z-20">
                   <div>
                       <div className="flex items-center gap-2"><PenTool size={20} className="text-slate-800" /><h2 className="text-xl font-serif font-bold text-slate-800 tracking-tight">Done List</h2></div>
                       <p className="text-[10px] text-slate-400 mt-1 ml-7">{isCompleted ? '历史记录 (已存档)' : '点击时间轴，记录实际专注时段'}</p>
                   </div>
                   <div className="flex flex-col items-end gap-1">
                       <span className={`text-xs font-mono font-medium px-3 py-1.5 rounded-full border ${isCompleted ? 'bg-slate-100 text-slate-500 border-slate-200' : 'text-emerald-600 bg-emerald-50 border-emerald-100'}`}>{displayHours.length * 0.5}h</span>
                       {currentStageForDay && <span className="text-[10px] font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-0.5 rounded-md border border-fuchsia-100/50">{currentStageForDay.title}</span>}
                   </div>
               </div>
               <div className="px-6 py-2 bg-slate-50/50 border-b border-slate-100 flex items-center justify-between z-20">
                  <button onClick={() => { const prev = Math.max(1, currentDay - 1); setCurrentComparisonDay(prev); setSelectedActualHours([]); }} className="p-1 rounded-full hover:bg-white text-slate-400 hover:text-slate-600"><ArrowLeft size={16} /></button>
                  <div className="flex flex-col items-center"><span className="text-sm font-bold text-slate-800">Day {currentDay}</span><span className="text-[10px] text-slate-400 font-medium">{displayingDateStr}</span></div>
                  <button onClick={() => { setCurrentComparisonDay(currentDay + 1); setSelectedActualHours([]); }} className="p-1 rounded-full hover:bg-white text-slate-400 hover:text-slate-600"><ChevronRight size={16} /></button>
               </div>
               <div className="flex-1 overflow-y-auto custom-scrollbar pb-32 pt-4 px-6 relative">
                   <div className="max-w-lg mx-auto w-full relative">
                       {timeSlots.map((slot) => {
                           const bgClass = getPlanColor(slot.value);
                           const isLeftDone = displayHours.includes(`${slot.id}-00`);
                           const isRightDone = displayHours.includes(`${slot.id}-30`);
                           return (
                               <div key={slot.id} className="flex items-center h-16 mb-2">
                                   <div className="w-14 flex-shrink-0 text-right pr-3 pt-0"><span className="text-xs font-mono text-slate-400">{slot.label}</span></div>
                                   <div className={`flex-1 h-full rounded-2xl border border-slate-100 flex overflow-hidden ${bgClass} transition-colors ${isCompleted ? 'opacity-75 pointer-events-none grayscale-[0.3]' : ''}`}>
                                        <div onClick={() => toggleActualHour(`${slot.id}-00`)} className={`flex-1 h-full border-r border-dashed border-slate-300/60 cursor-pointer ${isLeftDone ? 'bg-[#a7d7c5]' : 'hover:bg-black/5'}`}></div>
                                        <div onClick={() => toggleActualHour(`${slot.id}-30`)} className={`flex-1 h-full cursor-pointer ${isRightDone ? 'bg-[#a7d7c5]' : 'hover:bg-black/5'}`}></div>
                                   </div>
                               </div>
                           );
                       })}
                       {!isCompleted && <button onClick={finishAll} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg mt-8 shadow-xl shadow-slate-200">完成记录</button>}
                   </div>
               </div>
          </div>
      );
  }

  // --- RENDER: SUMMARY & FEEDBACK ---
  if (planningStep === 'summary') {
      const getFeedback = () => {
          let hasPlanned = false, hasUnplanned = false;
          const ranges = { morning: [9,10,11,12], afternoon: [13,14,15,16,17], evening: Array.from({length:10},(_,i)=>i+18) };
          selectedActualHours.forEach(id => {
              const h = parseInt(id.split('-')[1].replace('h', ''));
              let box = '';
              if (ranges.morning.includes(h)) box = 'morning';
              else if (ranges.afternoon.includes(h)) box = 'afternoon';
              else if (ranges.evening.includes(h)) box = 'evening';
              if (box && selectedTimeBoxes.includes(box)) hasPlanned = true; else hasUnplanned = true;
          });
          if (hasPlanned && hasUnplanned) return { msg: "Way Ahead!", emoji: "❤️", title: "超额完成！" };
          return { msg: "Well Done!", emoji: "👍", title: "计划达成！" };
      };
      const feedback = getFeedback();
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 h-full pb-20 text-center">
              <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center text-4xl mb-6">{feedback.emoji}</div>
              <h2 className="text-2xl font-black text-slate-800 mb-3">{feedback.title}</h2>
              <p className="text-slate-500 mb-10">{feedback.msg}</p>
              <button onClick={handleContinueToNextDay} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold">进入下一天</button>
              <button onClick={() => setMode('dashboard')} className="mt-4 text-sm font-bold text-slate-400">返回列表</button>
          </div>
      );
  }

  // --- RENDER: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6"><Check size={40} strokeWidth={3} /></div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">规划已生成</h2>
              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left">
                  {stages.map((stage) => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                          <span className="font-medium text-slate-700">{stage.title}</span><span className="font-bold text-indigo-600">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between font-bold text-lg"><span>总计规划</span><span className={`${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} 天</span></div>
              </div>
              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2"><Box size={20} />时间盒子的规划法</button>
          </div>
      );
  }

  // --- RENDER: SETUP WIZARD ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} className="mr-1" /> 返回</button>
       </div>
       <div className="mb-6 bg-gradient-to-br from-fuchsia-50 to-rose-50 rounded-3xl border border-fuchsia-100 p-6">
            <h2 className="text-2xl font-bold text-fuchsia-900 flex items-center gap-2"><Sparkles size={20} className="text-fuchsia-500" />{syncedProject ? `规划: ${syncedProject.clientName}` : '灵感流 (P人模式)'}</h2>
            {!syncedProject && <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-1 bg-white/50 px-3 py-2 rounded-xl text-xs font-bold text-fuchsia-700 shadow-sm"><Link size={14} /> 关联排单</button>}
            {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="排单 ID" className="flex-1 text-sm bg-white border border-fuchsia-200 rounded-xl px-3 py-2 outline-none" /><button onClick={handleSyncProject} className="bg-fuchsia-600 text-white px-3 py-2 rounded-xl text-sm font-bold">同步</button></div>}
       </div>
       <div className="space-y-4">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-20 border-2 border-dashed border-slate-300 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all"><Plus size={24} /><span className="text-xs font-bold uppercase ml-2">添加新阶段</span></div>
          ) : (
            <div className="w-full h-20 border-2 border-fuchsia-300 rounded-2xl flex items-center justify-between px-4 bg-white shadow-sm animate-fade-in"><input autoFocus type="text" placeholder="阶段名称..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-lg font-medium outline-none" /><div className="flex gap-2"><button onClick={() => setIsAdding(false)} className="p-2 text-slate-400"><X size={20} /></button><button onClick={handleConfirmAdd} className="p-2 bg-fuchsia-500 text-white rounded-full"><Check size={20} /></button></div></div>
          )}
          {stages.map((stage, index) => {
            const isActive = index === activeTimeIndex;
            const isEntry = planningStep === 'time-entry';
            return (
                <div key={stage.id} className="relative flex items-center">
                    <div draggable={!isEntry} onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} onClick={() => isEntry && setActiveTimeIndex(index)} className={`relative border rounded-2xl flex items-center transition-all ${isEntry ? (isActive ? 'w-[45%] h-16 border-fuchsia-500 bg-white shadow-lg scale-105 z-10' : 'w-[45%] h-16 border-slate-100 bg-slate-50 opacity-40 grayscale cursor-pointer') : 'w-full h-24 px-6 border-slate-200 bg-white/50 cursor-grab'}`}>
                        {!isEntry && <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>}
                        <div className="flex flex-col truncate"><span className={`font-medium truncate ${isEntry ? 'text-sm' : 'text-lg text-slate-700'}`}>{stage.title}</span>{isEntry && estimates[stage.id] && <span className="text-[10px] text-fuchsia-600 font-bold flex items-center gap-1"><Clock size={10} /> {estimates[stage.id]} 天</span>}</div>
                        {!isEntry && <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-4 text-slate-200 hover:text-rose-400"><X size={16} /></button>}
                    </div>
                    {isEntry && isActive && (
                        <div className="flex-1 ml-4 animate-slide-up">
                            <label className="block text-[10px] font-bold text-fuchsia-500 uppercase mb-1">预期耗时 (天)</label>
                            <div className="flex gap-2"><input autoFocus type="text" value={currentInputTime} onChange={handleTimeInput} onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} className="w-20 bg-white border-2 border-fuchsia-200 rounded-xl px-3 py-2 text-lg font-bold outline-none focus:border-fuchsia-500 shadow-sm" /><button onClick={confirmTimeEntry} disabled={!currentInputTime} className="bg-slate-900 text-white px-4 rounded-xl disabled:opacity-50"><ArrowUp size={20} /></button></div>
                        </div>
                    )}
                </div>
            );
          })}
       </div>
       {planningStep === 'setup' && (
           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button onClick={startConfiguration} className="w-full bg-slate-900 text-white py-4 rounded-2xl shadow-xl font-bold text-lg flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-95 transition-all"><Check size={20} />已完成阶段配置</button>
               </div>
           </div>
       )}
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && b.status === 'blocked');
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 730) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      current.setHours(0,0,0,0);
      let validDaysFound = 0;
      let safetyCounter = 0;
      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }
          if (validDaysFound === dayIndex) return dateStr;
          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }
      return getYYYYMMDD(current);
  };

  const isDayCompleted = (dayIndex: number) => {
      const dateStr = getTargetDateStr(dayIndex);
      const hasBooking = bookings?.some(b => b.date === dateStr && b.actualHours && b.actualHours.length > 0);
      return hasBooking || localCompletedDays.includes(dayIndex);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  const generateTimeSlots = () => {
      const slots = [];
      for (let i = 9; i <= 27; i++) {
          const hour = i % 24;
          const label = `${hour.toString().padStart(2, '0')}:00`;
          slots.push({ id: `h-${i}`, value: i, label, isNextDay: i >= 24 });
      }
      return slots;
  };
  const timeSlots = generateTimeSlots();

  // --- Actions ---
  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([{ id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整至终版' }]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const copyListItems = [...stages];
    const dragItemContent = copyListItems[dragItem.current];
    copyListItems.splice(dragItem.current, 1);
    copyListItems.splice(dragOverItem.current, 0, dragItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setStages(copyListItems);
  };

  const handleConfirmAdd = () => {
    if (newStageTitle.trim()) {
        const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
        setStages([newStage, ...stages]);
        setNewStageTitle('');
        setIsAdding(false);
    }
  };

  const deleteStage = (index: number) => {
      if(confirm('确定删除此阶段吗?')) {
          const newStages = [...stages];
          newStages.splice(index, 1);
          setStages(newStages);
      }
  };

  const handleSyncProject = () => {
      if(!syncId.trim()) return;
      const found = projects?.find(p => p.id === syncId.trim());
      if(found) {
          setSyncedProject(found);
          setShowSyncInput(false);
          setSyncId('');
      } else alert('未找到该 ID 对应的排单。');
  };

  const toggleSessionBlockedDate = (dateStr: string) => {
      if (sessionBlockedDates.includes(dateStr)) setSessionBlockedDates(sessionBlockedDates.filter(d => d !== dateStr));
      else setSessionBlockedDates([...sessionBlockedDates, dateStr]);
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });
      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime('');
      } else setPlanningStep('finished');
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setCurrentComparisonDay(1); 
      setPlanningStep('time-boxing');
  };

  // --- RENDER DASHBOARD ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                            <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2">
                                <Trash2 size={16} />
                            </button>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- RENDER OFF-DAYS ---
  if (planningStep === 'off-days') {
      const calendarStart = getStartDate();
      const calendarDays = Array.from({ length: 42 }, (_, i) => {
          const d = new Date(calendarStart);
          d.setDate(calendarStart.getDate() + i);
          return getYYYYMMDD(d);
      });
      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>
              <h2 className="text-2xl font-black text-slate-800 mb-2">设置休息日</h2>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-slate-100 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-bold text-slate-300 uppercase">{d}</div>)}
                      {calendarDays.map(dateStr => (
                          <div key={dateStr} onClick={() => toggleSessionBlockedDate(dateStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer ${sessionBlockedDates.includes(dateStr) ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700'}`}>
                              <span className="text-xs font-bold">{new Date(dateStr + 'T00:00:00').getDate()}</span>
                              {sessionBlockedDates.includes(dateStr) && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                          </div>
                      ))}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl">进入工期分配</button>
          </div>
      );
  }

  // --- RENDER TIME ENTRY (Main Optimization Area) ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-4">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期分配中...</div>
            </div>

            {/* Prominent Countdown Header */}
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-500`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余工期倒数</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600' : 'text-slate-800'} transition-colors`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-500'} transition-colors`}>
                    {isOverBudget ? <AlertCircle size={28} /> : <Hourglass size={28} />}
                </div>
            </div>

            <div className="flex-1 space-y-6 relative">
                {stages.map((stage, index) => {
                    const isActive = index === activeTimeIndex;
                    const hasValue = estimates[stage.id];

                    return (
                        <div key={stage.id} className="relative flex flex-col items-center">
                            {/* Card Content - Centered when Active */}
                            <div 
                                onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }}
                                className={`
                                    relative border-2 rounded-2xl transition-all duration-500 
                                    flex flex-col items-center justify-center gap-1
                                    ${isActive 
                                        ? 'w-full h-32 border-fuchsia-500 bg-white shadow-2xl scale-100 z-10 p-6' 
                                        : 'w-2/3 h-16 border-slate-100 bg-slate-50 opacity-40 grayscale cursor-pointer p-4 scale-95'
                                    }
                                `}
                            >
                                <span className={`font-bold transition-all text-center ${isActive ? 'text-xl text-slate-800' : 'text-sm text-slate-500'}`}>
                                    {stage.title}
                                </span>
                                {hasValue && !isActive && (
                                    <span className="text-[10px] text-fuchsia-600 font-bold flex items-center gap-1">
                                        <Clock size={10} /> {estimates[stage.id]} 天
                                    </span>
                                )}

                                {/* Inner Input Field for Active Stage */}
                                {isActive && (
                                    <div className="mt-2 flex items-center gap-3 animate-fade-in w-full max-w-[200px]">
                                        <input 
                                            autoFocus
                                            type="text" 
                                            inputMode="decimal"
                                            placeholder="天数"
                                            value={currentInputTime}
                                            onChange={handleTimeInput}
                                            onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()}
                                            className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-4 py-2 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-400 transition-all"
                                        />
                                        <button 
                                            onClick={confirmTimeEntry}
                                            disabled={!currentInputTime}
                                            className="bg-slate-900 text-white p-3 rounded-xl disabled:opacity-30 flex-shrink-0"
                                        >
                                            <ArrowUp size={20} />
                                        </button>
                                    </div>
                                )}
                            </div>

                            {/* Connect Line */}
                            {index < stages.length - 1 && !isActive && (
                                <div className="h-6 w-0.5 bg-slate-100 mt-1"></div>
                            )}
                        </div>
                    );
                })}
            </div>

            {/* Bottom Actions */}
            <div className="fixed bottom-24 left-0 w-full px-5">
                <div className="max-w-lg mx-auto">
                    <button 
                        onClick={() => setPlanningStep('finished')}
                        disabled={Object.keys(estimates).length === 0}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 disabled:opacity-30"
                    >
                        <Check size={20} /> 生成最终规划
                    </button>
                </div>
            </div>
        </div>
    );
  }

  // --- RENDER FINISHED / BOXING ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 shadow-lg"><Check size={40} strokeWidth={3} /></div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">规划已就绪</h2>
              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left">
                  {stages.map(stage => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                          <span className="font-medium text-slate-700">{stage.title}</span>
                          <span className="font-bold text-indigo-600">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between font-bold text-lg">
                      <span>总计规划</span>
                      <span className={`${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} 天</span>
                  </div>
              </div>
              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2"><Box size={20} />开启时间盒子模式</button>
          </div>
      );
  }

  // --- RENDER SETUP (DEFAULT) ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 text-sm font-bold"><ArrowLeft size={16} /> 返回</button>
       </div>
       <div className="mb-6 bg-gradient-to-br from-fuchsia-50 to-rose-50 rounded-3xl border border-fuchsia-100 p-6">
            <h2 className="text-2xl font-bold text-fuchsia-900 flex items-center gap-2"><Sparkles size={20} className="text-fuchsia-500" />{syncedProject ? `项目: ${syncedProject.clientName}` : '灵感流规划'}</h2>
            {!syncedProject && <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-1 bg-white/50 px-3 py-2 rounded-xl text-xs font-bold text-fuchsia-700"><Link size={14} /> 关联排单项目</button>}
            {showSyncInput && <div className="mt-4 flex gap-2"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="排单 ID" className="flex-1 text-sm bg-white border border-fuchsia-200 rounded-xl px-3 py-2 outline-none" /><button onClick={handleSyncProject} className="bg-fuchsia-600 text-white px-3 py-2 rounded-xl text-sm font-bold">确定</button></div>}
       </div>
       <div className="space-y-4">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-20 border-2 border-dashed border-slate-300 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all"><Plus size={24} /><span className="text-xs font-bold uppercase ml-2">添加新阶段</span></div>
          ) : (
            <div className="w-full h-20 border-2 border-fuchsia-300 rounded-2xl flex items-center justify-between px-4 bg-white animate-fade-in"><input autoFocus type="text" placeholder="输入阶段名称..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-lg font-medium outline-none" /><div className="flex gap-2"><button onClick={() => setIsAdding(false)} className="p-2 text-slate-400"><X size={20} /></button><button onClick={handleConfirmAdd} className="p-2 bg-fuchsia-500 text-white rounded-full"><Check size={20} /></button></div></div>
          )}
          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border rounded-2xl flex items-center w-full h-20 px-6 border-slate-200 bg-white shadow-sm cursor-grab active:cursor-grabbing">
                <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                <span className="font-bold text-slate-700">{stage.title}</span>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-4 text-slate-200 hover:text-rose-400"><X size={16} /></button>
            </div>
          ))}
       </div>
       <div className="fixed bottom-24 left-0 w-full px-5">
           <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all"><Check size={20} /> 完成阶段配置</button>
       </div>
    </div>
  );
};

