import React, { useState } from 'react';
import { BookingSlot, ViewMode, Project } from '../types';
import { ShieldBan, Check, Lock, X, ChevronLeft, ChevronRight } from 'lucide-react';
import { getProjectLineColor } from '../utils';

interface ScheduleBoardProps {
  bookings: BookingSlot[];
  projects: Project[];
  mode: ViewMode;
  onUpdateBookings: (bookings: BookingSlot[]) => void;
  currentClientId?: string;
  currentClientName?: string;
}

const ScheduleBoard: React.FC<ScheduleBoardProps> = ({ 
  bookings, 
  projects, 
  mode, 
  onUpdateBookings,
  currentClientId,
  currentClientName 
}) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [bookingNote, setBookingNote] = useState('');
  const [viewDetailsDate, setViewDetailsDate] = useState<string | null>(null);

  const getLocalYYYYMMDD = (d: Date) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getDaysInMonth = (year: number, month: number) => {
    const date = new Date(year, month, 1);
    const days = [];
    // Padding for the start of the month
    const firstDayIndex = date.getDay();
    for (let i = 0; i < firstDayIndex; i++) {
      days.push(null);
    }
    while (date.getMonth() === month) {
      days.push(new Date(date));
      date.setDate(date.getDate() + 1);
    }
    return days;
  };

  const monthDays = getDaysInMonth(currentDate.getFullYear(), currentDate.getMonth());
  const getSlot = (date: string) => bookings.find(b => b.date === date);

  const getProjectsOnDate = (dateStr: string) => {
    const targetDate = new Date(dateStr + 'T00:00:00'); 
    const activeProjects = projects.filter(p => {
       if (p.status === 'completed') return false;
       if (mode === 'client' && p.targetClientId !== currentClientId) return false;
       const start = new Date(p.startDate);
       const end = new Date(p.deadline);
       const startDay = new Date(start.getFullYear(), start.getMonth(), start.getDate());
       const endDay = new Date(end.getFullYear(), end.getMonth(), end.getDate());
       return targetDate >= startDay && targetDate <= endDay;
    });
    return activeProjects.sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  const isMySlot = (clientId?: string, bookedBy?: string) => {
    if (mode === 'artist') return true;
    if (currentClientId && clientId === currentClientId) return true;
    if (bookedBy && currentClientName && bookedBy.toLowerCase() === currentClientName.toLowerCase()) return true;
    return false;
  };

  const handleDayClick = (date: string) => {
    const slot = getSlot(date);
    if (mode === 'artist') {
      if (slot?.actualHours && slot.actualHours.length > 0) {
          setViewDetailsDate(date);
          return;
      }
      const newBookings = [...bookings];
      const index = newBookings.findIndex(b => b.date === date);
      if (index >= 0) {
        if (newBookings[index].status === 'blocked') {
          newBookings.splice(index, 1);
        } else if(confirm("该日期已有预约，确定要清除吗？")) {
             newBookings.splice(index, 1);
        }
      } else {
        newBookings.push({ date, status: 'blocked' });
      }
      onUpdateBookings(newBookings);
    } else {
      if (slot?.status === 'blocked' || slot?.status === 'booked') return;
      setSelectedDate(date);
      setBookingNote('');
    }
  };

  const handleClientBook = () => {
    if (!selectedDate) return;
    const newBookings = [...bookings, {
      date: selectedDate,
      status: 'booked' as const,
      bookedBy: currentClientName || 'Client',
      clientId: currentClientId,
      note: bookingNote
    }];
    onUpdateBookings(newBookings);
    setSelectedDate(null);
    alert('预约申请已提交！');
  };

  const changeMonth = (offset: number) => {
    const next = new Date(currentDate.getFullYear(), currentDate.getMonth() + offset, 1);
    setCurrentDate(next);
  };

  const renderDetailsModal = () => {
      if (!viewDetailsDate) return null;
      const slot = getSlot(viewDetailsDate);
      if (!slot || !slot.actualHours) return null;

      const sortedHours = [...slot.actualHours].sort((a, b) => {
          const [hA, mA] = a.replace('h-', '').split('-').map(Number);
          const [hB, mB] = b.replace('h-', '').split('-').map(Number);
          return (hA * 60 + mA) - (hB * 60 + mB);
      });

      const mergedCapsules: any[] = [];
      let curStart = -1, curEnd = -1;

      const formatTime = (min: number) => {
          const h = Math.floor(min / 60);
          const m = min % 60;
          const lbl = `${(h % 24).toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
          return h >= 24 ? `次日 ${lbl}` : lbl;
      };

      sortedHours.forEach((s) => {
           const [h, m] = s.replace('h-', '').split('-').map(Number);
           const start = h * 60 + (m === 0 ? 0 : 30);
           const end = start + 30;
           if (curStart === -1) { curStart = start; curEnd = end; }
           else if (start === curEnd) curEnd = end;
           else {
               mergedCapsules.push({ label: `${formatTime(curStart)} - ${formatTime(curEnd)}`, type: curStart / 60 < 13 ? 'morning' : curStart / 60 < 18 ? 'afternoon' : 'evening' });
               curStart = start; curEnd = end;
           }
      });
      if (curStart !== -1) mergedCapsules.push({ label: `${formatTime(curStart)} - ${formatTime(curEnd)}`, type: curStart / 60 < 13 ? 'morning' : curStart / 60 < 18 ? 'afternoon' : 'evening' });

      return (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4 animate-fade-in">
              <div className="bg-white w-full max-w-sm rounded-3xl shadow-2xl p-6 relative animate-slide-up">
                  <button onClick={() => setViewDetailsDate(null)} className="absolute right-4 top-4 p-2 bg-slate-100 rounded-full"><X size={20} className="text-slate-500" /></button>
                  <div className="mb-6"><span className="text-[10px] font-bold text-slate-400 uppercase">实际工时记录</span><h3 className="text-2xl font-black text-slate-800 mt-1">{viewDetailsDate}</h3></div>
                  <div className="flex flex-wrap gap-2 mb-6">
                      {mergedCapsules.map((cap, idx) => (
                          <div key={idx} className={`${cap.type === 'morning' ? 'bg-orange-100 text-orange-700' : cap.type === 'afternoon' ? 'bg-sky-100 text-sky-700' : 'bg-indigo-100 text-indigo-700'} px-3 py-1.5 rounded-full text-xs font-bold shadow-sm`}>{cap.label}</div>
                      ))}
                  </div>
                  <div className="pt-4 border-t border-slate-100 flex justify-between items-center"><span className="text-slate-500 font-medium text-xs">总专注时长</span><span className="text-xl font-bold text-indigo-600">{slot.actualHours.length * 0.5} Hours</span></div>
              </div>
          </div>
      );
  };

  return (
    <div className="p-5">
      {renderDetailsModal()}
      <div className="flex justify-between items-center mb-6">
        <div>
           <h2 className="text-lg font-black text-slate-800 flex items-center gap-2">
            {currentDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}
          </h2>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">
            {mode === 'artist' ? '排期管理' : '预约排期'}
          </p>
        </div>
        <div className="flex gap-2">
            <button onClick={() => changeMonth(-1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 text-slate-600"><ChevronLeft size={20}/></button>
            <button onClick={() => changeMonth(1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 text-slate-600"><ChevronRight size={20}/></button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-1.5 mb-2">
        {['日', '一', '二', '三', '四', '五', '六'].map(d => (
            <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-1.5">
        {monthDays.map((day, idx) => {
          if (!day) return <div key={`empty-${idx}`} className="aspect-[4/5] bg-slate-50/30 rounded-lg"></div>;

          const dateStr = getLocalYYYYMMDD(day);
          const slot = getSlot(dateStr);
          const projectsOnDay = getProjectsOnDate(dateStr);
          const isToday = getLocalYYYYMMDD(new Date()) === dateStr;
          const status = slot?.status;
          const isMine = isMySlot(slot?.clientId, slot?.bookedBy);
          const hasWork = slot?.actualHours && slot.actualHours.length > 0;

          let bg = 'bg-white border-slate-100 text-slate-700';
          let icon = null;

          if (status === 'blocked') {
             if (mode === 'client' && !isMine) {
                bg = 'bg-slate-100/50 border-slate-50 text-slate-200';
                icon = <Lock size={10} className="opacity-20 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             } else {
                bg = 'bg-slate-100 border-slate-200 text-slate-400';
                icon = <ShieldBan size={12} className="opacity-40 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             }
          } else if (status === 'booked') {
             if (mode === 'client' && !isMine) {
                bg = 'bg-slate-100/50 border-slate-50 text-slate-200';
                icon = <Lock size={10} className="opacity-20 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             } else {
                bg = 'bg-indigo-600 border-indigo-600 text-white shadow-md shadow-indigo-100';
                icon = <Check size={14} strokeWidth={3} className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             }
          }

          if (hasWork && mode === 'artist') { bg = 'bg-emerald-50 border-emerald-100 text-emerald-800'; icon = null; }
          if (selectedDate === dateStr) { bg = 'ring-2 ring-indigo-500 ring-offset-2 bg-indigo-500 text-white z-10'; }

          return (
            <div key={dateStr} onClick={() => handleDayClick(dateStr)} className={`aspect-[4/5] rounded-lg border flex flex-col relative transition-all active:scale-95 overflow-hidden ${bg}`}>
              <span className={`text-[10px] font-black p-1.5 leading-none ${isToday && !selectedDate ? 'text-indigo-600' : ''}`}>
                {day.getDate()}
              </span>
              {isToday && !selectedDate && <div className="absolute top-1 right-1 w-1 h-1 bg-indigo-500 rounded-full"></div>}
              {hasWork && mode === 'artist' && <div className="absolute bottom-1 right-1 w-1.5 h-1.5 bg-emerald-500 rounded-full"></div>}
              {icon}
              <div className="mt-auto px-1 pb-1 flex flex-col gap-0.5 w-full">
                 {projectsOnDay.slice(0, 3).map(p => <div key={p.id} className={`h-0.5 w-full rounded-full ${getProjectLineColor(p.startDate, p.deadline)}`} />)}
              </div>
            </div>
          );
        })}
      </div>

      {mode === 'client' && selectedDate && (
        <div className="mt-6 animate-slide-up bg-slate-50 p-4 rounded-2xl border border-slate-100">
          <div className="flex items-center gap-2 mb-3 text-sm font-bold text-slate-700">预约: {selectedDate}</div>
          <div className="flex gap-2">
            <input type="text" placeholder="备注..." value={bookingNote} onChange={(e) => setBookingNote(e.target.value)} className="flex-1 bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm outline-none" />
            <button onClick={handleClientBook} className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-200">提交</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduleBoard;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date()); // For month navigation in Off-days
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 730) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      current.setHours(0,0,0,0);
      let validDaysFound = 0;
      let safetyCounter = 0;
      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }
          if (validDaysFound === dayIndex) return dateStr;
          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }
      return getYYYYMMDD(current);
  };

  const isDayCompleted = (dayIndex: number) => {
      const dateStr = getTargetDateStr(dayIndex);
      const hasBooking = bookings?.some(b => b.date === dateStr && b.actualHours && b.actualHours.length > 0);
      return hasBooking || localCompletedDays.includes(dayIndex);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([{ id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整至终版' }]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current === null || dragOverItem.current === null) return;
    const copyListItems = [...stages];
    const dragItemContent = copyListItems[dragItem.current];
    copyListItems.splice(dragItem.current, 1);
    copyListItems.splice(dragOverItem.current, 0, dragItemContent);
    dragItem.current = null;
    dragOverItem.current = null;
    setStages(copyListItems);
  };

  const handleConfirmAdd = () => {
    if (newStageTitle.trim()) {
        const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
        setStages([newStage, ...stages]);
        setNewStageTitle('');
        setIsAdding(false);
    }
  };

  const deleteStage = (index: number) => {
      if(confirm('确定删除此阶段吗?')) {
          const newStages = [...stages];
          newStages.splice(index, 1);
          setStages(newStages);
      }
  };

  const handleSyncProject = () => {
      if(!syncId.trim()) return;
      const found = projects?.find(p => p.id === syncId.trim());
      if(found) {
          setSyncedProject(found);
          setShowSyncInput(false);
          setSyncId('');
      } else alert('未找到该 ID 对应的排单。');
  };

  const toggleSessionBlockedDate = (dateStr: string) => {
      if (sessionBlockedDates.includes(dateStr)) setSessionBlockedDates(sessionBlockedDates.filter(d => d !== dateStr));
      else setSessionBlockedDates([...sessionBlockedDates, dateStr]);
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });
      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime('');
      } else setPlanningStep('finished');
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setCurrentComparisonDay(1); 
      setPlanningStep('time-boxing');
  };

  // --- RENDER DASHBOARD ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                            <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2">
                                <Trash2 size={16} />
                            </button>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- RENDER OFF-DAYS (Optimized Calendar View) ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      const changeOffMonth = (offset: number) => setOffDayViewDate(new Date(year, month + offset, 1));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>

              <div className="flex justify-between items-center mb-4">
                  <div>
                      <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                      <p className="text-[10px] text-rose-500 font-bold uppercase tracking-wider">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => changeOffMonth(-1)} className="p-2 bg-slate-50 rounded-xl"><ChevronLeft size={20} /></button>
                      <button onClick={() => changeOffMonth(1)} className="p-2 bg-slate-50 rounded-xl"><ChevronRight size={20} /></button>
                  </div>
              </div>

              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isGlobalBlocked = bookings?.some(b => b.date === dStr && (b.status === 'blocked' || b.status === 'booked'));
                          const isToday = getYYYYMMDD(new Date()) === dStr;

                          return (
                              <div key={dStr} onClick={() => !isGlobalBlocked && toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer active:scale-95 transition-all ${isGlobalBlocked ? 'bg-slate-100 border-slate-50 opacity-40 cursor-not-allowed' : isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline decoration-2 underline-offset-4' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                                  {isGlobalBlocked && <Lock size={10} className="absolute bottom-1 right-1 opacity-20" />}
                              </div>
                          );
                      })}
                  </div>
              </div>

              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-xs text-slate-500 font-medium leading-relaxed">休息是为了更好的创作。标记为“X”的日期将从工期计算中自动扣除。目前已同步排期管理中的 <span className="text-rose-500 font-bold">{bookings.filter(b => b.status === 'blocked' || b.status === 'booked').length}</span> 个日期。</p>
              </div>

              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl">进入工期分配</button>
          </div>
      );
  }

  // --- RENDER TIME ENTRY ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-4">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-xs font-bold text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期分配中...</div>
            </div>

            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-500`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余工期倒数</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600' : 'text-slate-800'} transition-colors`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-emerald-50 text-emerald-500'}`}>
                    {isOverBudget ? <AlertCircle size={28} /> : <Hourglass size={28} />}
                </div>
            </div>

            <div className="flex-1 space-y-6 relative">
                {stages.map((stage, index) => {
                    const isActive = index === activeTimeIndex;
                    const hasValue = estimates[stage.id];

                    return (
                        <div key={stage.id} className="relative flex flex-col items-center">
                            <div 
                                onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }}
                                className={`relative border-2 rounded-2xl transition-all duration-500 flex flex-col items-center justify-center gap-1 ${isActive ? 'w-full h-32 border-fuchsia-500 bg-white shadow-2xl z-10 p-6' : 'w-2/3 h-16 border-slate-100 bg-slate-50 opacity-40 grayscale cursor-pointer p-4 scale-95'}`}
                            >
                                <span className={`font-black transition-all text-center ${isActive ? 'text-xl text-slate-800' : 'text-sm text-slate-500'}`}>{stage.title}</span>
                                {hasValue && !isActive && <span className="text-[10px] text-fuchsia-600 font-bold flex items-center gap-1"><Clock size={10} /> {estimates[stage.id]} 天</span>}
                                {isActive && (
                                    <div className="mt-2 flex items-center gap-3 animate-fade-in w-full max-w-[180px]">
                                        <input autoFocus type="text" inputMode="decimal" placeholder="0" value={currentInputTime} onChange={handleTimeInput} onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-4 py-2 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-400" />
                                        <button onClick={confirmTimeEntry} disabled={!currentInputTime} className="bg-slate-900 text-white p-3 rounded-xl disabled:opacity-30"><ArrowUp size={20} /></button>
                                    </div>
                                )}
                            </div>
                            {index < stages.length - 1 && !isActive && <div className="h-6 w-0.5 bg-slate-100 mt-1"></div>}
                        </div>
                    );
                })}
            </div>

            <div className="fixed bottom-24 left-0 w-full px-5">
                <button onClick={() => setPlanningStep('finished')} disabled={Object.keys(estimates).length === 0} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 disabled:opacity-30"><Check size={20} /> 生成最终规划</button>
            </div>
        </div>
    );
  }

  // --- RENDER DASHBOARD (REST OF THE COMPONENT REMAINS) ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-20 h-20 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-6 shadow-lg"><Check size={40} strokeWidth={3} /></div>
              <h2 className="text-2xl font-bold text-slate-800 mb-2">规划已就绪</h2>
              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left">
                  {stages.map(stage => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                          <span className="font-medium text-slate-700">{stage.title}</span>
                          <span className="font-bold text-indigo-600">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-4 border-t border-slate-100 flex justify-between font-bold text-lg">
                      <span>总计规划</span>
                      <span className={`${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} 天</span>
                  </div>
              </div>
              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2"><Box size={20} />开启时间盒子模式</button>
          </div>
      );
  }

  // (The rest of the code is unchanged from the last state but included here for correctness if needed)
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 text-sm font-bold"><ArrowLeft size={16} /> 返回</button>
       </div>
       <div className="mb-6 bg-gradient-to-br from-fuchsia-50 to-rose-50 rounded-3xl border border-fuchsia-100 p-6">
            <h2 className="text-2xl font-bold text-fuchsia-900 flex items-center gap-2"><Sparkles size={20} className="text-fuchsia-500" />{syncedProject ? `项目: ${syncedProject.clientName}` : '灵感流规划'}</h2>
            {!syncedProject && <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-1 bg-white/50 px-3 py-2 rounded-xl text-xs font-bold text-fuchsia-700"><Link size={14} /> 关联排单项目</button>}
            {showSyncInput && <div className="mt-4 flex gap-2"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="排单 ID" className="flex-1 text-sm bg-white border border-fuchsia-200 rounded-xl px-3 py-2 outline-none" /><button onClick={handleSyncProject} className="bg-fuchsia-600 text-white px-3 py-2 rounded-xl text-sm font-bold">确定</button></div>}
       </div>
       <div className="space-y-4">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-20 border-2 border-dashed border-slate-300 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all"><Plus size={24} /><span className="text-xs font-bold uppercase ml-2">添加新阶段</span></div>
          ) : (
            <div className="w-full h-20 border-2 border-fuchsia-300 rounded-2xl flex items-center justify-between px-4 bg-white animate-fade-in"><input autoFocus type="text" placeholder="输入阶段名称..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-lg font-medium outline-none" /><div className="flex gap-2"><button onClick={() => setIsAdding(false)} className="p-2 text-slate-400"><X size={20} /></button><button onClick={handleConfirmAdd} className="p-2 bg-fuchsia-500 text-white rounded-full"><Check size={20} /></button></div></div>
          )}
          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border rounded-2xl flex items-center w-full h-20 px-6 border-slate-200 bg-white shadow-sm cursor-grab active:cursor-grabbing">
                <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                <span className="font-bold text-slate-700">{stage.title}</span>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-4 text-slate-200 hover:text-rose-400"><X size={16} /></button>
            </div>
          ))}
       </div>
       <div className="fixed bottom-24 left-0 w-full px-5">
           <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all"><Check size={20} /> 完成阶段配置</button>
       </div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 730) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      current.setHours(0,0,0,0);
      let validDaysFound = 0;
      let safetyCounter = 0;
      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }
          if (validDaysFound === dayIndex) return dateStr;
          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }
      return getYYYYMMDD(current);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([{ id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整至终版' }]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });

      // Automatic upward flow: from bottom to top
      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime(estimates[stages[activeTimeIndex - 1].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setCurrentComparisonDay(1); 
      setPlanningStep('time-boxing');
  };

  // --- RENDER DASHBOARD ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                            <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2">
                                <Trash2 size={16} />
                            </button>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- RENDER OFF-DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      const changeOffMonth = (offset: number) => setOffDayViewDate(new Date(year, month + offset, 1));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>

              <div className="flex justify-between items-center mb-4">
                  <div>
                      <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                      <p className="text-[10px] text-rose-500 font-bold uppercase tracking-wider">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => changeOffMonth(-1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={20} /></button>
                      <button onClick={() => changeOffMonth(1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={20} /></button>
                  </div>
              </div>

              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isGlobalBlocked = bookings?.some(b => b.date === dStr && (b.status === 'blocked' || b.status === 'booked'));
                          const isToday = getYYYYMMDD(new Date()) === dStr;

                          return (
                              <div key={dStr} onClick={() => !isGlobalBlocked && toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer active:scale-95 transition-all ${isGlobalBlocked ? 'bg-slate-100 border-slate-50 opacity-40 cursor-not-allowed' : isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline decoration-2 underline-offset-4' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                                  {isGlobalBlocked && <Lock size={10} className="absolute bottom-1 right-1 opacity-20" />}
                              </div>
                          );
                      })}
                  </div>
              </div>

              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-xs text-slate-500 font-medium leading-relaxed">休息是为了更好的创作。标记为“X”的日期将从工期计算中自动扣除。</p>
              </div>

              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all">确认休息日，分配工期</button>
          </div>
      );
  }

  // --- RENDER TIME ENTRY (NEW VERTICAL TIMELINE LAYOUT) ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100 uppercase tracking-widest">物理工期分配</div>
            </div>

            {/* Global Countdown Header */}
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden transition-all">
                <div 
                    className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} 
                    style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}
                ></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数 (含休息日计算)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'} transition-colors`}>
                            {remainingDays}
                        </span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'} transition-colors`}>
                    {isOverBudget ? <AlertCircle size={28} /> : <Hourglass size={28} />}
                </div>
            </div>

            {/* Vertical Timeline Container */}
            <div className="flex-1 relative pl-8">
                {/* Vertical Line Connector */}
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-gradient-to-b from-fuchsia-200/0 via-fuchsia-500 to-fuchsia-200/0 opacity-30 rounded-full"></div>

                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center group">
                                {/* Left Timeline Node */}
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-500 flex items-center justify-center
                                    ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-200' : 
                                      isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}
                                >
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>}
                                </div>

                                {/* Main Card Container (Stage on Left, Input on Right) */}
                                <div 
                                    onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }}
                                    className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl transition-all duration-500 border-2
                                        ${isActive ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 -translate-x-2' : 
                                          'bg-white/50 border-slate-100 opacity-60 hover:opacity-100 cursor-pointer'}`}
                                >
                                    {/* Left Content (Title) */}
                                    <div className="flex flex-col">
                                        <span className={`font-black transition-colors ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>
                                            {stage.title}
                                        </span>
                                        {isActive && <span className="text-[10px] text-fuchsia-500 font-bold uppercase mt-1">正在规划此阶段...</span>}
                                    </div>

                                    {/* Right Content (Input/Value) */}
                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2 animate-fade-in">
                                                <input 
                                                    autoFocus
                                                    type="text" 
                                                    inputMode="decimal"
                                                    placeholder="0"
                                                    value={currentInputTime}
                                                    onChange={handleTimeInput}
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()}
                                                    className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-all"
                                                />
                                                <button 
                                                    onClick={confirmTimeEntry}
                                                    disabled={!currentInputTime}
                                                    className="bg-slate-900 text-white p-2.5 rounded-xl disabled:opacity-20 shadow-md active:scale-90 transition-all"
                                                >
                                                    <ArrowUp size={20} />
                                                </button>
                                            </div>
                                        ) : (
                                            <div className="flex flex-col items-end">
                                                <span className={`font-black font-mono ${isDone ? 'text-fuchsia-600 text-xl' : 'text-slate-200 text-lg'}`}>
                                                    {estimates[stage.id] || '--'}
                                                </span>
                                                {isDone && <span className="text-[10px] text-slate-400 font-bold">DAYS</span>}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Summary Action */}
            <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button 
                        onClick={() => setPlanningStep('finished')}
                        disabled={Object.keys(estimates).length === 0}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl shadow-slate-200 flex items-center justify-center gap-2 disabled:opacity-30 hover:scale-[1.02] active:scale-95 transition-all"
                    >
                        <CheckCircle2 size={20} /> 完成所有阶段规划
                    </button>
                </div>
            </div>
        </div>
    );
  }

  // --- REST OF RENDERS (SUMMARY/FINISH) ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
              <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
              <p className="text-slate-400 text-sm mb-8">系统已为您计算出最佳创作路径</p>

              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                  {stages.map(stage => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                          <span className="font-bold text-slate-600 group-hover:text-slate-900 transition-colors">{stage.title}</span>
                          <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-end font-bold">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase tracking-widest">总计工期</span>
                        <span className="text-2xl text-slate-800">TOTAL PLAN</span>
                      </div>
                      <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} Days</span>
                  </div>
              </div>

              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                <Box size={24} /> 开启时间盒子工作流
              </button>
          </div>
      );
  }

  // --- SETUP RENDER ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
            <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
       </div>

       <div className="mb-8 p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 mb-2">
                    <Sparkles size={20} className="text-fuchsia-400" />
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                </div>
                <h2 className="text-2xl font-black leading-tight">
                    {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                </h2>
                {!syncedProject && (
                    <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10">
                        <Link size={14} /> 关联现有排单项目
                    </button>
                )}
                {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
            </div>
       </div>

       <div className="space-y-4 relative">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-3xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group">
                <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors"><Plus size={28} /></div>
                <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
            </div>
          ) : (
            <div className="w-full p-4 border-2 border-fuchsia-300 rounded-3xl flex items-center justify-between bg-white shadow-xl animate-slide-up">
                <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                <div className="flex gap-2">
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                    <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                </div>
            </div>
          )}

          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-3xl flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                    <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                </div>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-2 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                    <Trash2 size={20} />
                </button>
            </div>
          ))}
       </div>

       <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
           <div className="max-w-lg mx-auto pointer-events-auto">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                   <ChevronRight size={24} /> 确认阶段，设置休息日
               </button>
           </div>
       </div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 730) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      current.setHours(0,0,0,0);
      let validDaysFound = 0;
      let safetyCounter = 0;
      while (safetyCounter < 730) {
          const dateStr = getYYYYMMDD(current);
          if (!isDateBlocked(dateStr)) {
              validDaysFound++;
          }
          if (validDaysFound === dayIndex) return dateStr;
          current.setDate(current.getDate() + 1);
          safetyCounter++;
      }
      return getYYYYMMDD(current);
  };

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  // Added missing toggleSessionBlockedDate handler to manage user selected rest days.
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => 
      prev.includes(dateStr) 
        ? prev.filter(d => d !== dateStr) 
        : [...prev, dateStr]
    );
  };

  // Added missing handleSyncProject handler to link a session with an existing project by ID.
  const handleSyncProject = () => {
    if (!syncId.trim()) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID，请检查输入是否正确。');
    }
  };

  // Added missing handleConfirmAdd handler to add a new stage to the planning sequence.
  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) {
      setIsAdding(false);
      return;
    }
    const newStage: PlannerStage = {
      id: Date.now().toString(),
      title: newStageTitle.trim(),
      isDeletable: true
    };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  // Added missing drag and drop handlers to allow reordering of stages.
  const handleDragStart = (index: number) => {
    dragItem.current = index;
  };

  const handleDragEnter = (index: number) => {
    dragOverItem.current = index;
  };

  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copyListItems = [...stages];
      const dragItemContent = copyListItems[dragItem.current];
      copyListItems.splice(dragItem.current, 1);
      copyListItems.splice(dragOverItem.current, 0, dragItemContent);
      dragItem.current = null;
      dragOverItem.current = null;
      setStages(copyListItems);
    }
  };

  // Added missing deleteStage handler to remove a stage from the sequence.
  const deleteStage = (index: number) => {
    if (stages.length <= 1) {
      alert('至少需要保留一个阶段');
      return;
    }
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([{ id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整至终版' }]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });

      // Automatic upward flow: from bottom to top
      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime(estimates[stages[activeTimeIndex - 1].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setCurrentComparisonDay(1); 
      setPlanningStep('time-boxing');
  };

  // --- RENDER DASHBOARD ---
  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                            <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2">
                                <Trash2 size={16} />
                            </button>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- RENDER OFF-DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      const changeOffMonth = (offset: number) => setOffDayViewDate(new Date(year, month + offset, 1));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>

              <div className="flex justify-between items-center mb-4">
                  <div>
                      <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                      <p className="text-[10px] text-rose-500 font-bold uppercase tracking-wider">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => changeOffMonth(-1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={20} /></button>
                      <button onClick={() => changeOffMonth(1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={20} /></button>
                  </div>
              </div>

              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isGlobalBlocked = bookings?.some(b => b.date === dStr && (b.status === 'blocked' || b.status === 'booked'));
                          const isToday = getYYYYMMDD(new Date()) === dStr;

                          return (
                              <div key={dStr} onClick={() => !isGlobalBlocked && toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer active:scale-95 transition-all ${isGlobalBlocked ? 'bg-slate-100 border-slate-50 opacity-40 cursor-not-allowed' : isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline decoration-2 underline-offset-4' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                                  {isGlobalBlocked && <Lock size={10} className="absolute bottom-1 right-1 opacity-20" />}
                              </div>
                          );
                      })}
                  </div>
              </div>

              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-xs text-slate-500 font-medium leading-relaxed">休息是为了更好的创作。标记为“X”的日期将从工期计算中自动扣除。</p>
              </div>

              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all">确认休息日，分配工期</button>
          </div>
      );
  }

  // --- RENDER TIME ENTRY (NEW VERTICAL TIMELINE LAYOUT) ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100 uppercase tracking-widest">物理工期分配</div>
            </div>

            {/* Global Countdown Header */}
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden transition-all">
                <div 
                    className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} 
                    style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}
                ></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数 (含休息日计算)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'} transition-colors`}>
                            {remainingDays}
                        </span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'} transition-colors`}>
                    {isOverBudget ? <AlertCircle size={28} /> : <Hourglass size={28} />}
                </div>
            </div>

            {/* Vertical Timeline Container */}
            <div className="flex-1 relative pl-8">
                {/* Vertical Line Connector */}
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-gradient-to-b from-fuchsia-200/0 via-fuchsia-500 to-fuchsia-200/0 opacity-30 rounded-full"></div>

                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center group">
                                {/* Left Timeline Node */}
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-500 flex items-center justify-center
                                    ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-200' : 
                                      isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}
                                >
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>}
                                </div>

                                {/* Main Card Container (Stage on Left, Input on Right) */}
                                <div 
                                    onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }}
                                    className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl transition-all duration-500 border-2
                                        ${isActive ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 -translate-x-2' : 
                                          'bg-white/50 border-slate-100 opacity-60 hover:opacity-100 cursor-pointer'}`}
                                >
                                    {/* Left Content (Title) */}
                                    <div className="flex flex-col">
                                        <span className={`font-black transition-colors ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>
                                            {stage.title}
                                        </span>
                                        {isActive && <span className="text-[10px] text-fuchsia-500 font-bold uppercase mt-1">正在规划此阶段...</span>}
                                    </div>

                                    {/* Right Content (Input/Value) */}
                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2 animate-fade-in">
                                                <input 
                                                    autoFocus
                                                    type="text" 
                                                    inputMode="decimal"
                                                    placeholder="0"
                                                    value={currentInputTime}
                                                    onChange={handleTimeInput}
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()}
                                                    className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-all"
                                                />
                                                <button 
                                                    onClick={confirmTimeEntry}
                                                    disabled={!currentInputTime}
                                                    className="bg-slate-900 text-white p-2.5 rounded-xl disabled:opacity-20 shadow-md active:scale-90 transition-all"
                                                >
                                                    <ArrowUp size={20} />
                                                </button>
                                            </div>
                                        ) : (
                                            <div className="flex flex-col items-end">
                                                <span className={`font-black font-mono ${isDone ? 'text-fuchsia-600 text-xl' : 'text-slate-200 text-lg'}`}>
                                                    {estimates[stage.id] || '--'}
                                                </span>
                                                {isDone && <span className="text-[10px] text-slate-400 font-bold">DAYS</span>}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Summary Action */}
            <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button 
                        onClick={() => setPlanningStep('finished')}
                        disabled={Object.keys(estimates).length === 0}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl shadow-slate-200 flex items-center justify-center gap-2 disabled:opacity-30 hover:scale-[1.02] active:scale-95 transition-all"
                    >
                        <CheckCircle2 size={20} /> 完成所有阶段规划
                    </button>
                </div>
            </div>
        </div>
    );
  }

  // --- REST OF RENDERS (SUMMARY/FINISH) ---
  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
              <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
              <p className="text-slate-400 text-sm mb-8">系统已为您计算出最佳创作路径</p>

              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                  {stages.map(stage => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                          <span className="font-bold text-slate-600 group-hover:text-slate-900 transition-colors">{stage.title}</span>
                          <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-end font-bold">
                      <div className="flex flex-col">
                        <span className="text-[10px] text-slate-400 uppercase tracking-widest">总计工期</span>
                        <span className="text-2xl text-slate-800">TOTAL PLAN</span>
                      </div>
                      <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600' : 'text-emerald-600'}`}>{currentPlannedDays} Days</span>
                  </div>
              </div>

              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                <Box size={24} /> 开启时间盒子工作流
              </button>
          </div>
      );
  }

  // --- SETUP RENDER ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
            <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
       </div>

       <div className="mb-8 p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 mb-2">
                    <Sparkles size={20} className="text-fuchsia-400" />
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                </div>
                <h2 className="text-2xl font-black leading-tight">
                    {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                </h2>
                {!syncedProject && (
                    <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10">
                        <Link size={14} /> 关联现有排单项目
                    </button>
                )}
                {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
            </div>
       </div>

       <div className="space-y-4 relative">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-3xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group">
                <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors"><Plus size={28} /></div>
                <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
            </div>
          ) : (
            <div className="w-full p-4 border-2 border-fuchsia-300 rounded-3xl flex items-center justify-between bg-white shadow-xl animate-slide-up">
                <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                <div className="flex gap-2">
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                    <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                </div>
            </div>
          )}

          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-3xl flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                    <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                </div>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-2 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                    <Trash2 size={20} />
                </button>
            </div>
          ))}
       </div>

       <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
           <div className="max-w-lg mx-auto pointer-events-auto">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                   <ChevronRight size={24} /> 确认阶段，设置休息日
               </button>
           </div>
       </div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[]; // Receive projects to find sync match
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    start.setHours(0,0,0,0);
    end.setHours(0,0,0,0);

    let count = 0;
    let curr = new Date(start);
    let loopCount = 0;
    while (curr <= end && loopCount < 730) {
        if (!isDateBlocked(getYYYYMMDD(curr))) {
            count++;
        }
        curr.setDate(curr.getDate() + 1);
        loopCount++;
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => 
      prev.includes(dateStr) 
        ? prev.filter(d => d !== dateStr) 
        : [...prev, dateStr]
    );
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID，请检查输入是否正确。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) {
      setIsAdding(false);
      return;
    }
    const newStage: PlannerStage = {
      id: Date.now().toString(),
      title: newStageTitle.trim(),
      isDeletable: true
    };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => {
    dragItem.current = index;
  };

  const handleDragEnter = (index: number) => {
    dragOverItem.current = index;
  };

  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copyListItems = [...stages];
      const dragItemContent = copyListItems[dragItem.current];
      copyListItems.splice(dragItem.current, 1);
      copyListItems.splice(dragOverItem.current, 0, dragItemContent);
      dragItem.current = null;
      dragOverItem.current = null;
      setStages(copyListItems);
    }
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) {
      alert('至少需要保留一个阶段');
      return;
    }
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setSyncId('');
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setStages([{ id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整至终版' }]);
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if(confirm('确定删除此规划存档吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const currentStage = stages[activeTimeIndex];
      setEstimates({ ...estimates, [currentStage.id]: currentInputTime });

      if (activeTimeIndex > 0) {
          setActiveTimeIndex(activeTimeIndex - 1);
          setCurrentInputTime(estimates[stages[activeTimeIndex - 1].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleTimeInput = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value;
      if (/^\d*\.?\d*$/.test(val)) setCurrentInputTime(val);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setCurrentComparisonDay(1); 
      setPlanningStep('time-boxing');
  };

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的多个排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-xs text-slate-400 font-medium">开启一个新的灵感流</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                            <button onClick={(e) => handleDeleteSession(session.id, e)} className="absolute bottom-4 right-4 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all p-2">
                                <Trash2 size={16} />
                            </button>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      const changeOffMonth = (offset: number) => setOffDayViewDate(new Date(year, month + offset, 1));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>

              <div className="flex justify-between items-center mb-4">
                  <div>
                      <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                      <p className="text-[10px] text-rose-500 font-bold uppercase tracking-wider">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => changeOffMonth(-1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={20} /></button>
                      <button onClick={() => changeOffMonth(1)} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={20} /></button>
                  </div>
              </div>

              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isGlobalBlocked = bookings?.some(b => b.date === dStr && (b.status === 'blocked' || b.status === 'booked'));
                          const isToday = getYYYYMMDD(new Date()) === dStr;

                          return (
                              <div key={dStr} onClick={() => !isGlobalBlocked && toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer active:scale-95 transition-all ${isGlobalBlocked ? 'bg-slate-100 border-slate-50 opacity-40 cursor-not-allowed' : isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline decoration-2 underline-offset-4' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                                  {isGlobalBlocked && <Lock size={10} className="absolute bottom-1 right-1 opacity-20" />}
                              </div>
                          );
                      })}
                  </div>
              </div>

              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-xs text-slate-500 font-medium leading-relaxed">休息是为了更好的创作。标记为“X”的日期将从工期计算中自动扣除。</p>
              </div>

              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl shadow-slate-200 hover:scale-[1.02] active:scale-95 transition-all">确认休息日，分配工期</button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100 uppercase tracking-widest">物理工期分配</div>
            </div>

            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden transition-all">
                <div 
                    className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} 
                    style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}
                ></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数 (含休息日计算)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'} transition-colors`}>
                            {remainingDays}
                        </span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'} transition-colors`}>
                    {isOverBudget ? <AlertCircle size={28} /> : <Hourglass size={28} />}
                </div>
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-gradient-to-b from-fuchsia-200/0 via-fuchsia-500 to-fuchsia-200/0 opacity-30 rounded-full"></div>

                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center group">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-500 flex items-center justify-center
                                    ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-200' : 
                                      isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}
                                >
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>}
                                </div>

                                <div 
                                    onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }}
                                    className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl transition-all duration-500 border-2
                                        ${isActive ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 -translate-x-2' : 
                                          'bg-white/50 border-slate-100 opacity-60 hover:opacity-100 cursor-pointer'}`}
                                >
                                    <div className="flex flex-col">
                                        <span className={`font-black transition-colors ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>
                                            {stage.title}
                                        </span>
                                        {isActive && <span className="text-[10px] text-fuchsia-500 font-bold uppercase mt-1">正在规划此阶段...</span>}
                                    </div>

                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2 animate-fade-in">
                                                <input 
                                                    autoFocus
                                                    type="text" 
                                                    inputMode="decimal"
                                                    placeholder="0"
                                                    value={currentInputTime}
                                                    onChange={handleTimeInput}
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()}
                                                    className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-all"
                                                />
                                                <button 
                                                    onClick={confirmTimeEntry}
                                                    disabled={!currentInputTime}
                                                    className="bg-slate-900 text-white p-2.5 rounded-xl disabled:opacity-20 shadow-md active:scale-90 transition-all"
                                                >
                                                    <ArrowUp size={20} />
                                                </button>
                                            </div>
                                        ) : (
                                            <div className="flex flex-col items-end">
                                                <span className={`font-black font-mono ${isDone ? 'text-fuchsia-600 text-xl' : 'text-slate-200 text-lg'}`}>
                                                    {estimates[stage.id] || '--'}
                                                </span>
                                                {isDone && <span className="text-[10px] text-slate-400 font-bold">DAYS</span>}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
                <div className="max-w-lg mx-auto pointer-events-auto">
                    <button 
                        onClick={() => setPlanningStep('finished')}
                        disabled={Object.keys(estimates).length === 0}
                        className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl shadow-slate-200 flex items-center justify-center gap-2 disabled:opacity-30 hover:scale-[1.02] active:scale-95 transition-all"
                    >
                        <CheckCircle2 size={20} /> 完成所有阶段规划
                    </button>
                </div>
            </div>
        </div>
    );
  }

  if (planningStep === 'finished') {
      return (
          <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
              <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
              <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
              <p className="text-slate-400 text-sm mb-8">系统已为您计算出最佳创作路径</p>

              <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                  {stages.map(stage => (
                      <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                          <span className="font-bold text-slate-600 group-hover:text-slate-900 transition-colors">{stage.title}</span>
                          <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                      </div>
                  ))}
                  <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                      <span className="font-bold text-slate-800 text-lg">总计工期</span>
                      <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>
                        {currentPlannedDays} 天
                      </span>
                  </div>
              </div>

              <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                <Box size={24} /> 开启时间盒子工作流
              </button>
          </div>
      );
  }

  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
            <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
       </div>

       <div className="mb-8 p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 mb-2">
                    <Sparkles size={20} className="text-fuchsia-400" />
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                </div>
                <h2 className="text-2xl font-black leading-tight">
                    {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                </h2>
                {!syncedProject && (
                    <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10">
                        <Link size={14} /> 关联现有排单项目
                    </button>
                )}
                {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
            </div>
       </div>

       <div className="space-y-4 relative">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-3xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group">
                <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors"><Plus size={28} /></div>
                <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
            </div>
          ) : (
            <div className="w-full p-4 border-2 border-fuchsia-300 rounded-3xl flex items-center justify-between bg-white shadow-xl animate-slide-up">
                <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                <div className="flex gap-2">
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                    <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                </div>
            </div>
          )}

          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-3xl flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                    <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                </div>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-2 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all">
                    <Trash2 size={20} />
                </button>
            </div>
          ))}
       </div>

       <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
           <div className="max-w-lg mx-auto pointer-events-auto">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                   <ChevronRight size={24} /> 确认阶段，设置休息日
               </button>
           </div>
       </div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;

  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      let validDaysFound = 0;
      while (validDaysFound < dayIndex) {
          if (!isDateBlocked(getYYYYMMDD(current))) validDaysFound++;
          if (validDaysFound === dayIndex) return getYYYYMMDD(current);
          current.setDate(current.getDate() + 1);
      }
      return getYYYYMMDD(current);
  };

  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr]);
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) { setIsAdding(false); return; }
    const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copy = [...stages];
      const content = copy[dragItem.current];
      copy.splice(dragItem.current, 1);
      copy.splice(dragOverItem.current, 0, content);
      setStages(copy);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) return;
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      setEstimates({ ...estimates, [stages[activeTimeIndex].id]: currentInputTime });
      if (activeTimeIndex > 0) {
          const next = activeTimeIndex - 1;
          setActiveTimeIndex(next);
          setCurrentInputTime(estimates[stages[next].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleDayComplete = (day: number) => {
      setLocalCompletedDays(prev => prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]);
  };

  // --- RENDERS ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all">
                <div className="bg-white/20 p-3 rounded-full"><Plus size={24} /></div>
                <div className="text-center"><h3 className="font-bold text-lg">创建新规划</h3></div>
             </button>
             <div className="space-y-4">
                 {sessions.map(session => (
                    <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all cursor-pointer group relative">
                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                        <p className="text-xs text-slate-400 mt-0.5">上次更新: {formatDate(session.lastUpdated)}</p>
                    </div>
                 ))}
             </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4">
                  <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl"><ChevronLeft size={20} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl"><ChevronRight size={20} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isToday = getYYYYMMDD(new Date()) === dStr;
                          return (
                              <div key={dStr} onClick={() => toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline underline-offset-4' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl">确认休息日，分配工期</button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期分配</div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'}`}><Hourglass size={28} /></div>
            </div>
            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isActive ? 'bg-white border-fuchsia-500 shadow-xl' : 'bg-white/50 border-slate-100 opacity-60'}`}>
                                    <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>{stage.title}</span>
                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2"><input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600" /><button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-2.5 rounded-xl"><ArrowUp size={20} /></button></div>
                                        ) : <span className="font-black text-fuchsia-600 text-xl">{estimates[stage.id] || '--'}</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
            <div className="fixed bottom-24 left-0 w-full px-5"><button onClick={() => setPlanningStep('finished')} disabled={Object.keys(estimates).length === 0} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold shadow-xl">完成规划</button></div>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                    </div>
                ))}
                <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                    <span className="font-bold text-slate-800 text-lg">总计工期</span>
                    <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>{currentPlannedDays} 天</span>
                </div>
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl"><Box size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- Done List / Time Boxing Mode ---
  if (planningStep === 'time-boxing') {
      const currentDay = localCompletedDays.length + 1;
      const progressPercent = (localCompletedDays.length / currentPlannedDays) * 100;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                  <button onClick={() => setMode('dashboard')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回</button>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-indigo-600 font-black text-xs bg-indigo-50 px-3 py-1.5 rounded-full flex items-center gap-2">
                      <Zap size={14} /> 每日复盘对比
                  </button>
              </div>

              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl mb-8 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
                  <div className="relative z-10">
                      <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Progress Dashboard</span>
                      <h2 className="text-4xl font-black mt-2">第 {currentDay} 天</h2>
                      <div className="mt-6 flex items-center justify-between mb-2">
                          <span className="text-xs font-bold text-slate-400">总体进度</span>
                          <span className="text-xs font-black text-indigo-400">{Math.round(progressPercent)}%</span>
                      </div>
                      <div className="w-full h-3 bg-white/10 rounded-full overflow-hidden">
                          <div className="h-full bg-indigo-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                      </div>
                  </div>
              </div>

              <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-4 px-2">今日 Done List</h3>
              <div className="space-y-4">
                  {stages.map((stage, idx) => {
                      const isCompleted = localCompletedDays.length >= (idx + 1); // Mock completion logic
                      return (
                          <div key={stage.id} className={`p-6 rounded-3xl border-2 transition-all flex items-center justify-between ${isCompleted ? 'bg-emerald-50 border-emerald-100 opacity-60' : 'bg-white border-slate-100 shadow-sm'}`}>
                              <div className="flex items-center gap-4">
                                  <div className={`p-3 rounded-2xl ${isCompleted ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
                                      {isCompleted ? <Check size={20} /> : <PenTool size={20} />}
                                  </div>
                                  <div>
                                      <h4 className="font-black text-slate-800">{stage.title}</h4>
                                      <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase">ESTIMATED: {estimates[stage.id]} DAYS</p>
                                  </div>
                              </div>
                              {!isCompleted && (
                                  <button onClick={() => toggleDayComplete(currentDay)} className="bg-slate-900 text-white p-3 rounded-2xl shadow-lg active:scale-90 transition-all"><ThumbsUp size={20} /></button>
                              )}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- Daily Comparison Mode ---
  if (planningStep === 'daily-comparison') {
      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
              <h2 className="text-2xl font-black text-slate-800 mb-2">进度对比复盘</h2>
              <p className="text-slate-400 text-sm mb-8">理想 vs 现实的差距是灵感的温床</p>

              <div className="space-y-8">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative">
                          <div className="flex justify-between items-center mb-4">
                              <h4 className="font-black text-slate-800 text-lg">{stage.title}</h4>
                              <span className="text-xs font-bold text-slate-400">PLAN: {estimates[stage.id]} 天</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4">
                              <div className="bg-indigo-50 p-4 rounded-2xl border border-indigo-100">
                                  <span className="text-[10px] font-black text-indigo-400 uppercase">原本规划</span>
                                  <div className="text-2xl font-black text-indigo-600 mt-1">{estimates[stage.id]} 天</div>
                              </div>
                              <div className="bg-emerald-50 p-4 rounded-2xl border border-emerald-100">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase">实际耗时</span>
                                  <div className="text-2xl font-black text-emerald-600 mt-1">-- 天</div>
                              </div>
                          </div>
                          <div className="mt-4 flex items-center gap-2 bg-slate-50 p-3 rounded-xl">
                              <Smile size={14} className="text-slate-400" />
                              <span className="text-[10px] font-bold text-slate-500">状态：未完成此阶段，实际耗时待记录。</span>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      );
  }

  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
       </div>
       <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="relative z-10">
                <h2 className="text-2xl font-black leading-tight">{syncedProject ? `${syncedProject.clientName} 规划` : '自定义创作节奏'}</h2>
                {!syncedProject && (
                    <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 px-4 py-2 rounded-xl text-xs font-bold"><Link size={14} /> 关联项目</button>
                )}
                {showSyncInput && <div className="mt-4 flex gap-2"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="排单 ID" className="flex-1 text-sm bg-white/10 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
            </div>
       </div>
       <div className="space-y-4">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-3xl flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 transition-all"><Plus size={28} /><span className="text-xs font-black uppercase ml-4">添加绘画阶段</span></div>
          ) : (
            <div className="w-full p-4 border-2 border-fuchsia-300 rounded-3xl flex items-center justify-between bg-white animate-slide-up"><input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" /><div className="flex gap-2"><button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button><button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl"><Check size={20} /></button></div></div>
          )}
          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-3xl flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab group transition-all">
                <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                <div className="flex flex-col"><span className="text-[10px] font-black text-slate-300 uppercase">Phase {index + 1}</span><span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span></div>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-2 text-slate-200 hover:text-rose-500"><Trash2 size={20} /></button>
            </div>
          ))}
       </div>
       <div className="fixed bottom-24 left-0 w-full px-5"><button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3"><ChevronRight size={24} /> 确认阶段，设置休息日</button></div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft, Target, Rocket } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;
  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a, b) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr]);
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) { setIsAdding(false); return; }
    const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copy = [...stages];
      const content = copy[dragItem.current];
      copy.splice(dragItem.current, 1);
      copy.splice(dragOverItem.current, 0, content);
      setStages(copy);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) return;
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      setEstimates({ ...estimates, [stages[activeTimeIndex].id]: currentInputTime });
      if (activeTimeIndex > 0) {
          const next = activeTimeIndex - 1;
          setActiveTimeIndex(next);
          setCurrentInputTime(estimates[stages[next].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleDayComplete = (day: number) => {
      setLocalCompletedDays(prev => {
          const next = prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day];
          // Update in persistence if we have an ID
          if (currentSessionId) {
              const updated = sessions.map(s => s.id === currentSessionId ? { ...s, completedDays: next, lastUpdated: new Date().toISOString() } : s);
              persistSessions(updated);
          }
          return next;
      });
  };

  // --- RENDERS ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((session.completedDays.length / Object.values(session.estimates).reduce((a, b) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- STEP: OFF DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                    <p className="text-[10px] text-rose-500 font-bold uppercase tracking-widest">设定你的喘息时刻</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-100 rounded-xl"><ChevronLeft size={20} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-100 rounded-xl"><ChevronRight size={20} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isToday = getYYYYMMDD(new Date()) === dStr;
                          return (
                              <div key={dStr} onClick={() => toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer active:scale-95 transition-all ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 shadow-inner' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline underline-offset-4 decoration-2' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8 border border-slate-100">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-[11px] text-slate-500 font-medium leading-relaxed">选中的日期将从工期计算中扣除。P人也要记得休息哦！</p>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  // --- STEP: TIME ENTRY ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100">工期分配</div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'}`}><Hourglass size={28} /></div>
            </div>
            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isActive ? 'bg-white border-fuchsia-500 shadow-xl' : 'bg-white/50 border-slate-100 opacity-60 hover:opacity-100'}`}>
                                    <div className="flex flex-col">
                                        <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>{stage.title}</span>
                                        {isActive && <span className="text-[10px] text-fuchsia-500 font-bold uppercase mt-1">输入预计耗时 (天)</span>}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2"><input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} /><button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-2.5 rounded-xl"><ArrowUp size={20} /></button></div>
                                        ) : <span className="font-black text-fuchsia-600 text-xl">{estimates[stage.id] || '--'}</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
            <div className="fixed bottom-24 left-0 w-full px-5"><button onClick={() => setPlanningStep('finished')} disabled={Object.keys(estimates).length === 0} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">完成所有工期分配</button></div>
        </div>
    );
  }

  // --- STEP: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <p className="text-slate-400 text-sm mb-8">最佳路径已计算完毕</p>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                    </div>
                ))}
                <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                    <span className="font-bold text-slate-800 text-lg">总计工期</span>
                    <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>{currentPlannedDays} 天</span>
                </div>
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Box size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- STEP: TIME BOXING (DONE LIST) ---
  if (planningStep === 'time-boxing') {
      const currentDay = localCompletedDays.length + 1;
      const progressPercent = (localCompletedDays.length / currentPlannedDays) * 100;

      // Calculate which stage we are currently in based on currentDay
      let daySum = 0;
      let currentStageIndex = 0;
      for (let i = 0; i < stages.length; i++) {
          const est = Number(estimates[stages[i].id]) || 0;
          daySum += est;
          if (currentDay <= daySum) {
              currentStageIndex = i;
              break;
          }
      }

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                  <button onClick={() => setMode('dashboard')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回列表</button>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full flex items-center gap-2 border border-fuchsia-100 active:scale-95 transition-all">
                      <Zap size={14} /> 进度复盘
                  </button>
              </div>

              {/* Today's Focus Card */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl mb-8 relative overflow-hidden">
                  <div className="absolute -top-10 -right-10 w-48 h-48 bg-fuchsia-500 rounded-full opacity-10"></div>
                  <div className="relative z-10">
                      <div className="flex justify-between items-start mb-6">
                        <div className="bg-white/10 px-3 py-1 rounded-full"><span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest">Day {currentDay} of {currentPlannedDays}</span></div>
                        <Rocket size={24} className="text-fuchsia-400" />
                      </div>
                      <h2 className="text-4xl font-black tracking-tight mb-2">第 {currentDay} 天</h2>
                      <p className="text-slate-400 font-bold mb-8">当前目标: <span className="text-white">{stages[currentStageIndex]?.title}</span></p>

                      <div className="space-y-2">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inspiration Progress</span>
                            <span className="text-sm font-black text-fuchsia-400">{Math.round(progressPercent)}%</span>
                        </div>
                        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-fuchsia-600 to-indigo-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                        </div>
                      </div>
                  </div>
              </div>

              {/* Done List: Sequence of Days */}
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2 flex items-center gap-2">
                <Target size={14} /> 规划日 Done List
              </h3>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const isCompleted = localCompletedDays.includes(dayNum);
                      const isCurrent = dayNum === currentDay;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => toggleDayComplete(dayNum)}
                            className={`p-6 rounded-[2rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isCompleted ? 'bg-emerald-50 border-emerald-100' : 
                                  isCurrent ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 ring-4 ring-fuchsia-50/50' : 
                                  'bg-white border-slate-100 opacity-60'}`}
                          >
                              <div className="relative z-10 flex flex-col items-center">
                                  <span className={`text-[10px] font-black mb-1 uppercase tracking-widest ${isCompleted ? 'text-emerald-400' : isCurrent ? 'text-fuchsia-400' : 'text-slate-300'}`}>Day</span>
                                  <span className={`text-3xl font-black ${isCompleted ? 'text-emerald-600' : isCurrent ? 'text-slate-800' : 'text-slate-200'}`}>{dayNum}</span>
                                  <div className={`mt-3 p-2 rounded-xl transition-all ${isCompleted ? 'bg-emerald-500 text-white' : isCurrent ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-200'}`}>
                                      {isCompleted ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                              {isCurrent && <div className="absolute top-2 right-2 w-2 h-2 bg-fuchsia-500 rounded-full animate-ping"></div>}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- STEP: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const completedCount = localCompletedDays.length;
      const plannedTotal = currentPlannedDays;
      const status = completedCount >= plannedTotal ? 'ahead' : 'working';

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感复盘对比</h2>
                <p className="text-slate-400 text-sm mt-1 font-medium">理想进度 vs 现实节奏</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                              <div className="flex items-center gap-3">
                                <div className="p-3 bg-fuchsia-100 text-fuchsia-600 rounded-2xl"><PenTool size={20} /></div>
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                              </div>
                              <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4 mb-6">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1">原本规划</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">目前已用</span>
                                  {/* Since we don't track stage-specific completion in this simple logic, we show a mock or summary */}
                                  <div className="text-3xl font-black text-emerald-600">-- <span className="text-xs">天</span></div>
                              </div>
                          </div>

                          <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-dashed border-slate-200">
                              <div className="bg-white p-2 rounded-full text-slate-400 shadow-sm"><Smile size={16} /></div>
                              <span className="text-xs font-bold text-slate-500 leading-tight">
                                {status === 'ahead' ? '进度喜人！你在这个阶段的创作速度惊人。' : '正在这个阶段稳步推进中...'}
                              </span>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-8 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent)]"></div>
                <h3 className="text-xl font-black mb-2 flex items-center gap-2"><Sparkles size={20} /> 创作寄语</h3>
                <p className="text-sm text-indigo-100 font-medium leading-relaxed opacity-90">
                  规划只是灵感的骨架，真正的艺术是在现实的起伏中开出的花。不论快慢，保持画笔不停即是胜利。
                </p>
              </div>
          </div>
      );
  }

  // --- STEP: INITIAL SETUP ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
            <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
       </div>

       <div className="mb-8 p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 mb-2">
                    <Sparkles size={20} className="text-fuchsia-400" />
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                </div>
                <h2 className="text-2xl font-black leading-tight">
                    {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                </h2>
                {!syncedProject && (
                    <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10 active:scale-95">
                        <Link size={14} /> 关联现有排单项目
                    </button>
                )}
                {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black active:scale-90 transition-all">同步</button></div>}
            </div>
       </div>

       <div className="space-y-4 relative mb-12">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group active:scale-95">
                <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors shadow-sm"><Plus size={28} /></div>
                <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
            </div>
          ) : (
            <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                <div className="flex gap-2">
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                    <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                </div>
            </div>
          )}

          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">Phase {index + 1}</span>
                    <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                </div>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all active:scale-90">
                    <Trash2 size={20} />
                </button>
            </div>
          ))}
       </div>

       <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
           <div className="max-w-lg mx-auto pointer-events-auto">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                   <ChevronRight size={24} /> 确认阶段，设置休息日
               </button>
           </div>
       </div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, AlertCircle, ChevronLeft, Target, Rocket } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;
  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;

  // FIX: Explicitly typed accumulator 'a' to avoid 'unknown' inference in reduce
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a: number, b: number) => a + b, 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr]);
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) { setIsAdding(false); return; }
    const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copy = [...stages];
      const content = copy[dragItem.current];
      copy.splice(dragItem.current, 1);
      copy.splice(dragOverItem.current, 0, content);
      setStages(copy);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) return;
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      setEstimates({ ...estimates, [stages[activeTimeIndex].id]: currentInputTime });
      if (activeTimeIndex > 0) {
          const next = activeTimeIndex - 1;
          setActiveTimeIndex(next);
          setCurrentInputTime(estimates[stages[next].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleDayComplete = (day: number) => {
      setLocalCompletedDays(prev => {
          const next = prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day];
          // Update in persistence if we have an ID
          if (currentSessionId) {
              const updated = sessions.map(s => s.id === currentSessionId ? { ...s, completedDays: next, lastUpdated: new Date().toISOString() } : s);
              persistSessions(updated);
          }
          return next;
      });
  };

  // --- RENDERS ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1">管理你的创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 border-2 border-slate-900 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {/* FIX: Explicitly typed accumulator 'a' to number to resolve 'unknown' operator error (Line 230) */}
                                    {Math.round((session.completedDays.length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- STEP: OFF DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                    <p className="text-[10px] text-rose-500 font-bold uppercase tracking-widest">设定你的喘息时刻</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-100 rounded-xl"><ChevronLeft size={20} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-100 rounded-xl"><ChevronRight size={20} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isToday = getYYYYMMDD(new Date()) === dStr;
                          return (
                              <div key={dStr} onClick={() => toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer active:scale-95 transition-all ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 shadow-inner' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline underline-offset-4 decoration-2' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8 border border-slate-100">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-[11px] text-slate-500 font-medium leading-relaxed">选中的日期将从工期计算中扣除。P人也要记得休息哦！</p>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  // --- STEP: TIME ENTRY ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100">工期分配</div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'}`}><Hourglass size={28} /></div>
            </div>
            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isActive ? 'bg-white border-fuchsia-500 shadow-xl' : 'bg-white/50 border-slate-100 opacity-60 hover:opacity-100'}`}>
                                    <div className="flex flex-col">
                                        <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>{stage.title}</span>
                                        {isActive && <span className="text-[10px] text-fuchsia-500 font-bold uppercase mt-1">输入预计耗时 (天)</span>}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2"><input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} /><button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-2.5 rounded-xl"><ArrowUp size={20} /></button></div>
                                        ) : <span className="font-black text-fuchsia-600 text-xl">{estimates[stage.id] || '--'}</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
            <div className="fixed bottom-24 left-0 w-full px-5"><button onClick={() => setPlanningStep('finished')} disabled={Object.keys(estimates).length === 0} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">完成所有工期分配</button></div>
        </div>
    );
  }

  // --- STEP: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <p className="text-slate-400 text-sm mb-8">最佳路径已计算完毕</p>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                    </div>
                ))}
                <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                    <span className="font-bold text-slate-800 text-lg">总计工期</span>
                    <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>{currentPlannedDays} 天</span>
                </div>
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Box size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- STEP: TIME BOXING (DONE LIST) ---
  if (planningStep === 'time-boxing') {
      const currentDay = localCompletedDays.length + 1;
      const progressPercent = (localCompletedDays.length / currentPlannedDays) * 100;

      // Calculate which stage we are currently in based on currentDay
      let daySum = 0;
      let currentStageIndex = 0;
      for (let i = 0; i < stages.length; i++) {
          const est = Number(estimates[stages[i].id]) || 0;
          daySum += est;
          if (currentDay <= daySum) {
              currentStageIndex = i;
              break;
          }
      }

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                  <button onClick={() => setMode('dashboard')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回列表</button>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full flex items-center gap-2 border border-fuchsia-100 active:scale-95 transition-all">
                      <Zap size={14} /> 进度复盘
                  </button>
              </div>

              {/* Today's Focus Card */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl mb-8 relative overflow-hidden">
                  <div className="absolute -top-10 -right-10 w-48 h-48 bg-fuchsia-500 rounded-full opacity-10"></div>
                  <div className="relative z-10">
                      <div className="flex justify-between items-start mb-6">
                        <div className="bg-white/10 px-3 py-1 rounded-full"><span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest">Day {currentDay} of {currentPlannedDays}</span></div>
                        <Rocket size={24} className="text-fuchsia-400" />
                      </div>
                      <h2 className="text-4xl font-black tracking-tight mb-2">第 {currentDay} 天</h2>
                      <p className="text-slate-400 font-bold mb-8">当前目标: <span className="text-white">{stages[currentStageIndex]?.title}</span></p>

                      <div className="space-y-2">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inspiration Progress</span>
                            <span className="text-sm font-black text-fuchsia-400">{Math.round(progressPercent)}%</span>
                        </div>
                        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-fuchsia-600 to-indigo-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                        </div>
                      </div>
                  </div>
              </div>

              {/* Done List: Sequence of Days */}
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2 flex items-center gap-2">
                <Target size={14} /> 规划日 Done List
              </h3>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const isCompleted = localCompletedDays.includes(dayNum);
                      const isCurrent = dayNum === currentDay;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => toggleDayComplete(dayNum)}
                            className={`p-6 rounded-[2rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isCompleted ? 'bg-emerald-50 border-emerald-100' : 
                                  isCurrent ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 ring-4 ring-fuchsia-50/50' : 
                                  'bg-white border-slate-100 opacity-60'}`}
                          >
                              <div className="relative z-10 flex flex-col items-center">
                                  <span className={`text-[10px] font-black mb-1 uppercase tracking-widest ${isCompleted ? 'text-emerald-400' : isCurrent ? 'text-fuchsia-400' : 'text-slate-300'}`}>Day</span>
                                  <span className={`text-3xl font-black ${isCompleted ? 'text-emerald-600' : isCurrent ? 'text-slate-800' : 'text-slate-200'}`}>{dayNum}</span>
                                  <div className={`mt-3 p-2 rounded-xl transition-all ${isCompleted ? 'bg-emerald-500 text-white' : isCurrent ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-200'}`}>
                                      {isCompleted ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                              {isCurrent && <div className="absolute top-2 right-2 w-2 h-2 bg-fuchsia-500 rounded-full animate-ping"></div>}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- STEP: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const completedCount = localCompletedDays.length;
      const plannedTotal = currentPlannedDays;
      const status = completedCount >= plannedTotal ? 'ahead' : 'working';

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感复盘对比</h2>
                <p className="text-slate-400 text-sm mt-1 font-medium">理想进度 vs 现实节奏</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                              <div className="flex items-center gap-3">
                                <div className="p-3 bg-fuchsia-100 text-fuchsia-600 rounded-2xl"><PenTool size={20} /></div>
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                              </div>
                              <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4 mb-6">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1">原本规划</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">目前已用</span>
                                  {/* Since we don't track stage-specific completion in this simple logic, we show a mock or summary */}
                                  <div className="text-3xl font-black text-emerald-600">-- <span className="text-xs">天</span></div>
                              </div>
                          </div>

                          <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-dashed border-slate-200">
                              <div className="bg-white p-2 rounded-full text-slate-400 shadow-sm"><Smile size={16} /></div>
                              <span className="text-xs font-bold text-slate-500 leading-tight">
                                {status === 'ahead' ? '进度喜人！你在这个阶段的创作速度惊人。' : '正在这个阶段稳步推进中...'}
                              </span>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-8 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent)]"></div>
                <h3 className="text-xl font-black mb-2 flex items-center gap-2"><Sparkles size={20} /> 创作寄语</h3>
                <p className="text-sm text-indigo-100 font-medium leading-relaxed opacity-90">
                  规划只是灵感的骨架，真正的艺术是在现实的起伏中开出的花。不论快慢，保持画笔不停即是胜利。
                </p>
              </div>
          </div>
      );
  }

  // --- STEP: INITIAL SETUP ---
  return (
    <div className="animate-fade-in pb-32">
       <div className="flex justify-between items-center mb-6">
            <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
            <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
       </div>

       <div className="mb-8 p-6 bg-gradient-to-br from-slate-900 to-slate-800 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
            <div className="relative z-10">
                <div className="flex items-center gap-2 mb-2">
                    <Sparkles size={20} className="text-fuchsia-400" />
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                </div>
                <h2 className="text-2xl font-black leading-tight">
                    {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                </h2>
                {!syncedProject && (
                    <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10 active:scale-95">
                        <Link size={14} /> 关联现有排单项目
                    </button>
                )}
                {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black active:scale-90 transition-all">同步</button></div>}
            </div>
       </div>

       <div className="space-y-4 relative mb-12">
          {!isAdding ? (
            <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group active:scale-95">
                <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors shadow-sm"><Plus size={28} /></div>
                <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
            </div>
          ) : (
            <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                <div className="flex gap-2">
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                    <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                </div>
            </div>
          )}

          {stages.map((stage, index) => (
            <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">Phase {index + 1}</span>
                    <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                </div>
                <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all active:scale-90">
                    <Trash2 size={20} />
                </button>
            </div>
          ))}
       </div>

       <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
           <div className="max-w-lg mx-auto pointer-events-auto">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                   <ChevronRight size={24} /> 确认阶段，设置休息日
               </button>
           </div>
       </div>
    </div>
  );
};

export default PTypePlanner;

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [planningMode, setPlanningMode] = useState<'selection' | 'j-type' | 'p-type'>('selection');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>(''); // NEW: Client ID
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // WeChat User State (Port for Mini Program)
  const [wechatUser, setWechatUser] = useState<{nickname: string, avatar?: string} | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', // NEW
    description: '',
    startDate: '',
    deadline: ''
  });

  // Initialization: Load or Create IDs
  useEffect(() => {
    // Artist ID
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    // Client ID
    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    // Load Connected Artist ID (Persistence)
    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }
  }, []);

  // Determine current active Data Source ID based on View Mode
  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  // Load Data when ID or Mode changes
  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      return;
    }

    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
  }, [currentDataId, viewMode]);

  // Persist Data (Simulate Backend)
  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;

    if (searchId === myArtistId) {
       setConnectedArtistId(searchId);
       localStorage.setItem('artflow_connected_artist_id', searchId);
       return;
    }

    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    // Ideally we verify if it exists, but for local simulation we act as if it might
    if (targetProjects) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接（假设其存在）？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  // --- WeChat Login Port ---
  const handleWeChatLogin = () => {
    alert("微信登录接口已预留。小程序发布后将在此处调用 wx.login 同步账户信息。");
    setWechatUser({ nickname: "微信用户", avatar: "" });
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;

    if (editingProjectId) {
      setProjects(projects.map(p => 
        p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
        } : p
      ));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || 'No description',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }

    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({
      clientName: project.clientName,
      targetClientId: project.targetClientId,
      description: project.description,
      startDate: project.startDate,
      deadline: project.deadline
    });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;
    if(confirm('Delete this project?')) {
        setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');

    const response = await analyzeSchedule(projects, bookings, aiQuery);

    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制到剪贴板`);
  };

  // Switch Mode Handler
  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') {
      handleDisconnect();
    }
  };

  // Filter projects based on mode
  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  // Filter based on sub-tab
  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex flex-col">

      {/* Mobile Sticky Header */}
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm transition-all">
        <div className="flex justify-between items-center mb-3 md:mb-0">
          <div className="flex items-center gap-2.5">
            <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-indigo-200 shadow-lg">
              <Paintbrush size={18} />
            </div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight hidden md:block">
              ArtFlow
            </h1>
          </div>

          <div className="flex items-center gap-3">
             {viewMode === 'artist' && (
                <button 
                  onClick={() => setShowAI(!showAI)}
                  className={`p-2 rounded-full transition-colors ${showAI ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 text-slate-400'}`}
                >
                  <Sparkles size={20} />
                </button>
             )}
            <button 
                onClick={toggleViewMode}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full transition-all border ${viewMode === 'artist' ? 'bg-slate-800 text-white border-slate-800' : 'bg-indigo-600 text-white border-indigo-600'}`}
            >
                {viewMode === 'artist' ? <><Paintbrush size={12}/> 画手模式</> : <><UserCircle2 size={14}/> 单主模式</>}
            </button>
          </div>
        </div>

        {/* Dynamic Sub-Header Area */}
        <div className="w-full">
           {viewMode === 'artist' ? (
             <div className="flex items-center justify-between bg-slate-50 rounded-lg p-1.5 border border-slate-100">
               <div className="flex items-center gap-2 flex-1 min-w-0">
                  {wechatUser ? (
                      <div className="flex items-center gap-1.5 pl-1.5 bg-emerald-100/50 py-1 px-2 rounded-md">
                          <MessageCircle size={12} className="text-emerald-600" fill="currentColor" fillOpacity={0.2} />
                          <span className="text-xs font-bold text-emerald-800 truncate max-w-[80px]">{wechatUser.nickname}</span>
                      </div>
                  ) : (
                      <button 
                        onClick={handleWeChatLogin}
                        className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg transition-all shadow-sm shadow-emerald-200 active:scale-95"
                      >
                         <MessageCircle size={12} fill="currentColor" fillOpacity={0.2} />
                         <span className="text-[10px] font-bold">微信登录</span>
                      </button>
                  )}

                  <div className="flex items-center gap-1 min-w-0 flex-1 justify-end mr-2">
                     <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">ID</span>
                     <span className="text-xs text-slate-800 font-bold font-mono truncate">{myArtistId}</span>
                  </div>
               </div>

               <button onClick={() => copyText(myArtistId, 'Artist ID')} className="p-1.5 bg-white shadow-sm border border-slate-100 rounded-md text-slate-400 hover:text-indigo-600 transition-colors flex-shrink-0">
                 <Copy size={14} />
               </button>
             </div>
           ) : (
             <div className="flex gap-2">
               {!connectedArtistId ? (
                 <>
                  <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      value={searchId}
                      onChange={(e) => setSearchId(e.target.value)}
                      placeholder="搜索画手 ID (如: ART-1234)"
                      className="w-full bg-slate-100 border-none rounded-lg pl-9 pr-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
                  <button 
                    onClick={handleSearchArtist}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap"
                  >
                    连接
                  </button>
                 </>
               ) : (
                 <div className="flex items-center justify-between w-full bg-indigo-50 rounded-lg p-2 border border-indigo-100">
                    <span className="text-xs text-indigo-800 font-medium px-2 flex items-center gap-1">
                      <span className="opacity-60">已连接:</span> 
                      <span className="font-bold">{connectedArtistId}</span>
                    </span>
                    <button 
                      onClick={handleDisconnect}
                      className="flex items-center gap-1 bg-white px-2 py-1 rounded text-[10px] font-bold text-slate-500 shadow-sm"
                    >
                      <LogOut size={10} /> 退出
                    </button>
                 </div>
               )}
             </div>
           )}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 w-full max-w-lg mx-auto p-5 pb-32">

        {/* Client Mode - Initial State (Show ID) */}
        {viewMode === 'client' && !connectedArtistId && (
           <div className="flex flex-col items-center justify-center mt-10 animate-fade-in">
              <div className="w-full bg-white rounded-2xl shadow-xl shadow-slate-100 border border-slate-100 p-6 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-20 h-20 bg-indigo-50 rounded-bl-full -mr-10 -mt-10"></div>
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint className="text-indigo-600" size={24} />
                  <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider">我的单主 ID</h3>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-3xl font-black text-slate-800 tracking-tight">{myClientId}</span>
                  <button 
                    onClick={() => copyText(myClientId, '单主 ID')}
                    className="bg-indigo-50 text-indigo-600 p-2 rounded-lg hover:bg-indigo-100 transition-colors"
                    title="复制"
                  >
                    <Copy size={18} />
                  </button>
                </div>
                <p className="text-xs text-slate-400 mt-3 leading-relaxed">
                  请将此 ID 发送给画手。画手为您新建排单时填入此 ID，您连接后即可同步看到进度。
                </p>
              </div>

              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="text-slate-400 text-sm text-center max-w-[200px]">
                在上方搜索框输入画手 ID 开始连接
              </p>
           </div>
        )}

        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg shadow-indigo-100/50 animate-fade-in">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm">
                    <Sparkles size={14} className="text-indigo-500" /> 智能助理
                  </h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400 hover:text-slate-600">
                    <X size={16} />
                  </button>
                </div>

                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">
                  {isAiLoading ? (
                    <div className="flex items-center gap-2 text-indigo-500">
                      <div className="animate-spin h-3 w-3 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                      正在思考中...
                    </div>
                  ) : (
                    aiResponse || "你好！我是你的排单助手。可以问我关于档期安排、截稿压力的问题。"
                  )}
                </div>

                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={aiQuery}
                    onChange={(e) => setAiQuery(e.target.value)}
                    placeholder="问问我：下周还能接急单吗？"
                    className="flex-1 text-sm rounded-lg bg-white border border-slate-200 px-3 py-2.5 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()}
                  />
                  <button 
                    onClick={handleAiAsk}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                  >
                    发送
                  </button>
                </div>
              </div>
            )}

            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-4">
                <div className="flex flex-col gap-4">
                   <div className="flex justify-between items-end px-1">
                      <div>
                        <h2 className="text-xl font-bold text-slate-800">
                          {viewMode === 'artist' ? '我的排单' : '我的订单'}
                        </h2>
                        <p className="text-slate-400 text-xs mt-1">
                          {viewMode === 'artist' ? '关注颜色变化，避免延期' : `仅展示关联 ID: ${myClientId} 的项目`}
                        </p>
                      </div>
                      {viewMode === 'artist' && (
                        <button 
                          onClick={() => setShowAddModal(true)}
                          className="hidden md:flex bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold shadow-lg hover:scale-105 transition-transform gap-2 items-center"
                        >
                          <Plus size={16} /> 新建
                        </button>
                      )}
                   </div>

                   <div className="flex p-1 bg-slate-200/50 rounded-xl">
                      <button 
                        onClick={() => setProjectSubTab('active')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                         <Clock size={16} />
                         进行中
                         {allVisibleProjects.filter(p => p.status !== 'completed').length > 0 && (
                            <span className="bg-indigo-100 text-indigo-600 text-[10px] px-1.5 py-0.5 rounded-full ml-1">
                               {allVisibleProjects.filter(p => p.status !== 'completed').length}
                            </span>
                         )}
                      </button>
                      <button 
                        onClick={() => setProjectSubTab('completed')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                         <CheckCircle2 size={16} />
                         已完成
                         {allVisibleProjects.filter(p => p.status === 'completed').length > 0 && (
                            <span className="bg-emerald-100 text-emerald-600 text-[10px] px-1.5 py-0.5 rounded-full ml-1">
                               {allVisibleProjects.filter(p => p.status === 'completed').length}
                            </span>
                         )}
                      </button>
                   </div>
                </div>

                <div className="space-y-3 min-h-[200px]">
                  {displayedProjects.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-16 text-slate-400 bg-white rounded-2xl border border-dashed border-slate-200 mt-2">
                      <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-3">
                        {projectSubTab === 'active' ? <Paintbrush size={20} className="opacity-50" /> : <CheckCircle2 size={20} className="opacity-50" />}
                      </div>
                      <p className="text-sm font-medium">
                        {projectSubTab === 'active' ? '暂无进行中的约稿' : '暂无已完成的记录'}
                      </p>
                    </div>
                  )}

                  {displayedProjects
                    .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                    .map(project => (
                      <ProjectCard 
                        key={project.id} 
                        project={project} 
                        onComplete={handleCompleteProject}
                        onDelete={handleDeleteProject}
                        onEdit={handleEditProject}
                        readOnly={viewMode === 'client'}
                      />
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'schedule' && (
              <div className="animate-fade-in">
