import React, { useState } from 'react';
import { BookingSlot, ViewMode, Project } from '../types';
import { ShieldBan, Check, Lock, X, ChevronLeft, ChevronRight, Calendar } from 'lucide-react';
import { getProjectLineColor } from '../utils';

interface ScheduleBoardProps {
  bookings: BookingSlot[];
  projects: Project[];
  mode: ViewMode;
  onUpdateBookings: (bookings: BookingSlot[]) => void;
  currentClientId?: string;
  currentClientName?: string;
}

const ScheduleBoard: React.FC<ScheduleBoardProps> = ({ 
  bookings, 
  projects, 
  mode, 
  onUpdateBookings,
  currentClientId,
  currentClientName 
}) => {
  const [viewDate, setViewDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [bookingNote, setBookingNote] = useState('');
  const [viewDetailsDate, setViewDetailsDate] = useState<string | null>(null);

  // Helper to get local YYYY-MM-DD string
  const getLocalYYYYMMDD = (d: Date) => {
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const getMonthDays = () => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    const firstDayOfMonth = new Date(year, month, 1);
    const lastDayOfMonth = new Date(year, month + 1, 0);

    const days = [];
    // Padding for start of month
    for (let i = 0; i < firstDayOfMonth.getDay(); i++) {
      days.push(null);
    }
    // Days of month
    for (let i = 1; i <= lastDayOfMonth.getDate(); i++) {
      days.push(new Date(year, month, i));
    }
    return days;
  };

  const days = getMonthDays();
  const getSlot = (date: string) => bookings.find(b => b.date === date);

  const getProjectsOnDate = (dateStr: string) => {
    const targetDate = new Date(dateStr + 'T00:00:00'); 
    return projects.filter(p => {
       if (p.status === 'completed') return false;
       if (mode === 'client' && p.targetClientId !== currentClientId) return false;
       const start = new Date(p.startDate);
       const end = new Date(p.deadline);
       const startDay = new Date(start.getFullYear(), start.getMonth(), start.getDate());
       const endDay = new Date(end.getFullYear(), end.getMonth(), end.getDate());
       return targetDate >= startDay && targetDate <= endDay;
    }).sort((a, b) => new Date(a.startDate).getTime() - new Date(b.startDate).getTime());
  };

  const isMySlot = (clientId?: string, bookedBy?: string) => {
    if (mode === 'artist') return true;
    if (currentClientId && clientId === currentClientId) return true;
    if (bookedBy && currentClientName && bookedBy.toLowerCase() === currentClientName.toLowerCase()) return true;
    return false;
  };

  const handleDayClick = (date: string) => {
    const slot = getSlot(date);
    if (mode === 'artist') {
      if (slot?.actualHours && slot.actualHours.length > 0) {
          setViewDetailsDate(date);
          return;
      }
      const newBookings = [...bookings];
      const index = newBookings.findIndex(b => b.date === date);
      if (index >= 0) {
        if (newBookings[index].status === 'blocked') {
          newBookings.splice(index, 1);
        } else if(confirm("该日期已有预约，确定要清除吗？")) {
             newBookings.splice(index, 1);
        }
      } else {
        newBookings.push({ date, status: 'blocked' });
      }
      onUpdateBookings(newBookings);
    } else {
      if (slot?.status === 'blocked' || slot?.status === 'booked') return;
      setSelectedDate(date);
      setBookingNote('');
    }
  };

  const handleClientBook = () => {
    if (!selectedDate) return;
    const newBookings = [...bookings, {
      date: selectedDate,
      status: 'booked' as const,
      bookedBy: currentClientName || 'Client',
      clientId: currentClientId,
      note: bookingNote
    }];
    onUpdateBookings(newBookings);
    setSelectedDate(null);
    alert('预约申请已提交！');
  };

  const changeMonth = (offset: number) => {
    const newDate = new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1);
    setViewDate(newDate);
  };

  return (
    <div className="p-5 bg-white rounded-3xl shadow-sm border border-slate-100">
      <div className="flex justify-between items-center mb-6 px-1">
        <div>
           <h2 className="text-xl font-black text-slate-800 tracking-tight flex items-center gap-2">
            排期日历
          </h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">
            {viewDate.toLocaleString('zh-CN', { year: 'numeric', month: 'long' })}
          </p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => changeMonth(-1)} className="p-2 bg-slate-50 hover:bg-slate-100 rounded-xl transition-colors"><ChevronLeft size={18} /></button>
          <button onClick={() => changeMonth(1)} className="p-2 bg-slate-50 hover:bg-slate-100 rounded-xl transition-colors"><ChevronRight size={18} /></button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-1.5 mb-2">
        {['日', '一', '二', '三', '四', '五', '六'].map(d => (
            <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase tracking-widest py-1">{d}</div>
        ))}
        {days.map((dateObj, idx) => {
          if (!dateObj) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;

          const date = getLocalYYYYMMDD(dateObj);
          const slot = getSlot(date);
          const projectsOnDay = getProjectsOnDate(date);
          const status = slot?.status;
          const isToday = getLocalYYYYMMDD(new Date()) === date;
          const isMine = isMySlot(slot?.clientId, slot?.bookedBy);
          const hasActualHours = slot?.actualHours && slot.actualHours.length > 0;

          let bgClass = 'bg-white border-slate-100 text-slate-700 hover:bg-slate-50';
          let contentIcon = null;

          if (status === 'blocked') {
             bgClass = 'bg-slate-100 border-slate-200 text-slate-400 shadow-inner';
             contentIcon = <Lock size={10} className="opacity-20 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
          } else if (status === 'booked') {
             if (mode === 'client' && !isMine) {
                bgClass = 'bg-slate-100 border-slate-100 text-slate-300';
             } else {
                bgClass = 'bg-indigo-600 border-indigo-600 text-white shadow-md shadow-indigo-200';
                contentIcon = <Check size={14} strokeWidth={3} className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />;
             }
          }

          if (hasActualHours && mode === 'artist') {
              bgClass = 'bg-emerald-50 border-emerald-200 text-emerald-800';
          }

          if (selectedDate === date) {
            bgClass = 'ring-2 ring-indigo-500 ring-offset-2 bg-indigo-500 text-white z-10';
          }

          return (
            <div 
              key={date}
              onClick={() => handleDayClick(date)}
              className={`aspect-square rounded-xl border flex flex-col relative transition-all duration-200 active:scale-95 overflow-hidden cursor-pointer ${bgClass}`}
            >
              <span className={`text-[10px] font-black p-1 leading-none ${isToday && !selectedDate ? 'text-indigo-600' : ''}`}>
                {dateObj.getDate()}
              </span>

              {contentIcon}

              <div className="mt-auto px-1 pb-1 flex flex-col gap-0.5 w-full">
                 {projectsOnDay.slice(0, 3).map((p, i) => (
                   <div key={p.id} className={`h-1 w-full rounded-full ${getProjectLineColor(p.startDate, p.deadline)}`} />
                 ))}
              </div>
            </div>
          );
        })}
      </div>

      {mode === 'client' && selectedDate && (
        <div className="mt-6 animate-slide-up bg-indigo-50 p-4 rounded-2xl border border-indigo-100">
          <div className="flex items-center gap-2 mb-3 text-xs font-black text-indigo-700 uppercase tracking-widest">
            预约: {selectedDate}
          </div>
          <div className="flex gap-2">
            <input 
              type="text" 
              placeholder="备注 (可选)"
              value={bookingNote}
              onChange={(e) => setBookingNote(e.target.value)}
              className="flex-1 bg-white border border-indigo-100 rounded-xl px-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button 
              onClick={handleClientBook}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-xs font-black shadow-lg shadow-indigo-200 hover:bg-indigo-700 transition-colors"
            >
              提交
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScheduleBoard;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'pre-comparison-confirm' | 'daily-comparison' | 'summary'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [selectedTimeBoxes, setSelectedTimeBoxes] = useState<string[]>([]);
  const [selectedActualHours, setSelectedActualHours] = useState<string[]>([]);
  const [currentComparisonDay, setCurrentComparisonDay] = useState(1);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && b.status === 'blocked');
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;
  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).map(val => Number(val)).reduce((a: number, b: string) => a + Number(b), 0);
  const isOverBudget = syncedProject ? currentPlannedDays > totalAvailableDays : false;

  const getTargetDateStr = (dayIndex: number) => {
      const start = getStartDate();
      let current = new Date(start);
      let validDaysFound = 0;
      while (validDaysFound < dayIndex) {
          if (!isDateBlocked(getYYYYMMDD(current))) validDaysFound++;
          if (validDaysFound === dayIndex) return getYYYYMMDD(current);
          current.setDate(current.getDate() + 1);
      }
      return getYYYYMMDD(current);
  };

