                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="排单 ID" className="flex-1 text-sm bg-white/10 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={() => { const p = projects?.find(x => x.id === syncId); if(p) {setSyncedProject(p); setShowSyncInput(false);} }} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>
           <div className="space-y-4">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all"><Plus size={28} /><span className="text-xs font-black uppercase ml-4">添加绘画阶段</span></div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white animate-slide-up"><input autoFocus type="text" placeholder="草稿..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([{id: Date.now().toString(), title: newStageTitle}, ...stages]), setNewStageTitle(''), setIsAdding(false))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" /><button onClick={() => setIsAdding(false)} className="p-3"><X size={20} /></button></div>
              )}
              {stages.map((stage, index) => (
                <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab group transition-all">
                    <div className="text-slate-200 group-hover:text-slate-400 mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col truncate"><span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span><span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span></div>
                    <button onClick={() => deleteStage(index)} className="absolute right-6 p-2 text-slate-200 hover:text-rose-500"><Trash2 size={20} /></button>
                </div>
              ))}
           </div>
           <div className="fixed bottom-24 left-0 w-full px-5"><button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">确认阶段，设置休息日</button></div>
        </div>
    );
  }

  // --- Fallback to standard step views from previous restores if not setup/off-days ---
  return null; 
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;
  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr]);
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) { setIsAdding(false); return; }
    const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copy = [...stages];
      const content = copy[dragItem.current];
      copy.splice(dragItem.current, 1);
      copy.splice(dragOverItem.current, 0, content);
      setStages(copy);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) return;
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      setEstimates({ ...estimates, [stages[activeTimeIndex].id]: currentInputTime });
      if (activeTimeIndex > 0) {
          const next = activeTimeIndex - 1;
          setActiveTimeIndex(next);
          setCurrentInputTime(estimates[stages[next].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleDayComplete = (day: number) => {
      setLocalCompletedDays(prev => {
          const next = prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day];
          if (currentSessionId) {
              const updated = sessions.map(s => s.id === currentSessionId ? { ...s, completedDays: next, lastUpdated: new Date().toISOString() } : s);
              persistSessions(updated);
          }
          return next;
      });
  };

  // --- RENDERS ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((session.completedDays.length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- STEP: SETUP ---
  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
                        <Sparkles size={20} className="text-fuchsia-400" />
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                    </div>
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10 active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black active:scale-90 transition-all">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 relative mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group active:scale-95">
                    <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors shadow-sm"><Plus size={28} /></div>
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <div className="flex gap-2">
                        <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                    </div>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                    <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all active:scale-90">
                        <Trash2 size={20} />
                    </button>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                       <ChevronRight size={24} /> 确认阶段，设置休息日
                   </button>
               </div>
           </div>
        </div>
    );
  }

  // --- STEP: OFF DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                    <p className="text-[10px] text-rose-500 font-bold uppercase tracking-widest">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={20} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={20} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isToday = getYYYYMMDD(new Date()) === dStr;
                          return (
                              <div key={dStr} onClick={() => toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline underline-offset-4 decoration-2' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8 border border-slate-100">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-[11px] text-slate-500 font-medium leading-relaxed">点击日期标记“X”，规划时将自动跳过。P人也需要喘息。</p>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  // --- STEP: TIME ENTRY ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100">工期分配</div>
            </div>
            <div className="bg-white rounded-3xl p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">剩余可用天数</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'}`}><Hourglass size={28} /></div>
            </div>
            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-4">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${isActive ? 'bg-white border-fuchsia-500 shadow-xl' : 'bg-white/50 border-slate-100 opacity-60 hover:opacity-100'}`}>
                                    <div className="flex flex-col">
                                        <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500 text-sm'}`}>{stage.title}</span>
                                        {isActive && <span className="text-[10px] text-fuchsia-500 font-bold uppercase mt-1">输入预计耗时 (天)</span>}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        {isActive ? (
                                            <div className="flex items-center gap-2"><input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} /><button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-2.5 rounded-xl"><ArrowUp size={20} /></button></div>
                                        ) : <span className="font-black text-fuchsia-600 text-xl">{estimates[stage.id] || '--'}</span>}
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
            <div className="fixed bottom-24 left-0 w-full px-5"><button onClick={() => setPlanningStep('finished')} disabled={Object.keys(estimates).length === 0} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">完成所有工期分配</button></div>
        </div>
    );
  }

  // --- STEP: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <p className="text-slate-400 text-sm mb-8">最佳路径已计算完毕</p>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                    </div>
                ))}
                <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                    <span className="font-bold text-slate-800 text-lg">总计工期</span>
                    <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>{currentPlannedDays} 天</span>
                </div>
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Box size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- STEP: TIME BOXING (DONE LIST) ---
  if (planningStep === 'time-boxing') {
      const currentDay = localCompletedDays.length + 1;
      const progressPercent = (localCompletedDays.length / currentPlannedDays) * 100;

      let daySum = 0;
      let currentStageIndex = 0;
      for (let i = 0; i < stages.length; i++) {
          const est = Number(estimates[stages[i].id]) || 0;
          daySum += est;
          if (currentDay <= daySum) {
              currentStageIndex = i;
              break;
          }
      }

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                  <button onClick={() => setMode('dashboard')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回列表</button>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full flex items-center gap-2 border border-fuchsia-100 active:scale-95 transition-all">
                      <Zap size={14} /> 进度复盘
                  </button>
              </div>

              {/* Execution Dashboard */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl mb-8 relative overflow-hidden">
                  <div className="absolute -top-10 -right-10 w-48 h-48 bg-fuchsia-500 rounded-full opacity-10"></div>
                  <div className="relative z-10">
                      <div className="flex justify-between items-start mb-6">
                        <div className="bg-white/10 px-3 py-1 rounded-full"><span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest">Day {currentDay} of {currentPlannedDays}</span></div>
                        <Rocket size={24} className="text-fuchsia-400" />
                      </div>
                      <h2 className="text-4xl font-black tracking-tight mb-2">第 {currentDay} 天</h2>
                      <p className="text-slate-400 font-bold mb-8">当前目标: <span className="text-white">{stages[currentStageIndex]?.title || '任务完成'}</span></p>

                      <div className="space-y-2">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inspiration Progress</span>
                            <span className="text-sm font-black text-fuchsia-400">{Math.round(progressPercent)}%</span>
                        </div>
                        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-fuchsia-600 to-indigo-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                        </div>
                      </div>
                  </div>
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2 flex items-center gap-2">
                <Target size={14} /> 规划日 Done List
              </h3>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const isCompleted = localCompletedDays.includes(dayNum);
                      const isCurrent = dayNum === currentDay;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => toggleDayComplete(dayNum)}
                            className={`p-6 rounded-[2rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isCompleted ? 'bg-emerald-50 border-emerald-100 shadow-inner' : 
                                  isCurrent ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 ring-4 ring-fuchsia-50/50' : 
                                  'bg-white border-slate-100 opacity-60 hover:opacity-100'}`}
                          >
                              <div className="relative z-10 flex flex-col items-center">
                                  <span className={`text-[10px] font-black mb-1 uppercase tracking-widest ${isCompleted ? 'text-emerald-400' : isCurrent ? 'text-fuchsia-400' : 'text-slate-300'}`}>Day</span>
                                  <span className={`text-3xl font-black ${isCompleted ? 'text-emerald-600' : isCurrent ? 'text-slate-800' : 'text-slate-200'}`}>{dayNum}</span>
                                  <div className={`mt-3 p-2 rounded-xl transition-all ${isCompleted ? 'bg-emerald-500 text-white' : isCurrent ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-200'}`}>
                                      {isCompleted ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                              {isCurrent && <div className="absolute top-2 right-2 w-2 h-2 bg-fuchsia-500 rounded-full animate-ping"></div>}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- STEP: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const completedCount = localCompletedDays.length;
      const plannedTotal = currentPlannedDays;
      const status = completedCount >= plannedTotal ? 'ahead' : 'working';

      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感复盘对比</h2>
                <p className="text-slate-400 text-sm mt-1 font-medium">理想进度 vs 现实节奏</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                              <div className="flex items-center gap-3">
                                <div className="p-3 bg-fuchsia-100 text-fuchsia-600 rounded-2xl"><PenTool size={20} /></div>
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                              </div>
                              <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4 mb-6">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1 text-center">原本规划</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1 text-center">目前进度</span>
                                  <div className="text-3xl font-black text-emerald-600">-- <span className="text-xs">天</span></div>
                              </div>
                          </div>

                          <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-dashed border-slate-200">
                              <div className="bg-white p-2 rounded-full text-slate-400 shadow-sm"><Smile size={16} /></div>
                              <span className="text-xs font-bold text-slate-500 leading-tight">
                                {status === 'ahead' ? '进度符合预期！请保持现在的创作手感。' : '正在根据实际情况灵活调整中...'}
                              </span>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-8 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent)]"></div>
                <h3 className="text-xl font-black mb-2 flex items-center gap-2"><Sparkles size={20} /> 创作寄语</h3>
                <p className="text-sm text-indigo-100 font-medium leading-relaxed opacity-90">
                  规划只是灵感的骨架，真正的艺术是在现实的起伏中开出的花。不论快慢，保持画笔不停即是胜利。
                </p>
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;
  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr]);
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) { setIsAdding(false); return; }
    const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copy = [...stages];
      const content = copy[dragItem.current];
      copy.splice(dragItem.current, 1);
      copy.splice(dragOverItem.current, 0, content);
      setStages(copy);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) return;
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;

      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          // If we finished the top one, we are done
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: []
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleDayComplete = (day: number) => {
      setLocalCompletedDays(prev => {
          const next = prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day];
          if (currentSessionId) {
              const updated = sessions.map(s => s.id === currentSessionId ? { ...s, completedDays: next, lastUpdated: new Date().toISOString() } : s);
              persistSessions(updated);
          }
          return next;
      });
  };

  // --- RENDERS ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((session.completedDays.length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- STEP: SETUP ---
  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
                        <Sparkles size={20} className="text-fuchsia-400" />
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                    </div>
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10 active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black active:scale-90 transition-all">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 relative mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group active:scale-95">
                    <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors shadow-sm"><Plus size={28} /></div>
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <div className="flex gap-2">
                        <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                    </div>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                    <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all active:scale-90">
                        <Trash2 size={20} />
                    </button>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                       <ChevronRight size={24} /> 确认阶段，设置休息日
                   </button>
               </div>
           </div>
        </div>
    );
  }

  // --- STEP: OFF DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                    <p className="text-[10px] text-rose-500 font-bold uppercase tracking-widest">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isToday = getYYYYMMDD(new Date()) === dStr;
                          return (
                              <div key={dStr} onClick={() => toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline underline-offset-4 decoration-2' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8 border border-slate-100">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-[11px] text-slate-500 font-medium leading-relaxed">点击日期标记“X”，规划时将自动跳过。P人也需要喘息。</p>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(estimates[stages[stages.length - 1].id] || ''); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  // --- STEP: TIME ENTRY ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100">工期分配</div>
            </div>

            {/* Live Budget Dashboard */}
            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1.5 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'}`}>
                    {isOverBudget ? <AlertTriangle size={28} /> : <Hourglass size={28} className="animate-bounce" />}
                </div>
            </div>

            {/* Smart Step List */}
            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center group">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-200' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2.5 h-2.5 bg-white rounded-full animate-pulse"></div>}
                                </div>
                                <div 
                                    onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2rem] border-2 transition-all cursor-pointer relative overflow-hidden
                                        ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl ring-4 ring-fuchsia-50 translate-x-2' : 
                                          isDone ? 'bg-white border-emerald-50 opacity-100' : 'bg-slate-50 border-slate-100 opacity-60 hover:opacity-100'}`}
                                >
                                    <div className="flex items-center justify-between mb-1">
                                        <span className={`font-black uppercase tracking-widest text-[10px] ${isActive ? 'text-fuchsia-400' : 'text-slate-300'}`}>Phase {index + 1}</span>
                                        {isDone && <span className="text-[10px] font-black text-emerald-500 bg-emerald-50 px-2 py-0.5 rounded-full">已分配</span>}
                                    </div>
                                    <div className="flex items-center justify-between">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-xl' : 'text-slate-500 text-sm'}`}>{stage.title}</span>
                                        <div className="flex items-center gap-2">
                                            {isActive ? (
                                                <div className="flex items-center gap-2 animate-fade-in" onClick={(e) => e.stopPropagation()}>
                                                    <input 
                                                        key={`input-${activeTimeIndex}`}
                                                        autoFocus 
                                                        type="text" 
                                                        inputMode="decimal"
                                                        value={currentInputTime} 
                                                        onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                        className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 focus:border-fuchsia-500 outline-none transition-all shadow-inner" 
                                                        onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                        placeholder="0"
                                                    />
                                                    <button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-3 rounded-xl shadow-lg active:scale-90 transition-all hover:bg-fuchsia-600">
                                                        <ArrowUp size={20} />
                                                    </button>
                                                </div>
                                            ) : (
                                                <span className={`font-black ${isDone ? 'text-fuchsia-600 text-xl' : 'text-slate-300 text-sm'}`}>
                                                    {estimates[stage.id] ? `${estimates[stage.id]} 天` : '--'}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="mt-12 px-5 pb-8">
                <button 
                    onClick={() => setPlanningStep('finished')} 
                    disabled={Object.keys(estimates).length === 0} 
                    className={`w-full py-5 rounded-2xl font-black text-lg shadow-xl transition-all flex items-center justify-center gap-3 active:scale-95
                        ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white hover:bg-black' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                >
                    <Box size={22} />
                    确认并生成总结
                </button>
            </div>
        </div>
    );
  }

  // --- STEP: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <p className="text-slate-400 text-sm mb-8">最佳路径已计算完毕</p>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                    </div>
                ))}
                <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                    <span className="font-bold text-slate-800 text-lg">总计工期</span>
                    <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>{currentPlannedDays} 天</span>
                </div>
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Rocket size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- STEP: TIME BOXING (DONE LIST) ---
  if (planningStep === 'time-boxing') {
      const currentDay = localCompletedDays.length + 1;
      const progressPercent = (localCompletedDays.length / currentPlannedDays) * 100;

      let daySum = 0;
      let currentStageIndex = 0;
      for (let i = 0; i < stages.length; i++) {
          const est = Number(estimates[stages[i].id]) || 0;
          daySum += est;
          if (currentDay <= daySum) {
              currentStageIndex = i;
              break;
          }
      }

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                  <button onClick={() => setMode('dashboard')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回列表</button>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full flex items-center gap-2 border border-fuchsia-100 active:scale-95 transition-all">
                      <Zap size={14} /> 进度复盘
                  </button>
              </div>

              {/* Execution Dashboard */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl mb-8 relative overflow-hidden">
                  <div className="absolute -top-10 -right-10 w-48 h-48 bg-fuchsia-500 rounded-full opacity-10"></div>
                  <div className="relative z-10">
                      <div className="flex justify-between items-start mb-6">
                        <div className="bg-white/10 px-3 py-1 rounded-full"><span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest">Day {currentDay} of {currentPlannedDays}</span></div>
                        <Rocket size={24} className="text-fuchsia-400" />
                      </div>
                      <h2 className="text-4xl font-black tracking-tight mb-2">第 {currentDay} 天</h2>
                      <p className="text-slate-400 font-bold mb-8">当前目标: <span className="text-white">{stages[currentStageIndex]?.title || '任务完成'}</span></p>

                      <div className="space-y-2">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inspiration Progress</span>
                            <span className="text-sm font-black text-fuchsia-400">{Math.round(progressPercent)}%</span>
                        </div>
                        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-fuchsia-600 to-indigo-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                        </div>
                      </div>
                  </div>
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2 flex items-center gap-2">
                <Target size={14} /> 规划日 Done List
              </h3>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const isCompleted = localCompletedDays.includes(dayNum);
                      const isCurrent = dayNum === currentDay;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => toggleDayComplete(dayNum)}
                            className={`p-6 rounded-[2rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isCompleted ? 'bg-emerald-50 border-emerald-100 shadow-inner' : 
                                  isCurrent ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 ring-4 ring-fuchsia-50/50' : 
                                  'bg-white border-slate-100 opacity-60 hover:opacity-100'}`}
                          >
                              <div className="relative z-10 flex flex-col items-center">
                                  <span className={`text-[10px] font-black mb-1 uppercase tracking-widest ${isCompleted ? 'text-emerald-400' : isCurrent ? 'text-fuchsia-400' : 'text-slate-300'}`}>Day</span>
                                  <span className={`text-3xl font-black ${isCompleted ? 'text-emerald-600' : isCurrent ? 'text-slate-800' : 'text-slate-200'}`}>{dayNum}</span>
                                  <div className={`mt-3 p-2 rounded-xl transition-all ${isCompleted ? 'bg-emerald-500 text-white' : isCurrent ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-200'}`}>
                                      {isCompleted ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                              {isCurrent && <div className="absolute top-2 right-2 w-2 h-2 bg-fuchsia-500 rounded-full animate-ping"></div>}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- STEP: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const completedCount = localCompletedDays.length;
      const plannedTotal = currentPlannedDays;
      const status = completedCount >= plannedTotal ? 'ahead' : 'working';

      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感复盘对比</h2>
                <p className="text-slate-400 text-sm mt-1 font-medium">理想进度 vs 现实节奏</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                              <div className="flex items-center gap-3">
                                <div className="p-3 bg-fuchsia-100 text-fuchsia-600 rounded-2xl"><PenTool size={20} /></div>
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                              </div>
                              <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4 mb-6">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1 text-center">原本规划</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1 text-center">目前进度</span>
                                  <div className="text-3xl font-black text-emerald-600">-- <span className="text-xs">天</span></div>
                              </div>
                          </div>

                          <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-dashed border-slate-200">
                              <div className="bg-white p-2 rounded-full text-slate-400 shadow-sm"><Smile size={16} /></div>
                              <span className="text-xs font-bold text-slate-500 leading-tight">
                                {status === 'ahead' ? '进度符合预期！请保持现在的创作手感。' : '正在根据实际情况灵活调整中...'}
                              </span>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-8 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent)]"></div>
                <h3 className="text-xl font-black mb-2 flex items-center gap-2"><Sparkles size={20} /> 创作寄语</h3>
                <p className="text-sm text-indigo-100 font-medium leading-relaxed opacity-90">
                  规划只是灵感的骨架，真正的艺术是在现实的起伏中开出的花。不论快慢，保持画笔不停即是胜利。
                </p>
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string; // New: To identify which client owns this project
  description: string;
  startDate: string; // ISO String
  deadline: string; // ISO String
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string; // YYYY-MM-DD
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string; // New: To identify who booked/owns this slot
  note?: string;
  actualHours?: string[]; // New: Stores the IDs of actual worked slots (e.g., 'h-9-00')
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>; // StageId -> Days
  blockedDates: string[]; // New: Dates user chose to rest (YYYY-MM-DD)
  createdAt: string;
  lastUpdated: string;
  completedDays: number[]; // Array of completed day indices (1, 2, 3...)
  dailyHours?: Record<number, number>; // New: Day index -> Hours worked (0.5 increments)
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle, Minus, Timer } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [localCompletedDays, setLocalCompletedDays] = useState<number[]>([]);
  const [dailyHours, setDailyHours] = useState<Record<number, number>>({});

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Date Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const calculateAvailableDays = (startStr: string, endStr: string) => {
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    let curr = new Date(start);
    while (curr <= end) {
        if (!isDateBlocked(getYYYYMMDD(curr))) count++;
        curr.setDate(curr.getDate() + 1);
    }
    return count;
  };

  const getStartDate = () => syncedProject ? new Date(syncedProject.startDate) : sessionStartDate;
  const totalAvailableDays = syncedProject ? calculateAvailableDays(syncedProject.startDate, syncedProject.deadline) : 30;
  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const toggleSessionBlockedDate = (dateStr: string) => {
    setSessionBlockedDates(prev => prev.includes(dateStr) ? prev.filter(d => d !== dateStr) : [...prev, dateStr]);
  };

  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const handleConfirmAdd = () => {
    if (!newStageTitle.trim()) { setIsAdding(false); return; }
    const newStage: PlannerStage = { id: Date.now().toString(), title: newStageTitle.trim(), isDeletable: true };
    setStages([...stages, newStage]);
    setNewStageTitle('');
    setIsAdding(false);
  };

  const handleDragStart = (index: number) => { dragItem.current = index; };
  const handleDragEnter = (index: number) => { dragOverItem.current = index; };
  const handleDragEnd = () => {
    if (dragItem.current !== null && dragOverItem.current !== null) {
      const copy = [...stages];
      const content = copy[dragItem.current];
      copy.splice(dragItem.current, 1);
      copy.splice(dragOverItem.current, 0, content);
      setStages(copy);
    }
    dragItem.current = null;
    dragOverItem.current = null;
  };

  const deleteStage = (index: number) => {
    if (stages.length <= 1) return;
    const newStages = [...stages];
    newStages.splice(index, 1);
    setStages(newStages);
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setLocalCompletedDays([]);
      setDailyHours({});
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setLocalCompletedDays(session.completedDays || []);
      setDailyHours(session.dailyHours || {});
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;

      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
          dailyHours: {}
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const adjustDailyHours = (day: number, delta: number) => {
      setDailyHours(prev => {
          const current = prev[day] || 0;
          const next = Math.max(0, current + delta);
          const newHours = { ...prev, [day]: next };

          // Sync with persistence
          if (currentSessionId) {
              const updated = sessions.map(s => s.id === currentSessionId ? { 
                ...s, 
                dailyHours: newHours, 
                completedDays: next > 0 ? Array.from(new Set([...s.completedDays, day])) : s.completedDays.filter(d => d !== day),
                lastUpdated: new Date().toISOString() 
              } : s);
              persistSessions(updated);
          }

          // Also sync localCompletedDays for visual indicators if needed
          if (next > 0 && !localCompletedDays.includes(day)) {
            setLocalCompletedDays([...localCompletedDays, day]);
          } else if (next === 0) {
            setLocalCompletedDays(localCompletedDays.filter(d => d !== day));
          }

          return newHours;
      });
  };

  // --- RENDERS ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((Object.keys(session.dailyHours || {}).length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // --- STEP: SETUP ---
  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
                        <Sparkles size={20} className="text-fuchsia-400" />
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                    </div>
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all border border-white/10 active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white placeholder-white/30" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black active:scale-90 transition-all">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 relative mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 hover:text-fuchsia-500 hover:bg-fuchsia-50/30 transition-all group active:scale-95">
                    <div className="bg-slate-50 p-3 rounded-full group-hover:bg-white transition-colors shadow-sm"><Plus size={28} /></div>
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleConfirmAdd()} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <div className="flex gap-2">
                        <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400 hover:text-slate-600"><X size={20} /></button>
                        <button onClick={handleConfirmAdd} className="p-3 bg-slate-900 text-white rounded-2xl shadow-lg active:scale-90 transition-all"><Check size={20} /></button>
                    </div>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} draggable onDragStart={() => handleDragStart(index)} onDragEnter={() => handleDragEnter(index)} onDragEnd={handleDragEnd} onDragOver={(e) => e.preventDefault()} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm cursor-grab active:cursor-grabbing hover:border-slate-300 transition-all group">
                    <div className="text-slate-200 group-hover:text-slate-400 transition-colors mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); deleteStage(index); }} className="absolute right-6 p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all active:scale-90">
                        <Trash2 size={20} />
                    </button>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5 pointer-events-none">
               <div className="max-w-lg mx-auto pointer-events-auto">
                   <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl shadow-slate-200 flex items-center justify-center gap-3 hover:scale-[1.02] active:scale-95 transition-all">
                       <ChevronRight size={24} /> 确认阶段，设置休息日
                   </button>
               </div>
           </div>
        </div>
    );
  }

  // --- STEP: OFF DAYS ---
  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                    <p className="text-[10px] text-rose-500 font-bold uppercase tracking-widest">设置休息日</p>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          const isToday = getYYYYMMDD(new Date()) === dStr;
                          return (
                              <div key={dStr} onClick={() => toggleSessionBlockedDate(dStr)} className={`aspect-square rounded-xl border flex items-center justify-center relative cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className={`text-xs font-black ${isToday ? 'text-rose-600 underline underline-offset-4 decoration-2' : ''}`}>{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl mb-8 border border-slate-100">
                  <Coffee size={20} className="text-rose-400" />
                  <p className="text-[11px] text-slate-500 font-medium leading-relaxed">点击日期标记“X”，规划时将自动跳过。P人也需要喘息。</p>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(estimates[stages[stages.length - 1].id] || ''); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  // --- STEP: TIME ENTRY ---
  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg border border-fuchsia-100">工期分配</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className={`absolute top-0 left-0 h-1.5 bg-gradient-to-r ${isOverBudget ? 'from-rose-500 to-rose-400' : 'from-emerald-500 to-emerald-400'} transition-all duration-700`} style={{ width: `${Math.min(100, (currentPlannedDays / totalAvailableDays) * 100)}%` }}></div>
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <div className={`p-4 rounded-full ${isOverBudget ? 'bg-rose-50 text-rose-500' : 'bg-fuchsia-50 text-fuchsia-500'}`}>
                    {isOverBudget ? <AlertTriangle size={28} /> : <Hourglass size={28} className="animate-bounce" />}
                </div>
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center group">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-200' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                    {isActive && <div className="w-2.5 h-2.5 bg-white rounded-full animate-pulse"></div>}
                                </div>
                                <div 
                                    onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2rem] border-2 transition-all cursor-pointer relative overflow-hidden
                                        ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl ring-4 ring-fuchsia-50 translate-x-2' : 
                                          isDone ? 'bg-white border-emerald-50 opacity-100' : 'bg-slate-50 border-slate-100 opacity-60 hover:opacity-100'}`}
                                >
                                    <div className="flex items-center justify-between mb-1">
                                        <span className={`font-black uppercase tracking-widest text-[10px] ${isActive ? 'text-fuchsia-400' : 'text-slate-300'}`}>Phase {index + 1}</span>
                                        {isDone && <span className="text-[10px] font-black text-emerald-500 bg-emerald-50 px-2 py-0.5 rounded-full">已分配</span>}
                                    </div>
                                    <div className="flex items-center justify-between">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-xl' : 'text-slate-500 text-sm'}`}>{stage.title}</span>
                                        <div className="flex items-center gap-2">
                                            {isActive ? (
                                                <div className="flex items-center gap-2 animate-fade-in" onClick={(e) => e.stopPropagation()}>
                                                    <input 
                                                        key={`input-${activeTimeIndex}`}
                                                        autoFocus 
                                                        type="text" 
                                                        inputMode="decimal"
                                                        value={currentInputTime} 
                                                        onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                        className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 focus:border-fuchsia-500 outline-none transition-all shadow-inner" 
                                                        onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                        placeholder="0"
                                                    />
                                                    <button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-3 rounded-xl shadow-lg active:scale-90 transition-all hover:bg-fuchsia-600">
                                                        <ArrowUp size={20} />
                                                    </button>
                                                </div>
                                            ) : (
                                                <span className={`font-black ${isDone ? 'text-fuchsia-600 text-xl' : 'text-slate-300 text-sm'}`}>
                                                    {estimates[stage.id] ? `${estimates[stage.id]} 天` : '--'}
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="mt-12 px-5 pb-8">
                <button 
                    onClick={() => setPlanningStep('finished')} 
                    disabled={Object.keys(estimates).length === 0} 
                    className={`w-full py-5 rounded-2xl font-black text-lg shadow-xl transition-all flex items-center justify-center gap-3 active:scale-95
                        ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white hover:bg-black' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                >
                    <Box size={22} />
                    确认并生成总结
                </button>
            </div>
        </div>
    );
  }

  // --- STEP: FINISHED SUMMARY ---
  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl shadow-emerald-50 ring-4 ring-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <p className="text-slate-400 text-sm mb-8">最佳路径已计算完毕</p>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-1">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0 group">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg text-lg">{estimates[stage.id]} 天</span>
                    </div>
                ))}
                <div className="mt-4 pt-6 border-t-2 border-slate-100 flex justify-between items-center">
                    <span className="font-bold text-slate-800 text-lg">总计工期</span>
                    <span className={`font-black px-3 py-1 rounded-lg text-lg ${isOverBudget ? 'text-rose-600 bg-rose-50' : 'text-emerald-600 bg-emerald-50'}`}>{currentPlannedDays} 天</span>
                </div>
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Rocket size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- STEP: TIME BOXING (DONE LIST) ---
  if (planningStep === 'time-boxing') {
      const currentDayIndex = Object.keys(dailyHours).length;
      const progressPercent = (Object.keys(dailyHours).length / currentPlannedDays) * 100;
      const totalWorkedHours = Object.values(dailyHours).reduce((a, b) => a + b, 0);

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                  <button onClick={() => setMode('dashboard')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回列表</button>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full flex items-center gap-2 border border-fuchsia-100 active:scale-95 transition-all">
                      <Zap size={14} /> 进度复盘
                  </button>
              </div>

              {/* Execution Dashboard */}
              <div className="bg-slate-900 rounded-[2.5rem] p-8 text-white shadow-2xl mb-8 relative overflow-hidden">
                  <div className="absolute -top-10 -right-10 w-48 h-48 bg-fuchsia-500 rounded-full opacity-10"></div>
                  <div className="relative z-10">
                      <div className="flex justify-between items-start mb-6">
                        <div className="bg-white/10 px-3 py-1 rounded-full"><span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest">Progress: {Math.round(progressPercent)}%</span></div>
                        <Timer size={24} className="text-fuchsia-400" />
                      </div>
                      <h2 className="text-4xl font-black tracking-tight mb-2">{totalWorkedHours} <span className="text-lg opacity-60">小时</span></h2>
                      <p className="text-slate-400 font-bold mb-8">累计绘画时长记录</p>

                      <div className="space-y-2">
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Inspiration Flow</span>
                            <span className="text-sm font-black text-fuchsia-400">Day {currentDayIndex} / {currentPlannedDays}</span>
                        </div>
                        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
                            <div className="h-full bg-gradient-to-r from-fuchsia-600 to-indigo-500 transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                        </div>
                      </div>
                  </div>
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2 flex items-center gap-2">
                <Target size={14} /> 规划日 Time Box (半小时起步)
              </h3>

              <div className="grid grid-cols-1 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const hours = dailyHours[dayNum] || 0;
                      const isCompleted = hours > 0;
                      const isCurrent = dayNum === currentDayIndex + 1 || (dayNum === 1 && currentDayIndex === 0);

                      return (
                          <div 
                            key={dayNum} 
                            className={`p-6 rounded-[2.5rem] border-2 transition-all relative overflow-hidden group
                                ${isCompleted ? 'bg-white border-indigo-100 shadow-sm' : 
                                  isCurrent ? 'bg-white border-fuchsia-500 shadow-xl shadow-fuchsia-50 ring-4 ring-fuchsia-50/50' : 
                                  'bg-white border-slate-50 opacity-60'}`}
                          >
                              <div className="relative z-10 flex items-center justify-between">
                                  <div className="flex flex-col">
                                      <span className={`text-[10px] font-black mb-0.5 uppercase tracking-widest ${isCompleted ? 'text-indigo-400' : isCurrent ? 'text-fuchsia-400' : 'text-slate-300'}`}>Day {dayNum}</span>
                                      <div className="flex items-baseline gap-1">
                                        <span className={`text-2xl font-black ${isCompleted ? 'text-slate-800' : isCurrent ? 'text-slate-700' : 'text-slate-200'}`}>{hours}</span>
                                        <span className="text-xs font-bold text-slate-400">h</span>
                                      </div>
                                  </div>

                                  <div className="flex items-center gap-3">
                                      <button 
                                        onClick={() => adjustDailyHours(dayNum, -0.5)}
                                        className="w-10 h-10 rounded-2xl bg-slate-50 flex items-center justify-center text-slate-400 hover:bg-slate-100 active:scale-90 transition-all border border-slate-100"
                                      >
                                          <Minus size={18} />
                                      </button>
                                      <button 
                                        onClick={() => adjustDailyHours(dayNum, 0.5)}
                                        className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-lg active:scale-90 transition-all
                                            ${isCurrent ? 'bg-fuchsia-500 shadow-fuchsia-200' : 'bg-slate-900 shadow-slate-200'}`}
                                      >
                                          <Plus size={24} strokeWidth={3} />
                                      </button>
                                  </div>
                              </div>

                              {/* Visual Indicator of Blocks */}
                              <div className="mt-4 flex flex-wrap gap-1">
                                  {Array.from({ length: Math.ceil(hours / 0.5) }).map((_, b) => (
                                    <div key={b} className={`h-1.5 w-4 rounded-full ${isCurrent ? 'bg-fuchsia-400' : 'bg-indigo-500'}`}></div>
                                  ))}
                              </div>

                              {isCurrent && <div className="absolute top-4 right-4 w-2 h-2 bg-fuchsia-500 rounded-full animate-ping"></div>}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- STEP: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const totalWorkedHours = Object.values(dailyHours).reduce((a, b) => a + b, 0);
      const plannedTotal = currentPlannedDays;
      const status = totalWorkedHours > 0 ? 'working' : 'idle';

      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感复盘对比</h2>
                <p className="text-slate-400 text-sm mt-1 font-medium">理想进度 vs 现实节奏</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                              <div className="flex items-center gap-3">
                                <div className="p-3 bg-fuchsia-100 text-fuchsia-600 rounded-2xl"><PenTool size={20} /></div>
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                              </div>
                              <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4 mb-6">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1 text-center">原本规划</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1 text-center">累计工时</span>
                                  <div className="text-3xl font-black text-emerald-600">{totalWorkedHours} <span className="text-xs">h</span></div>
                              </div>
                          </div>

                          <div className="flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-dashed border-slate-200">
                              <div className="bg-white p-2 rounded-full text-slate-400 shadow-sm"><Smile size={16} /></div>
                              <span className="text-xs font-bold text-slate-500 leading-tight">
                                {totalWorkedHours > 0 ? '进度正在稳步推进！请保持现在的创作手感。' : '正在根据实际情况灵活调整中...'}
                              </span>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-8 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent)]"></div>
                <h3 className="text-xl font-black mb-2 flex items-center gap-2"><Sparkles size={20} /> 创作寄语</h3>
                <p className="text-sm text-indigo-100 font-medium leading-relaxed opacity-90">
                  规划只是灵感的骨架，真正的艺术是在现实的起伏中开出的花。不论快慢，保持画笔不停即是胜利。
                </p>
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string;
  description: string;
  startDate: string; // ISO String
  deadline: string; // ISO String
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string; // YYYY-MM-DD
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string;
  note?: string;
  actualHours?: string[]; // Stores slot IDs like "09:30"
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>; // StageId -> Days
  blockedDates: string[]; // Dates user chose to rest
  createdAt: string;
  lastUpdated: string;
  completedDays: number[]; // Array of completed day indices
  dailySlots?: Record<number, string[]>; // Day index -> Array of slot strings "09:00", "09:30"...
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle, Minus, Timer } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'period-select' | 'timeline-entry' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Recording State
  const [currentRecordingDay, setCurrentRecordingDay] = useState<number>(1);
  const [dailySlots, setDailySlots] = useState<Record<number, string[]>>({});

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const totalAvailableDays = syncedProject ? 30 : 30; // Simplify for now
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Time Logic ---
  const timelineSlots = Array.from({ length: 37 }).map((_, i) => {
    let hour = 9 + Math.floor(i / 2);
    let displayHour = hour;
    let label = '';
    if (hour >= 24) displayHour -= 24;
    const minutes = (i % 2 === 0) ? '00' : '30';
    const timeStr = `${String(displayHour).padStart(2, '0')}:${minutes}`;
    return timeStr;
  });

  // --- Actions ---
  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setDailySlots({});
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setDailySlots(session.dailySlots || {});
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);
      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
          dailySlots: {}
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleSlot = (slot: string) => {
    setDailySlots(prev => {
      const currentDaySlots = prev[currentRecordingDay] || [];
      const nextSlots = currentDaySlots.includes(slot) 
        ? currentDaySlots.filter(s => s !== slot) 
        : [...currentDaySlots, slot];
      const newDaily = { ...prev, [currentRecordingDay]: nextSlots };

      if (currentSessionId) {
        const updated = sessions.map(s => s.id === currentSessionId ? {
          ...s,
          dailySlots: newDaily,
          lastUpdated: new Date().toISOString()
        } : s);
        persistSessions(updated);
      }
      return newDaily;
    });
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((Object.keys(session.dailySlots || {}).length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                </div>
              )}
              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between">
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ 30 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex flex-col p-5 rounded-[2rem] border-2 transition-all ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                                    <span className="font-black text-slate-800">{stage.title}</span>
                                    {isActive ? (
                                        <div className="flex items-center gap-2 mt-2">
                                            <input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} />
                                            <button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-3 rounded-xl"><ArrowUp size={20} /></button>
                                        </div>
                                    ) : <span className="font-black text-fuchsia-600 mt-1">{estimates[stage.id] ? `${estimates[stage.id]} 天` : '--'}</span>}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button onClick={() => setPlanningStep('finished')} className="fixed bottom-24 left-5 right-5 bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">确认并生成规划</button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600">{estimates[stage.id]} 天</span>
                    </div>
                ))}
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Rocket size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  if (planningStep === 'time-boxing') {
      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">灵感工作流 (Done List)</h2>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full border border-fuchsia-100">进度复盘</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const slots = dailySlots[dayNum] || [];
                      const isRecorded = slots.length > 0;
                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => { setCurrentRecordingDay(dayNum); setPlanningStep('period-select'); }}
                            className={`p-6 rounded-[2.5rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isRecorded ? 'bg-indigo-50 border-indigo-100' : 'bg-white border-slate-100'}`}
                          >
                              <div className="flex flex-col items-center">
                                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Day</span>
                                  <span className={`text-4xl font-black ${isRecorded ? 'text-indigo-600' : 'text-slate-800'}`}>{dayNum}</span>
                                  <div className={`mt-3 p-2 rounded-xl ${isRecorded ? 'bg-indigo-500 text-white' : 'bg-slate-50 text-slate-300'}`}>
                                      {isRecorded ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                                  {isRecorded && <span className="text-[10px] font-bold text-indigo-400 mt-2">{slots.length * 0.5}h 记录</span>}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  if (planningStep === 'period-select') {
    return (
        <div className="animate-fade-in pb-32">
            <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-8 font-bold text-sm"><ArrowLeft size={16} /> 返回列表</button>
            <div className="mb-8">
                <span className="text-fuchsia-500 font-black uppercase text-xs tracking-widest">Day {currentRecordingDay} 记录</span>
                <h2 className="text-3xl font-black text-slate-800 mt-1">请选择绘画时段</h2>
            </div>
            <div className="space-y-4">
                {[
                    { id: 'morning', title: '早间时段', desc: '清晨灵感迸发', icon: <Sunrise size={28} />, bg: 'from-orange-50 to-amber-50', color: 'text-orange-600' },
                    { id: 'afternoon', title: '午后时段', desc: '持续稳定输出', icon: <Sun size={28} />, bg: 'from-blue-50 to-indigo-50', color: 'text-blue-600' },
                    { id: 'night', title: '深夜时段', desc: '极致专注时刻', icon: <Moon size={28} />, bg: 'from-indigo-50 to-purple-50', color: 'text-indigo-600' }
                ].map(p => (
                    <button 
                        key={p.id} 
                        onClick={() => setPlanningStep('timeline-entry')}
                        className={`w-full p-6 bg-gradient-to-br ${p.bg} rounded-[2rem] border border-black/5 flex items-center gap-6 text-left active:scale-95 transition-all group`}
                    >
                        <div className={`w-14 h-14 bg-white rounded-2xl shadow-sm flex items-center justify-center ${p.color} group-hover:scale-110 transition-transform`}>{p.icon}</div>
                        <div>
                            <h3 className={`font-black text-lg ${p.color.replace('text', 'text-slate-800')}`}>{p.title}</h3>
                            <p className="text-slate-400 text-xs font-bold">{p.desc}</p>
                        </div>
                        <ChevronRight className="ml-auto text-slate-300" />
                    </button>
                ))}
            </div>
        </div>
    );
  }

  if (planningStep === 'timeline-entry') {
      const currentDaySlots = dailySlots[currentRecordingDay] || [];
      const totalHours = currentDaySlots.length * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('period-select')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回时段</button>
                <div className="bg-slate-900 text-white px-4 py-2 rounded-full text-xs font-black">Day {currentRecordingDay}</div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl mb-8 border border-slate-50 relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-4 text-fuchsia-100"><Timer size={60} /></div>
                  <div className="relative z-10">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">今日绘画总计</span>
                    <div className="flex items-baseline gap-2 mt-1">
                        <span className="text-5xl font-black text-slate-800">{totalHours}</span>
                        <span className="text-lg font-bold text-slate-400">小时</span>
                    </div>
                  </div>
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2">点击标记已完成时段 (09:00 - 03:00)</h3>

              <div className="grid grid-cols-3 gap-2">
                  {timelineSlots.map(slot => {
                      const isSelected = currentDaySlots.includes(slot);
                      return (
                          <div 
                            key={slot} 
                            onClick={() => toggleSlot(slot)}
                            className={`p-3 rounded-2xl border-2 transition-all cursor-pointer text-center relative
                                ${isSelected ? 'bg-fuchsia-500 border-fuchsia-500 text-white shadow-lg shadow-fuchsia-100 scale-105 z-10' : 'bg-white border-slate-50 text-slate-400 hover:border-slate-200'}`}
                          >
                              <span className="text-sm font-black">{slot}</span>
                          </div>
                      );
                  })}
              </div>

              <button 
                onClick={() => setPlanningStep('time-boxing')}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg mt-12 shadow-xl active:scale-95 transition-all"
              >
                  保存并完成今日记录
              </button>
          </div>
      );
  }

  if (planningStep === 'daily-comparison') {
      const totalSlots = Object.values(dailySlots).reduce((acc, curr) => acc + curr.length, 0);
      const totalHours = totalSlots * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800">进度对比复盘</h2>
                <p className="text-slate-400 text-sm mt-1">当前工期执行情况一览</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                                <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1 block">预计进度</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1 block">累计时长</span>
                                  <div className="text-3xl font-black text-emerald-600">{totalHours} <span className="text-xs">h</span></div>
                              </div>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string;
  description: string;
  startDate: string; // ISO String
  deadline: string; // ISO String
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string; // YYYY-MM-DD
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string;
  note?: string;
  actualHours?: string[]; // Stores slot IDs like "09:30"
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>; // StageId -> Days
  blockedDates: string[]; // Dates user chose to rest (YYYY-MM-DD)
  createdAt: string;
  lastUpdated: string;
  completedDays: number[]; // Array of completed day indices
  dailySlots?: Record<number, string[]>; // Day index -> Array of slot strings "09:00", "09:30"...
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle, Minus, Timer } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'period-select' | 'timeline-entry' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Recording State
  const [currentRecordingDay, setCurrentRecordingDay] = useState<number>(1);
  const [dailySlots, setDailySlots] = useState<Record<number, string[]>>({});

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const totalAvailableDays = 30; // Default buffer
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // Calculate the actual calendar date for a specific work day index
  const getWorkDayDate = (dayIndex: number): Date => {
    let current = new Date(sessionStartDate);
    let workDayCount = 0;

    // safety break to prevent infinite loops
    let attempts = 0;
    while (workDayCount < dayIndex && attempts < 365) {
      if (!isDateBlocked(getYYYYMMDD(current))) {
        workDayCount++;
        if (workDayCount === dayIndex) return current;
      }
      current.setDate(current.getDate() + 1);
      attempts++;
    }
    return current;
  };

  // --- Time Slot Logic (09:00 - 03:00 next day) ---
  const timelineSlots = Array.from({ length: 37 }).map((_, i) => {
    let hour = 9 + Math.floor(i / 2);
    let displayHour = hour;
    if (hour >= 24) displayHour -= 24;
    const minutes = (i % 2 === 0) ? '00' : '30';
    return `${String(displayHour).padStart(2, '0')}:${minutes}`;
  });

  // --- Actions ---
  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setDailySlots({});
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setDailySlots(session.dailySlots || {});
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);
      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
          dailySlots: {}
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleSlot = (slot: string) => {
    setDailySlots(prev => {
      const currentDaySlots = prev[currentRecordingDay] || [];
      const nextSlots = currentDaySlots.includes(slot) 
        ? currentDaySlots.filter(s => s !== slot) 
        : [...currentDaySlots, slot];
      const newDaily = { ...prev, [currentRecordingDay]: nextSlots };

      if (currentSessionId) {
        const updated = sessions.map(s => s.id === currentSessionId ? {
          ...s,
          dailySlots: newDaily,
          lastUpdated: new Date().toISOString()
        } : s);
        persistSessions(updated);
      }
      return newDaily;
    });
  };

  // --- Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((Object.keys(session.dailySlots || {}).length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  // ... (Setup, Off-Days, Time-Entry, Finished steps remain largely same, just keeping the flow)

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500 rounded-full -mr-16 -mt-16 opacity-20"></div>
                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
                        <Sparkles size={20} className="text-fuchsia-400" />
                        <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">规划核心</span>
                    </div>
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                </div>
           </div>

           <div className="space-y-4 relative mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <div className="flex gap-2">
                        <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                    </div>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between">
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ 30 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex flex-col p-5 rounded-[2rem] border-2 transition-all cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                                    <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    {isActive ? (
                                        <div className="flex items-center gap-2 mt-2">
                                            <input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 focus:border-fuchsia-500 outline-none" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} />
                                            <button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-3 rounded-xl shadow-lg active:scale-90 transition-all"><ArrowUp size={20} /></button>
                                        </div>
                                    ) : (
                                        <span className={`font-black ${isDone ? 'text-fuchsia-600' : 'text-slate-300'}`}>{estimates[stage.id] ? `${estimates[stage.id]} 天` : '--'}</span>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button onClick={() => setPlanningStep('finished')} className="fixed bottom-24 left-5 right-5 bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">确认并生成规划总结</button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600">{estimates[stage.id]} 天</span>
                    </div>
                ))}
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"><Rocket size={24} className="mr-2 inline" />开启时间盒子工作流</button>
        </div>
    );
  }

  // --- STEP: TIME BOXING (DONE LIST GRID) ---
  if (planningStep === 'time-boxing') {
      const progressPercent = (Object.keys(dailySlots).length / currentPlannedDays) * 100;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">灵感工作流 (Done List)</h2>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full border border-fuchsia-100">进度复盘</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const dateObj = getWorkDayDate(dayNum);
                      const slots = dailySlots[dayNum] || [];
                      const isRecorded = slots.length > 0;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => { setCurrentRecordingDay(dayNum); setPlanningStep('period-select'); }}
                            className={`p-6 rounded-[2.5rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isRecorded ? 'bg-indigo-50 border-indigo-100' : 'bg-white border-slate-100'}`}
                          >
                              <div className="flex flex-col items-center">
                                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Day {dayNum}</span>
                                  <span className={`text-4xl font-black ${isRecorded ? 'text-indigo-600' : 'text-slate-800'}`}>{dateObj.getDate()}</span>
                                  <span className="text-[10px] font-bold text-slate-400 mt-1">{dateObj.toLocaleDateString('zh-CN', { month: 'short' })}</span>
                                  <div className={`mt-3 p-2 rounded-xl ${isRecorded ? 'bg-indigo-500 text-white' : 'bg-slate-50 text-slate-300'}`}>
                                      {isRecorded ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                                  {isRecorded && <span className="text-[10px] font-bold text-indigo-400 mt-2">{slots.length * 0.5}h 记录</span>}
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // --- STEP: PERIOD SELECT ---
  if (planningStep === 'period-select') {
    return (
        <div className="animate-fade-in pb-32">
            <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-8 font-bold text-sm"><ArrowLeft size={16} /> 返回列表</button>
            <div className="mb-8">
                <span className="text-fuchsia-500 font-black uppercase text-xs tracking-widest">Day {currentRecordingDay} 记录</span>
                <h2 className="text-3xl font-black text-slate-800 mt-1">请选择绘画时段</h2>
                <p className="text-slate-400 text-sm font-medium">针对不同生理时钟优化记录体验</p>
            </div>
            <div className="space-y-4">
                {[
                    { id: 'morning', title: '早间时段', desc: '清晨灵感迸发 (09:00 - 13:00)', icon: <Sunrise size={28} />, bg: 'from-orange-50 to-amber-50', color: 'text-orange-600' },
                    { id: 'afternoon', title: '午后时段', desc: '持续稳定输出 (13:00 - 20:00)', icon: <Sun size={28} />, bg: 'from-blue-50 to-indigo-50', color: 'text-blue-600' },
                    { id: 'night', title: '深夜时段', desc: '极致专注时刻 (20:00 - 03:00)', icon: <Moon size={28} />, bg: 'from-indigo-50 to-purple-50', color: 'text-indigo-600' }
                ].map(p => (
                    <button 
                        key={p.id} 
                        onClick={() => setPlanningStep('timeline-entry')}
                        className={`w-full p-6 bg-gradient-to-br ${p.bg} rounded-[2rem] border border-black/5 flex items-center gap-6 text-left active:scale-95 transition-all group shadow-sm`}
                    >
                        <div className={`w-14 h-14 bg-white rounded-2xl shadow-sm flex items-center justify-center ${p.color} group-hover:scale-110 transition-transform`}>{p.icon}</div>
                        <div>
                            <h3 className={`font-black text-lg ${p.color.replace('text', 'text-slate-800')}`}>{p.title}</h3>
                            <p className="text-slate-400 text-xs font-bold leading-relaxed">{p.desc}</p>
                        </div>
                        <ChevronRight className="ml-auto text-slate-300" />
                    </button>
                ))}
            </div>
        </div>
    );
  }

  // --- STEP: TIMELINE ENTRY ---
  if (planningStep === 'timeline-entry') {
      const currentDaySlots = dailySlots[currentRecordingDay] || [];
      const totalHours = currentDaySlots.length * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('period-select')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回时段</button>
                <div className="bg-slate-900 text-white px-4 py-2 rounded-full text-xs font-black">Day {currentRecordingDay} Timeline</div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl mb-8 border border-slate-50 relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-4 text-fuchsia-100"><Timer size={60} /></div>
                  <div className="relative z-10">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">今日绘画记录</span>
                    <div className="flex items-baseline gap-2 mt-1">
                        <span className="text-5xl font-black text-slate-800">{totalHours}</span>
                        <span className="text-lg font-bold text-slate-400">小时 (h)</span>
                    </div>
                  </div>
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2">点击标记已完成时段 (09:00 - 03:00)</h3>

              <div className="grid grid-cols-3 gap-2">
                  {timelineSlots.map(slot => {
                      const isSelected = currentDaySlots.includes(slot);
                      return (
                          <div 
                            key={slot} 
                            onClick={() => toggleSlot(slot)}
                            className={`p-3 rounded-2xl border-2 transition-all cursor-pointer text-center relative
                                ${isSelected ? 'bg-fuchsia-500 border-fuchsia-500 text-white shadow-lg shadow-fuchsia-100 scale-105 z-10' : 'bg-white border-slate-50 text-slate-400 hover:border-slate-200'}`}
                          >
                              <span className="text-sm font-black">{slot}</span>
                          </div>
                      );
                  })}
              </div>

              <button 
                onClick={() => setPlanningStep('time-boxing')}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg mt-12 shadow-xl active:scale-95 transition-all"
              >
                  保存并完成今日记录
              </button>
          </div>
      );
  }

  // --- STEP: DAILY COMPARISON ---
  if (planningStep === 'daily-comparison') {
      const totalSlots = Object.values(dailySlots).reduce((acc, curr) => acc + curr.length, 0);
      const totalHours = totalSlots * 0.5;

      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回工作流</button>
              </div>
              <div className="mb-8">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">进度对比复盘</h2>
                <p className="text-slate-400 text-sm mt-1 font-medium">当前工期执行情况一览</p>
              </div>

              <div className="space-y-10">
                  {stages.map(stage => (
                      <div key={stage.id} className="relative bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <div className="flex justify-between items-center mb-6">
                                <h4 className="font-black text-slate-800 text-xl">{stage.title}</h4>
                                <span className="text-[10px] font-black text-slate-300 uppercase bg-slate-50 px-3 py-1 rounded-full">EST: {estimates[stage.id]} DAYS</span>
                          </div>

                          <div className="grid grid-cols-2 gap-4">
                              <div className="bg-fuchsia-50 p-5 rounded-3xl border border-fuchsia-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase tracking-widest mb-1 text-center">原本规划</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-5 rounded-3xl border border-emerald-100 flex flex-col items-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1 text-center">累计工时</span>
                                  <div className="text-3xl font-black text-emerald-600">{totalHours} <span className="text-xs">h</span></div>
                              </div>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-8 bg-gradient-to-br from-indigo-600 to-violet-700 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_top_right,rgba(255,255,255,0.1),transparent)]"></div>
                <h3 className="text-xl font-black mb-2 flex items-center gap-2"><Sparkles size={20} /> 创作寄语</h3>
                <p className="text-sm text-indigo-100 font-medium leading-relaxed opacity-90">
                  规划只是灵感的骨架，真正的艺术是在现实的起伏中开出的花。不论快慢，保持画笔不停即是胜利。
                </p>
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useRef, useEffect } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle, Minus, Timer } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'period-select' | 'timeline-entry' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Recording State
  const [currentRecordingDay, setCurrentRecordingDay] = useState<number>(1);
  const [dailySlots, setDailySlots] = useState<Record<number, string[]>>({});

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  // Calculate the actual calendar date for a specific work day index
  const getWorkDayDate = (dayIndex: number): Date => {
    let current = syncedProject ? new Date(syncedProject.startDate) : new Date(sessionStartDate);
    let workDayCount = 0;

    let attempts = 0;
    while (workDayCount < dayIndex && attempts < 365) {
      const dStr = getYYYYMMDD(current);
      if (!isDateBlocked(dStr)) {
        workDayCount++;
        if (workDayCount === dayIndex) return current;
      }
      current.setDate(current.getDate() + 1);
      attempts++;
    }
    return current;
  };

  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const totalAvailableDays = 30; // Default context
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Time Slot Logic (09:00 - 03:00 next day) ---
  const timelineSlots = Array.from({ length: 37 }).map((_, i) => {
    let hour = 9 + Math.floor(i / 2);
    let displayHour = hour;
    if (hour >= 24) displayHour -= 24;
    const minutes = (i % 2 === 0) ? '00' : '30';
    return `${String(displayHour).padStart(2, '0')}:${minutes}`;
  });

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      // Automatic upward jump logic: focus previous stage
      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setDailySlots({});
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setDailySlots(session.dailySlots || {});
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
          dailySlots: {}
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleSlot = (slot: string) => {
    setDailySlots(prev => {
      const currentDaySlots = prev[currentRecordingDay] || [];
      const nextSlots = currentDaySlots.includes(slot) 
        ? currentDaySlots.filter(s => s !== slot) 
        : [...currentDaySlots, slot];
      const newDaily = { ...prev, [currentRecordingDay]: nextSlots };

      if (currentSessionId) {
        const updated = sessions.map(s => s.id === currentSessionId ? {
          ...s,
          dailySlots: newDaily,
          lastUpdated: new Date().toISOString()
        } : s);
        persistSessions(updated);
      }
      return newDaily;
    });
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((Object.keys(session.dailySlots || {}).length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                </div>
              )}
              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between">
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ 30 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex flex-col p-5 rounded-[2rem] border-2 transition-all cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                                    <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    {isActive ? (
                                        <div className="flex items-center gap-2 mt-2">
                                            <input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 outline-none" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} />
                                            <button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-3 rounded-xl shadow-lg active:scale-90"><ArrowUp size={20} /></button>
                                        </div>
                                    ) : (
                                        <span className={`font-black ${isDone ? 'text-fuchsia-600' : 'text-slate-300'}`}>{estimates[stage.id] ? `${estimates[stage.id]} 天` : '--'}</span>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button onClick={() => setPlanningStep('finished')} className="fixed bottom-24 left-5 right-5 bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl">确认并完成规划</button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600">{estimates[stage.id]} 天</span>
                    </div>
                ))}
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95"><Rocket size={24} className="mr-2 inline" />开启工作流 (Done List)</button>
        </div>
    );
  }

  if (planningStep === 'time-boxing') {
      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">灵感工作流</h2>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full border border-fuchsia-100">复盘</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const dateObj = getWorkDayDate(dayNum);
                      const slots = dailySlots[dayNum] || [];
                      const isRecorded = slots.length > 0;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => { setCurrentRecordingDay(dayNum); setPlanningStep('period-select'); }}
                            className={`p-6 rounded-[2.5rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isRecorded ? 'bg-indigo-50 border-indigo-100' : 'bg-white border-slate-100'}`}
                          >
                              <div className="flex flex-col items-center text-center">
                                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Day {dayNum}</span>
                                  <span className={`text-4xl font-black ${isRecorded ? 'text-indigo-600' : 'text-slate-800'}`}>{dateObj.getDate()}</span>
                                  <span className="text-[10px] font-bold text-slate-400 mt-1">{dateObj.toLocaleDateString('zh-CN', { month: 'short' })}</span>
                                  <div className={`mt-3 p-2 rounded-xl ${isRecorded ? 'bg-indigo-500 text-white' : 'bg-slate-50 text-slate-300'}`}>
                                      {isRecorded ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  if (planningStep === 'period-select') {
    return (
        <div className="animate-fade-in pb-32">
            <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-8 font-bold text-sm"><ArrowLeft size={16} /> 返回列表</button>
            <div className="mb-8">
                <span className="text-fuchsia-500 font-black uppercase text-xs tracking-widest">Day {currentRecordingDay} 记录</span>
                <h2 className="text-3xl font-black text-slate-800 mt-1">绘画时段</h2>
            </div>
            <div className="space-y-4">
                {[
                    { id: 'morning', title: '早间时段', desc: '09:00 - 13:00', icon: <Sunrise size={28} />, bg: 'from-orange-50 to-amber-50', color: 'text-orange-600' },
                    { id: 'afternoon', title: '午后时段', desc: '13:00 - 20:00', icon: <Sun size={28} />, bg: 'from-blue-50 to-indigo-50', color: 'text-blue-600' },
                    { id: 'night', title: '深夜时段', desc: '20:00 - 03:00', icon: <Moon size={28} />, bg: 'from-indigo-50 to-purple-50', color: 'text-indigo-600' }
                ].map(p => (
                    <button 
                        key={p.id} 
                        onClick={() => setPlanningStep('timeline-entry')}
                        className={`w-full p-6 bg-gradient-to-br ${p.bg} rounded-[2rem] border border-black/5 flex items-center gap-6 text-left active:scale-95 transition-all group shadow-sm`}
                    >
                        <div className={`w-14 h-14 bg-white rounded-2xl shadow-sm flex items-center justify-center ${p.color}`}>{p.icon}</div>
                        <div>
                            <h3 className={`font-black text-lg ${p.color.replace('text', 'text-slate-800')}`}>{p.title}</h3>
                            <p className="text-slate-400 text-xs font-bold leading-relaxed">{p.desc}</p>
                        </div>
                        <ChevronRight className="ml-auto text-slate-300" />
                    </button>
                ))}
            </div>
        </div>
    );
  }

  if (planningStep === 'timeline-entry') {
      const currentDaySlots = dailySlots[currentRecordingDay] || [];
      const totalHours = currentDaySlots.length * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('period-select')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回</button>
                <div className="bg-slate-900 text-white px-4 py-2 rounded-full text-xs font-black">Day {currentRecordingDay} Timeline</div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl mb-8 border border-slate-50 flex items-center justify-between">
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">今日时长</span>
                    <div className="flex items-baseline gap-1 mt-1">
                        <span className="text-4xl font-black text-slate-800">{totalHours}</span>
                        <span className="text-sm font-bold text-slate-400">h</span>
                    </div>
                </div>
                <Timer size={40} className="text-fuchsia-100" />
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2">选择完成时间点 (09:00 - 03:00)</h3>

              <div className="grid grid-cols-3 gap-2">
                  {timelineSlots.map(slot => {
                      const isSelected = currentDaySlots.includes(slot);
                      return (
                          <div 
                            key={slot} 
                            onClick={() => toggleSlot(slot)}
                            className={`p-3 rounded-2xl border-2 transition-all cursor-pointer text-center relative
                                ${isSelected ? 'bg-fuchsia-500 border-fuchsia-500 text-white shadow-lg' : 'bg-white border-slate-50 text-slate-400'}`}
                          >
                              <span className="text-sm font-black">{slot}</span>
                          </div>
                      );
                  })}
              </div>

              <button 
                onClick={() => setPlanningStep('time-boxing')}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg mt-12 shadow-xl active:scale-95"
              >
                  保存记录
              </button>
          </div>
      );
  }

  if (planningStep === 'daily-comparison') {
      const totalSlots = Object.values(dailySlots).reduce((acc, curr) => acc + curr.length, 0);
      const totalHours = totalSlots * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold"><ArrowLeft size={16} /> 返回</button>
              </div>
              <div className="mb-8 px-1">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感对比</h2>
                <p className="text-slate-400 text-sm mt-1">理想 vs 现实</p>
              </div>

              <div className="space-y-6">
                  {stages.map(stage => (
                      <div key={stage.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <h4 className="font-black text-slate-800 text-lg mb-4">{stage.title}</h4>
                          <div className="grid grid-cols-2 gap-4">
                              <div className="bg-fuchsia-50 p-4 rounded-3xl text-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase block mb-1">规划天数</span>
                                  <div className="text-2xl font-black text-fuchsia-600">{estimates[stage.id]} 天</div>
                              </div>
                              <div className="bg-emerald-50 p-4 rounded-3xl text-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase block mb-1">执行时长</span>
                                  <div className="text-2xl font-black text-emerald-600">{totalHours} h</div>
                              </div>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle, Minus, Timer } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'period-select' | 'timeline-entry' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Recording State
  const [currentRecordingDay, setCurrentRecordingDay] = useState<number>(1);
  const [dailySlots, setDailySlots] = useState<Record<number, string[]>>({});

  const dragItem = useRef<number | null>(null);
  const dragOverItem = useRef<number | null>(null);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  // NEW: Calculate Total Available Days based on the sync'd project range minus blocked days
  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; // Default if no project linked

    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0;
    let curr = new Date(start);

    while (curr <= end) {
      if (!isDateBlocked(getYYYYMMDD(curr))) {
        count++;
      }
      curr.setDate(curr.getDate() + 1);
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  // Calculate the actual calendar date for a specific work day index, skipping blocked dates
  const getWorkDayDate = (dayIndex: number): Date => {
    let current = syncedProject ? new Date(syncedProject.startDate) : new Date(sessionStartDate);
    let workDayCount = 0;

    let attempts = 0;
    while (workDayCount < dayIndex && attempts < 365) {
      const dStr = getYYYYMMDD(current);
      if (!isDateBlocked(dStr)) {
        workDayCount++;
        if (workDayCount === dayIndex) return current;
      }
      current.setDate(current.getDate() + 1);
      attempts++;
    }
    return current;
  };

  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Time Slot Logic (09:00 - 03:00 next day) ---
  const timelineSlots = Array.from({ length: 37 }).map((_, i) => {
    let hour = 9 + Math.floor(i / 2);
    let displayHour = hour;
    if (hour >= 24) displayHour -= 24;
    const minutes = (i % 2 === 0) ? '00' : '30';
    return `${String(displayHour).padStart(2, '0')}:${minutes}`;
  });

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      // Automatic upward jump logic: focus previous stage
      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setDailySlots({});
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setDailySlots(session.dailySlots || {});
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
          dailySlots: {}
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleSlot = (slot: string) => {
    setDailySlots(prev => {
      const currentDaySlots = prev[currentRecordingDay] || [];
      const nextSlots = currentDaySlots.includes(slot) 
        ? currentDaySlots.filter(s => s !== slot) 
        : [...currentDaySlots, slot];
      const newDaily = { ...prev, [currentRecordingDay]: nextSlots };

      if (currentSessionId) {
        const updated = sessions.map(s => s.id === currentSessionId ? {
          ...s,
          dailySlots: newDaily,
          lastUpdated: new Date().toISOString()
        } : s);
        persistSessions(updated);
      }
      return newDaily;
    });
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col items-center justify-center gap-3 mb-8 active:scale-95 transition-all group">
                <div className="bg-white/20 p-3 rounded-full group-hover:bg-fuchsia-500 transition-colors"><Plus size={24} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-lg">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((Object.keys(session.dailySlots || {}).length / Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0)) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                </div>
              )}
              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-3xl p-5 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                                  {isBlocked && <X size={20} className="absolute inset-0 m-auto opacity-30" strokeWidth={3} />}
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); }} className="w-full bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between">
                <div className="flex flex-col">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算 (排除休息日)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const isDone = estimates[stage.id] && !isActive;
                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div onClick={() => { setActiveTimeIndex(index); setCurrentInputTime(estimates[stage.id] || ''); }} className={`ml-10 flex-1 flex flex-col p-5 rounded-[2rem] border-2 transition-all cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
                                    <span className={`font-black ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    {isActive ? (
                                        <div className="flex items-center gap-2 mt-2">
                                            <input autoFocus type="text" value={currentInputTime} onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} className="w-16 bg-slate-50 border-2 border-fuchsia-100 rounded-xl px-2 py-2 text-center text-xl font-black text-fuchsia-600 outline-none" onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} />
                                            <button onClick={confirmTimeEntry} className="bg-slate-900 text-white p-3 rounded-xl shadow-lg active:scale-90"><ArrowUp size={20} /></button>
                                        </div>
                                    ) : (
                                        <span className={`font-black ${isDone ? 'text-fuchsia-600' : 'text-slate-300'}`}>{estimates[stage.id] ? `${estimates[stage.id]} 天` : '--'}</span>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button onClick={() => setPlanningStep('finished')} className="fixed bottom-24 left-5 right-5 bg-slate-900 text-white py-4 rounded-2xl font-black text-lg shadow-xl">确认并完成规划</button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-xl"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3">规划已就绪</h2>
            <div className="w-full bg-white rounded-3xl p-6 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-2 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <span className="font-black text-indigo-600">{estimates[stage.id]} 天</span>
                    </div>
                ))}
            </div>
            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95"><Rocket size={24} className="mr-2 inline" />开启工作流 (Done List)</button>
        </div>
    );
  }

  if (planningStep === 'time-boxing') {
      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">灵感工作流</h2>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-xs bg-fuchsia-50 px-4 py-2 rounded-full border border-fuchsia-100">复盘</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const dateObj = getWorkDayDate(dayNum);
                      const slots = dailySlots[dayNum] || [];
                      const isRecorded = slots.length > 0;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => { setCurrentRecordingDay(dayNum); setPlanningStep('period-select'); }}
                            className={`p-6 rounded-[2.5rem] border-2 transition-all cursor-pointer relative overflow-hidden group active:scale-95
                                ${isRecorded ? 'bg-indigo-50 border-indigo-100' : 'bg-white border-slate-100'}`}
                          >
                              <div className="flex flex-col items-center text-center">
                                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Day {dayNum}</span>
                                  <span className={`text-4xl font-black ${isRecorded ? 'text-indigo-600' : 'text-slate-800'}`}>{dateObj.getDate()}</span>
                                  <span className="text-[10px] font-bold text-slate-400 mt-1">{dateObj.toLocaleDateString('zh-CN', { month: 'short' })}</span>
                                  <div className={`mt-3 p-2 rounded-xl ${isRecorded ? 'bg-indigo-500 text-white' : 'bg-slate-50 text-slate-300'}`}>
                                      {isRecorded ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  if (planningStep === 'period-select') {
    return (
        <div className="animate-fade-in pb-32">
            <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-8 font-bold text-sm"><ArrowLeft size={16} /> 返回列表</button>
            <div className="mb-8">
                <span className="text-fuchsia-500 font-black uppercase text-xs tracking-widest">Day {currentRecordingDay} 记录</span>
                <h2 className="text-3xl font-black text-slate-800 mt-1">绘画时段</h2>
            </div>
            <div className="space-y-4">
                {[
                    { id: 'morning', title: '早间时段', desc: '09:00 - 13:00', icon: <Sunrise size={28} />, bg: 'from-orange-50 to-amber-50', color: 'text-orange-600' },
                    { id: 'afternoon', title: '午后时段', desc: '13:00 - 20:00', icon: <Sun size={28} />, bg: 'from-blue-50 to-indigo-50', color: 'text-blue-600' },
                    { id: 'night', title: '深夜时段', desc: '20:00 - 03:00', icon: <Moon size={28} />, bg: 'from-indigo-50 to-purple-50', color: 'text-indigo-600' }
                ].map(p => (
                    <button 
                        key={p.id} 
                        onClick={() => setPlanningStep('timeline-entry')}
                        className={`w-full p-6 bg-gradient-to-br ${p.bg} rounded-[2rem] border border-black/5 flex items-center gap-6 text-left active:scale-95 transition-all group shadow-sm`}
                    >
                        <div className={`w-14 h-14 bg-white rounded-2xl shadow-sm flex items-center justify-center ${p.color}`}>{p.icon}</div>
                        <div>
                            <h3 className={`font-black text-lg ${p.color.replace('text', 'text-slate-800')}`}>{p.title}</h3>
                            <p className="text-slate-400 text-xs font-bold leading-relaxed">{p.desc}</p>
                        </div>
                        <ChevronRight className="ml-auto text-slate-300" />
                    </button>
                ))}
            </div>
        </div>
    );
  }

  if (planningStep === 'timeline-entry') {
      const currentDaySlots = dailySlots[currentRecordingDay] || [];
      const totalHours = currentDaySlots.length * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('period-select')} className="text-slate-400 font-bold text-sm flex items-center gap-1"><ArrowLeft size={16} /> 返回</button>
                <div className="bg-slate-900 text-white px-4 py-2 rounded-full text-xs font-black">Day {currentRecordingDay} Timeline</div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl mb-8 border border-slate-50 flex items-center justify-between">
                <div className="flex flex-col">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">今日时长</span>
                    <div className="flex items-baseline gap-1 mt-1">
                        <span className="text-4xl font-black text-slate-800">{totalHours}</span>
                        <span className="text-sm font-bold text-slate-400">h</span>
                    </div>
                </div>
                <Timer size={40} className="text-fuchsia-100" />
              </div>

              <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-6 px-2">选择完成时间点 (09:00 - 03:00)</h3>

              <div className="grid grid-cols-3 gap-2">
                  {timelineSlots.map(slot => {
                      const isSelected = currentDaySlots.includes(slot);
                      return (
                          <div 
                            key={slot} 
                            onClick={() => toggleSlot(slot)}
                            className={`p-3 rounded-2xl border-2 transition-all cursor-pointer text-center relative
                                ${isSelected ? 'bg-fuchsia-500 border-fuchsia-500 text-white shadow-lg' : 'bg-white border-slate-50 text-slate-400'}`}
                          >
                              <span className="text-sm font-black">{slot}</span>
                          </div>
                      );
                  })}
              </div>

              <button 
                onClick={() => setPlanningStep('time-boxing')}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg mt-12 shadow-xl active:scale-95"
              >
                  保存记录
              </button>
          </div>
      );
  }

  if (planningStep === 'daily-comparison') {
      const totalSlots = Object.values(dailySlots).reduce((acc, curr) => acc + curr.length, 0);
      const totalHours = totalSlots * 0.5;

      return (
          <div className="animate-fade-in pb-32">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold"><ArrowLeft size={16} /> 返回</button>
              </div>
              <div className="mb-8 px-1">
                <h2 className="text-3xl font-black text-slate-800 tracking-tight">灵感对比</h2>
                <p className="text-slate-400 text-sm mt-1">理想 vs 现实</p>
              </div>

              <div className="space-y-6">
                  {stages.map(stage => (
                      <div key={stage.id} className="bg-white p-6 rounded-[2.5rem] border-2 border-slate-50 shadow-sm">
                          <h4 className="font-black text-slate-800 text-lg mb-4">{stage.title}</h4>
                          <div className="grid grid-cols-2 gap-4">
                              <div className="bg-fuchsia-50 p-4 rounded-3xl text-center">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase block mb-1">规划天数</span>
                                  <div className="text-2xl font-black text-fuchsia-600">{estimates[stage.id]} 天</div>
                              </div>
                              <div className="bg-emerald-50 p-4 rounded-3xl text-center">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase block mb-1">执行时长</span>
                                  <div className="text-2xl font-black text-emerald-600">{totalHours} h</div>
                              </div>
                          </div>
                      </div>
                  ))}
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Sparkles, Check, Clock, ArrowUp, Box, Link, Calendar, Hourglass, Sunrise, Sun, Moon, ChevronRight, CheckCircle, CheckCircle2, PlayCircle, PenTool, ThumbsUp, Zap, Heart, Smile, Lock, LayoutGrid, MoreHorizontal, Trash2, Coffee, ChevronLeft, Target, Rocket, AlertTriangle, Minus, Timer } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [], onUpdateBookings }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [sessionStartDate] = useState(new Date());
  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'time-boxing' | 'period-select' | 'timeline-entry' | 'daily-comparison'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // Recording State
  const [currentRecordingDay, setCurrentRecordingDay] = useState<number>(1);
  const [dailySlots, setDailySlots] = useState<Record<number, string[]>>({});

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  // Calculate Total Available Days based on the sync'd project range minus blocked days
  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; // Default if no project linked

    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0;
    let curr = new Date(start);

    // Ensure loop terminates
    let limit = 0;
    while (curr <= end && limit < 1000) {
      if (!isDateBlocked(getYYYYMMDD(curr))) {
        count++;
      }
      curr.setDate(curr.getDate() + 1);
      limit++;
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  // Calculate the actual calendar date for a specific work day index, skipping blocked dates
  const getWorkDayDate = (dayIndex: number): Date => {
    let current = syncedProject ? new Date(syncedProject.startDate) : new Date(sessionStartDate);
    let workDayCount = 0;

    let attempts = 0;
    while (workDayCount < dayIndex && attempts < 365) {
      const dStr = getYYYYMMDD(current);
      if (!isDateBlocked(dStr)) {
        workDayCount++;
        if (workDayCount === dayIndex) return current;
      }
      current.setDate(current.getDate() + 1);
      attempts++;
    }
    return current;
  };

  const currentPlannedDays = Object.values(estimates).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Time Slot Logic (09:00 - 03:00 next day) ---
  const timelineSlots = Array.from({ length: 37 }).map((_, i) => {
    let hour = 9 + Math.floor(i / 2);
    let displayHour = hour;
    if (hour >= 24) displayHour -= 24;
    const minutes = (i % 2 === 0) ? '00' : '30';
    return `${String(displayHour).padStart(2, '0')}:${minutes}`;
  });

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      // Automatic upward jump logic: focus previous stage (from bottom to top)
      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          // If the top stage is finished, show the summary
          setActiveTimeIndex(-1); // No active stage
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setCurrentSessionId(null);
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setDailySlots({});
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleResumeSession = (session: PlanningSession) => {
      setMode('planner');
      setCurrentSessionId(session.id);
      setStages(session.stages);
      setEstimates(session.estimates);
      setSessionBlockedDates(session.blockedDates || []);
      setDailySlots(session.dailySlots || {});
      if (session.projectId) {
          const project = projects?.find(p => p.id === session.projectId);
          if (project) setSyncedProject(project);
      } else setSyncedProject(null);
      setPlanningStep('time-boxing');
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
          dailySlots: {}
      };
      persistSessions([newSession, ...sessions]);
      setCurrentSessionId(newSession.id);
      setPlanningStep('time-boxing');
  };

  const toggleSlot = (slot: string) => {
    setDailySlots(prev => {
      const currentDaySlots = prev[currentRecordingDay] || [];
      const nextSlots = currentDaySlots.includes(slot) 
        ? currentDaySlots.filter(s => s !== slot) 
        : [...currentDaySlots, slot];
      const newDaily = { ...prev, [currentRecordingDay]: nextSlots };

      if (currentSessionId) {
        const updated = sessions.map(s => s.id === currentSessionId ? {
          ...s,
          dailySlots: newDaily,
          lastUpdated: new Date().toISOString()
        } : s);
        persistSessions(updated);
      }
      return newDaily;
    });
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>
             <div className="mb-8 px-1">
                 <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                 <p className="text-slate-400 text-sm mt-1 font-medium">管理你的排单创作节奏</p>
             </div>
             <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center gap-4 mb-8 active:scale-95 transition-all group overflow-hidden relative">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/20 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                <div className="bg-white/20 p-4 rounded-3xl group-hover:bg-fuchsia-500 transition-colors"><Plus size={32} /></div>
                <div className="text-center">
                    <h3 className="font-bold text-xl">创建新规划</h3>
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Inspiration</p>
                </div>
             </button>
             {sessions.length > 0 ? (
                 <div className="space-y-4">
                     {sessions.map(session => (
                        <div key={session.id} onClick={() => handleResumeSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group relative">
                            <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                            <div className="flex items-center gap-3 mt-1">
                                <p className="text-xs text-slate-400">上次更新: {formatDate(session.lastUpdated)}</p>
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-black px-2 py-0.5 rounded-full uppercase">
                                    {Math.round((Object.keys(session.dailySlots || {}).length / Math.max(1, Object.values(session.estimates).reduce((a: number, b: string) => a + Number(b), 0))) * 100)}% 完成
                                </span>
                            </div>
                        </div>
                     ))}
                 </div>
             ) : (
                <div className="text-center py-12 bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200">
                    <p className="text-sm text-slate-400 font-medium">暂无进行中的规划</p>
                </div>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>
                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                </div>
              )}
              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2.5rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="text-slate-200 mr-4"><GripVertical size={24} /></div>
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                        <span className="font-black text-slate-700 text-lg leading-none">{stage.title}</span>
                    </div>
                    {stage.isDeletable !== false && (
                        <button onClick={() => setStages(stages.filter(s => s.id !== stage.id))} className="ml-auto p-2 text-slate-200 hover:text-rose-400 opacity-0 group-hover:opacity-100 transition-all">
                            <Trash2 size={16} />
                        </button>
                    )}
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32 px-1">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 font-bold' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(''); }} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col px-1">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                <div className="flex flex-col relative z-10">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算 (排除休息日)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black transition-colors ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500 relative z-10" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const value = estimates[stage.id];
                        const isDone = value && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-300 flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-100' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div 
                                    onClick={() => { 
                                        setActiveTimeIndex(index); 
                                        setCurrentInputTime(estimates[stage.id] || ''); 
                                    }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2.5rem] border-2 transition-all duration-300 cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}
                                >
                                    <div className="flex justify-between items-start">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                        {isDone && (
                                            <span className="text-[10px] font-black text-fuchsia-600/60 uppercase tracking-widest bg-fuchsia-50 px-2 py-0.5 rounded-full">已完成</span>
                                        )}
                                    </div>

                                    {isActive ? (
                                        <div className="flex items-center gap-3 mt-3 animate-fade-in">
                                            <div className="relative flex-1 max-w-[120px]">
                                                <input 
                                                    autoFocus 
                                                    type="text" 
                                                    value={currentInputTime} 
                                                    onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                    className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-2xl px-4 py-3 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-colors" 
                                                    placeholder="0"
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-fuchsia-300">DAYS</span>
                                            </div>
                                            <button 
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    confirmTimeEntry();
                                                }} 
                                                className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl shadow-slate-200 active:scale-90 transition-all hover:bg-slate-800"
                                            >
                                                <ArrowUp size={24} strokeWidth={2.5} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="mt-1">
                                            {value ? (
                                                <span className="text-xs font-black text-fuchsia-600">预期损耗: {value} 天</span>
                                            ) : (
                                                <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">待填写</span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button 
                onClick={() => setPlanningStep('finished')} 
                className={`fixed bottom-24 left-5 right-5 py-5 rounded-2xl font-black text-lg shadow-xl transition-all ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                disabled={Object.keys(estimates).length !== stages.length}
            >
                确认并生成规划
            </button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center pb-32">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-2xl shadow-emerald-100 border-4 border-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3 tracking-tight">规划已就绪</h2>
            <p className="text-slate-400 text-sm font-medium mb-8">每一个阶段都已准备好被灵感填满</p>

            <div className="w-full bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-slate-300 uppercase">预计</span>
                            <span className="font-black text-indigo-600 text-lg">{estimates[stage.id]} 天</span>
                        </div>
                    </div>
                ))}
            </div>

            <button onClick={handleFinalize} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                <Rocket size={24} />
                开启工作流 (Done List)
            </button>
        </div>
    );
  }

  if (planningStep === 'time-boxing') {
      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-8">
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">灵感工作流</h2>
                  <button onClick={() => setPlanningStep('daily-comparison')} className="text-fuchsia-600 font-black text-[10px] uppercase tracking-widest bg-fuchsia-50 px-4 py-2 rounded-full border border-fuchsia-100 hover:bg-fuchsia-100 transition-colors">进度复盘</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                  {Array.from({ length: currentPlannedDays }).map((_, i) => {
                      const dayNum = i + 1;
                      const dateObj = getWorkDayDate(dayNum);
                      const slots = dailySlots[dayNum] || [];
                      const isRecorded = slots.length > 0;

                      return (
                          <div 
                            key={dayNum} 
                            onClick={() => { setCurrentRecordingDay(dayNum); setPlanningStep('period-select'); }}
                            className={`p-6 rounded-[2.5rem] border-2 transition-all duration-300 cursor-pointer relative overflow-hidden group active:scale-95
                                ${isRecorded ? 'bg-indigo-50 border-indigo-100 shadow-lg shadow-indigo-50' : 'bg-white border-slate-100 hover:border-slate-200'}`}
                          >
                              <div className="flex flex-col items-center text-center">
                                  <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-1">Day {dayNum}</span>
                                  <span className={`text-5xl font-black transition-colors ${isRecorded ? 'text-indigo-600' : 'text-slate-800'}`}>{dateObj.getDate()}</span>
                                  <span className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-tighter">{dateObj.toLocaleDateString('zh-CN', { month: 'short' })}</span>
                                  <div className={`mt-4 p-2.5 rounded-2xl transition-all ${isRecorded ? 'bg-indigo-500 text-white scale-110 shadow-md shadow-indigo-200' : 'bg-slate-50 text-slate-200 group-hover:text-slate-400'}`}>
                                      {isRecorded ? <CheckCircle size={20} /> : <ThumbsUp size={20} />}
                                  </div>
                              </div>
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  if (planningStep === 'period-select') {
    return (
        <div className="animate-fade-in pb-32 px-1">
            <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 mb-8 font-bold text-sm hover:text-slate-800"><ArrowLeft size={16} /> 返回列表</button>
            <div className="mb-8 px-1">
                <span className="text-fuchsia-500 font-black uppercase text-[10px] tracking-widest bg-fuchsia-50 px-2 py-1 rounded-md">Day {currentRecordingDay} 记录</span>
                <h2 className="text-3xl font-black text-slate-800 mt-2 tracking-tight">请选择绘画时段</h2>
                <p className="text-slate-400 text-xs mt-1 font-medium italic">选择最符合你生理时钟的时段进行记录</p>
            </div>
            <div className="space-y-4">
                {[
                    { id: 'morning', title: '早间时段', desc: '09:00 - 13:00', icon: <Sunrise size={28} />, bg: 'from-orange-50 to-amber-50', color: 'text-orange-600', shadow: 'shadow-orange-100' },
                    { id: 'afternoon', title: '午后时段', desc: '13:00 - 20:00', icon: <Sun size={28} />, bg: 'from-blue-50 to-indigo-50', color: 'text-blue-600', shadow: 'shadow-blue-100' },
                    { id: 'night', title: '深夜时段', desc: '20:00 - 03:00', icon: <Moon size={28} />, bg: 'from-indigo-50 to-purple-50', color: 'text-indigo-600', shadow: 'shadow-indigo-100' }
                ].map(p => (
                    <button 
                        key={p.id} 
                        onClick={() => setPlanningStep('timeline-entry')}
                        className={`w-full p-7 bg-gradient-to-br ${p.bg} rounded-[2.5rem] border border-black/5 flex items-center gap-6 text-left active:scale-[0.97] transition-all group shadow-sm hover:${p.shadow} hover:shadow-lg`}
                    >
                        <div className={`w-16 h-16 bg-white rounded-3xl shadow-sm flex items-center justify-center ${p.color} group-hover:scale-110 transition-transform`}>{p.icon}</div>
                        <div>
                            <h3 className={`font-black text-xl ${p.color.replace('text', 'text-slate-800')}`}>{p.title}</h3>
                            <p className="text-slate-400 text-xs font-bold leading-relaxed tracking-wide opacity-80">{p.desc}</p>
                        </div>
                        <ChevronRight className="ml-auto text-slate-300 group-hover:text-slate-500 transition-colors" />
                    </button>
                ))}
            </div>
        </div>
    );
  }

  if (planningStep === 'timeline-entry') {
      const currentDaySlots = dailySlots[currentRecordingDay] || [];
      const totalHours = currentDaySlots.length * 0.5;

      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('period-select')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回时段</button>
                <div className="bg-slate-900 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">Day {currentRecordingDay} Timeline</div>
              </div>

              <div className="bg-white rounded-[2.5rem] p-8 shadow-2xl mb-8 border border-slate-50 flex items-center justify-between relative overflow-hidden">
                <div className="absolute top-0 right-0 w-40 h-40 bg-fuchsia-100/50 rounded-full -mr-20 -mt-20 blur-3xl"></div>
                <div className="flex flex-col relative z-10">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">今日绘画累计时长</span>
                    <div className="flex items-baseline gap-2 mt-1">
                        <span className="text-5xl font-black text-slate-800 tracking-tighter">{totalHours}</span>
                        <span className="text-xl font-bold text-slate-400">h</span>
                    </div>
                </div>
                <Timer size={48} className="text-fuchsia-200 relative z-10" strokeWidth={2.5} />
              </div>

              <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-6 px-3">点击标记已完成时间点 (09:00 - 03:00)</h3>

              <div className="grid grid-cols-3 gap-3">
                  {timelineSlots.map(slot => {
                      const isSelected = currentDaySlots.includes(slot);
                      return (
                          <div 
                            key={slot} 
                            onClick={() => toggleSlot(slot)}
                            className={`py-4 rounded-2xl border-2 transition-all duration-300 cursor-pointer text-center relative font-black text-sm
                                ${isSelected ? 'bg-fuchsia-500 border-fuchsia-500 text-white shadow-lg shadow-fuchsia-100 scale-105 z-10' : 'bg-white border-slate-50 text-slate-400 hover:border-slate-200'}`}
                          >
                              {slot}
                          </div>
                      );
                  })}
              </div>

              <button 
                onClick={() => setPlanningStep('time-boxing')}
                className="w-full bg-slate-900 text-white py-6 rounded-[2.5rem] font-black text-xl mt-12 shadow-2xl shadow-slate-200 active:scale-95 transition-all"
              >
                  保存并完成今日记录
              </button>
          </div>
      );
  }

  if (planningStep === 'daily-comparison') {
      const totalSlots = Object.values(dailySlots).reduce((acc, curr) => acc + curr.length, 0);
      const totalHours = totalSlots * 0.5;

      return (
          <div className="animate-fade-in pb-32 px-1">
              <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('time-boxing')} className="flex items-center text-slate-400 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回</button>
                <span className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-3 py-1 rounded-full uppercase tracking-widest border border-fuchsia-100">灵感统计</span>
              </div>
              <div className="mb-10 px-1">
                <h2 className="text-4xl font-black text-slate-800 tracking-tighter">理想 vs 现实</h2>
                <p className="text-slate-400 text-sm mt-2 font-medium">看看你的绘画节奏是否符合预期</p>
              </div>

              <div className="space-y-8">
                  {stages.map(stage => (
                      <div key={stage.id} className="bg-white p-7 rounded-[3rem] border-2 border-slate-50 shadow-sm relative overflow-hidden group">
                          <div className="absolute top-0 left-0 w-2 h-full bg-indigo-500 opacity-0 group-hover:opacity-100 transition-all"></div>
                          <h4 className="font-black text-slate-800 text-xl mb-6 flex justify-between items-center">
                              {stage.title}
                              <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">Stage {stage.id}</span>
                          </h4>
                          <div className="grid grid-cols-2 gap-6">
                              <div className="bg-fuchsia-50 p-6 rounded-[2rem] text-center border border-fuchsia-100">
                                  <span className="text-[10px] font-black text-fuchsia-400 uppercase block mb-2 tracking-widest">规划损耗</span>
                                  <div className="text-3xl font-black text-fuchsia-600">{estimates[stage.id]} <span className="text-xs">天</span></div>
                              </div>
                              <div className="bg-emerald-50 p-6 rounded-[2rem] text-center border border-emerald-100">
                                  <span className="text-[10px] font-black text-emerald-400 uppercase block mb-2 tracking-widest">实际投入</span>
                                  <div className="text-3xl font-black text-emerald-600">{totalHours} <span className="text-xs font-black">h</span></div>
                              </div>
                          </div>
                      </div>
                  ))}
              </div>

              <div className="mt-12 p-10 bg-gradient-to-br from-slate-900 to-indigo-950 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-fuchsia-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
                <div className="relative z-10 flex flex-col items-center text-center">
                    <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center mb-6 backdrop-blur-sm border border-white/10">
                        <Sparkles size={32} className="text-fuchsia-400" />
                    </div>
                    <h3 className="text-2xl font-black mb-3">进度总结</h3>
                    <p className="text-indigo-100/70 text-sm leading-relaxed max-w-[280px]">
                        规划是骨架，灵感是血肉。每一个小时的投入都是你向终稿迈进的坚实脚步。
                    </p>
                </div>
              </div>
          </div>
      );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [planningMode, setPlanningMode] = useState<'selection' | 'j-type' | 'p-type'>('selection');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>(''); // NEW: Client ID
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // WeChat User State (Port for Mini Program)
  const [wechatUser, setWechatUser] = useState<{nickname: string, avatar?: string} | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', // NEW
    description: '',
    startDate: '',
    deadline: ''
  });

  // Initialization: Load or Create IDs
  useEffect(() => {
    // Artist ID
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    // Client ID
    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    // Load Connected Artist ID (Persistence)
    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }
  }, []);

  // Determine current active Data Source ID based on View Mode
  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  // Load Data when ID or Mode changes
  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      return;
    }

    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
  }, [currentDataId, viewMode]);

  // Persist Data (Simulate Backend)
  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;

    if (searchId === myArtistId) {
       setConnectedArtistId(searchId);
       localStorage.setItem('artflow_connected_artist_id', searchId);
       return;
    }

    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    // Ideally we verify if it exists, but for local simulation we act as if it might
    if (targetProjects) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接（假设其存在）？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  // --- WeChat Login Port ---
  const handleWeChatLogin = () => {
    alert("微信登录接口已预留。小程序发布后将在此处调用 wx.login 同步账户信息。");
    setWechatUser({ nickname: "微信用户", avatar: "" });
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;

    if (editingProjectId) {
      setProjects(projects.map(p => 
        p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
        } : p
      ));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || 'No description',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }

    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({
      clientName: project.clientName,
      targetClientId: project.targetClientId,
      description: project.description,
      startDate: project.startDate,
      deadline: project.deadline
    });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;
    if(confirm('Delete this project?')) {
        setProjects(projects.filter(p => p.id !== id));
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');

    const response = await analyzeSchedule(projects, bookings, aiQuery);

    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制到剪贴板`);
  };

  // Switch Mode Handler
  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') {
      handleDisconnect();
    }
  };

  // Filter projects based on mode
  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  // Filter based on sub-tab
  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex flex-col">

      {/* Mobile Sticky Header */}
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm transition-all">
        <div className="flex justify-between items-center mb-3 md:mb-0">
          <div className="flex items-center gap-2.5">
            <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-indigo-200 shadow-lg">
              <Paintbrush size={18} />
            </div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight hidden md:block">
              ArtFlow
            </h1>
          </div>

          <div className="flex items-center gap-3">
             {viewMode === 'artist' && (
                <button 
                  onClick={() => setShowAI(!showAI)}
                  className={`p-2 rounded-full transition-colors ${showAI ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 text-slate-400'}`}
                >
                  <Sparkles size={20} />
                </button>
             )}
            <button 
                onClick={toggleViewMode}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full transition-all border ${viewMode === 'artist' ? 'bg-slate-800 text-white border-slate-800' : 'bg-indigo-600 text-white border-indigo-600'}`}
            >
                {viewMode === 'artist' ? <><Paintbrush size={12}/> 画手模式</> : <><UserCircle2 size={14}/> 单主模式</>}
            </button>
          </div>
        </div>

        {/* Dynamic Sub-Header Area */}
        <div className="w-full">
           {viewMode === 'artist' ? (
             <div className="flex items-center justify-between bg-slate-50 rounded-lg p-1.5 border border-slate-100">
               <div className="flex items-center gap-2 flex-1 min-w-0">
                  {wechatUser ? (
                      <div className="flex items-center gap-1.5 pl-1.5 bg-emerald-100/50 py-1 px-2 rounded-md">
                          <MessageCircle size={12} className="text-emerald-600" fill="currentColor" fillOpacity={0.2} />
                          <span className="text-xs font-bold text-emerald-800 truncate max-w-[80px]">{wechatUser.nickname}</span>
                      </div>
                  ) : (
                      <button 
                        onClick={handleWeChatLogin}
                        className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg transition-all shadow-sm shadow-emerald-200 active:scale-95"
                      >
                         <MessageCircle size={12} fill="currentColor" fillOpacity={0.2} />
                         <span className="text-[10px] font-bold">微信登录</span>
                      </button>
                  )}

                  <div className="flex items-center gap-1 min-w-0 flex-1 justify-end mr-2">
                     <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">ID</span>
                     <span className="text-xs text-slate-800 font-bold font-mono truncate">{myArtistId}</span>
                  </div>
               </div>

               <button onClick={() => copyText(myArtistId, 'Artist ID')} className="p-1.5 bg-white shadow-sm border border-slate-100 rounded-md text-slate-400 hover:text-indigo-600 transition-colors flex-shrink-0">
                 <Copy size={14} />
               </button>
             </div>
           ) : (
             <div className="flex gap-2">
               {!connectedArtistId ? (
                 <>
                  <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      value={searchId}
                      onChange={(e) => setSearchId(e.target.value)}
                      placeholder="搜索画手 ID (如: ART-1234)"
                      className="w-full bg-slate-100 border-none rounded-lg pl-9 pr-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
                  <button 
                    onClick={handleSearchArtist}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap"
                  >
                    连接
                  </button>
                 </>
               ) : (
                 <div className="flex items-center justify-between w-full bg-indigo-50 rounded-lg p-2 border border-indigo-100">
                    <span className="text-xs text-indigo-800 font-medium px-2 flex items-center gap-1">
                      <span className="opacity-60">已连接:</span> 
                      <span className="font-bold">{connectedArtistId}</span>
                    </span>
                    <button 
                      onClick={handleDisconnect}
                      className="flex items-center gap-1 bg-white px-2 py-1 rounded text-[10px] font-bold text-slate-500 shadow-sm"
                    >
                      <LogOut size={10} /> 退出
                    </button>
                 </div>
               )}
             </div>
           )}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 w-full max-w-lg mx-auto p-5 pb-32">

        {/* Client Mode - Initial State (Show ID) */}
        {viewMode === 'client' && !connectedArtistId && (
           <div className="flex flex-col items-center justify-center mt-10 animate-fade-in">
              <div className="w-full bg-white rounded-2xl shadow-xl shadow-slate-100 border border-slate-100 p-6 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-20 h-20 bg-indigo-50 rounded-bl-full -mr-10 -mt-10"></div>
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint className="text-indigo-600" size={24} />
                  <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider">我的单主 ID</h3>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-3xl font-black text-slate-800 tracking-tight">{myClientId}</span>
                  <button 
                    onClick={() => copyText(myClientId, '单主 ID')}
                    className="bg-indigo-50 text-indigo-600 p-2 rounded-lg hover:bg-indigo-100 transition-colors"
                    title="复制"
                  >
                    <Copy size={18} />
                  </button>
                </div>
                <p className="text-xs text-slate-400 mt-3 leading-relaxed">
                  请将此 ID 发送给画手。画手为您新建排单时填入此 ID，您连接后即可同步看到进度。
                </p>
              </div>

              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="text-slate-400 text-sm text-center max-w-[200px]">
                在上方搜索框输入画手 ID 开始连接
              </p>
           </div>
        )}

        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg shadow-indigo-100/50 animate-fade-in">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm">
                    <Sparkles size={14} className="text-indigo-500" /> 智能助理
                  </h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400 hover:text-slate-600">
                    <X size={16} />
                  </button>
                </div>

                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">
                  {isAiLoading ? (
                    <div className="flex items-center gap-2 text-indigo-500">
                      <div className="animate-spin h-3 w-3 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                      正在思考中...
                    </div>
                  ) : (
                    aiResponse || "你好！我是你的排单助手。可以问我关于档期安排、截稿压力的问题。"
                  )}
                </div>

                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={aiQuery}
                    onChange={(e) => setAiQuery(e.target.value)}
                    placeholder="问问我：下周还能接急单吗？"
                    className="flex-1 text-sm rounded-lg bg-white border border-slate-200 px-3 py-2.5 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()}
                  />
                  <button 
                    onClick={handleAiAsk}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                  >
                    发送
                  </button>
                </div>
              </div>
            )}

            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-4">
                <div className="flex flex-col gap-4">
                   <div className="flex justify-between items-end px-1">
                      <div>
                        <h2 className="text-xl font-bold text-slate-800">
                          {viewMode === 'artist' ? '我的排单' : '我的订单'}
                        </h2>
                        <p className="text-slate-400 text-xs mt-1">
                          {viewMode === 'artist' ? '关注颜色变化，避免延期' : `仅展示关联 ID: ${myClientId} 的项目`}
                        </p>
                      </div>
                      {viewMode === 'artist' && (
                        <button 
                          onClick={() => setShowAddModal(true)}
                          className="hidden md:flex bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold shadow-lg hover:scale-105 transition-transform gap-2 items-center"
                        >
                          <Plus size={16} /> 新建
                        </button>
                      )}
                   </div>

                   <div className="flex p-1 bg-slate-200/50 rounded-xl">
                      <button 
                        onClick={() => setProjectSubTab('active')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                         <Clock size={16} />
                         进行中
                         {allVisibleProjects.filter(p => p.status !== 'completed').length > 0 && (
                            <span className="bg-indigo-100 text-indigo-600 text-[10px] px-1.5 py-0.5 rounded-full ml-1">
                               {allVisibleProjects.filter(p => p.status !== 'completed').length}
                            </span>
                         )}
                      </button>
                      <button 
                        onClick={() => setProjectSubTab('completed')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                         <CheckCircle2 size={16} />
                         已完成
                         {allVisibleProjects.filter(p => p.status === 'completed').length > 0 && (
                            <span className="bg-emerald-100 text-emerald-600 text-[10px] px-1.5 py-0.5 rounded-full ml-1">
                               {allVisibleProjects.filter(p => p.status === 'completed').length}
                            </span>
                         )}
                      </button>
                   </div>
                </div>

                <div className="space-y-3 min-h-[200px]">
                  {displayedProjects.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-16 text-slate-400 bg-white rounded-2xl border border-dashed border-slate-200 mt-2">
                      <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-3">
                        {projectSubTab === 'active' ? <Paintbrush size={20} className="opacity-50" /> : <CheckCircle2 size={20} className="opacity-50" />}
                      </div>
                      <p className="text-sm font-medium">
                        {projectSubTab === 'active' ? '暂无进行中的约稿' : '暂无已完成的记录'}
                      </p>
                    </div>
                  )}

                  {displayedProjects
                    .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                    .map(project => (
                      <ProjectCard 
                        key={project.id} 
                        project={project} 
                        onComplete={handleCompleteProject}
                        onDelete={handleDeleteProject}
                        onEdit={handleEditProject}
                        readOnly={viewMode === 'client'}
                      />
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'schedule' && (
              <div className="animate-fade-in">
                 <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                    <ScheduleBoard 
                      bookings={bookings} 
                      projects={projects} 
                      mode={viewMode}
                      onUpdateBookings={setBookings}
                      currentClientId={viewMode === 'client' ? myClientId : undefined}
                      currentClientName={viewMode === 'client' ? '我' : undefined}
                    />
                 </div>
              </div>
            )}

            {activeTab === 'planning' && viewMode === 'artist' && (
              <div className="animate-fade-in">
                {planningMode === 'selection' && (
                  <div className="flex flex-col gap-6">
                    <div>
                      <h2 className="text-xl font-bold text-slate-800">辅助规划</h2>
                      <p className="text-slate-400 text-xs mt-1">选择最适合你的时间管理风格</p>
                    </div>

                    <button 
                      onClick={() => alert('J人规划法功能开发中...')}
                      className="bg-gradient-to-br from-indigo-50 to-blue-50 border border-indigo-100 p-6 rounded-3xl flex flex-col gap-3 shadow-sm hover:shadow-md transition-all active:scale-95 text-left group"
                    >
                      <div className="w-12 h-12 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                        <ListTodo size={24} />
                      </div>
                      <div>
                        <h3 className="text-lg font-bold text-indigo-900">J人规划法</h3>
                        <p className="text-xs text-indigo-600/70 font-medium mt-1">可量化，累计时间即可完成的任务类型</p>
                      </div>
                    </button>

                    <button 
                      onClick={() => setPlanningMode('p-type')}
                      className="bg-gradient-to-br from-fuchsia-50 to-rose-50 border border-fuchsia-100 p-6 rounded-3xl flex flex-col gap-3 shadow-sm hover:shadow-md transition-all active:scale-95 text-left group"
                    >
                      <div className="w-12 h-12 bg-fuchsia-100 rounded-2xl flex items-center justify-center text-fuchsia-600 group-hover:bg-fuchsia-600 group-hover:text-white transition-colors">
                        <Lightbulb size={24} />
                      </div>
                      <div>
                        <h3 className="text-lg font-bold text-fuchsia-900">P人规划法</h3>
                        <p className="text-xs text-fuchsia-600/70 font-medium mt-1">抽象化，难以量化，以灵感驱动的任务类型</p>
                      </div>
                    </button>
                  </div>
                )}

                {planningMode === 'p-type' && (
                   <PTypePlanner 
                      onBack={() => setPlanningMode('selection')} 
                      projects={projects} 
                      bookings={bookings}
                      onUpdateBookings={setBookings}
                    />
