import React from 'react';
import { Project } from '../types';
import { calculateUrgencyColor, formatDate, getStatusLabel } from '../utils';
import { Clock, CheckCircle2, User, Trash2, Edit2, Copy, Link } from 'lucide-react';

interface ProjectCardProps {
  project: Project;
  onComplete: (id: string) => void;
  onDelete: (id: string) => void;
  onEdit: (project: Project) => void;
  readOnly?: boolean;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project, onComplete, onDelete, onEdit, readOnly = false }) => {
  const bgClass = project.status === 'completed' 
    ? 'bg-slate-50 border border-slate-100 text-slate-400' 
    : calculateUrgencyColor(project.startDate, project.deadline);

  // Button styles adjusted for soft backgrounds (White bg with shadow)
  const buttonBaseClass = "bg-white shadow-sm border border-slate-100 p-2 rounded-full transition-all hover:scale-110 hover:shadow-md active:scale-95";

  const handleCopyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(project.id);
    alert(`已复制排单 ID: ${project.id}\n请前往“辅助规划”粘贴此 ID 以同步任务。`);
  };

  return (
    <div className={`relative p-5 rounded-2xl transition-all duration-300 mb-4 ${bgClass} ${project.status !== 'completed' ? 'shadow-sm hover:shadow-md' : ''}`}>

      <div className="flex justify-between items-start mb-2">
        <h3 className="font-bold text-lg flex items-center gap-2 tracking-tight">
          <User size={18} className="opacity-60" />
          {project.clientName}
        </h3>
        <div className="flex gap-2 items-center">
            {/* Sync ID Button (Artist Only) */}
            {!readOnly && project.status !== 'completed' && (
                <button 
                  onClick={handleCopyId}
                  className="bg-white/60 hover:bg-white text-slate-500 hover:text-indigo-600 p-1.5 rounded-lg backdrop-blur-sm transition-colors flex items-center gap-1"
                  title="复制 ID 用于辅助规划"
                >
                  <Link size={12} />
                  <span className="text-[10px] font-bold">规划 ID</span>
                </button>
            )}
            {project.status !== 'completed' && (
              <span className="text-[10px] font-bold uppercase tracking-wider bg-white/60 px-2 py-1 rounded-full backdrop-blur-sm border border-black/5">
                {getStatusLabel(project.startDate, project.deadline)}
              </span>
            )}
        </div>
      </div>

      <p className="text-sm opacity-80 mb-5 font-medium line-clamp-2 leading-relaxed">
        {project.description}
      </p>

      <div className="flex items-center justify-between mt-auto">
        <div className="flex flex-col text-xs opacity-70 font-semibold gap-1.5">
          <div className="flex items-center gap-1.5">
            <Clock size={13} />
            <span>开始: {formatDate(project.startDate)}</span>
          </div>
          <div className="flex items-center gap-1.5">
            <Clock size={13} />
            <span>截止: {formatDate(project.deadline)}</span>
          </div>
        </div>

        {!readOnly && (
          <div className="flex gap-2 pl-2">
             <button 
                onClick={(e) => { e.stopPropagation(); onEdit(project); }}
                className={`${buttonBaseClass} text-slate-600 hover:text-indigo-600`}
                title="编辑"
              >
                <Edit2 size={16} />
             </button>
             {project.status !== 'completed' && (
              <button 
                onClick={(e) => { e.stopPropagation(); onComplete(project.id); }}
                className={`${buttonBaseClass} text-slate-600 hover:text-emerald-600`}
                title="完成"
              >
                <CheckCircle2 size={16} />
              </button>
             )}
             <button 
                onClick={(e) => { e.stopPropagation(); onDelete(project.id); }}
                className={`${buttonBaseClass} text-slate-400 hover:text-rose-600`}
                title="删除"
              >
                <Trash2 size={16} />
             </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ProjectCard;

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode, PlanningSession } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [planningMode, setPlanningMode] = useState<'selection' | 'j-type' | 'p-type'>('selection');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>(''); // NEW: Client ID
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // WeChat User State (Port for Mini Program)
  const [wechatUser, setWechatUser] = useState<{nickname: string, avatar?: string} | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', // NEW
    description: '',
    startDate: '',
    deadline: ''
  });

  // Initialization: Load or Create IDs
  useEffect(() => {
    // Artist ID
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    // Client ID
    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    // Load Connected Artist ID (Persistence)
    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }
  }, []);

  // Determine current active Data Source ID based on View Mode
  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  // Load Data when ID or Mode changes
  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      return;
    }

    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
  }, [currentDataId, viewMode]);

  // Persist Data (Simulate Backend)
  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;

    if (searchId === myArtistId) {
       setConnectedArtistId(searchId);
       localStorage.setItem('artflow_connected_artist_id', searchId);
       return;
    }

    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    // Ideally we verify if it exists, but for local simulation we act as if it might
    if (targetProjects) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接（假设其存在）？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  // --- WeChat Login Port ---
  const handleWeChatLogin = () => {
    alert("微信登录接口已预留。小程序发布后将在此处调用 wx.login 同步账户信息。");
    setWechatUser({ nickname: "微信用户", avatar: "" });
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;

    if (editingProjectId) {
      setProjects(projects.map(p => 
        p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
        } : p
      ));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || 'No description',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }

    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({
      clientName: project.clientName,
      targetClientId: project.targetClientId,
      description: project.description,
      startDate: project.startDate,
      deadline: project.deadline
    });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;
    if(confirm('确定要删除这个排单工单吗？删除后相关的辅助规划记录也将一并移除。')) {
        // 1. Update project list state
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));

        // 2. Cleanup associated planning sessions from local storage
        const storedSessions = localStorage.getItem('artflow_planning_sessions');
        if (storedSessions) {
            try {
                const sessions = JSON.parse(storedSessions) as PlanningSession[];
                const updatedSessions = sessions.filter(s => s.projectId !== id);
                localStorage.setItem('artflow_planning_sessions', JSON.stringify(updatedSessions));
            } catch (error) {
                console.error("Cleanup error:", error);
            }
        }
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');

    const response = await analyzeSchedule(projects, bookings, aiQuery);

    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制到剪贴板`);
  };

  // Switch Mode Handler
  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') {
      handleDisconnect();
    }
  };

  // Filter projects based on mode
  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  // Filter based on sub-tab
  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex flex-col">

      {/* Mobile Sticky Header */}
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm transition-all">
        <div className="flex justify-between items-center mb-3 md:mb-0">
          <div className="flex items-center gap-2.5">
            <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-indigo-200 shadow-lg">
              <Paintbrush size={18} />
            </div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight hidden md:block">
              ArtFlow
            </h1>
          </div>

          <div className="flex items-center gap-3">
             {viewMode === 'artist' && (
                <button 
                  onClick={() => setShowAI(!showAI)}
                  className={`p-2 rounded-full transition-colors ${showAI ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 text-slate-400'}`}
                >
                  <Sparkles size={20} />
                </button>
             )}
            <button 
                onClick={toggleViewMode}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full transition-all border ${viewMode === 'artist' ? 'bg-slate-800 text-white border-slate-800' : 'bg-indigo-600 text-white border-indigo-600'}`}
            >
                {viewMode === 'artist' ? <><Paintbrush size={12}/> 画手模式</> : <><UserCircle2 size={14}/> 单主模式</>}
            </button>
          </div>
        </div>

        {/* Dynamic Sub-Header Area */}
        <div className="w-full">
           {viewMode === 'artist' ? (
             <div className="flex items-center justify-between bg-slate-50 rounded-lg p-1.5 border border-slate-100">
               <div className="flex items-center gap-2 flex-1 min-w-0">
                  {wechatUser ? (
                      <div className="flex items-center gap-1.5 pl-1.5 bg-emerald-100/50 py-1 px-2 rounded-md">
                          <MessageCircle size={12} className="text-emerald-600" fill="currentColor" fillOpacity={0.2} />
                          <span className="text-xs font-bold text-emerald-800 truncate max-w-[80px]">{wechatUser.nickname}</span>
                      </div>
                  ) : (
                      <button 
                        onClick={handleWeChatLogin}
                        className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg transition-all shadow-sm shadow-emerald-200 active:scale-95"
                      >
                         <MessageCircle size={12} fill="currentColor" fillOpacity={0.2} />
                         <span className="text-[10px] font-bold">微信登录</span>
                      </button>
                  )}

                  <div className="flex items-center gap-1 min-w-0 flex-1 justify-end mr-2">
                     <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">ID</span>
                     <span className="text-xs text-slate-800 font-bold font-mono truncate">{myArtistId}</span>
                  </div>
               </div>

               <button onClick={() => copyText(myArtistId, 'Artist ID')} className="p-1.5 bg-white shadow-sm border border-slate-100 rounded-md text-slate-400 hover:text-indigo-600 transition-colors flex-shrink-0">
                 <Copy size={14} />
               </button>
             </div>
           ) : (
             <div className="flex gap-2">
               {!connectedArtistId ? (
                 <>
                  <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                      type="text" 
                      value={searchId}
                      onChange={(e) => setSearchId(e.target.value)}
                      placeholder="搜索画手 ID (如: ART-1234)"
                      className="w-full bg-slate-100 border-none rounded-lg pl-9 pr-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none"
                    />
                  </div>
                  <button 
                    onClick={handleSearchArtist}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap"
                  >
                    连接
                  </button>
                 </>
               ) : (
                 <div className="flex items-center justify-between w-full bg-indigo-50 rounded-lg p-2 border border-indigo-100">
                    <span className="text-xs text-indigo-800 font-medium px-2 flex items-center gap-1">
                      <span className="opacity-60">已连接:</span> 
                      <span className="font-bold">{connectedArtistId}</span>
                    </span>
                    <button 
                      onClick={handleDisconnect}
                      className="flex items-center gap-1 bg-white px-2 py-1 rounded text-[10px] font-bold text-slate-500 shadow-sm"
                    >
                      <LogOut size={10} /> 退出
                    </button>
                 </div>
               )}
             </div>
           )}
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 w-full max-w-lg mx-auto p-5 pb-32">

        {/* Client Mode - Initial State (Show ID) */}
        {viewMode === 'client' && !connectedArtistId && (
           <div className="flex flex-col items-center justify-center mt-10 animate-fade-in">
              <div className="w-full bg-white rounded-2xl shadow-xl shadow-slate-100 border border-slate-100 p-6 mb-8 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-20 h-20 bg-indigo-50 rounded-bl-full -mr-10 -mt-10"></div>
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint className="text-indigo-600" size={24} />
                  <h3 className="text-sm font-bold text-slate-500 uppercase tracking-wider">我的单主 ID</h3>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-3xl font-black text-slate-800 tracking-tight">{myClientId}</span>
                  <button 
                    onClick={() => copyText(myClientId, '单主 ID')}
                    className="bg-indigo-50 text-indigo-600 p-2 rounded-lg hover:bg-indigo-100 transition-colors"
                    title="复制"
                  >
                    <Copy size={18} />
                  </button>
                </div>
                <p className="text-xs text-slate-400 mt-3 leading-relaxed">
                  请将此 ID 发送给画手。画手为您新建排单时填入此 ID，您连接后即可同步看到进度。
                </p>
              </div>

              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-4 text-slate-300">
                <Search size={32} />
              </div>
              <p className="text-slate-400 text-sm text-center max-w-[200px]">
                在上方搜索框输入画手 ID 开始连接
              </p>
           </div>
        )}

        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg shadow-indigo-100/50 animate-fade-in">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm">
                    <Sparkles size={14} className="text-indigo-500" /> 智能助理
                  </h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400 hover:text-slate-600">
                    <X size={16} />
                  </button>
                </div>

                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">
                  {isAiLoading ? (
                    <div className="flex items-center gap-2 text-indigo-500">
                      <div className="animate-spin h-3 w-3 border-2 border-indigo-500 border-t-transparent rounded-full"></div>
                      正在思考中...
                    </div>
                  ) : (
                    aiResponse || "你好！我是你的排单助手。可以问我关于档期安排、截稿压力的问题。"
                  )}
                </div>

                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={aiQuery}
                    onChange={(e) => setAiQuery(e.target.value)}
                    placeholder="问问我：下周还能接急单吗？"
                    className="flex-1 text-sm rounded-lg bg-white border border-slate-200 px-3 py-2.5 focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
                    onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()}
                  />
                  <button 
                    onClick={handleAiAsk}
                    className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold shadow-md shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all"
                  >
                    发送
                  </button>
                </div>
              </div>
            )}

            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-4">
                <div className="flex flex-col gap-4">
                   <div className="flex justify-between items-end px-1">
                      <div>
                        <h2 className="text-xl font-bold text-slate-800">
                          {viewMode === 'artist' ? '我的排单' : '我的订单'}
                        </h2>
                        <p className="text-slate-400 text-xs mt-1">
                          {viewMode === 'artist' ? '关注颜色变化，避免延期' : `仅展示关联 ID: ${myClientId} 的项目`}
                        </p>
                      </div>
                      {viewMode === 'artist' && (
                        <button 
                          onClick={() => setShowAddModal(true)}
                          className="hidden md:flex bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold shadow-lg hover:scale-105 transition-transform gap-2 items-center"
                        >
                          <Plus size={16} /> 新建
                        </button>
                      )}
                   </div>

                   <div className="flex p-1 bg-slate-200/50 rounded-xl">
                      <button 
                        onClick={() => setProjectSubTab('active')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                         <Clock size={16} />
                         进行中
                         {allVisibleProjects.filter(p => p.status !== 'completed').length > 0 && (
                            <span className="bg-indigo-100 text-indigo-600 text-[10px] px-1.5 py-0.5 rounded-full ml-1">
                               {allVisibleProjects.filter(p => p.status !== 'completed').length}
                            </span>
                         )}
                      </button>
                      <button 
                        onClick={() => setProjectSubTab('completed')}
                        className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                      >
                         <CheckCircle2 size={16} />
                         已完成
                         {allVisibleProjects.filter(p => p.status === 'completed').length > 0 && (
                            <span className="bg-emerald-100 text-emerald-600 text-[10px] px-1.5 py-0.5 rounded-full ml-1">
                               {allVisibleProjects.filter(p => p.status === 'completed').length}
                            </span>
                         )}
                      </button>
                   </div>
                </div>

                <div className="space-y-3 min-h-[200px]">
                  {displayedProjects.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-16 text-slate-400 bg-white rounded-2xl border border-dashed border-slate-200 mt-2">
                      <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-3">
                        {projectSubTab === 'active' ? <Paintbrush size={20} className="opacity-50" /> : <CheckCircle2 size={20} className="opacity-50" />}
                      </div>
                      <p className="text-sm font-medium">
                        {projectSubTab === 'active' ? '暂无进行中的约稿' : '暂无已完成的记录'}
                      </p>
                    </div>
                  )}

                  {displayedProjects
                    .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                    .map(project => (
                      <ProjectCard 
                        key={project.id} 
                        project={project} 
                        onComplete={handleCompleteProject}
