            {/* Floating FAB (Artist Only) */}
            {viewMode === 'artist' && (
              <div className="absolute left-1/2 -translate-x-1/2 -top-6">
                <button 
                  onClick={() => setShowAddModal(true)}
                  className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center text-white shadow-xl shadow-slate-300 active:scale-90 transition-transform border-4 border-slate-50"
                >
                  <Plus size={24} strokeWidth={2.5} />
                </button>
              </div>
            )}
          </div>

          {/* Desktop Nav Swapped: Projects -> Schedule -> Planning */}
          <div className="hidden md:flex justify-center gap-8 py-4 bg-white border-t border-slate-200">
             <button 
              onClick={() => setActiveTab('projects')}
              className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              排单列表
            </button>
            <button 
              onClick={() => setActiveTab('schedule')}
              className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
            >
              排期日历
            </button>
             {viewMode === 'artist' && (
               <button 
                onClick={() => setActiveTab('planning')}
                className={`px-6 py-2 rounded-xl font-bold transition-all ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                辅助规划
              </button>
             )}
          </div>
        </nav>
      )}

      {/* Add/Edit Project */}
      {showAddModal && viewMode === 'artist' && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end md:justify-center md:items-center bg-slate-900/40 backdrop-blur-sm animate-fade-in">
          <div className="absolute inset-0" onClick={handleCloseModal}></div>
          <div className="relative bg-white w-full md:w-[400px] md:rounded-3xl rounded-t-3xl shadow-2xl animate-slide-up overflow-hidden flex flex-col max-h-[90vh]">
            <div className="w-full flex justify-center pt-3 pb-1 md:hidden" onClick={handleCloseModal}>
              <div className="w-12 h-1.5 bg-slate-200 rounded-full"></div>
            </div>
            <div className="p-6 overflow-y-auto custom-scrollbar pb-10 safe-pb">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-bold text-slate-800">{editingProjectId ? '编辑排单' : '新建排单'}</h3>
                <button onClick={handleCloseModal} className="bg-slate-100 p-2 rounded-full text-slate-500 hover:bg-slate-200 transition-colors">
                  <X size={20} />
                </button>
              </div>
              <div className="space-y-5">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">单主名称 (备注)</label>
                  <input 
                    type="text" 
                    placeholder="例如: 老板A"
                    value={newProject.clientName}
                    onChange={e => setNewProject({...newProject, clientName: e.target.value})}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-indigo-600 uppercase mb-2">单主 ID (必填)</label>
                  <input 
                    type="text" 
                    placeholder="CLI-xxxx"
                    value={newProject.targetClientId}
                    onChange={e => setNewProject({...newProject, targetClientId: e.target.value})}
                    className="w-full bg-indigo-50 border border-indigo-200 rounded-xl px-4 py-3 text-sm font-bold text-indigo-900 outline-none focus:ring-2 focus:ring-indigo-500 transition-all placeholder-indigo-300"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-2">约稿内容</label>
                  <textarea 
                    rows={3}
                    placeholder="描述约稿的具体要求..."
                    value={newProject.description}
                    onChange={e => setNewProject({...newProject, description: e.target.value})}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white resize-none transition-all"
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-2">开始时间</label>
                     <input 
                        type="datetime-local" 
                        value={newProject.startDate}
                        onChange={e => setNewProject({...newProject, startDate: e.target.value})}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                      />
                  </div>
                  <div>
                     <label className="block text-xs font-bold text-slate-500 uppercase mb-2">截稿时间</label>
                     <input 
                        type="datetime-local" 
                        value={newProject.deadline}
                        onChange={e => setNewProject({...newProject, deadline: e.target.value})}
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-3 text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white"
                      />
                  </div>
                </div>
              </div>
              <div className="flex gap-3 mt-8">
                <button 
                  onClick={handleSaveProject}
                  className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl shadow-xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                  {editingProjectId ? <><Save size={20}/> 保存修改</> : <><Plus size={20}/> 创建任务</>}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Check, ArrowUp, Link, Hourglass, ChevronRight, ChevronLeft, Rocket, Trash2, Sparkles, Zap, Palette, Eye, Layout, Timer, Play, Pause, RefreshCw, Calendar, Edit3, Save } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [] }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [viewingSession, setViewingSession] = useState<PlanningSession | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [editingStageId, setEditingStageId] = useState<string | null>(null);
  const [editingStageTitle, setEditingStageTitle] = useState('');

  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'commitment' | 'timer'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // --- Timer State ---
  const [selectedCommitment, setSelectedCommitment] = useState<{id: number, title: string, icon: React.ReactNode, color: string} | null>(null);
  const [timeLeft, setTimeLeft] = useState(600); // 10 minutes
  const [isTimerActive, setIsTimerActive] = useState(false);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Timer Logic ---
  useEffect(() => {
    let interval: number | null = null;
    if (isTimerActive && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setIsTimerActive(false);
      if (interval) clearInterval(interval);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isTimerActive, timeLeft]);

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const formatShortDate = (isoString: string) => {
    const d = new Date(isoString);
    return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; 
    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0;
    let curr = new Date(start);
    let limit = 0;
    while (curr <= end && limit < 1000) {
      if (!isDateBlocked(getYYYYMMDD(curr))) {
        count++;
      }
      curr.setDate(curr.getDate() + 1);
      limit++;
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  const currentPlannedDays = (Object.values(estimates) as string[]).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setActiveTimeIndex(-1); 
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      if (confirm('确定要删除这个规划吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
      };
      persistSessions([newSession, ...sessions]);
      setMode('dashboard');
      setPlanningStep('setup');
      // Reset timer states
      setIsTimerActive(false);
      setTimeLeft(600);
      setSelectedCommitment(null);
  };

  const handleSelectCommitment = (option: {id: number, title: string, icon: React.ReactNode, color: string}) => {
    setSelectedCommitment(option);
    setPlanningStep('timer');
    setTimeLeft(600);
    setIsTimerActive(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const handleDeleteStage = (id: string) => {
    if (stages.length <= 1) {
      alert('至少需要保留一个绘画阶段。');
      return;
    }
    setStages(prev => prev.filter(s => s.id !== id));
  };

  const startEditStage = (stage: PlannerStage) => {
    setEditingStageId(stage.id);
    setEditingStageTitle(stage.title);
  };

  const saveEditedStage = () => {
    if (!editingStageTitle.trim()) return;
    setStages(prev => prev.map(s => s.id === editingStageId ? { ...s, title: editingStageTitle } : s));
    setEditingStageId(null);
    setEditingStageTitle('');
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             {viewingSession ? (
                 <div className="animate-fade-in">
                    <button onClick={() => setViewingSession(null)} className="flex items-center text-indigo-600 mb-6 text-sm font-bold">
                        <ArrowLeft size={16} className="mr-1" /> 返回规划列表
                    </button>
                    <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8">
                        <h2 className="text-2xl font-black text-slate-800 mb-1">{viewingSession.clientName}</h2>
                        <p className="text-xs text-slate-400 mb-8 font-medium">规划于 {formatDate(viewingSession.createdAt)}</p>

                        <div className="space-y-4">
                            {viewingSession.stages.map(stage => (
                                <div key={stage.id} className="flex justify-between items-center py-4 border-b border-slate-50 last:border-0">
                                    <span className="font-bold text-slate-600">{stage.title}</span>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-300 uppercase">分配</span>
                                        <span className="font-black text-indigo-600 text-lg">{viewingSession.estimates[stage.id]} 天</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                 </div>
             ) : (
                <>
                    <div className="mb-8 px-1">
                        <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                        <p className="text-slate-400 text-sm mt-1 font-medium">预估你的排单创作节奏</p>
                    </div>

                    <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center gap-4 mb-8 active:scale-95 transition-all group overflow-hidden relative">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/20 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                        <div className="bg-white/20 p-4 rounded-3xl group-hover:bg-fuchsia-500 transition-colors"><Plus size={32} /></div>
                        <div className="text-center">
                            <h3 className="font-bold text-xl">创建新规划</h3>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Plan</p>
                        </div>
                    </button>

                    {sessions.length > 0 ? (
                        <div className="space-y-4">
                            {sessions.map(session => (
                                <div key={session.id} onClick={() => setViewingSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group flex justify-between items-center">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-1">
                                            {session.stages.length} 个阶段 · 合计 {(Object.values(session.estimates) as string[]).reduce((a, b) => a + Number(b), 0)} 天
                                        </p>
                                    </div>
                                    <button 
                                        onClick={(e) => handleDeleteSession(e, session.id)}
                                        className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-12 bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200">
                            <p className="text-sm text-slate-400 font-medium">暂无已保存的规划</p>
                        </div>
                    )}
                </>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>

                    {syncedProject && (
                      <div className="mt-2 flex items-center gap-2 text-fuchsia-300 font-bold text-xs bg-white/5 w-fit px-3 py-1.5 rounded-lg border border-white/10">
                        <Calendar size={12} />
                        <span>工期: {formatShortDate(syncedProject.startDate)} - {formatShortDate(syncedProject.deadline)}</span>
                      </div>
                    )}

                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2.5rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="text-slate-200 mr-4 flex-shrink-0"><GripVertical size={24} /></div>

                    {editingStageId === stage.id ? (
                      <div className="flex-1 flex items-center gap-2 pr-2 animate-fade-in">
                        <input 
                          autoFocus 
                          type="text" 
                          value={editingStageTitle} 
                          onChange={(e) => setEditingStageTitle(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && saveEditedStage()}
                          className="flex-1 bg-slate-50 border-2 border-fuchsia-200 rounded-xl px-4 py-2 text-sm font-black text-slate-800 outline-none"
                        />
                        <button onClick={saveEditedStage} className="p-2 bg-fuchsia-500 text-white rounded-xl shadow-md active:scale-90 transition-all">
                          <Save size={16} />
                        </button>
                        <button onClick={() => setEditingStageId(null)} className="p-2 text-slate-400">
                          <X size={16} />
                        </button>
                      </div>
                    ) : (
                      <>
                        <div className="flex flex-col flex-1 min-w-0">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                            <span className="font-black text-slate-700 text-lg anonymous-block leading-none truncate pr-4">{stage.title}</span>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => startEditStage(stage)}
                              className="p-2 text-slate-300 hover:text-indigo-500 transition-colors"
                              title="重命名"
                            >
                              <Edit3 size={18} />
                            </button>
                            <button 
                              onClick={() => handleDeleteStage(stage.id)}
                              className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                              title="删除"
                            >
                              <X size={18} />
                            </button>
                        </div>
                      </>
                    )}
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32 px-1">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 font-bold' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(''); }} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col px-1">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                <div className="flex flex-col relative z-10">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算 (排除休息日)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black transition-colors ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500 relative z-10" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const value = estimates[stage.id];
                        const isDone = value && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-300 flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-100' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div 
                                    onClick={() => { 
                                        setActiveTimeIndex(index); 
                                        setCurrentInputTime(estimates[stage.id] || ''); 
                                    }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2.5rem] border-2 transition-all duration-300 cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}
                                >
                                    <div className="flex justify-between items-start">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    </div>

                                    {isActive ? (
                                        <div className="flex items-center gap-3 mt-3 animate-fade-in">
                                            <div className="relative flex-1 max-w-[120px]">
                                                <input 
                                                    autoFocus 
                                                    type="text" 
                                                    value={currentInputTime} 
                                                    onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                    className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-2xl px-4 py-3 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-colors" 
                                                    placeholder="0"
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-fuchsia-300">DAYS</span>
                                            </div>
                                            <button 
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    confirmTimeEntry();
                                                }} 
                                                className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl shadow-slate-200 active:scale-90 transition-all hover:bg-slate-800"
                                            >
                                                <ArrowUp size={24} strokeWidth={2.5} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="mt-1">
                                            {value ? (
                                                <span className="text-xs font-black text-fuchsia-600">预期损耗: {value} 天</span>
                                            ) : (
                                                <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">待填写</span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button 
                onClick={() => setPlanningStep('finished')} 
                className={`fixed bottom-24 left-5 right-5 py-5 rounded-2xl font-black text-lg shadow-xl transition-all ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                disabled={Object.keys(estimates).length !== stages.length}
            >
                预览规划摘要
            </button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center pb-32">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-2xl shadow-emerald-100 border-4 border-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3 tracking-tight">规划已就绪</h2>
            <p className="text-slate-400 text-sm font-medium mb-8">每一个阶段都已准备好被灵感填满</p>

            <div className="w-full bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-slate-300 uppercase">预计</span>
                            <span className="font-black text-indigo-600 text-lg">{estimates[stage.id]} 天</span>
                        </div>
                    </div>
                ))}
            </div>

            <button onClick={() => setPlanningStep('commitment')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                <Rocket size={24} />
                开启第一步
            </button>
        </div>
    );
  }

  if (planningStep === 'commitment') {
    return (
        <div className="animate-fade-in pb-32 flex flex-col items-center">
            <div className="w-full bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-[3rem] p-8 text-white shadow-2xl mb-10 relative overflow-hidden">
                <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
                <div className="relative z-10">
                    <Sparkles className="text-indigo-200 mb-6" size={32} />
                    <h2 className="text-2xl font-black leading-tight mb-4 tracking-tight">
                        现在就开始实施的有计划的举动，比无目的的晚点再做，有 <span className="text-fuchsia-300 italic">80%</span> 的可能性更容易成功哦~来试一试吗
                    </h2>
                    <div className="h-1 w-20 bg-fuchsia-400 rounded-full"></div>
                </div>
            </div>

            <div className="w-full space-y-4 mb-10">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4 mb-4">选择一个微小的开始：</h3>
                {[
                    { id: 1, title: '现在打开画布画 5 笔', icon: <Palette size={20} />, color: 'bg-rose-50 text-rose-600 border-rose-100' },
                    { id: 2, title: '再看一次单主的需求', icon: <Eye size={20} />, color: 'bg-emerald-50 text-emerald-600 border-emerald-100' },
                    { id: 3, title: '想一下构图', icon: <Layout size={20} />, color: 'bg-indigo-50 text-indigo-600 border-indigo-100' },
                    { id: 4, title: '整理一套参考图', icon: <Zap size={20} />, color: 'bg-amber-50 text-amber-600 border-amber-100' },
                ].map((option) => (
                    <div key={option.id} onClick={() => handleSelectCommitment(option)} className={`flex items-center gap-4 p-5 rounded-[2rem] border-2 transition-all hover:scale-[1.02] cursor-pointer bg-white border-slate-50 shadow-sm active:scale-95`}>
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${option.color.split(' ')[0]} ${option.color.split(' ')[1]}`}>
                            {option.icon}
                        </div>
                        <span className="font-black text-slate-700">{option.title}</span>
                        <ChevronRight className="ml-auto text-slate-200" size={18} />
                    </div>
                ))}
            </div>

            <div className="bg-slate-900/5 p-6 rounded-[2rem] border border-dashed border-slate-200 flex items-start gap-4 mb-12 w-full">
                <Timer className="text-slate-400 flex-shrink-0 mt-1" size={20} />
                <p className="text-xs text-slate-500 font-bold leading-relaxed">
                    <span className="text-slate-900 uppercase">准则：</span>
                    任意一条需进行 10 分钟，可以不完成任何事，但是让身为 P 人的自己明白，<span className="text-indigo-600">第一步已经开始啦。</span>
                </p>
            </div>

            <button 
                onClick={handleFinalize}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"
            >
                跳过专注，直接保存
            </button>
        </div>
    );
  }

  if (planningStep === 'timer') {
    return (
      <div className="animate-fade-in pb-32 flex flex-col items-center">
        <button onClick={() => setPlanningStep('commitment')} className="self-start flex items-center text-slate-400 mb-8 font-bold text-sm hover:text-slate-800 transition-colors">
          <ArrowLeft size={16} className="mr-1" /> 返回选择
        </button>

        <div className="w-full flex flex-col items-center justify-center mb-10">
          <div className={`w-24 h-24 rounded-3xl flex items-center justify-center mb-6 shadow-xl ${selectedCommitment?.color.split(' ')[0]} ${selectedCommitment?.color.split(' ')[1]}`}>
            {selectedCommitment?.icon}
          </div>
          <h2 className="text-2xl font-black text-slate-800 mb-2 tracking-tight">{selectedCommitment?.title}</h2>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">专注 10 分钟</p>
        </div>

        <div className="w-full bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 flex flex-col items-center justify-center mb-12 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-slate-100 overflow-hidden">
            <div 
              className="h-full bg-indigo-500 transition-all duration-1000 ease-linear"
              style={{ width: `${(timeLeft / 600) * 100}%` }}
            />
          </div>

          <div className="text-7xl font-black text-slate-900 tracking-tighter tabular-nums mb-8">
            {formatTime(timeLeft)}
          </div>

          {!isTimerActive ? (
            <button 
              onClick={() => setIsTimerActive(true)}
              className="flex items-center gap-3 bg-indigo-600 text-white px-10 py-5 rounded-2xl font-black text-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all"
            >
              <Play size={24} fill="currentColor" /> 开始吧
            </button>
          ) : (
            <div className="flex gap-4">
               <button 
                  onClick={() => setIsTimerActive(false)}
                  className="flex items-center gap-2 bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-black transition-all active:scale-95"
                >
                  <Pause size={20} fill="currentColor" /> 暂停
                </button>
                <button 
                  onClick={() => setTimeLeft(600)}
                  className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-100 transition-colors"
                >
                  <RefreshCw size={20} />
                </button>
            </div>
          )}
        </div>

        <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 text-center mb-10">
           <p className="text-xs text-amber-700 font-bold leading-relaxed">
             不必强求结果，只要这 10 分钟你在与画布对话。<br/>
             <span className="opacity-60 font-black">第一步一旦迈出，接下来的路就清晰了。</span>
           </p>
        </div>

        <button 
          onClick={handleFinalize}
          className="text-slate-400 font-black text-xs uppercase tracking-widest hover:text-slate-800 transition-colors"
        >
          {timeLeft === 0 ? "专注结束，保存规划" : "提前退出专注"}
        </button>
      </div>
    );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useEffect, useMemo } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Check, ArrowUp, Link, Hourglass, ChevronRight, ChevronLeft, Rocket, Trash2, Sparkles, Zap, Palette, Eye, Layout, Timer, Play, Pause, RefreshCw, Calendar, Edit3, Save, ChevronUp, ChevronDown } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [] }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [viewingSession, setViewingSession] = useState<PlanningSession | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [editingStageId, setEditingStageId] = useState<string | null>(null);
  const [editingStageTitle, setEditingStageTitle] = useState('');

  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'commitment' | 'timer'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // --- Timer State ---
  const [selectedCommitment, setSelectedCommitment] = useState<{id: number, title: string, icon: React.ReactNode, color: string} | null>(null);
  const [timeLeft, setTimeLeft] = useState(600); // 10 minutes
  const [isTimerActive, setIsTimerActive] = useState(false);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Timer Logic ---
  useEffect(() => {
    let interval: number | null = null;
    if (isTimerActive && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setIsTimerActive(false);
      if (interval) clearInterval(interval);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isTimerActive, timeLeft]);

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const formatShortDate = (isoString: string) => {
    const d = new Date(isoString);
    return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; 
    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0;
    let curr = new Date(start);
    let limit = 0;
    while (curr <= end && limit < 1000) {
      if (!isDateBlocked(getYYYYMMDD(curr))) {
        count++;
      }
      curr.setDate(curr.getDate() + 1);
      limit++;
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  const currentPlannedDays = (Object.values(estimates) as string[]).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setActiveTimeIndex(-1); 
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      if (confirm('确定要删除这个规划吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
      };
      persistSessions([newSession, ...sessions]);
      setMode('dashboard');
      setPlanningStep('setup');
      // Reset timer states
      setIsTimerActive(false);
      setTimeLeft(600);
      setSelectedCommitment(null);
  };

  const handleSelectCommitment = (option: {id: number, title: string, icon: React.ReactNode, color: string}) => {
    setSelectedCommitment(option);
    setPlanningStep('timer');
    setTimeLeft(600);
    setIsTimerActive(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const handleDeleteStage = (id: string) => {
    if (stages.length <= 1) {
      alert('至少需要保留一个绘画阶段。');
      return;
    }
    setStages(prev => prev.filter(s => s.id !== id));
  };

  const startEditStage = (stage: PlannerStage) => {
    setEditingStageId(stage.id);
    setEditingStageTitle(stage.title);
  };

  const saveEditedStage = () => {
    if (!editingStageTitle.trim()) return;
    setStages(prev => prev.map(s => s.id === editingStageId ? { ...s, title: editingStageTitle } : s));
    setEditingStageId(null);
    setEditingStageTitle('');
  };

  const moveStage = (index: number, direction: 'up' | 'down') => {
    const newStages = [...stages];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newStages.length) return;
    [newStages[index], newStages[targetIndex]] = [newStages[targetIndex], newStages[index]];
    setStages(newStages);
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             {viewingSession ? (
                 <div className="animate-fade-in">
                    <button onClick={() => setViewingSession(null)} className="flex items-center text-indigo-600 mb-6 text-sm font-bold">
                        <ArrowLeft size={16} className="mr-1" /> 返回规划列表
                    </button>
                    <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8">
                        <h2 className="text-2xl font-black text-slate-800 mb-1">{viewingSession.clientName}</h2>
                        <p className="text-xs text-slate-400 mb-8 font-medium">规划于 {formatDate(viewingSession.createdAt)}</p>

                        <div className="space-y-4">
                            {viewingSession.stages.map(stage => (
                                <div key={stage.id} className="flex justify-between items-center py-4 border-b border-slate-50 last:border-0">
                                    <span className="font-bold text-slate-600">{stage.title}</span>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-300 uppercase">分配</span>
                                        <span className="font-black text-indigo-600 text-lg">{viewingSession.estimates[stage.id]} 天</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                 </div>
             ) : (
                <>
                    <div className="mb-8 px-1">
                        <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                        <p className="text-slate-400 text-sm mt-1 font-medium">预估你的排单创作节奏</p>
                    </div>

                    <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center gap-4 mb-8 active:scale-95 transition-all group overflow-hidden relative">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/20 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                        <div className="bg-white/20 p-4 rounded-3xl group-hover:bg-fuchsia-500 transition-colors"><Plus size={32} /></div>
                        <div className="text-center">
                            <h3 className="font-bold text-xl">创建新规划</h3>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Plan</p>
                        </div>
                    </button>

                    {sessions.length > 0 ? (
                        <div className="space-y-4">
                            {sessions.map(session => (
                                <div key={session.id} onClick={() => setViewingSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group flex justify-between items-center">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-1">
                                            {session.stages.length} 个阶段 · 合计 {(Object.values(session.estimates) as string[]).reduce((a, b) => a + Number(b), 0)} 天
                                        </p>
                                    </div>
                                    <button 
                                        onClick={(e) => handleDeleteSession(e, session.id)}
                                        className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-12 bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200">
                            <p className="text-sm text-slate-400 font-medium">暂无已保存的规划</p>
                        </div>
                    )}
                </>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>

                    {syncedProject && (
                      <div className="mt-2 flex items-center gap-2 text-fuchsia-300 font-bold text-xs bg-white/5 w-fit px-3 py-1.5 rounded-lg border border-white/10">
                        <Calendar size={12} />
                        <span>工期: {formatShortDate(syncedProject.startDate)} - {formatShortDate(syncedProject.deadline)}</span>
                      </div>
                    )}

                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input autoFocus type="text" placeholder="例如：精修细化..." value={newStageTitle} onChange={(e) => setNewStageTitle(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && (setStages([...stages, {id: Date.now().toString(), title: newStageTitle}]), setIsAdding(false), setNewStageTitle(''))} className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" />
                    <button onClick={() => setIsAdding(false)} className="p-3 text-slate-400"><X size={20} /></button>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2.5rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="flex flex-col items-center mr-4 flex-shrink-0 text-slate-200 gap-1">
                        <button 
                          onClick={() => moveStage(index, 'up')} 
                          disabled={index === 0}
                          className={`p-1 rounded-md transition-colors ${index === 0 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-slate-50 hover:text-indigo-500 active:scale-90'}`}
                        >
                          <ChevronUp size={14} />
                        </button>
                        <GripVertical size={20} className="opacity-50" />
                        <button 
                          onClick={() => moveStage(index, 'down')} 
                          disabled={index === stages.length - 1}
                          className={`p-1 rounded-md transition-colors ${index === stages.length - 1 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-slate-50 hover:text-indigo-500 active:scale-90'}`}
                        >
                          <ChevronDown size={14} />
                        </button>
                    </div>

                    {editingStageId === stage.id ? (
                      <div className="flex-1 flex items-center gap-2 pr-2 animate-fade-in">
                        <input 
                          autoFocus 
                          type="text" 
                          value={editingStageTitle} 
                          onChange={(e) => setEditingStageTitle(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && saveEditedStage()}
                          className="flex-1 bg-slate-50 border-2 border-fuchsia-200 rounded-xl px-4 py-2 text-sm font-black text-slate-800 outline-none"
                        />
                        <button onClick={saveEditedStage} className="p-2 bg-fuchsia-500 text-white rounded-xl shadow-md active:scale-90 transition-all">
                          <Save size={16} />
                        </button>
                        <button onClick={() => setEditingStageId(null)} className="p-2 text-slate-400">
                          <X size={16} />
                        </button>
                      </div>
                    ) : (
                      <>
                        <div className="flex flex-col flex-1 min-w-0">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                            <span className="font-black text-slate-700 text-lg anonymous-block leading-none truncate pr-4">{stage.title}</span>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => startEditStage(stage)}
                              className="p-2 text-slate-300 hover:text-indigo-500 transition-colors"
                              title="重命名"
                            >
                              <Edit3 size={18} />
                            </button>
                            <button 
                              onClick={() => handleDeleteStage(stage.id)}
                              className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                              title="删除"
                            >
                              <X size={18} />
                            </button>
                        </div>
                      </>
                    )}
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32 px-1">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 font-bold' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(''); }} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col px-1">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                <div className="flex flex-col relative z-10">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算 (排除休息日)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black transition-colors ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500 relative z-10" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const value = estimates[stage.id];
                        const isDone = value && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-300 flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-100' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div 
                                    onClick={() => { 
                                        setActiveTimeIndex(index); 
                                        setCurrentInputTime(estimates[stage.id] || ''); 
                                    }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2.5rem] border-2 transition-all duration-300 cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}
                                >
                                    <div className="flex justify-between items-start">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    </div>

                                    {isActive ? (
                                        <div className="flex items-center gap-3 mt-3 animate-fade-in">
                                            <div className="relative flex-1 max-w-[120px]">
                                                <input 
                                                    autoFocus 
                                                    type="text" 
                                                    value={currentInputTime} 
                                                    onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                    className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-2xl px-4 py-3 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-colors" 
                                                    placeholder="0"
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-fuchsia-300">DAYS</span>
                                            </div>
                                            <button 
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    confirmTimeEntry();
                                                }} 
                                                className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl shadow-slate-200 active:scale-90 transition-all hover:bg-slate-800"
                                            >
                                                <ArrowUp size={24} strokeWidth={2.5} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="mt-1">
                                            {value ? (
                                                <span className="text-xs font-black text-fuchsia-600">预期损耗: {value} 天</span>
                                            ) : (
                                                <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">待填写</span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button 
                onClick={() => setPlanningStep('finished')} 
                className={`fixed bottom-24 left-5 right-5 py-5 rounded-2xl font-black text-lg shadow-xl transition-all ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                disabled={Object.keys(estimates).length !== stages.length}
            >
                预览规划摘要
            </button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center pb-32">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-2xl shadow-emerald-100 border-4 border-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3 tracking-tight">规划已就绪</h2>
            <p className="text-slate-400 text-sm font-medium mb-8">每一个阶段都已准备好被灵感填满</p>

            <div className="w-full bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-slate-300 uppercase">预计</span>
                            <span className="font-black text-indigo-600 text-lg">{estimates[stage.id]} 天</span>
                        </div>
                    </div>
                ))}
            </div>

            <button onClick={() => setPlanningStep('commitment')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                <Rocket size={24} />
                开启第一步
            </button>
        </div>
    );
  }

  if (planningStep === 'commitment') {
    return (
        <div className="animate-fade-in pb-32 flex flex-col items-center">
            <div className="w-full bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-[3rem] p-8 text-white shadow-2xl mb-10 relative overflow-hidden">
                <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
                <div className="relative z-10">
                    <Sparkles className="text-indigo-200 mb-6" size={32} />
                    <h2 className="text-2xl font-black leading-tight mb-4 tracking-tight">
                        现在就开始实施的有计划的举动，比无目的的晚点再做，有 <span className="text-fuchsia-300 italic">80%</span> 的可能性更容易成功哦~来试一试吗
                    </h2>
                    <div className="h-1 w-20 bg-fuchsia-400 rounded-full"></div>
                </div>
            </div>

            <div className="w-full space-y-4 mb-10">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4 mb-4">选择一个微小的开始：</h3>
                {[
                    { id: 1, title: '现在打开画布画 5 笔', icon: <Palette size={20} />, color: 'bg-rose-50 text-rose-600 border-rose-100' },
                    { id: 2, title: '再看一次单主的需求', icon: <Eye size={20} />, color: 'bg-emerald-50 text-emerald-600 border-emerald-100' },
                    { id: 3, title: '想一下构图', icon: <Layout size={20} />, color: 'bg-indigo-50 text-indigo-600 border-indigo-100' },
                    { id: 4, title: '整理一套参考图', icon: <Zap size={20} />, color: 'bg-amber-50 text-amber-600 border-amber-100' },
                ].map((option) => (
                    <div key={option.id} onClick={() => handleSelectCommitment(option)} className={`flex items-center gap-4 p-5 rounded-[2rem] border-2 transition-all hover:scale-[1.02] cursor-pointer bg-white border-slate-50 shadow-sm active:scale-95`}>
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${option.color.split(' ')[0]} ${option.color.split(' ')[1]}`}>
                            {option.icon}
                        </div>
                        <span className="font-black text-slate-700">{option.title}</span>
                        <ChevronRight className="ml-auto text-slate-200" size={18} />
                    </div>
                ))}
            </div>

            <div className="bg-slate-900/5 p-6 rounded-[2rem] border border-dashed border-slate-200 flex items-start gap-4 mb-12 w-full">
                <Timer className="text-slate-400 flex-shrink-0 mt-1" size={20} />
                <p className="text-xs text-slate-500 font-bold leading-relaxed">
                    <span className="text-slate-900 uppercase">准则：</span>
                    任意一条需进行 10 分钟，可以不完成任何事，但是让身为 P 人的自己明白，<span className="text-indigo-600">第一步已经开始啦。</span>
                </p>
            </div>

            <button 
                onClick={handleFinalize}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"
            >
                跳过专注，直接保存
            </button>
        </div>
    );
  }

  if (planningStep === 'timer') {
    return (
      <div className="animate-fade-in pb-32 flex flex-col items-center">
        <button onClick={() => setPlanningStep('commitment')} className="self-start flex items-center text-slate-400 mb-8 font-bold text-sm hover:text-slate-800 transition-colors">
          <ArrowLeft size={16} className="mr-1" /> 返回选择
        </button>

        <div className="w-full flex flex-col items-center justify-center mb-10">
          <div className={`w-24 h-24 rounded-3xl flex items-center justify-center mb-6 shadow-xl ${selectedCommitment?.color.split(' ')[0]} ${selectedCommitment?.color.split(' ')[1]}`}>
            {selectedCommitment?.icon}
          </div>
          <h2 className="text-2xl font-black text-slate-800 mb-2 tracking-tight">{selectedCommitment?.title}</h2>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">专注 10 分钟</p>
        </div>

        <div className="w-full bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 flex flex-col items-center justify-center mb-12 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-slate-100 overflow-hidden">
            <div 
              className="h-full bg-indigo-500 transition-all duration-1000 ease-linear"
              style={{ width: `${(timeLeft / 600) * 100}%` }}
            />
          </div>

          <div className="text-7xl font-black text-slate-900 tracking-tighter tabular-nums mb-8">
            {formatTime(timeLeft)}
          </div>

          {!isTimerActive ? (
            <button 
              onClick={() => setIsTimerActive(true)}
              className="flex items-center gap-3 bg-indigo-600 text-white px-10 py-5 rounded-2xl font-black text-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all"
            >
              <Play size={24} fill="currentColor" /> 开始吧
            </button>
          ) : (
            <div className="flex gap-4">
               <button 
                  onClick={() => setIsTimerActive(false)}
                  className="flex items-center gap-2 bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-black transition-all active:scale-95"
                >
                  <Pause size={20} fill="currentColor" /> 暂停
                </button>
                <button 
                  onClick={() => setTimeLeft(600)}
                  className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-100 transition-colors"
                >
                  <RefreshCw size={20} />
                </button>
            </div>
          )}
        </div>

        <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 text-center mb-10">
           <p className="text-xs text-amber-700 font-bold leading-relaxed">
             不必强求结果，只要这 10 分钟你在与画布对话。<br/>
             <span className="opacity-60 font-black">第一步一旦迈出，接下来的路就清晰了。</span>
           </p>
        </div>

        <button 
          onClick={handleFinalize}
          className="text-slate-400 font-black text-xs uppercase tracking-widest hover:text-slate-800 transition-colors"
        >
          {timeLeft === 0 ? "专注结束，保存规划" : "提前退出专注"}
        </button>
      </div>
    );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useEffect, useMemo } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Check, ArrowUp, Link, Hourglass, ChevronRight, ChevronLeft, Rocket, Trash2, Sparkles, Zap, Palette, Eye, Layout, Timer, Play, Pause, RefreshCw, Calendar, Edit3, Save, ChevronUp, ChevronDown } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [] }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [viewingSession, setViewingSession] = useState<PlanningSession | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [editingStageId, setEditingStageId] = useState<string | null>(null);
  const [editingStageTitle, setEditingStageTitle] = useState('');

  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'commitment' | 'timer'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // --- Timer State ---
  const [selectedCommitment, setSelectedCommitment] = useState<{id: number, title: string, icon: React.ReactNode, color: string} | null>(null);
  const [timeLeft, setTimeLeft] = useState(600); // 10 minutes
  const [isTimerActive, setIsTimerActive] = useState(false);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Timer Logic ---
  useEffect(() => {
    let interval: number | null = null;
    if (isTimerActive && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setIsTimerActive(false);
      if (interval) clearInterval(interval);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isTimerActive, timeLeft]);

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const formatShortDate = (isoString: string) => {
    const d = new Date(isoString);
    return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; 
    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0;
    let curr = new Date(start);
    let limit = 0;
    while (curr <= end && limit < 1000) {
      if (!isDateBlocked(getYYYYMMDD(curr))) {
        count++;
      }
      curr.setDate(curr.getDate() + 1);
      limit++;
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  const currentPlannedDays = (Object.values(estimates) as string[]).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setActiveTimeIndex(-1); 
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      if (confirm('确定要删除这个规划吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
      };
      persistSessions([newSession, ...sessions]);
      setMode('dashboard');
      setPlanningStep('setup');
      // Reset timer states
      setIsTimerActive(false);
      setTimeLeft(600);
      setSelectedCommitment(null);
  };

  const handleSelectCommitment = (option: {id: number, title: string, icon: React.ReactNode, color: string}) => {
    setSelectedCommitment(option);
    setPlanningStep('timer');
    setTimeLeft(600);
    setIsTimerActive(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const handleDeleteStage = (id: string) => {
    if (stages.length <= 1) {
      alert('至少需要保留一个绘画阶段。');
      return;
    }
    setStages(prev => prev.filter(s => s.id !== id));
  };

  const startEditStage = (stage: PlannerStage) => {
    setEditingStageId(stage.id);
    setEditingStageTitle(stage.title);
  };

  const saveEditedStage = () => {
    if (!editingStageTitle.trim()) {
        setEditingStageId(null);
        return;
    }
    setStages(prev => prev.map(s => s.id === editingStageId ? { ...s, title: editingStageTitle } : s));
    setEditingStageId(null);
    setEditingStageTitle('');
  };

  const handleSaveNewStage = () => {
    if (newStageTitle.trim()) {
      setStages([...stages, { id: Date.now().toString(), title: newStageTitle.trim() }]);
    }
    setIsAdding(false);
    setNewStageTitle('');
  };

  const moveStage = (index: number, direction: 'up' | 'down') => {
    const newStages = [...stages];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newStages.length) return;
    [newStages[index], newStages[targetIndex]] = [newStages[targetIndex], newStages[index]];
    setStages(newStages);
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             {viewingSession ? (
                 <div className="animate-fade-in">
                    <button onClick={() => setViewingSession(null)} className="flex items-center text-indigo-600 mb-6 text-sm font-bold">
                        <ArrowLeft size={16} className="mr-1" /> 返回规划列表
                    </button>
                    <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8">
                        <h2 className="text-2xl font-black text-slate-800 mb-1">{viewingSession.clientName}</h2>
                        <p className="text-xs text-slate-400 mb-8 font-medium">规划于 {formatDate(viewingSession.createdAt)}</p>

                        <div className="space-y-4">
                            {viewingSession.stages.map(stage => (
                                <div key={stage.id} className="flex justify-between items-center py-4 border-b border-slate-50 last:border-0">
                                    <span className="font-bold text-slate-600">{stage.title}</span>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-300 uppercase">分配</span>
                                        <span className="font-black text-indigo-600 text-lg">{viewingSession.estimates[stage.id]} 天</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                 </div>
             ) : (
                <>
                    <div className="mb-8 px-1">
                        <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                        <p className="text-slate-400 text-sm mt-1 font-medium">预估你的排单创作节奏</p>
                    </div>

                    <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center gap-4 mb-8 active:scale-95 transition-all group overflow-hidden relative">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/20 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                        <div className="bg-white/20 p-4 rounded-3xl group-hover:bg-fuchsia-500 transition-colors"><Plus size={32} /></div>
                        <div className="text-center">
                            <h3 className="font-bold text-xl">创建新规划</h3>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Plan</p>
                        </div>
                    </button>

                    {sessions.length > 0 ? (
                        <div className="space-y-4">
                            {sessions.map(session => (
                                <div key={session.id} onClick={() => setViewingSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group flex justify-between items-center">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-1">
                                            {session.stages.length} 个阶段 · 合计 {(Object.values(session.estimates) as string[]).reduce((a, b) => a + Number(b), 0)} 天
                                        </p>
                                    </div>
                                    <button 
                                        onClick={(e) => handleDeleteSession(e, session.id)}
                                        className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-12 bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200">
                            <p className="text-sm text-slate-400 font-medium">暂无已保存的规划</p>
                        </div>
                    )}
                </>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>

                    {syncedProject && (
                      <div className="mt-2 flex items-center gap-2 text-fuchsia-300 font-bold text-xs bg-white/5 w-fit px-3 py-1.5 rounded-lg border border-white/10">
                        <Calendar size={12} />
                        <span>工期: {formatShortDate(syncedProject.startDate)} - {formatShortDate(syncedProject.deadline)}</span>
                      </div>
                    )}

                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input 
                      autoFocus 
                      type="text" 
                      placeholder="例如：精修细化..." 
                      value={newStageTitle} 
                      onChange={(e) => setNewStageTitle(e.target.value)} 
                      onBlur={handleSaveNewStage}
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveNewStage()} 
                      className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" 
                    />
                    <button 
                      onMouseDown={(e) => {
                          e.preventDefault(); // Prevent onBlur from firing before onClick
                          setIsAdding(false);
                          setNewStageTitle('');
                      }} 
                      className="p-3 text-slate-400 hover:text-rose-500 transition-colors"
                    >
                      <X size={20} />
                    </button>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2.5rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group">
                    <div className="flex flex-col items-center mr-4 flex-shrink-0 text-slate-200 gap-1">
                        <button 
                          onClick={() => moveStage(index, 'up')} 
                          disabled={index === 0}
                          className={`p-1 rounded-md transition-colors ${index === 0 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-slate-50 hover:text-indigo-500 active:scale-90'}`}
                        >
                          <ChevronUp size={14} />
                        </button>
                        <GripVertical size={20} className="opacity-50" />
                        <button 
                          onClick={() => moveStage(index, 'down')} 
                          disabled={index === stages.length - 1}
                          className={`p-1 rounded-md transition-colors ${index === stages.length - 1 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-slate-50 hover:text-indigo-500 active:scale-90'}`}
                        >
                          <ChevronDown size={14} />
                        </button>
                    </div>

                    {editingStageId === stage.id ? (
                      <div className="flex-1 flex items-center gap-2 pr-2 animate-fade-in">
                        <input 
                          autoFocus 
                          type="text" 
                          value={editingStageTitle} 
                          onChange={(e) => setEditingStageTitle(e.target.value)}
                          onBlur={saveEditedStage}
                          onKeyDown={(e) => e.key === 'Enter' && saveEditedStage()}
                          className="flex-1 bg-slate-50 border-2 border-fuchsia-200 rounded-xl px-4 py-2 text-sm font-black text-slate-800 outline-none"
                        />
                        <button 
                          onMouseDown={(e) => e.preventDefault()}
                          onClick={saveEditedStage} 
                          className="p-2 bg-fuchsia-500 text-white rounded-xl shadow-md active:scale-90 transition-all"
                        >
                          <Save size={16} />
                        </button>
                        <button 
                          onMouseDown={(e) => {
                              e.preventDefault();
                              setEditingStageId(null);
                          }}
                          className="p-2 text-slate-400"
                        >
                          <X size={16} />
                        </button>
                      </div>
                    ) : (
                      <>
                        <div className="flex flex-col flex-1 min-w-0">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                            <span className="font-black text-slate-700 text-lg anonymous-block leading-none truncate pr-4">{stage.title}</span>
                        </div>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => startEditStage(stage)}
                              className="p-2 text-slate-300 hover:text-indigo-500 transition-colors"
                              title="重命名"
                            >
                              <Edit3 size={18} />
                            </button>
                            <button 
                              onClick={() => handleDeleteStage(stage.id)}
                              className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                              title="删除"
                            >
                              <X size={18} />
                            </button>
                        </div>
                      </>
                    )}
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32 px-1">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 font-bold' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(''); }} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col px-1">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                <div className="flex flex-col relative z-10">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算 (排除休息日)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black transition-colors ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500 relative z-10" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const value = estimates[stage.id];
                        const isDone = value && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-300 flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-100' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div 
                                    onClick={() => { 
                                        setActiveTimeIndex(index); 
                                        setCurrentInputTime(estimates[stage.id] || ''); 
                                    }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2.5rem] border-2 transition-all duration-300 cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}
                                >
                                    <div className="flex justify-between items-start">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    </div>

                                    {isActive ? (
                                        <div className="flex items-center gap-3 mt-3 animate-fade-in">
                                            <div className="relative flex-1 max-w-[120px]">
                                                <input 
                                                    autoFocus 
                                                    type="text" 
                                                    value={currentInputTime} 
                                                    onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                    className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-2xl px-4 py-3 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-colors" 
                                                    placeholder="0"
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-fuchsia-300">DAYS</span>
                                            </div>
                                            <button 
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    confirmTimeEntry();
                                                }} 
                                                className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl shadow-slate-200 active:scale-90 transition-all hover:bg-slate-800"
                                            >
                                                <ArrowUp size={24} strokeWidth={2.5} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="mt-1">
                                            {value ? (
                                                <span className="text-xs font-black text-fuchsia-600">预期损耗: {value} 天</span>
                                            ) : (
                                                <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">待填写</span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button 
                onClick={() => setPlanningStep('finished')} 
                className={`fixed bottom-24 left-5 right-5 py-5 rounded-2xl font-black text-lg shadow-xl transition-all ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                disabled={Object.keys(estimates).length !== stages.length}
            >
                预览规划摘要
            </button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center pb-32">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-2xl shadow-emerald-100 border-4 border-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3 tracking-tight">规划已就绪</h2>
            <p className="text-slate-400 text-sm font-medium mb-8">每一个阶段都已准备好被灵感填满</p>

            <div className="w-full bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-slate-300 uppercase">预计</span>
                            <span className="font-black text-indigo-600 text-lg">{estimates[stage.id]} 天</span>
                        </div>
                    </div>
                ))}
            </div>

            <button onClick={() => setPlanningStep('commitment')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                <Rocket size={24} />
                开启第一步
            </button>
        </div>
    );
  }

  if (planningStep === 'commitment') {
    return (
        <div className="animate-fade-in pb-32 flex flex-col items-center">
            <div className="w-full bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-[3rem] p-8 text-white shadow-2xl mb-10 relative overflow-hidden">
                <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
                <div className="relative z-10">
                    <Sparkles className="text-indigo-200 mb-6" size={32} />
                    <h2 className="text-2xl font-black leading-tight mb-4 tracking-tight">
                        现在就开始实施的有计划的举动，比无目的的晚点再做，有 <span className="text-fuchsia-300 italic">80%</span> 的可能性更容易成功哦~来试一试吗
                    </h2>
                    <div className="h-1 w-20 bg-fuchsia-400 rounded-full"></div>
                </div>
            </div>

            <div className="w-full space-y-4 mb-10">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4 mb-4">选择一个微小的开始：</h3>
                {[
                    { id: 1, title: '现在打开画布画 5 笔', icon: <Palette size={20} />, color: 'bg-rose-50 text-rose-600 border-rose-100' },
                    { id: 2, title: '再看一次单主的需求', icon: <Eye size={20} />, color: 'bg-emerald-50 text-emerald-600 border-emerald-100' },
                    { id: 3, title: '想一下构图', icon: <Layout size={20} />, color: 'bg-indigo-50 text-indigo-600 border-indigo-100' },
                    { id: 4, title: '整理一套参考图', icon: <Zap size={20} />, color: 'bg-amber-50 text-amber-600 border-amber-100' },
                ].map((option) => (
                    <div key={option.id} onClick={() => handleSelectCommitment(option)} className={`flex items-center gap-4 p-5 rounded-[2rem] border-2 transition-all hover:scale-[1.02] cursor-pointer bg-white border-slate-50 shadow-sm active:scale-95`}>
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${option.color.split(' ')[0]} ${option.color.split(' ')[1]}`}>
                            {option.icon}
                        </div>
                        <span className="font-black text-slate-700">{option.title}</span>
                        <ChevronRight className="ml-auto text-slate-200" size={18} />
                    </div>
                ))}
            </div>

            <div className="bg-slate-900/5 p-6 rounded-[2rem] border border-dashed border-slate-200 flex items-start gap-4 mb-12 w-full">
                <Timer className="text-slate-400 flex-shrink-0 mt-1" size={20} />
                <p className="text-xs text-slate-500 font-bold leading-relaxed">
                    <span className="text-slate-900 uppercase">准则：</span>
                    任意一条需进行 10 分钟，可以不完成任何事，但是让身为 P 人的自己明白，<span className="text-indigo-600">第一步已经开始啦。</span>
                </p>
            </div>

            <button 
                onClick={handleFinalize}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"
            >
                跳过专注，直接保存
            </button>
        </div>
    );
  }

  if (planningStep === 'timer') {
    return (
      <div className="animate-fade-in pb-32 flex flex-col items-center">
        <button onClick={() => setPlanningStep('commitment')} className="self-start flex items-center text-slate-400 mb-8 font-bold text-sm hover:text-slate-800 transition-colors">
          <ArrowLeft size={16} className="mr-1" /> 返回选择
        </button>

        <div className="w-full flex flex-col items-center justify-center mb-10">
          <div className={`w-24 h-24 rounded-3xl flex items-center justify-center mb-6 shadow-xl ${selectedCommitment?.color.split(' ')[0]} ${selectedCommitment?.color.split(' ')[1]}`}>
            {selectedCommitment?.icon}
          </div>
          <h2 className="text-2xl font-black text-slate-800 mb-2 tracking-tight">{selectedCommitment?.title}</h2>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">专注 10 分钟</p>
        </div>

        <div className="w-full bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 flex flex-col items-center justify-center mb-12 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-slate-100 overflow-hidden">
            <div 
              className="h-full bg-indigo-500 transition-all duration-1000 ease-linear"
              style={{ width: `${(timeLeft / 600) * 100}%` }}
            />
          </div>

          <div className="text-7xl font-black text-slate-900 tracking-tighter tabular-nums mb-8">
            {formatTime(timeLeft)}
          </div>

          {!isTimerActive ? (
            <button 
              onClick={() => setIsTimerActive(true)}
              className="flex items-center gap-3 bg-indigo-600 text-white px-10 py-5 rounded-2xl font-black text-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all"
            >
              <Play size={24} fill="currentColor" /> 开始吧
            </button>
          ) : (
            <div className="flex gap-4">
               <button 
                  onClick={() => setIsTimerActive(false)}
                  className="flex items-center gap-2 bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-black transition-all active:scale-95"
                >
                  <Pause size={20} fill="currentColor" /> 暂停
                </button>
                <button 
                  onClick={() => setTimeLeft(600)}
                  className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-100 transition-colors"
                >
                  <RefreshCw size={20} />
                </button>
            </div>
          )}
        </div>

        <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 text-center mb-10">
           <p className="text-xs text-amber-700 font-bold leading-relaxed">
             不必强求结果，只要这 10 分钟你在与画布对话。<br/>
             <span className="opacity-60 font-black">第一步一旦迈出，接下来的路就清晰了。</span>
           </p>
        </div>

        <button 
          onClick={handleFinalize}
          className="text-slate-400 font-black text-xs uppercase tracking-widest hover:text-slate-800 transition-colors"
        >
          {timeLeft === 0 ? "专注结束，保存规划" : "提前退出专注"}
        </button>
      </div>
    );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Check, ArrowUp, Link, Hourglass, ChevronRight, ChevronLeft, Rocket, Trash2, Sparkles, Zap, Palette, Eye, Layout, Timer, Play, Pause, RefreshCw, Calendar, Edit3, Save, ChevronUp, ChevronDown } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [] }) => {
  // --- Global View State ---
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [viewingSession, setViewingSession] = useState<PlanningSession | null>(null);

  // --- Planner Logic State ---
  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' },
    { id: '2', title: '线稿' },
    { id: '3', title: '上色' },
    { id: '4', title: '细节调整至终版' },
  ]);

  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [editingStageId, setEditingStageId] = useState<string | null>(null);
  const [editingStageTitle, setEditingStageTitle] = useState('');

  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'commitment' | 'timer'>('setup');

  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);

  // --- Timer State ---
  const [selectedCommitment, setSelectedCommitment] = useState<{id: number, title: string, icon: React.ReactNode, color: string} | null>(null);
  const [timeLeft, setTimeLeft] = useState(600); // 10 minutes
  const [isTimerActive, setIsTimerActive] = useState(false);

  // --- Refs to track blur interactions ---
  const isCancellingRef = useRef(false);

  // --- Initialization ---
  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) {
        setSessions(JSON.parse(storedSessions));
    }
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  // --- Timer Logic ---
  useEffect(() => {
    let interval: number | null = null;
    if (isTimerActive && timeLeft > 0) {
      interval = window.setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (timeLeft === 0) {
      setIsTimerActive(false);
      if (interval) clearInterval(interval);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isTimerActive, timeLeft]);

  // --- Helpers ---
  const getYYYYMMDD = (date: Date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const formatShortDate = (isoString: string) => {
    const d = new Date(isoString);
    return `${d.getFullYear()}/${d.getMonth() + 1}/${d.getDate()}`;
  };

  const isDateBlocked = (dateStr: string) => {
      const isGlobalBlocked = bookings?.some(b => b.date === dateStr && (b.status === 'blocked' || b.status === 'booked'));
      const isSessionBlocked = sessionBlockedDates.includes(dateStr);
      return isGlobalBlocked || isSessionBlocked;
  };

  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; 
    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0;
    let curr = new Date(start);
    let limit = 0;
    while (curr <= end && limit < 1000) {
      if (!isDateBlocked(getYYYYMMDD(curr))) {
        count++;
      }
      curr.setDate(curr.getDate() + 1);
      limit++;
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  const currentPlannedDays = (Object.values(estimates) as string[]).reduce((a: number, b: string) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;
  const isOverBudget = remainingDays < 0;

  // --- Actions ---
  const handleSyncProject = () => {
    if (!syncId.trim() || !projects) return;
    const project = projects.find(p => p.id === syncId.trim());
    if (project) {
      setSyncedProject(project);
      setShowSyncInput(false);
      setSyncId('');
    } else {
      alert('未找到该排单 ID。');
    }
  };

  const confirmTimeEntry = () => {
      if (!currentInputTime) return;
      const newEstimates = { ...estimates, [stages[activeTimeIndex].id]: currentInputTime };
      setEstimates(newEstimates);

      if (activeTimeIndex > 0) {
          const nextIndex = activeTimeIndex - 1;
          setActiveTimeIndex(nextIndex);
          setCurrentInputTime(newEstimates[stages[nextIndex].id] || '');
      } else {
          setActiveTimeIndex(-1); 
          setPlanningStep('finished');
      }
  };

  const handleCreateNew = () => {
      setMode('planner');
      setPlanningStep('setup');
      setSyncedProject(null);
      setEstimates({});
      setSessionBlockedDates([]);
      setStages([
        { id: '1', title: '草稿' },
        { id: '2', title: '线稿' },
        { id: '3', title: '上色' },
        { id: '4', title: '细节调整至终版' },
      ]);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      if (confirm('确定要删除这个规划吗？')) {
          const updated = sessions.filter(s => s.id !== id);
          persistSessions(updated);
      }
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(),
          projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages: stages,
          estimates: estimates,
          blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(),
          lastUpdated: new Date().toISOString(),
          completedDays: [],
      };
      persistSessions([newSession, ...sessions]);
      setMode('dashboard');
      setPlanningStep('setup');
      // Reset timer states
      setIsTimerActive(false);
      setTimeLeft(600);
      setSelectedCommitment(null);
  };

  const handleSelectCommitment = (option: {id: number, title: string, icon: React.ReactNode, color: string}) => {
    setSelectedCommitment(option);
    setPlanningStep('timer');
    setTimeLeft(600);
    setIsTimerActive(false);
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  };

  const handleDeleteStage = (id: string) => {
    if (stages.length <= 1) {
      alert('至少需要保留一个绘画阶段。');
      return;
    }
    setStages(prev => prev.filter(s => s.id !== id));
  };

  const startEditStage = (stage: PlannerStage) => {
    setEditingStageId(stage.id);
    setEditingStageTitle(stage.title);
  };

  const saveEditedStage = () => {
    if (isCancellingRef.current) {
        isCancellingRef.current = false;
        return;
    }
    if (editingStageTitle.trim()) {
        setStages(prev => prev.map(s => s.id === editingStageId ? { ...s, title: editingStageTitle.trim() } : s));
    }
    setEditingStageId(null);
    setEditingStageTitle('');
  };

  const handleSaveNewStage = () => {
    if (isCancellingRef.current) {
        isCancellingRef.current = false;
        return;
    }
    if (newStageTitle.trim()) {
      setStages([...stages, { id: Date.now().toString(), title: newStageTitle.trim() }]);
    }
    setIsAdding(false);
    setNewStageTitle('');
  };

  const moveStage = (index: number, direction: 'up' | 'down') => {
    const newStages = [...stages];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newStages.length) return;
    [newStages[index], newStages[targetIndex]] = [newStages[targetIndex], newStages[index]];
    setStages(newStages);
  };

  // --- Main Renders ---

  if (mode === 'dashboard') {
    return (
        <div className="animate-fade-in pb-32">
             <div className="flex justify-between items-center mb-6">
                <button onClick={onBack} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold">
                    <ArrowLeft size={16} className="mr-1" /> 返回主菜单
                </button>
             </div>

             {viewingSession ? (
                 <div className="animate-fade-in">
                    <button onClick={() => setViewingSession(null)} className="flex items-center text-indigo-600 mb-6 text-sm font-bold">
                        <ArrowLeft size={16} className="mr-1" /> 返回规划列表
                    </button>
                    <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8">
                        <h2 className="text-2xl font-black text-slate-800 mb-1">{viewingSession.clientName}</h2>
                        <p className="text-xs text-slate-400 mb-8 font-medium">规划于 {formatDate(viewingSession.createdAt)}</p>

                        <div className="space-y-4">
                            {viewingSession.stages.map(stage => (
                                <div key={stage.id} className="flex justify-between items-center py-4 border-b border-slate-50 last:border-0">
                                    <span className="font-bold text-slate-600">{stage.title}</span>
                                    <div className="flex items-center gap-2">
                                        <span className="text-[10px] font-black text-slate-300 uppercase">分配</span>
                                        <span className="font-black text-indigo-600 text-lg">{viewingSession.estimates[stage.id]} 天</span>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                 </div>
             ) : (
                <>
                    <div className="mb-8 px-1">
                        <h2 className="text-2xl font-black text-slate-800 tracking-tight">辅助规划</h2>
                        <p className="text-slate-400 text-sm mt-1 font-medium">预估你的排单创作节奏</p>
                    </div>

                    <button onClick={handleCreateNew} className="w-full bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-xl flex flex-col items-center justify-center gap-4 mb-8 active:scale-95 transition-all group overflow-hidden relative">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/20 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                        <div className="bg-white/20 p-4 rounded-3xl group-hover:bg-fuchsia-500 transition-colors"><Plus size={32} /></div>
                        <div className="text-center">
                            <h3 className="font-bold text-xl">创建新规划</h3>
                            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Start New Plan</p>
                        </div>
                    </button>

                    {sessions.length > 0 ? (
                        <div className="space-y-4">
                            {sessions.map(session => (
                                <div key={session.id} onClick={() => setViewingSession(session)} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group flex justify-between items-center">
                                    <div>
                                        <h4 className="font-bold text-slate-800 text-lg">{session.clientName}</h4>
                                        <p className="text-xs text-slate-400 mt-1">
                                            {session.stages.length} 个阶段 · 合计 {(Object.values(session.estimates) as string[]).reduce((a, b) => a + Number(b), 0)} 天
                                        </p>
                                    </div>
                                    <button 
                                        onClick={(e) => handleDeleteSession(e, session.id)}
                                        className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                                    >
                                        <Trash2 size={18} />
                                    </button>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-12 bg-slate-50 rounded-[2.5rem] border border-dashed border-slate-200">
                            <p className="text-sm text-slate-400 font-medium">暂无已保存的规划</p>
                        </div>
                    )}
                </>
             )}
        </div>
    );
  }

  if (planningStep === 'setup') {
    return (
        <div className="animate-fade-in pb-32">
           <div className="flex justify-between items-center mb-6">
                <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 hover:text-slate-800 transition-colors text-sm font-bold"><ArrowLeft size={16} /> 返回列表</button>
                <div className="bg-fuchsia-100 text-fuchsia-600 px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest border border-fuchsia-200">Stage Setup</div>
           </div>

           <div className="mb-8 p-6 bg-slate-900 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                    <h2 className="text-2xl font-black leading-tight">
                        {syncedProject ? `${syncedProject.clientName} 的专属工期` : '自定义创作节奏'}
                    </h2>

                    {syncedProject && (
                      <div className="mt-2 flex items-center gap-2 text-fuchsia-300 font-bold text-xs bg-white/5 w-fit px-3 py-1.5 rounded-lg border border-white/10">
                        <Calendar size={12} />
                        <span>工期: {formatShortDate(syncedProject.startDate)} - {formatShortDate(syncedProject.deadline)}</span>
                      </div>
                    )}

                    {!syncedProject && (
                        <button onClick={() => setShowSyncInput(true)} className="mt-4 flex items-center gap-2 bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-xs font-bold transition-all active:scale-95">
                            <Link size={14} /> 关联现有排单项目
                        </button>
                    )}
                    {showSyncInput && <div className="mt-4 flex gap-2 animate-fade-in"><input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入 ID" className="flex-1 text-sm bg-white/10 border border-white/20 rounded-xl px-4 py-2 outline-none text-white" /><button onClick={handleSyncProject} className="bg-white text-slate-900 px-4 py-2 rounded-xl text-xs font-black">同步</button></div>}
                </div>
           </div>

           <div className="space-y-4 mb-12">
              {!isAdding ? (
                <div onClick={() => setIsAdding(true)} className="w-full h-24 border-2 border-dashed border-slate-200 rounded-[2rem] flex items-center justify-center text-slate-400 cursor-pointer hover:border-fuchsia-400 transition-all group active:scale-[0.98]">
                    <Plus size={28} />
                    <span className="text-xs font-black uppercase tracking-widest ml-4">添加绘画阶段</span>
                </div>
              ) : (
                <div className="w-full p-4 border-2 border-fuchsia-300 rounded-[2rem] flex items-center justify-between bg-white shadow-xl animate-slide-up">
                    <input 
                      autoFocus 
                      type="text" 
                      placeholder="例如：精修细化..." 
                      value={newStageTitle} 
                      onChange={(e) => setNewStageTitle(e.target.value)} 
                      onBlur={handleSaveNewStage}
                      onKeyDown={(e) => e.key === 'Enter' && handleSaveNewStage()} 
                      className="flex-1 bg-transparent text-xl font-black text-slate-800 outline-none px-2" 
                    />
                    <button 
                      onMouseDown={(e) => {
                          e.preventDefault(); 
                          isCancellingRef.current = true;
                          setIsAdding(false);
                          setNewStageTitle('');
                      }} 
                      className="p-3 text-slate-400 hover:text-rose-500 transition-colors"
                    >
                      <X size={20} />
                    </button>
                </div>
              )}

              {stages.map((stage, index) => (
                <div key={stage.id} className="relative border-2 border-slate-100 rounded-[2.5rem] flex items-center w-full h-20 px-6 bg-white shadow-sm group transition-all duration-300">
                    <div className="flex flex-col items-center mr-4 flex-shrink-0 text-slate-200 gap-1">
                        <button 
                          onClick={() => moveStage(index, 'up')} 
                          disabled={index === 0}
                          className={`p-1 rounded-md transition-colors ${index === 0 ? 'opacity-10 cursor-not-allowed' : 'hover:bg-slate-50 hover:text-indigo-500 active:scale-90 text-slate-300'}`}
                        >
                          <ChevronUp size={16} />
                        </button>
                        <GripVertical size={16} className="opacity-30" />
                        <button 
                          onClick={() => moveStage(index, 'down')} 
                          disabled={index === stages.length - 1}
                          className={`p-1 rounded-md transition-colors ${index === stages.length - 1 ? 'opacity-10 cursor-not-allowed' : 'hover:bg-slate-50 hover:text-indigo-500 active:scale-90 text-slate-300'}`}
                        >
                          <ChevronDown size={16} />
                        </button>
                    </div>

                    {editingStageId === stage.id ? (
                      <div className="flex-1 flex items-center gap-2 pr-2 animate-fade-in">
                        <input 
                          autoFocus 
                          type="text" 
                          value={editingStageTitle} 
                          onChange={(e) => setEditingStageTitle(e.target.value)}
                          onBlur={saveEditedStage}
                          onKeyDown={(e) => e.key === 'Enter' && saveEditedStage()}
                          className="flex-1 bg-slate-50 border-2 border-fuchsia-200 rounded-xl px-4 py-2 text-sm font-black text-slate-800 outline-none"
                        />
                        <button 
                          onMouseDown={(e) => e.preventDefault()}
                          onClick={saveEditedStage} 
                          className="p-2 bg-fuchsia-500 text-white rounded-xl shadow-md active:scale-90 transition-all"
                        >
                          <Save size={16} />
                        </button>
                        <button 
                          onMouseDown={(e) => {
                              e.preventDefault();
                              isCancellingRef.current = true;
                              setEditingStageId(null);
                          }}
                          className="p-2 text-slate-400"
                        >
                          <X size={16} />
                        </button>
                      </div>
                    ) : (
                      <>
                        <div className="flex flex-col flex-1 min-w-0">
                            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Phase {index + 1}</span>
                            <span className="font-black text-slate-700 text-lg anonymous-block leading-none truncate pr-4">{stage.title}</span>
                        </div>
                        <div className="flex items-center gap-1 opacity-100 md:opacity-0 md:group-hover:opacity-100 transition-opacity">
                            <button 
                              onClick={() => startEditStage(stage)}
                              className="p-2 text-slate-300 hover:text-indigo-500 transition-colors"
                              title="重命名"
                            >
                              <Edit3 size={18} />
                            </button>
                            <button 
                              onClick={() => handleDeleteStage(stage.id)}
                              className="p-2 text-slate-300 hover:text-rose-500 transition-colors"
                              title="删除"
                            >
                              <X size={18} />
                            </button>
                        </div>
                      </>
                    )}
                </div>
              ))}
           </div>

           <div className="fixed bottom-24 left-0 w-full px-5">
               <button onClick={() => setPlanningStep('off-days')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                   确认阶段，设置休息日
               </button>
           </div>
        </div>
    );
  }

  if (planningStep === 'off-days') {
      const year = offDayViewDate.getFullYear();
      const month = offDayViewDate.getMonth();
      const firstDay = new Date(year, month, 1);
      const calendarDays: (Date|null)[] = [];
      for (let i = 0; i < firstDay.getDay(); i++) calendarDays.push(null);
      const lastDay = new Date(year, month + 1, 0);
      for (let i = 1; i <= lastDay.getDate(); i++) calendarDays.push(new Date(year, month, i));

      return (
          <div className="animate-fade-in pb-32 px-1">
              <button onClick={() => setPlanningStep('setup')} className="flex items-center text-slate-400 mb-6 text-sm font-bold hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回设置</button>
              <div className="flex justify-between items-center mb-4 px-1">
                  <div>
                    <h2 className="text-2xl font-black text-slate-800 tracking-tight">{offDayViewDate.toLocaleString('zh-CN', { month: 'long', year: 'numeric' })}</h2>
                  </div>
                  <div className="flex gap-2">
                      <button onClick={() => setOffDayViewDate(new Date(year, month - 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronLeft size={18} /></button>
                      <button onClick={() => setOffDayViewDate(new Date(year, month + 1, 1))} className="p-2 bg-slate-50 rounded-xl hover:bg-slate-100 transition-colors"><ChevronRight size={18} /></button>
                  </div>
              </div>
              <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-rose-50 mb-6">
                  <div className="grid grid-cols-7 gap-2">
                      {['日', '一', '二', '三', '四', '五', '六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase py-1">{d}</div>)}
                      {calendarDays.map((day, idx) => {
                          if (!day) return <div key={`empty-${idx}`} className="aspect-square bg-slate-50/30 rounded-lg"></div>;
                          const dStr = getYYYYMMDD(day);
                          const isBlocked = sessionBlockedDates.includes(dStr);
                          return (
                              <div key={dStr} onClick={() => setSessionBlockedDates(prev => prev.includes(dStr) ? prev.filter(d => d !== dStr) : [...prev, dStr])} className={`aspect-square rounded-xl border flex items-center justify-center cursor-pointer transition-all active:scale-90 ${isBlocked ? 'bg-rose-50 border-rose-200 text-rose-500 font-bold' : 'bg-white border-slate-50 text-slate-700 hover:bg-slate-50'}`}>
                                  <span className="text-xs font-black">{day.getDate()}</span>
                              </div>
                          );
                      })}
                  </div>
              </div>
              <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(stages.length - 1); setCurrentInputTime(''); }} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all">
                  确认休息日，分配工期
              </button>
          </div>
      );
  }

  if (planningStep === 'time-entry') {
    return (
        <div className="animate-fade-in pb-32 h-full flex flex-col px-1">
            <div className="flex justify-between items-center mb-6">
                <button onClick={() => setPlanningStep('off-days')} className="text-slate-400 font-bold text-sm flex items-center gap-1 hover:text-slate-800 transition-colors"><ArrowLeft size={16} /> 返回休息日</button>
                <div className="text-[10px] font-black text-fuchsia-600 bg-fuchsia-50 px-2 py-1 rounded-lg">工期预算</div>
            </div>

            <div className="bg-white rounded-[2.5rem] p-6 shadow-xl border border-fuchsia-100 mb-8 flex items-center justify-between relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-fuchsia-500/5 rounded-full -mr-16 -mt-16 blur-2xl"></div>
                <div className="flex flex-col relative z-10">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">可用天数预算 (排除休息日)</span>
                    <div className="flex items-baseline gap-2">
                        <span className={`text-4xl font-black transition-colors ${isOverBudget ? 'text-rose-600 animate-pulse' : 'text-slate-800'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-slate-400">/ {totalAvailableDays} 天</span>
                    </div>
                </div>
                <Hourglass size={28} className="text-fuchsia-500 relative z-10" />
            </div>

            <div className="flex-1 relative pl-8">
                <div className="absolute left-12 top-4 bottom-12 w-1 bg-slate-100 rounded-full"></div>
                <div className="space-y-6">
                    {stages.map((stage, index) => {
                        const isActive = index === activeTimeIndex;
                        const value = estimates[stage.id];
                        const isDone = value && !isActive;

                        return (
                            <div key={stage.id} className="relative flex items-center">
                                <div className={`absolute -left-0 w-8 h-8 rounded-full border-4 z-10 transition-all duration-300 flex items-center justify-center ${isActive ? 'bg-fuchsia-500 border-fuchsia-100 scale-125 shadow-lg shadow-fuchsia-100' : isDone ? 'bg-white border-fuchsia-500' : 'bg-slate-100 border-white'}`}>
                                    {isDone && <Check size={14} className="text-fuchsia-600" strokeWidth={3} />}
                                </div>
                                <div 
                                    onClick={() => { 
                                        setActiveTimeIndex(index); 
                                        setCurrentInputTime(estimates[stage.id] || ''); 
                                    }} 
                                    className={`ml-10 flex-1 flex flex-col p-5 rounded-[2.5rem] border-2 transition-all duration-300 cursor-pointer ${isActive ? 'bg-white border-fuchsia-500 shadow-2xl translate-x-2' : 'bg-slate-50 border-slate-100 opacity-60'}`}
                                >
                                    <div className="flex justify-between items-start">
                                        <span className={`font-black transition-all ${isActive ? 'text-slate-800 text-lg' : 'text-slate-500'}`}>{stage.title}</span>
                                    </div>

                                    {isActive ? (
                                        <div className="flex items-center gap-3 mt-3 animate-fade-in">
                                            <div className="relative flex-1 max-w-[120px]">
                                                <input 
                                                    autoFocus 
                                                    type="text" 
                                                    value={currentInputTime} 
                                                    onChange={(e) => /^\d*\.?\d*$/.test(e.target.value) && setCurrentInputTime(e.target.value)} 
                                                    className="w-full bg-slate-50 border-2 border-fuchsia-100 rounded-2xl px-4 py-3 text-center text-2xl font-black text-fuchsia-600 outline-none focus:border-fuchsia-500 transition-colors" 
                                                    placeholder="0"
                                                    onKeyDown={(e) => e.key === 'Enter' && confirmTimeEntry()} 
                                                />
                                                <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] font-black text-fuchsia-300">DAYS</span>
                                            </div>
                                            <button 
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    confirmTimeEntry();
                                                }} 
                                                className="bg-slate-900 text-white p-4 rounded-2xl shadow-xl shadow-slate-200 active:scale-90 transition-all hover:bg-slate-800"
                                            >
                                                <ArrowUp size={24} strokeWidth={2.5} />
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="mt-1">
                                            {value ? (
                                                <span className="text-xs font-black text-fuchsia-600">预期损耗: {value} 天</span>
                                            ) : (
                                                <span className="text-[10px] font-bold text-slate-300 uppercase tracking-widest">待填写</span>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <button 
                onClick={() => setPlanningStep('finished')} 
                className={`fixed bottom-24 left-5 right-5 py-5 rounded-2xl font-black text-lg shadow-xl transition-all ${Object.keys(estimates).length === stages.length ? 'bg-slate-900 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
                disabled={Object.keys(estimates).length !== stages.length}
            >
                预览规划摘要
            </button>
        </div>
    );
  }

  if (planningStep === 'finished') {
    return (
        <div className="animate-fade-in flex flex-col items-center justify-center pt-16 px-6 text-center pb-32">
            <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 mb-8 shadow-2xl shadow-emerald-100 border-4 border-white"><Check size={48} strokeWidth={3} /></div>
            <h2 className="text-3xl font-black text-slate-800 mb-3 tracking-tight">规划已就绪</h2>
            <p className="text-slate-400 text-sm font-medium mb-8">每一个阶段都已准备好被灵感填满</p>

            <div className="w-full bg-white rounded-[2.5rem] p-8 shadow-xl border border-slate-100 mb-8 text-left space-y-4">
                {stages.map(stage => (
                    <div key={stage.id} className="flex justify-between items-center py-3 border-b border-slate-50 last:border-0">
                        <span className="font-bold text-slate-600">{stage.title}</span>
                        <div className="flex items-center gap-2">
                            <span className="text-[10px] font-black text-slate-300 uppercase">预计</span>
                            <span className="font-black text-indigo-600 text-lg">{estimates[stage.id]} 天</span>
                        </div>
                    </div>
                ))}
            </div>

            <button onClick={() => setPlanningStep('commitment')} className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                <Rocket size={24} />
                开启第一步
            </button>
        </div>
    );
  }

  if (planningStep === 'commitment') {
    return (
        <div className="animate-fade-in pb-32 flex flex-col items-center">
            <div className="w-full bg-gradient-to-br from-indigo-600 to-indigo-900 rounded-[3rem] p-8 text-white shadow-2xl mb-10 relative overflow-hidden">
                <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
                <div className="relative z-10">
                    <Sparkles className="text-indigo-200 mb-6" size={32} />
                    <h2 className="text-2xl font-black leading-tight mb-4 tracking-tight">
                        现在就开始实施的有计划的举动，比无目的的晚点再做，有 <span className="text-fuchsia-300 italic">80%</span> 的可能性更容易成功哦~来试一试吗
                    </h2>
                    <div className="h-1 w-20 bg-fuchsia-400 rounded-full"></div>
                </div>
            </div>

            <div className="w-full space-y-4 mb-10">
                <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest px-4 mb-4">选择一个微小的开始：</h3>
                {[
                    { id: 1, title: '现在打开画布画 5 笔', icon: <Palette size={20} />, color: 'bg-rose-50 text-rose-600 border-rose-100' },
                    { id: 2, title: '再看一次单主的需求', icon: <Eye size={20} />, color: 'bg-emerald-50 text-emerald-600 border-emerald-100' },
                    { id: 3, title: '想一下构图', icon: <Layout size={20} />, color: 'bg-indigo-50 text-indigo-600 border-indigo-100' },
                    { id: 4, title: '整理一套参考图', icon: <Zap size={20} />, color: 'bg-amber-50 text-amber-600 border-amber-100' },
                ].map((option) => (
                    <div key={option.id} onClick={() => handleSelectCommitment(option)} className={`flex items-center gap-4 p-5 rounded-[2rem] border-2 transition-all hover:scale-[1.02] cursor-pointer bg-white border-slate-50 shadow-sm active:scale-95`}>
                        <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${option.color.split(' ')[0]} ${option.color.split(' ')[1]}`}>
                            {option.icon}
                        </div>
                        <span className="font-black text-slate-700">{option.title}</span>
                        <ChevronRight className="ml-auto text-slate-200" size={18} />
                    </div>
                ))}
            </div>

            <div className="bg-slate-900/5 p-6 rounded-[2rem] border border-dashed border-slate-200 flex items-start gap-4 mb-12 w-full">
                <Timer className="text-slate-400 flex-shrink-0 mt-1" size={20} />
                <p className="text-xs text-slate-500 font-bold leading-relaxed">
                    <span className="text-slate-900 uppercase">准则：</span>
                    任意一条需进行 10 分钟，可以不完成任何事，但是让身为 P 人的自己明白，<span className="text-indigo-600">第一步已经开始啦。</span>
                </p>
            </div>

            <button 
                onClick={handleFinalize}
                className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black text-lg shadow-xl active:scale-95 transition-all"
            >
                跳过专注，直接保存
            </button>
        </div>
    );
  }

  if (planningStep === 'timer') {
    return (
      <div className="animate-fade-in pb-32 flex flex-col items-center">
        <button onClick={() => setPlanningStep('commitment')} className="self-start flex items-center text-slate-400 mb-8 font-bold text-sm hover:text-slate-800 transition-colors">
          <ArrowLeft size={16} className="mr-1" /> 返回选择
        </button>

        <div className="w-full flex flex-col items-center justify-center mb-10">
          <div className={`w-24 h-24 rounded-3xl flex items-center justify-center mb-6 shadow-xl ${selectedCommitment?.color.split(' ')[0]} ${selectedCommitment?.color.split(' ')[1]}`}>
            {selectedCommitment?.icon}
          </div>
          <h2 className="text-2xl font-black text-slate-800 mb-2 tracking-tight">{selectedCommitment?.title}</h2>
          <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">专注 10 分钟</p>
        </div>

        <div className="w-full bg-white rounded-[3rem] p-12 shadow-2xl border border-slate-100 flex flex-col items-center justify-center mb-12 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-slate-100 overflow-hidden">
            <div 
              className="h-full bg-indigo-500 transition-all duration-1000 ease-linear"
              style={{ width: `${(timeLeft / 600) * 100}%` }}
            />
          </div>

          <div className="text-7xl font-black text-slate-900 tracking-tighter tabular-nums mb-8">
            {formatTime(timeLeft)}
          </div>

          {!isTimerActive ? (
            <button 
              onClick={() => setIsTimerActive(true)}
              className="flex items-center gap-3 bg-indigo-600 text-white px-10 py-5 rounded-2xl font-black text-xl shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all"
            >
              <Play size={24} fill="currentColor" /> 开始吧
            </button>
          ) : (
            <div className="flex gap-4">
               <button 
                  onClick={() => setIsTimerActive(false)}
                  className="flex items-center gap-2 bg-slate-100 text-slate-600 px-8 py-4 rounded-2xl font-black transition-all active:scale-95"
                >
                  <Pause size={20} fill="currentColor" /> 暂停
                </button>
                <button 
                  onClick={() => setTimeLeft(600)}
                  className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-100 transition-colors"
                >
                  <RefreshCw size={20} />
                </button>
            </div>
          )}
        </div>

        <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 text-center mb-10">
           <p className="text-xs text-amber-700 font-bold leading-relaxed">
             不必强求结果，只要这 10 分钟你在与画布对话。<br/>
             <span className="opacity-60 font-black">第一步一旦迈出，接下来的路就清晰了。</span>
           </p>
        </div>

        <button 
          onClick={handleFinalize}
          className="text-slate-400 font-black text-xs uppercase tracking-widest hover:text-slate-800 transition-colors"
        >
          {timeLeft === 0 ? "专注结束，保存规划" : "提前退出专注"}
        </button>
      </div>
    );
  }

  return null; 
};

export default PTypePlanner;

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode, PlanningSession } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [planningMode, setPlanningMode] = useState<'selection' | 'j-type' | 'p-type'>('selection');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>('');
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // WeChat User State
  const [wechatUser, setWechatUser] = useState<{nickname: string, avatar?: string} | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', 
    description: '',
    startDate: '',
    deadline: ''
  });

  // Initialization: Load or Create IDs
  useEffect(() => {
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }
  }, []);

  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      return;
    }

    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
  }, [currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;
    if (searchId === myArtistId) {
       setConnectedArtistId(searchId);
       localStorage.setItem('artflow_connected_artist_id', searchId);
       return;
    }
    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    if (targetProjects) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接（假设其存在）？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  const handleWeChatLogin = () => {
    alert("微信登录接口已预留。");
    setWechatUser({ nickname: "微信用户", avatar: "" });
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;

    if (editingProjectId) {
      setProjects(projects.map(p => 
        p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
        } : p
      ));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || '无具体描述',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }

    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({
      clientName: project.clientName,
      targetClientId: project.targetClientId,
      description: project.description,
      startDate: project.startDate,
      deadline: project.deadline
    });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  /**
   * 删除工单逻辑
   */
  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;

    // 弹出确认框防止误删
    if(confirm('确定要删除这个排单工单吗？删除后该项目的排期进度和辅助规划数据也将一并清除，不可恢复。')) {
        // 1. 从项目列表中过滤掉
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));

        // 2. 清理相关的辅助规划记录 (Sessions)
        const storedSessions = localStorage.getItem('artflow_planning_sessions');
        if (storedSessions) {
            try {
                const sessions = JSON.parse(storedSessions) as PlanningSession[];
                const updatedSessions = sessions.filter(s => s.projectId !== id);
                localStorage.setItem('artflow_planning_sessions', JSON.stringify(updatedSessions));
            } catch (error) {
                console.error("Cleanup error during deletion:", error);
            }
        }
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');
    const response = await analyzeSchedule(projects, bookings, aiQuery);
    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制到剪贴板`);
  };

  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') {
      handleDisconnect();
    }
  };

  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex flex-col">
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm">
        <div className="flex justify-between items-center mb-3 md:mb-0">
          <div className="flex items-center gap-2.5">
            <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-lg">
              <Paintbrush size={18} />
            </div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight hidden md:block">ArtFlow</h1>
          </div>
          <div className="flex items-center gap-3">
             {viewMode === 'artist' && (
                <button onClick={() => setShowAI(!showAI)} className={`p-2 rounded-full transition-colors ${showAI ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 text-slate-400'}`}>
                  <Sparkles size={20} />
                </button>
             )}
            <button onClick={toggleViewMode} className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full transition-all border ${viewMode === 'artist' ? 'bg-slate-800 text-white border-slate-800' : 'bg-indigo-600 text-white border-indigo-600'}`}>
                {viewMode === 'artist' ? <><Paintbrush size={12}/> 画手模式</> : <><UserCircle2 size={14}/> 单主模式</>}
            </button>
          </div>
        </div>
        <div className="w-full">
           {viewMode === 'artist' ? (
             <div className="flex items-center justify-between bg-slate-50 rounded-lg p-1.5 border border-slate-100">
               <div className="flex items-center gap-2 flex-1 min-w-0">
                  {wechatUser ? (
                      <div className="flex items-center gap-1.5 pl-1.5 bg-emerald-100/50 py-1 px-2 rounded-md">
                          <MessageCircle size={12} className="text-emerald-600" />
                          <span className="text-xs font-bold text-emerald-800 truncate max-w-[80px]">{wechatUser.nickname}</span>
                      </div>
                  ) : (
                      <button onClick={handleWeChatLogin} className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg transition-all shadow-sm active:scale-95">
                         <span className="text-[10px] font-bold">微信登录</span>
                      </button>
                  )}
                  <div className="flex items-center gap-1 min-w-0 flex-1 justify-end mr-2">
                     <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">ID</span>
                     <span className="text-xs text-slate-800 font-bold font-mono truncate">{myArtistId}</span>
                  </div>
               </div>
               <button onClick={() => copyText(myArtistId, 'Artist ID')} className="p-1.5 bg-white shadow-sm border border-slate-100 rounded-md text-slate-400 hover:text-indigo-600">
                 <Copy size={14} />
               </button>
             </div>
           ) : (
             <div className="flex gap-2">
               {!connectedArtistId ? (
                 <>
                  <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input type="text" value={searchId} onChange={(e) => setSearchId(e.target.value)} placeholder="搜索画手 ID (如: ART-1234)" className="w-full bg-slate-100 border-none rounded-lg pl-9 pr-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
                  </div>
                  <button onClick={handleSearchArtist} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap">连接</button>
                 </>
               ) : (
                 <div className="flex items-center justify-between w-full bg-indigo-50 rounded-lg p-2 border border-indigo-100">
                    <span className="text-xs text-indigo-800 font-medium px-2 flex items-center gap-1">
                      <span className="opacity-60">已连接:</span> <span className="font-bold">{connectedArtistId}</span>
                    </span>
                    <button onClick={handleDisconnect} className="flex items-center gap-1 bg-white px-2 py-1 rounded text-[10px] font-bold text-slate-500 shadow-sm"><LogOut size={10} /> 退出</button>
                 </div>
               )}
             </div>
           )}
        </div>
      </header>

      <main className="flex-1 w-full max-w-lg mx-auto p-5 pb-32">
        {viewMode === 'client' && !connectedArtistId && (
           <div className="flex flex-col items-center justify-center mt-10 animate-fade-in">
              <div className="w-full bg-white rounded-2xl shadow-xl p-6 mb-8 border border-slate-100">
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint className="text-indigo-600" size={24} />
                  <h3 className="text-sm font-bold text-slate-500 uppercase">我的单主 ID</h3>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-3xl font-black text-slate-800">{myClientId}</span>
                  <button onClick={() => copyText(myClientId, '单主 ID')} className="bg-indigo-50 text-indigo-600 p-2 rounded-lg"><Copy size={18} /></button>
                </div>
                <p className="text-xs text-slate-400 mt-3">画手为您新建工单时填入此 ID，您连接后即可同步进度。</p>
              </div>
              <p className="text-slate-400 text-sm text-center">输入画手 ID 开始连接</p>
           </div>
        )}

        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg animate-fade-in">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm"><Sparkles size={14} className="text-indigo-500" /> 智能助理</h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400"><X size={16} /></button>
                </div>
                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">{isAiLoading ? "思考中..." : aiResponse || "你好！我是你的排单助手。"}</div>
                <div className="flex gap-2">
                  <input type="text" value={aiQuery} onChange={(e) => setAiQuery(e.target.value)} placeholder="下周还能接急单吗？" className="flex-1 text-sm rounded-lg border px-3 py-2 focus:ring-1 focus:ring-indigo-500 outline-none" onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()} />
                  <button onClick={handleAiAsk} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold">发送</button>
                </div>
              </div>
            )}

            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-4">
                <div className="flex flex-col gap-4">
                   <div className="flex justify-between items-end px-1">
                      <h2 className="text-xl font-bold text-slate-800">{viewMode === 'artist' ? '我的排单' : '我的订单'}</h2>
                      {viewMode === 'artist' && (
                        <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2"><Plus size={16} /> 新建</button>
                      )}
                   </div>
                   <div className="flex p-1 bg-slate-200/50 rounded-xl">
                      <button onClick={() => setProjectSubTab('active')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>进行中</button>
                      <button onClick={() => setProjectSubTab('completed')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>已完成</button>
                   </div>
                </div>
                <div className="space-y-3 min-h-[200px]">
                  {displayedProjects.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16 text-slate-400 bg-white rounded-2xl border border-dashed">暂无相关记录</div>
                  ) : (
                    displayedProjects
                      .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                      .map(project => (
                        <ProjectCard 
                          key={project.id} 
                          project={project} 
                          onComplete={handleCompleteProject}
                          onDelete={handleDeleteProject}
                          onEdit={handleEditProject}
                          readOnly={viewMode === 'client'}
                        />
                      ))
                  )}
                </div>
              </div>
            )}

            {activeTab === 'schedule' && (
              <div className="animate-fade-in">
                 <div className="bg-white rounded-2xl shadow-sm border overflow-hidden">
                    <ScheduleBoard bookings={bookings} projects={projects} mode={viewMode} onUpdateBookings={setBookings} currentClientId={viewMode === 'client' ? myClientId : undefined} currentClientName={viewMode === 'client' ? '我' : undefined} />
                 </div>
              </div>
            )}

            {activeTab === 'planning' && viewMode === 'artist' && (
              <div className="animate-fade-in">
                {planningMode === 'selection' ? (
                  <div className="flex flex-col gap-6">
                    <h2 className="text-xl font-bold text-slate-800">辅助规划</h2>
                    <button onClick={() => setPlanningMode('p-type')} className="bg-gradient-to-br from-fuchsia-50 to-rose-50 border border-fuchsia-100 p-6 rounded-3xl text-left group active:scale-95 transition-all">
                      <div className="w-12 h-12 bg-fuchsia-100 rounded-2xl flex items-center justify-center text-fuchsia-600 group-hover:bg-fuchsia-600 group-hover:text-white mb-3"><Lightbulb size={24} /></div>
                      <h3 className="text-lg font-bold text-fuchsia-900">P人规划法</h3>
                      <p className="text-xs text-fuchsia-600/70 font-medium mt-1">抽象化，靈感驱动，适合非量化创作</p>
                    </button>
                  </div>
                ) : (
                   <PTypePlanner onBack={() => setPlanningMode('selection')} projects={projects} bookings={bookings} onUpdateBookings={setBookings} />
                )}
              </div>
            )}
          </>
        )}
      </main>

      {(viewMode === 'artist' || connectedArtistId) && (
        <nav className="fixed bottom-0 left-0 w-full bg-white border-t pb-[env(safe-area-inset-bottom)] z-40 shadow-lg">
          <div className="flex justify-between items-center px-6 h-16 md:hidden">
            <button onClick={() => setActiveTab('projects')} className={`flex-1 flex flex-col items-center justify-center gap-1 active:scale-90 transition-transform ${activeTab === 'projects' ? 'text-indigo-600' : 'text-slate-400'}`}>
              <Layout size={22} />
              <span className="text-[10px] font-medium">工单</span>
            </button>
            <button onClick={() => setActiveTab('schedule')} className={`flex-1 flex flex-col items-center justify-center gap-1 active:scale-90 transition-transform ${activeTab === 'schedule' ? 'text-indigo-600' : 'text-slate-400'}`}>
              <CalendarDays size={22} />
              <span className="text-[10px] font-medium">排期</span>
            </button>
            {viewMode === 'artist' && (
                <button onClick={() => setActiveTab('planning')} className={`flex-1 flex flex-col items-center justify-center gap-1 active:scale-90 transition-transform ${activeTab === 'planning' ? 'text-indigo-600' : 'text-slate-400'}`}>
                  <BrainCircuit size={22} />
                  <span className="text-[10px] font-medium">规划</span>
                </button>
            )}
            {viewMode === 'artist' && (
              <div className="absolute left-1/2 -translate-x-1/2 -top-6">
                <button onClick={() => setShowAddModal(true)} className="w-12 h-12 bg-slate-900 rounded-full flex items-center justify-center text-white shadow-xl border-4 border-slate-50"><Plus size={24} /></button>
              </div>
            )}
          </div>
          <div className="hidden md:flex justify-center gap-8 py-4">
             <button onClick={() => setActiveTab('projects')} className={`px-6 py-2 rounded-xl font-bold ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500'}`}>排单列表</button>
             <button onClick={() => setActiveTab('schedule')} className={`px-6 py-2 rounded-xl font-bold ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500'}`}>排期日历</button>
             {viewMode === 'artist' && <button onClick={() => setActiveTab('planning')} className={`px-6 py-2 rounded-xl font-bold ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500'}`}>辅助规划</button>}
          </div>
        </nav>
      )}

      {showAddModal && viewMode === 'artist' && (
        <div className="fixed inset-0 z-50 flex flex-col justify-end md:justify-center md:items-center bg-slate-900/40 backdrop-blur-sm animate-fade-in">
          <div className="absolute inset-0" onClick={handleCloseModal}></div>
          <div className="relative bg-white w-full md:w-[400px] md:rounded-3xl rounded-t-3xl shadow-2xl animate-slide-up p-6 overflow-y-auto max-h-[90vh]">
            <h3 className="text-xl font-bold text-slate-800 mb-6">{editingProjectId ? '编辑排单' : '新建排单'}</h3>
            <div className="space-y-5">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-2">单主名称</label>
                <input type="text" value={newProject.clientName} onChange={e => setNewProject({...newProject, clientName: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="老板A" />
              </div>
              <div>
                <label className="block text-xs font-bold text-indigo-600 uppercase mb-2">单主 ID (必填)</label>
                <input type="text" value={newProject.targetClientId} onChange={e => setNewProject({...newProject, targetClientId: e.target.value})} className="w-full bg-indigo-50 border border-indigo-200 rounded-xl px-4 py-3 text-sm font-bold text-indigo-900 outline-none" placeholder="CLI-xxxx" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                   <label className="block text-xs font-bold text-slate-500 mb-2">开始时间</label>
                   <input type="datetime-local" value={newProject.startDate} onChange={e => setNewProject({...newProject, startDate: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-3 py-3 text-xs outline-none" />
                </div>
                <div>
                   <label className="block text-xs font-bold text-slate-500 mb-2">截稿时间</label>
                   <input type="datetime-local" value={newProject.deadline} onChange={e => setNewProject({...newProject, deadline: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-3 py-3 text-xs outline-none" />
                </div>
              </div>
              <button onClick={handleSaveProject} className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl shadow-xl active:scale-95 transition-all mt-4">{editingProjectId ? '保存修改' : '创建任务'}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode, PlanningSession } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [planningMode, setPlanningMode] = useState<'selection' | 'j-type' | 'p-type'>('selection');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>('');
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // WeChat User State
  const [wechatUser, setWechatUser] = useState<{nickname: string, avatar?: string} | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', 
    description: '',
    startDate: '',
    deadline: ''
  });

  // Initialization: Load or Create IDs
  useEffect(() => {
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }
  }, []);

  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      return;
    }

    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
  }, [currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;
    if (searchId === myArtistId) {
       setConnectedArtistId(searchId);
       localStorage.setItem('artflow_connected_artist_id', searchId);
       return;
    }
    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    if (targetProjects) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接（假设其存在）？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  const handleWeChatLogin = () => {
    alert("微信登录接口已预留。");
    setWechatUser({ nickname: "微信用户", avatar: "" });
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;

    if (editingProjectId) {
      setProjects(projects.map(p => 
        p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
        } : p
      ));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || '无具体描述',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }

    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({
      clientName: project.clientName,
      targetClientId: project.targetClientId,
      description: project.description,
      startDate: project.startDate,
      deadline: project.deadline
    });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  /**
   * 删除工单逻辑
   */
  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;

    // 弹出确认框防止误删
    if(confirm('确定要删除这个排单工单吗？删除后该项目的排期进度和辅助规划数据也将一并清除，不可恢复。')) {
        // 1. 从项目列表中过滤掉
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));

        // 2. 清理相关的辅助规划记录 (Sessions)
        const storedSessions = localStorage.getItem('artflow_planning_sessions');
        if (storedSessions) {
            try {
                const sessions = JSON.parse(storedSessions) as PlanningSession[];
                const updatedSessions = sessions.filter(s => s.projectId !== id);
                localStorage.setItem('artflow_planning_sessions', JSON.stringify(updatedSessions));
            } catch (error) {
                console.error("Cleanup error during deletion:", error);
            }
        }
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');
    const response = await analyzeSchedule(projects, bookings, aiQuery);
    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制到剪贴板`);
  };

  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') {
      handleDisconnect();
    }
  };

  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-800 flex flex-col">
      <header className="sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm">
        <div className="flex justify-between items-center mb-3 md:mb-0">
          <div className="flex items-center gap-2.5">
            <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-lg">
              <Paintbrush size={18} />
            </div>
            <h1 className="text-lg font-bold text-slate-800 tracking-tight hidden md:block">ArtFlow</h1>
          </div>
          <div className="flex items-center gap-3">
             {viewMode === 'artist' && (
                <button onClick={() => setShowAI(!showAI)} className={`p-2 rounded-full transition-colors ${showAI ? 'bg-indigo-100 text-indigo-600' : 'hover:bg-slate-100 text-slate-400'}`}>
                  <Sparkles size={20} />
                </button>
             )}
            <button onClick={toggleViewMode} className={`flex items-center gap-2 px-3 py-1.5 text-xs font-bold rounded-full transition-all border ${viewMode === 'artist' ? 'bg-slate-800 text-white border-slate-800' : 'bg-indigo-600 text-white border-indigo-600'}`}>
                {viewMode === 'artist' ? <><Paintbrush size={12}/> 画手模式</> : <><UserCircle2 size={14}/> 单主模式</>}
            </button>
          </div>
        </div>
        <div className="w-full">
           {viewMode === 'artist' ? (
             <div className="flex items-center justify-between bg-slate-50 rounded-lg p-1.5 border border-slate-100">
               <div className="flex items-center gap-2 flex-1 min-w-0">
                  {wechatUser ? (
                      <div className="flex items-center gap-1.5 pl-1.5 bg-emerald-100/50 py-1 px-2 rounded-md">
                          <MessageCircle size={12} className="text-emerald-600" />
                          <span className="text-xs font-bold text-emerald-800 truncate max-w-[80px]">{wechatUser.nickname}</span>
                      </div>
                  ) : (
                      <button onClick={handleWeChatLogin} className="flex items-center gap-1.5 bg-emerald-500 hover:bg-emerald-600 text-white px-3 py-1.5 rounded-lg transition-all shadow-sm active:scale-95">
                         <span className="text-[10px] font-bold">微信登录</span>
                      </button>
                  )}
                  <div className="flex items-center gap-1 min-w-0 flex-1 justify-end mr-2">
                     <span className="text-[10px] text-slate-400 font-medium whitespace-nowrap">ID</span>
                     <span className="text-xs text-slate-800 font-bold font-mono truncate">{myArtistId}</span>
                  </div>
               </div>
               <button onClick={() => copyText(myArtistId, 'Artist ID')} className="p-1.5 bg-white shadow-sm border border-slate-100 rounded-md text-slate-400 hover:text-indigo-600">
                 <Copy size={14} />
               </button>
             </div>
           ) : (
             <div className="flex gap-2">
               {!connectedArtistId ? (
                 <>
                  <div className="relative flex-1">
                    <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input type="text" value={searchId} onChange={(e) => setSearchId(e.target.value)} placeholder="搜索画手 ID (如: ART-1234)" className="w-full bg-slate-100 border-none rounded-lg pl-9 pr-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" />
                  </div>
                  <button onClick={handleSearchArtist} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-xs font-bold whitespace-nowrap">连接</button>
                 </>
               ) : (
                 <div className="flex items-center justify-between w-full bg-indigo-50 rounded-lg p-2 border border-indigo-100">
                    <span className="text-xs text-indigo-800 font-medium px-2 flex items-center gap-1">
                      <span className="opacity-60">已连接:</span> <span className="font-bold">{connectedArtistId}</span>
                    </span>
                    <button onClick={handleDisconnect} className="flex items-center gap-1 bg-white px-2 py-1 rounded text-[10px] font-bold text-slate-500 shadow-sm"><LogOut size={10} /> 退出</button>
                 </div>
               )}
             </div>
           )}
        </div>
      </header>

      <main className="flex-1 w-full max-w-lg mx-auto p-5 pb-32">
        {viewMode === 'client' && !connectedArtistId && (
           <div className="flex flex-col items-center justify-center mt-10 animate-fade-in">
              <div className="w-full bg-white rounded-2xl shadow-xl p-6 mb-8 border border-slate-100">
                <div className="flex items-center gap-3 mb-2">
                  <Fingerprint className="text-indigo-600" size={24} />
                  <h3 className="text-sm font-bold text-slate-500 uppercase">我的单主 ID</h3>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-3xl font-black text-slate-800">{myClientId}</span>
                  <button onClick={() => copyText(myClientId, '单主 ID')} className="bg-indigo-50 text-indigo-600 p-2 rounded-lg"><Copy size={18} /></button>
                </div>
                <p className="text-xs text-slate-400 mt-3">画手为您新建工单时填入此 ID，您连接后即可同步进度。</p>
              </div>
              <p className="text-slate-400 text-sm text-center">输入画手 ID 开始连接</p>
           </div>
        )}

        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg animate-fade-in">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm"><Sparkles size={14} className="text-indigo-500" /> 智能助理</h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400"><X size={16} /></button>
                </div>
                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">{isAiLoading ? "思考中..." : aiResponse || "你好！我是你的排单助手。"}</div>
                <div className="flex gap-2">
                  <input type="text" value={aiQuery} onChange={(e) => setAiQuery(e.target.value)} placeholder="下周还能接急单吗？" className="flex-1 text-sm rounded-lg border px-3 py-2 focus:ring-1 focus:ring-indigo-500 outline-none" onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()} />
                  <button onClick={handleAiAsk} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold">发送</button>
                </div>
              </div>
            )}

            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-4">
                <div className="flex flex-col gap-4">
                   <div className="flex justify-between items-end px-1">
                      <h2 className="text-xl font-bold text-slate-800">{viewMode === 'artist' ? '我的排单' : '我的订单'}</h2>
                      {viewMode === 'artist' && (
                        <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2"><Plus size={16} /> 新建</button>
                      )}
                   </div>
                   <div className="flex p-1 bg-slate-200/50 rounded-xl">
                      <button onClick={() => setProjectSubTab('active')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>进行中</button>
