        )}

        {(viewMode === 'artist' || connectedArtistId) && (
          <>
            {viewMode === 'artist' && showAI && (
              <div className="mb-6 bg-white border border-indigo-100 rounded-2xl p-4 shadow-lg animate-fade-in">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="font-bold text-indigo-900 flex items-center gap-2 text-sm"><Sparkles size={14} className="text-indigo-500" /> 智能助理</h3>
                  <button onClick={() => setShowAI(false)} className="text-slate-400"><X size={16} /></button>
                </div>
                <div className="bg-slate-50 rounded-xl p-3 min-h-[60px] mb-3 text-sm text-slate-600 leading-relaxed">{isAiLoading ? "思考中..." : aiResponse || "你好！我是你的排单助手。"}</div>
                <div className="flex gap-2">
                  <input type="text" value={aiQuery} onChange={(e) => setAiQuery(e.target.value)} placeholder="下周还能接急单吗？" className="flex-1 text-sm rounded-lg border px-3 py-2 focus:ring-1 focus:ring-indigo-500 outline-none" onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()} />
                  <button onClick={handleAiAsk} className="bg-indigo-600 text-white px-4 py-2 rounded-lg text-sm font-bold">发送</button>
                </div>
              </div>
            )}

            {activeTab === 'projects' && (
              <div className="animate-fade-in space-y-4">
                <div className="flex flex-col gap-4">
                   <div className="flex justify-between items-end px-1">
                      <h2 className="text-xl font-bold text-slate-800">{viewMode === 'artist' ? '我的排单' : '我的订单'}</h2>
                      {viewMode === 'artist' && (
                        <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2"><Plus size={16} /> 新建</button>
                      )}
                   </div>
                   <div className="flex p-1 bg-slate-200/50 rounded-xl">
                      <button onClick={() => setProjectSubTab('active')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>进行中</button>
                      <button onClick={() => setProjectSubTab('completed')} className={`flex-1 flex items-center justify-center gap-2 py-2.5 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>已完成</button>
                   </div>
                </div>
                <div className="space-y-3 min-h-[200px]">
                  {displayedProjects.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-16 text-slate-400 bg-white rounded-2xl border border-dashed">暂无相关记录</div>
                  ) : (
                    displayedProjects
                      .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                      .map(project => (
                        <ProjectCard 
                          key={project.id} 
                          project={project} 
                          onComplete={handleCompleteProject}
                          onDelete={handleDeleteProject}
                          onEdit={handleEditProject}
                          readOnly={viewMode === 'client'}
                        />
