import React, { useState, useEffect, useMemo, useRef } from 'react';
import { ArrowLeft, Plus, GripVertical, X, Check, ArrowUp, Link, Hourglass, ChevronRight, ChevronLeft, Rocket, Trash2, Sparkles, Zap, Palette, Eye, Layout, Timer, Play, Pause, RefreshCw, Calendar, Edit3, Save, ChevronUp, ChevronDown } from 'lucide-react';
import { PlannerStage, Project, BookingSlot, PlanningSession } from '../types';
import { formatDate } from '../utils';

interface PTypePlannerProps {
  onBack: () => void;
  projects?: Project[];
  bookings?: BookingSlot[];
  onUpdateBookings?: (bookings: BookingSlot[]) => void;
}

const PTypePlanner: React.FC<PTypePlannerProps> = ({ onBack, projects = [], bookings = [] }) => {
  const [mode, setMode] = useState<'dashboard' | 'planner'>('dashboard');
  const [sessions, setSessions] = useState<PlanningSession[]>([]);
  const [viewingSession, setViewingSession] = useState<PlanningSession | null>(null);
  const [planningStep, setPlanningStep] = useState<'setup' | 'off-days' | 'time-entry' | 'finished' | 'commitment' | 'timer'>('setup');

  const [stages, setStages] = useState<PlannerStage[]>([
    { id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整至终版' }
  ]);

  const [offDayViewDate, setOffDayViewDate] = useState(new Date());
  const [isAdding, setIsAdding] = useState(false);
  const [newStageTitle, setNewStageTitle] = useState('');
  const [editingStageId, setEditingStageId] = useState<string | null>(null);
  const [editingStageTitle, setEditingStageTitle] = useState('');
  const [showSyncInput, setShowSyncInput] = useState(false);
  const [syncId, setSyncId] = useState('');
  const [syncedProject, setSyncedProject] = useState<Project | null>(null);
  const [activeTimeIndex, setActiveTimeIndex] = useState<number>(-1);
  const [currentInputTime, setCurrentInputTime] = useState('');
  const [estimates, setEstimates] = useState<Record<string, string>>({});
  const [sessionBlockedDates, setSessionBlockedDates] = useState<string[]>([]);
  const [timeLeft, setTimeLeft] = useState(600);
  const [isTimerActive, setIsTimerActive] = useState(false);
  const [selectedCommitment, setSelectedCommitment] = useState<{id: number, title: string, icon: React.ReactNode, color: string} | null>(null);
  const isCancellingRef = useRef(false);

  useEffect(() => {
    const storedSessions = localStorage.getItem('artflow_planning_sessions');
    if (storedSessions) setSessions(JSON.parse(storedSessions));
  }, []);

  const persistSessions = (newSessions: PlanningSession[]) => {
      localStorage.setItem('artflow_planning_sessions', JSON.stringify(newSessions));
      setSessions(newSessions);
  };

  useEffect(() => {
    let interval: number | null = null;
    if (isTimerActive && timeLeft > 0) {
      interval = window.setInterval(() => setTimeLeft((p) => p - 1), 1000);
    } else if (timeLeft === 0) {
      setIsTimerActive(false);
    }
    return () => { if (interval) clearInterval(interval); };
  }, [isTimerActive, timeLeft]);

  const getYYYYMMDD = (date: Date) => {
    return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
  };

  const totalAvailableDays = useMemo(() => {
    if (!syncedProject) return 30; 
    const start = new Date(syncedProject.startDate);
    const end = new Date(syncedProject.deadline);
    let count = 0; let curr = new Date(start);
    while (curr <= end) {
      const dStr = getYYYYMMDD(curr);
      const isBlocked = bookings?.some(b => b.date === dStr && (b.status === 'blocked' || b.status === 'booked')) || sessionBlockedDates.includes(dStr);
      if (!isBlocked) count++;
      curr.setDate(curr.getDate() + 1);
    }
    return count;
  }, [syncedProject, bookings, sessionBlockedDates]);

  const currentPlannedDays = (Object.values(estimates) as string[]).reduce((a, b) => a + Number(b), 0);
  const remainingDays = totalAvailableDays - currentPlannedDays;

  const handleCreateNew = () => {
      setMode('planner'); setPlanningStep('setup'); setSyncedProject(null);
      setEstimates({}); setSessionBlockedDates([]);
      setStages([{ id: '1', title: '草稿' }, { id: '2', title: '线稿' }, { id: '3', title: '上色' }, { id: '4', title: '细节调整' }]);
  };

  const handleFinalize = () => {
      const newSession: PlanningSession = {
          id: Date.now().toString(), projectId: syncedProject?.id,
          clientName: syncedProject ? syncedProject.clientName : '未命名规划',
          stages, estimates, blockedDates: sessionBlockedDates,
          createdAt: new Date().toISOString(), lastUpdated: new Date().toISOString(), completedDays: [],
      };
      persistSessions([newSession, ...sessions]);
      setMode('dashboard'); setPlanningStep('setup');
  };

  if (mode === 'dashboard') {
    return (
      <div className="animate-fade-in space-y-8">
        <div className="flex justify-between items-end">
          <div>
            <h2 className="text-3xl font-black text-slate-800 tracking-tight">辅助规划</h2>
            <p className="text-slate-400 font-medium">克服拖延，从微小的第一步开始</p>
          </div>
        </div>

        {viewingSession ? (
          <div className="bg-white rounded-[3rem] p-10 shadow-xl border border-slate-100 animate-slide-up">
            <button onClick={() => setViewingSession(null)} className="flex items-center text-indigo-600 mb-8 text-sm font-black hover:translate-x-1 transition-transform">
              <ArrowLeft size={16} className="mr-2" /> 返回规划列表
            </button>
            <div className="flex flex-col md:flex-row justify-between gap-8">
              <div className="flex-1">
                <h3 className="text-4xl font-black text-slate-900 mb-2">{viewingSession.clientName}</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mb-10">规划时间: {formatDate(viewingSession.createdAt)}</p>
                <div className="space-y-4">
                  {viewingSession.stages.map(s => (
                    <div key={s.id} className="flex justify-between items-center p-6 bg-slate-50 rounded-3xl">
                      <span className="font-black text-slate-700">{s.title}</span>
                      <span className="bg-white px-4 py-2 rounded-xl font-black text-indigo-600 shadow-sm">{viewingSession.estimates[s.id]} 天</span>
                    </div>
                  ))}
                </div>
              </div>
              <div className="w-full md:w-80 bg-slate-900 rounded-[2.5rem] p-8 text-white">
                <h4 className="font-black text-lg mb-4">规划概览</h4>
                <div className="space-y-4 opacity-70">
                   <div className="flex justify-between text-sm"><span>阶段总数</span><span>{viewingSession.stages.length}</span></div>
                   <div className="flex justify-between text-sm"><span>总预算工期</span><span>{(Object.values(viewingSession.estimates) as string[]).reduce((a,b)=>a+Number(b),0)} 天</span></div>
                   <div className="flex justify-between text-sm"><span>休息日设置</span><span>{viewingSession.blockedDates.length} 天</span></div>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
            <button onClick={handleCreateNew} className="xl:col-span-1 bg-white border-4 border-dashed border-slate-200 rounded-[3rem] p-12 flex flex-col items-center justify-center gap-6 hover:border-indigo-400 hover:bg-indigo-50/30 transition-all group">
               <div className="bg-slate-100 p-6 rounded-[2rem] text-slate-400 group-hover:bg-indigo-600 group-hover:text-white transition-all"><Plus size={48}/></div>
               <div className="text-center">
                 <h4 className="text-xl font-black text-slate-800">创建新规划</h4>
                 <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">Start Brainstorming</p>
               </div>
            </button>

            <div className="xl:col-span-2 space-y-4">
              <h5 className="text-xs font-black text-slate-400 uppercase tracking-widest ml-2">已保存的规划 ({sessions.length})</h5>
              {sessions.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {sessions.map(s => (
                    <div key={s.id} onClick={() => setViewingSession(s)} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all cursor-pointer group flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-slate-50 flex items-center justify-center text-slate-400 group-hover:bg-indigo-50 group-hover:text-indigo-600"><Layout size={24}/></div>
                        <div>
                          <h4 className="font-black text-slate-800 group-hover:text-indigo-600 transition-colors">{s.clientName}</h4>
                          <p className="text-[10px] font-bold text-slate-400 uppercase">{s.stages.length} 阶段 · {formatDate(s.createdAt)}</p>
                        </div>
                      </div>
                      <button onClick={(e) => { e.stopPropagation(); if(confirm('删除规划？')) persistSessions(sessions.filter(ses => ses.id !== s.id)); }} className="p-2 text-slate-200 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={18}/></button>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="h-48 flex items-center justify-center text-slate-300 font-bold border-2 border-dashed border-slate-100 rounded-[2.5rem]">暂无记录</div>
              )}
            </div>
          </div>
        )}
      </div>
    );
  }

  // Multi-step planner layout
  return (
    <div className="max-w-4xl mx-auto pb-32 animate-fade-in">
       <button onClick={() => setMode('dashboard')} className="flex items-center text-slate-400 mb-8 font-black hover:text-slate-900 transition-colors"><ArrowLeft size={18} className="mr-2" /> 返回规划大厅</button>

       <div className="bg-white rounded-[3rem] shadow-2xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
          {/* Planner Header */}
          <div className="bg-slate-900 p-10 text-white relative">
             <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
             <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
                <div>
                   <h2 className="text-3xl font-black tracking-tight">{syncedProject ? syncedProject.clientName : '自定义创作节奏'}</h2>
                   <p className="text-slate-400 font-medium text-sm mt-1">{planningStep === 'setup' ? '定义你的绘画阶段' : planningStep === 'off-days' ? '标记你的休息日' : '分配每个阶段的预估工期'}</p>
                </div>
                {planningStep === 'setup' && !syncedProject && (
                   <button onClick={() => setShowSyncInput(!showSyncInput)} className="bg-white/10 hover:bg-white/20 px-6 py-3 rounded-2xl text-xs font-black flex items-center gap-2 transition-all">
                      <Link size={16}/> {showSyncInput ? '取消关联' : '关联现有排单项目'}
                   </button>
                )}
             </div>
             {showSyncInput && (
                <div className="mt-6 flex gap-3 animate-fade-in">
                   <input autoFocus type="text" value={syncId} onChange={(e) => setSyncId(e.target.value)} placeholder="输入排单 ID (例如: 17123456789)" className="flex-1 bg-white/10 border border-white/20 rounded-xl px-5 py-3 text-sm outline-none focus:bg-white/20 transition-all" />
                   <button onClick={() => { const p = projects.find(pr => pr.id === syncId); if(p){setSyncedProject(p); setShowSyncInput(false);}else{alert('未找到 ID');} }} className="bg-indigo-500 hover:bg-indigo-600 px-8 py-3 rounded-xl text-sm font-black transition-all">同步</button>
                </div>
             )}
          </div>

          <div className="p-8 md:p-12">
            {planningStep === 'setup' && (
              <div className="space-y-4">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                   {stages.map((s, idx) => (
                     <div key={s.id} className="bg-slate-50 p-6 rounded-[2rem] flex items-center justify-between group border-2 border-transparent hover:border-indigo-100 transition-all">
                        <div className="flex items-center gap-4">
                           <span className="text-xs font-black text-slate-300">0{idx+1}</span>
                           <span className="font-black text-slate-700">{s.title}</span>
                        </div>
                        <button onClick={() => setStages(stages.filter(st => st.id !== s.id))} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"><X size={18}/></button>
                     </div>
                   ))}
                   <button onClick={() => { const t = prompt('请输入阶段名称'); if(t) setStages([...stages, {id: Date.now().toString(), title: t}]); }} className="border-2 border-dashed border-slate-200 rounded-[2rem] p-6 flex items-center justify-center gap-3 text-slate-400 hover:bg-indigo-50/50 hover:border-indigo-200 transition-all font-black">
                      <Plus size={20}/> 添加新阶段
                   </button>
                 </div>
                 <button onClick={() => setPlanningStep('off-days')} className="w-full mt-10 bg-slate-900 text-white py-5 rounded-[2rem] font-black text-lg hover:bg-slate-800 transition-all shadow-xl shadow-slate-100">确认阶段，去设置休息日</button>
              </div>
            )}

            {planningStep === 'off-days' && (
              <div className="space-y-8">
                 <div className="flex justify-between items-center">
                    <h4 className="text-xl font-black text-slate-800">{offDayViewDate.toLocaleString('zh-CN', {month:'long', year:'numeric'})}</h4>
                    <div className="flex gap-2">
                       <button onClick={() => setOffDayViewDate(new Date(offDayViewDate.getFullYear(), offDayViewDate.getMonth()-1, 1))} className="p-3 bg-slate-100 rounded-xl hover:bg-slate-200 transition-colors"><ChevronLeft size={20}/></button>
                       <button onClick={() => setOffDayViewDate(new Date(offDayViewDate.getFullYear(), offDayViewDate.getMonth()+1, 1))} className="p-3 bg-slate-100 rounded-xl hover:bg-slate-200 transition-colors"><ChevronRight size={20}/></button>
                    </div>
                 </div>
                 <div className="grid grid-cols-7 gap-3">
                    {['日','一','二','三','四','五','六'].map(d => <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase">{d}</div>)}
                    {Array.from({length: new Date(offDayViewDate.getFullYear(), offDayViewDate.getMonth(), 1).getDay()}).map((_, i) => <div key={`e-${i}`} />)}
                    {Array.from({length: new Date(offDayViewDate.getFullYear(), offDayViewDate.getMonth()+1, 0).getDate()}).map((_, i) => {
                       const d = new Date(offDayViewDate.getFullYear(), offDayViewDate.getMonth(), i+1);
                       const dStr = getYYYYMMDD(d);
                       const isSel = sessionBlockedDates.includes(dStr);
                       return <div key={dStr} onClick={() => setSessionBlockedDates(isSel ? sessionBlockedDates.filter(x=>x!==dStr) : [...sessionBlockedDates, dStr])} className={`aspect-square rounded-2xl flex items-center justify-center font-black cursor-pointer transition-all border-2 ${isSel ? 'bg-rose-500 border-rose-600 text-white shadow-lg shadow-rose-100' : 'bg-white border-slate-50 text-slate-700 hover:border-indigo-100 hover:bg-slate-50'}`}>{i+1}</div>
                    })}
                 </div>
                 <button onClick={() => { setPlanningStep('time-entry'); setActiveTimeIndex(0); }} className="w-full bg-slate-900 text-white py-5 rounded-[2rem] font-black text-lg shadow-xl hover:bg-slate-800 transition-all">设置完毕，分配时间</button>
              </div>
            )}

            {planningStep === 'time-entry' && (
              <div className="space-y-10">
                 <div className="bg-indigo-50 p-8 rounded-[2.5rem] border border-indigo-100 flex items-center justify-between">
                    <div>
                      <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">工期预算余额</span>
                      <div className="flex items-baseline gap-2">
                        <span className={`text-5xl font-black ${remainingDays < 0 ? 'text-rose-500 animate-pulse' : 'text-indigo-600'}`}>{remainingDays}</span>
                        <span className="text-sm font-bold text-indigo-300">/ {totalAvailableDays} 天</span>
                      </div>
                    </div>
                    <Hourglass size={48} className="text-indigo-200" />
                 </div>

                 <div className="space-y-6">
                    {stages.map((s, idx) => (
                       <div key={s.id} className={`p-8 rounded-[2.5rem] border-2 transition-all ${activeTimeIndex === idx ? 'bg-white border-indigo-500 shadow-2xl scale-105' : 'bg-slate-50 border-transparent opacity-50'}`}>
                          <div className="flex justify-between items-center mb-4">
                             <span className="font-black text-slate-800 text-xl">{s.title}</span>
                             {estimates[s.id] && activeTimeIndex !== idx && <span className="bg-indigo-600 text-white px-4 py-1.5 rounded-full text-xs font-black">{estimates[s.id]} 天</span>}
                          </div>
                          {activeTimeIndex === idx && (
                             <div className="flex items-center gap-4 animate-fade-in">
                                <input autoFocus type="number" value={currentInputTime} onChange={e => setCurrentInputTime(e.target.value)} placeholder="输入天数" className="flex-1 bg-slate-100 rounded-2xl px-6 py-4 font-black text-indigo-600 outline-none" onKeyDown={e => e.key === 'Enter' && (setEstimates({...estimates, [s.id]: currentInputTime}), setCurrentInputTime(''), setActiveTimeIndex(idx+1 < stages.length ? idx+1 : -1))} />
                                <button onClick={() => { setEstimates({...estimates, [s.id]: currentInputTime}); setCurrentInputTime(''); if(idx+1 < stages.length) setActiveTimeIndex(idx+1); else {setActiveTimeIndex(-1); setPlanningStep('finished');} }} className="bg-slate-900 text-white p-4 rounded-2xl hover:bg-slate-800 transition-all"><ArrowUp size={24}/></button>
                             </div>
                          )}
                       </div>
                    ))}
                 </div>
              </div>
            )}

            {planningStep === 'finished' && (
              <div className="text-center py-10 animate-fade-in">
                 <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-6 shadow-xl shadow-emerald-50"><Check size={48} strokeWidth={3}/></div>
                 <h3 className="text-3xl font-black text-slate-900 mb-2">规划已完美就绪</h3>
                 <p className="text-slate-400 font-medium mb-12">每一个阶段都是一次新的灵感爆发</p>
                 <button onClick={handleFinalize} className="bg-slate-900 text-white px-12 py-5 rounded-[2rem] font-black text-xl hover:bg-slate-800 shadow-2xl shadow-slate-200 transition-all flex items-center gap-3 mx-auto">
                    <Rocket size={24}/> 开启第一步
                 </button>
              </div>
            )}
          </div>
       </div>
    </div>
  );
};

