                  <Lock size={14}/> {getSlot(selectedDate)?.status === 'blocked' ? '取消休假标记' : '标记为休息/占位'}
                </button>
                <button onClick={() => setSelectedDate(null)} className="p-3 bg-slate-50 text-slate-400 hover:text-slate-600 rounded-2xl transition-all">
                  <X size={20}/>
