      // Just select the date to show achievement list
    } else {
      const slot = getSlot(date);
      if (slot?.status === 'blocked' || (slot?.status === 'booked' && !isMySlot(slot.clientId))) return;
      setBookingNote('');
    }
  };

  const toggleBlockedStatus = (date: string) => {
    const newBookings = [...bookings];
    const index = newBookings.findIndex(b => b.date === date);
    if (index >= 0) {
      if (newBookings[index].status === 'blocked') {
        newBookings.splice(index, 1);
      } else if(confirm("该日期已有预约，确定要清除吗？")) {
           newBookings.splice(index, 1);
      }
    } else {
      newBookings.push({ date, status: 'blocked' });
    }
    onUpdateBookings(newBookings);
  };

  const handleClientBook = () => {
    if (!selectedDate) return;
    const newBookings = [...bookings, {
      date: selectedDate,
      status: 'booked' as const,
      bookedBy: currentClientName || 'Client',
      clientId: currentClientId,
      note: bookingNote
    }];
    onUpdateBookings(newBookings);
    setSelectedDate(null);
    alert('预约申请已提交！');
  };

  const handleAddAchievement = () => {
    if (!selectedDate || !newAchievement.trim()) return;
    const item: Achievement = {
      id: Date.now().toString(),
      text: newAchievement.trim(),
      date: selectedDate
    };
    onUpdateAchievements([...achievements, item]);
    setNewAchievement('');
  };

  const handleDeleteAchievement = (id: string) => {
    onUpdateAchievements(achievements.filter(a => a.id !== id));
  };

  const changeMonth = (offset: number) => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1));
  };

  const dayAchievements = achievements.filter(a => a.date === selectedDate);

  return (
    <div className="bg-white">
      <div className="p-8 border-b border-slate-100 flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
           <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-2">
            排期日历
          </h2>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">
            {viewDate.toLocaleString('zh-CN', { year: 'numeric', month: 'long' })}
          </p>
        </div>
        <div className="flex gap-2 bg-slate-50 p-1 rounded-2xl">
          <button onClick={() => changeMonth(-1)} className="p-3 hover:bg-white hover:shadow-sm rounded-xl transition-all text-slate-400 hover:text-indigo-600"><ChevronLeft size={20} /></button>
          <button onClick={() => setViewDate(new Date())} className="px-4 text-xs font-black text-slate-500 hover:text-indigo-600">今天</button>
          <button onClick={() => changeMonth(1)} className="p-3 hover:bg-white hover:shadow-sm rounded-xl transition-all text-slate-400 hover:text-indigo-600"><ChevronRight size={20} /></button>
        </div>
      </div>

      <div className="p-4 md:p-8">
        <div className="grid grid-cols-7 gap-px bg-slate-100 border border-slate-100 rounded-2xl overflow-hidden">
          {['周日', '周一', '周二', '周三', '周四', '周五', '周六'].map(d => (
              <div key={d} className="bg-slate-50 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest py-4 border-b border-slate-100">{d}</div>
          ))}
          {days.map((dateObj, idx) => {
            if (!dateObj) return <div key={`empty-${idx}`} className="bg-slate-50/50 min-h-[100px] md:min-h-[140px]"></div>;

            const date = getLocalYYYYMMDD(dateObj);
            const slot = getSlot(date);
            const projectsOnDay = getProjectsOnDate(date);
            const status = slot?.status;
            const isToday = getLocalYYYYMMDD(new Date()) === date;
            const isMine = isMySlot(slot?.clientId, slot?.bookedBy);
            const hasAchievements = achievements.some(a => a.date === date);

            let dayContent = null;
            let bgClass = 'bg-white hover:bg-slate-50 transition-colors';

            if (status === 'blocked') {
              bgClass = 'bg-slate-50 text-slate-300';
              dayContent = <Lock size={14} className="opacity-20 absolute bottom-3 right-3" />;
            } else if (status === 'booked') {
              if (mode === 'client' && !isMine) {
                bgClass = 'bg-slate-100 text-slate-300 cursor-not-allowed';
              } else {
                bgClass = 'bg-indigo-600 text-white shadow-inner';
                dayContent = <Check size={18} strokeWidth={3} className="absolute bottom-3 right-3 text-white/50" />;
              }
            }

            if (selectedDate === date) bgClass = 'ring-4 ring-indigo-500 ring-inset bg-indigo-50';

            return (
              <div 
                key={date}
                onClick={() => handleDayClick(date)}
                className={`min-h-[100px] md:min-h-[140px] p-3 flex flex-col relative group cursor-pointer ${bgClass}`}
              >
                <div className="flex justify-between items-start">
                  <span className={`text-sm font-black transition-all ${isToday ? 'bg-indigo-600 text-white w-7 h-7 flex items-center justify-center rounded-lg shadow-lg shadow-indigo-100' : 'text-slate-400 group-hover:text-slate-900'}`}>
                    {dateObj.getDate()}
                  </span>
                  {hasAchievements && mode === 'artist' && (
                    <div className="bg-emerald-500 text-white p-1 rounded-full shadow-sm">
                      <Sparkles size={10} />
                    </div>
                  )}
                </div>

                {dayContent}

                <div className="mt-auto space-y-1.5 w-full">
                   {projectsOnDay.map((p) => (
                     <div key={p.id} className={`h-1.5 md:h-2 w-full rounded-full ${getProjectLineColor(p.startDate, p.deadline)} transition-all group-hover:opacity-100`} title={p.clientName} />
                   ))}
                </div>
              </div>
            );
          })}
        </div>

        {/* 统计概览面板 */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-8">
            <div className="lg:col-span-2 bg-indigo-50 border border-indigo-100 p-8 rounded-[2.5rem]">
              <h4 className="font-black text-indigo-900 mb-4 flex items-center gap-2"><Calendar size={20}/> 排期概览</h4>
              <p className="text-sm text-indigo-700/70 font-medium leading-relaxed">
                日历中的彩色横线条代表正在进行中的工单。颜色根据截稿日期的紧急程度变化：<br/>
                <span className="inline-flex items-center gap-1.5 mt-2 shadow-sm bg-white px-3 py-1 rounded-full mr-4"><span className="w-2.5 h-2.5 rounded-full bg-rose-500"></span> <span className="text-[11px] font-bold">2天内截稿</span></span>
                <span className="inline-flex items-center gap-1.5 shadow-sm bg-white px-3 py-1 rounded-full mr-4"><span className="w-2.5 h-2.5 rounded-full bg-orange-500"></span> <span className="text-[11px] font-bold">5天内截稿</span></span>
                <span className="inline-flex items-center gap-1.5 shadow-sm bg-white px-3 py-1 rounded-full"><span className="w-2.5 h-2.5 rounded-full bg-emerald-500"></span> <span className="text-[11px] font-bold">时间充裕</span></span>
              </p>
            </div>
            <div className="bg-white border border-slate-100 p-8 rounded-[2.5rem] flex flex-col justify-center text-center shadow-sm">
              <span className="text-4xl font-black text-slate-800">{projectsInViewMonth}</span>
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">本月工单总数</span>
            </div>
        </div>

        {/* Artist View: Achievements / Done List Panel */}
        {mode === 'artist' && selectedDate && (
          <div className="mt-8 animate-slide-up bg-white p-8 rounded-[3rem] border border-slate-100 shadow-xl shadow-slate-100/50">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
              <div className="flex items-center gap-4">
                <div className="bg-emerald-100 text-emerald-600 p-3 rounded-2xl">
                  <Sparkles size={24}/>
                </div>
                <div>
                  <h4 className="text-xl font-black text-slate-800">今日成就 - {selectedDate}</h4>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-0.5">记录下今天的每一分努力</p>
                </div>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => toggleBlockedStatus(selectedDate)}
                  className={`px-6 py-3 rounded-2xl text-xs font-black transition-all flex items-center gap-2 ${getSlot(selectedDate)?.status === 'blocked' ? 'bg-rose-500 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}
                >
                  <Lock size={14}/> {getSlot(selectedDate)?.status === 'blocked' ? '取消休假标记' : '标记为休息/占位'}
                </button>
                <button onClick={() => setSelectedDate(null)} className="p-3 bg-slate-50 text-slate-400 hover:text-slate-600 rounded-2xl transition-all">
                  <X size={20}/>
                </button>
              </div>
            </div>

            <div className="space-y-4">
              {/* Done List */}
              <div className="space-y-3">
                {dayAchievements.length > 0 ? (
                  dayAchievements.map(ach => (
                    <div key={ach.id} className="flex items-center justify-between p-4 bg-emerald-50/50 border border-emerald-100 rounded-2xl group animate-fade-in">
                      <div className="flex items-center gap-3">
                        <div className="text-emerald-500">
                          <CheckCircle2 size={18}/>
                        </div>
                        <span className="font-bold text-slate-700">{ach.text}</span>
                      </div>
                      <button onClick={() => handleDeleteAchievement(ach.id)} className="text-slate-300 hover:text-rose-500 p-2 opacity-0 group-hover:opacity-100 transition-all">
                        <Trash2 size={16}/>
                      </button>
                    </div>
                  ))
                ) : (
                  <div className="py-12 border-2 border-dashed border-slate-100 rounded-[2rem] flex flex-col items-center justify-center text-slate-300">
                    <ListTodo size={32} className="mb-2 opacity-20"/>
                    <p className="text-sm font-bold">还没有记录今天的成就哦</p>
                  </div>
                )}
              </div>

              {/* Add Input */}
              <div className="flex gap-3 pt-6 border-t border-slate-50">
                <input 
                  type="text" 
                  value={newAchievement}
                  onChange={e => setNewAchievement(e.target.value)}
                  onKeyDown={e => e.key === 'Enter' && handleAddAchievement()}
                  placeholder="记下一笔今日进展，哪怕只是微小的..." 
                  className="flex-1 bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 text-sm font-medium outline-none focus:ring-2 focus:ring-emerald-500 transition-all"
                />
                <button 
                  onClick={handleAddAchievement}
                  disabled={!newAchievement.trim()}
                  className="bg-emerald-600 text-white px-8 py-4 rounded-2xl font-black text-sm shadow-lg shadow-emerald-100 flex items-center gap-2 hover:bg-emerald-700 active:scale-95 transition-all disabled:opacity-50 disabled:pointer-events-none"
                >
                  <Plus size={18}/> 记录
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Client View: Booking Request Panel */}
        {mode === 'client' && selectedDate && (
          <div className="mt-8 animate-slide-up bg-white p-6 rounded-[2rem] border border-indigo-100 shadow-xl shadow-indigo-50/50 flex flex-col md:flex-row md:items-center gap-6">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 text-white p-3 rounded-2xl shadow-lg shadow-indigo-100"><Calendar size={24}/></div>
              <div>
                <h4 className="font-black text-slate-800">申请预约: {selectedDate}</h4>
                <p className="text-xs text-slate-400 font-bold">请填写备注说明您的具体需求</p>
              </div>
            </div>
            <div className="flex-1 flex gap-3">
              <input 
                type="text" 
                placeholder="例如：想要约一张半身彩色，已有构图思路..."
                value={bookingNote}
                onChange={(e) => setBookingNote(e.target.value)}
                className="flex-1 bg-slate-50 border border-slate-100 rounded-2xl px-6 py-4 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              />
              <button 
                onClick={handleClientBook}
                className="bg-indigo-600 text-white px-8 py-4 rounded-2xl text-sm font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 active:scale-95 transition-all"
              >
                立即提交
              </button>
            </div>
            <button onClick={() => setSelectedDate(null)} className="text-slate-400 hover:text-slate-600 p-2"><X size={20}/></button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ScheduleBoard;

import React, { useState, useEffect, useMemo } from 'react';
import { Project, BookingSlot, ViewMode, PlanningSession, Achievement } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Calendar, // Added missing Calendar icon
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle,
  Coins,
  ChevronRight,
  History
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [planningMode, setPlanningMode] = useState<'selection' | 'j-type' | 'p-type'>('selection');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>('');
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // WeChat User State
  const [wechatUser, setWechatUser] = useState<{nickname: string, avatar?: string} | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);
  const [achievements, setAchievements] = useState<Achievement[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', 
    description: '',
    amount: '',
    startDate: '',
    deadline: ''
  });

  // Initialization
  useEffect(() => {
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }
  }, []);

  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      setAchievements([]);
      return;
    }
    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);
    const storedAchievements = localStorage.getItem(`artflow_data_${currentDataId}_achievements`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
    setAchievements(storedAchievements ? JSON.parse(storedAchievements) : []);
  }, [currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_achievements`, JSON.stringify(achievements));
    }
  }, [achievements, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;
    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    if (targetProjects || searchId === myArtistId) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;
    if (editingProjectId) {
      setProjects(projects.map(p => p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          amount: newProject.amount || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
      } : p));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || '无具体描述',
        amount: newProject.amount || '',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }
    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({ ...project });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', amount: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;
    if(confirm('确定要删除这个排单工单吗？相关规划数据也将一并清除。')) {
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');
    const response = await analyzeSchedule(projects, bookings, aiQuery);
    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制`);
  };

  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') handleDisconnect();
  };

  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col md:flex-row text-slate-800">

      {/* PC Side Navigation */}
      <aside className="hidden md:flex flex-col w-64 bg-white border-r border-slate-200 sticky top-0 h-screen z-40">
        <div className="p-6 flex items-center gap-3">
          <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-lg shadow-indigo-100">
            <Paintbrush size={24} />
          </div>
          <h1 className="text-xl font-black text-slate-900 tracking-tight">ArtFlow</h1>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Layout size={20} /> 排单工单
          </button>
          <button onClick={() => setActiveTab('schedule')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <CalendarDays size={20} /> 排期日历
          </button>
          {viewMode === 'artist' && (
            <button onClick={() => setActiveTab('planning')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <BrainCircuit size={20} /> 辅助规划
            </button>
          )}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className="bg-slate-50 rounded-2xl p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-black text-slate-400 uppercase">当前角色</span>
              <button onClick={toggleViewMode} className="text-[10px] font-black text-indigo-600 hover:underline">切换</button>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-indigo-100 flex items-center justify-center text-indigo-600">
                {viewMode === 'artist' ? <Paintbrush size={16} /> : <UserCircle2 size={16} />}
              </div>
              <div>
                <p className="text-xs font-bold">{viewMode === 'artist' ? '画手' : '单主'}</p>
                <p className="text-[10px] text-slate-400 font-mono truncate max-w-[120px]">{viewMode === 'artist' ? myArtistId : (connectedArtistId || '未连接')}</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Top Header */}
      <header className="md:hidden sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm flex justify-between items-center">
        <div className="flex items-center gap-2">
          <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-1.5 rounded-lg">
            <Paintbrush size={16} />
          </div>
          <h1 className="text-base font-bold text-slate-800">ArtFlow</h1>
        </div>
        <button onClick={toggleViewMode} className="text-xs font-black bg-slate-900 text-white px-3 py-1.5 rounded-full">
          {viewMode === 'artist' ? '画手' : '单主'}
        </button>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 min-h-screen overflow-x-hidden">
        {/* PC Top Dashboard Bar */}
        <div className="hidden md:flex items-center justify-between px-8 py-4 bg-white border-b border-slate-100 sticky top-0 z-30">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 bg-slate-50 border border-slate-100 rounded-full px-4 py-1.5">
               <span className="text-[10px] font-bold text-slate-400 uppercase">My ID:</span>
               <span className="text-xs font-bold font-mono">{viewMode === 'artist' ? myArtistId : myClientId}</span>
               <button onClick={() => copyText(viewMode === 'artist' ? myArtistId : myClientId, 'ID')} className="text-slate-400 hover:text-indigo-600 ml-1"><Copy size={12}/></button>
            </div>
            {viewMode === 'client' && !connectedArtistId && (
              <div className="flex items-center gap-2">
                <input type="text" value={searchId} onChange={(e) => setSearchId(e.target.value)} placeholder="输入画手 ID" className="bg-slate-50 border border-slate-100 rounded-full px-4 py-1.5 text-xs outline-none focus:ring-1 focus:ring-indigo-500 w-48" />
                <button onClick={handleSearchArtist} className="bg-indigo-600 text-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-indigo-700">连接</button>
              </div>
            )}
            {connectedArtistId && (
              <div className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 px-4 py-1.5 rounded-full border border-indigo-100">
                <span>已连接: {connectedArtistId}</span>
                <button onClick={handleDisconnect} className="hover:text-rose-600"><X size={14}/></button>
              </div>
            )}
          </div>

          <div className="flex items-center gap-4">
             {viewMode === 'artist' && (
                <button onClick={() => setShowAI(!showAI)} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-sm transition-all ${showAI ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`}>
                  <Sparkles size={16} /> 智能助理
                </button>
             )}
             {viewMode === 'artist' && (
                <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-800 transition-colors shadow-lg shadow-slate-200">
                  <Plus size={18} /> 新建排单
                </button>
             )}
          </div>
        </div>

        <div className="p-5 md:p-8 max-w-screen-2xl mx-auto">
          {/* AI Panel - Floating on PC if needed, but keeping inline for consistency */}
          {showAI && viewMode === 'artist' && (
            <div className="mb-8 bg-indigo-600 rounded-[2rem] p-6 text-white shadow-xl shadow-indigo-100 animate-fade-in relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
              <div className="relative z-10">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="font-black flex items-center gap-2"><Sparkles size={20} /> AI 创作分析</h3>
                  <button onClick={() => setShowAI(false)} className="bg-white/10 hover:bg-white/20 p-1.5 rounded-lg"><X size={18} /></button>
                </div>
                <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 min-h-[80px] mb-4 text-sm font-medium leading-relaxed">
                  {isAiLoading ? <div className="flex items-center gap-2"><div className="w-2 h-2 bg-white rounded-full animate-bounce"></div><div className="w-2 h-2 bg-white rounded-full animate-bounce delay-75"></div><span>思考中...</span></div> : aiResponse || "你好！我可以帮你分析工期、预估急单可行性或优化排期建议。"}
                </div>
                <div className="flex gap-2">
                  <input type="text" value={aiQuery} onChange={(e) => setAiQuery(e.target.value)} placeholder="我的排期下周还能接急单吗？" className="flex-1 bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm outline-none focus:bg-white/20 placeholder:text-white/50" onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()} />
                  <button onClick={handleAiAsk} className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-black text-sm hover:bg-indigo-50 active:scale-95 transition-all">发送</button>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'projects' && (
            <div className="space-y-6 animate-fade-in">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight">{viewMode === 'artist' ? '所有工单' : '我的约稿'}</h2>
                  <p className="text-slate-400 text-sm font-medium">共计 {displayedProjects.length} 个项目</p>
                </div>
                <div className="flex p-1 bg-slate-200/50 rounded-xl w-fit">
                  <button onClick={() => setProjectSubTab('active')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>进行中</button>
                  <button onClick={() => setProjectSubTab('completed')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>已完成</button>
                </div>
              </div>

              {displayedProjects.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                  <div className="bg-slate-50 p-6 rounded-full mb-4 text-slate-300"><ListTodo size={48} /></div>
                  <p className="text-slate-400 font-bold">暂无工单记录</p>
                  {viewMode === 'artist' && <button onClick={() => setShowAddModal(true)} className="mt-4 text-indigo-600 font-black hover:underline">点击创建第一个项目</button>}
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
                  {displayedProjects
                    .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                    .map(project => (
                      <ProjectCard 
                        key={project.id} 
                        project={project} 
                        onComplete={handleCompleteProject}
                        onDelete={handleDeleteProject}
                        onEdit={handleEditProject}
                        readOnly={viewMode === 'client'}
                      />
                    ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'schedule' && (
            <div className="animate-fade-in space-y-6">
               <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-100 border border-slate-100 overflow-hidden">
                  <ScheduleBoard 
                    bookings={bookings} 
                    projects={projects} 
                    achievements={achievements}
                    mode={viewMode} 
                    onUpdateBookings={setBookings} 
                    onUpdateAchievements={setAchievements}
                    currentClientId={viewMode === 'client' ? myClientId : undefined} 
                    currentClientName={viewMode === 'client' ? '我' : undefined} 
                  />
               </div>
            </div>
          )}

          {activeTab === 'planning' && viewMode === 'artist' && (
            <div className="animate-fade-in">
              <PTypePlanner onBack={() => setActiveTab('projects')} projects={projects} bookings={bookings} onUpdateBookings={setBookings} />
            </div>
          )}
        </div>
      </main>

      {/* Mobile Bottom Navigation (Only on small screens) */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-white border-t pb-[env(safe-area-inset-bottom)] z-40 shadow-lg flex justify-around items-center h-16">
        <button onClick={() => setActiveTab('projects')} className={`flex flex-col items-center gap-1 ${activeTab === 'projects' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <Layout size={20} /> <span className="text-[10px] font-bold">工单</span>
        </button>
        <button onClick={() => setActiveTab('schedule')} className={`flex flex-col items-center gap-1 ${activeTab === 'schedule' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <CalendarDays size={20} /> <span className="text-[10px] font-bold">排期</span>
        </button>
        {viewMode === 'artist' && (
          <button onClick={() => setActiveTab('planning')} className={`flex flex-col items-center gap-1 ${activeTab === 'planning' ? 'text-indigo-600' : 'text-slate-400'}`}>
            <BrainCircuit size={20} /> <span className="text-[10px] font-bold">规划</span>
          </button>
        )}
      </nav>

      {/* Modal - Centered for PC */}
      {showAddModal && viewMode === 'artist' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
          <div className="absolute inset-0" onClick={handleCloseModal}></div>
          <div className="relative bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl animate-slide-up p-8 md:p-10 overflow-y-auto max-h-[90vh] custom-scrollbar">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-slate-800">{editingProjectId ? '编辑排单项目' : '创建新排单'}</h3>
              <button onClick={handleCloseModal} className="text-slate-400 hover:text-slate-600 transition-colors"><X size={24}/></button>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">单主老板名称</label>
                  <input type="text" value={newProject.clientName} onChange={e => setNewProject({...newProject, clientName: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="例如：老板 A" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-1"><Coins size={12} className="text-amber-500" /> 报酬金额</label>
                  <div className="relative">
                    <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 font-bold">¥</span>
                    <input type="text" value={newProject.amount} onChange={e => setNewProject({...newProject, amount: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-10 pr-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="0.00" />
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-indigo-600 uppercase tracking-widest ml-1">单主专属 ID (必填，用于对方同步)</label>
                <div className="relative">
                  <UserCircle2 size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-indigo-400" />
                  <input type="text" value={newProject.targetClientId} onChange={e => setNewProject({...newProject, targetClientId: e.target.value})} className="w-full bg-indigo-50 border border-indigo-100 rounded-2xl pl-12 pr-5 py-4 text-sm font-bold text-indigo-900 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="CLI-xxxx" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                   <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">开始日期</label>
                   <input type="date" value={newProject.startDate} onChange={e => setNewProject({...newProject, startDate: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer" />
                </div>
                <div className="space-y-2">
                   <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">截稿日期</label>
                   <input type="date" value={newProject.deadline} onChange={e => setNewProject({...newProject, deadline: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer" />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">约稿需求 / 备注说明</label>
                <textarea 
                  rows={4}
                  value={newProject.description} 
                  onChange={e => setNewProject({...newProject, description: e.target.value})} 
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all resize-none" 
                  placeholder="详细记录约稿说明、构图要求、加急项等..."
                />
              </div>

              <div className="pt-4 flex gap-4">
                <button onClick={handleCloseModal} className="flex-1 py-4 border border-slate-200 text-slate-600 font-bold rounded-2xl hover:bg-slate-50 transition-all">取消</button>
                <button onClick={handleSaveProject} className="flex-[2] py-4 bg-slate-900 text-white font-bold rounded-2xl shadow-xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center justify-center gap-2">
                  <CheckCircle2 size={20} /> {editingProjectId ? '保存更改' : '确认创建任务'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export type ThemeType = 'modern' | 'pixel' | 'sketch';

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string;
  description: string;
  amount?: string;
  startDate: string;
  deadline: string;
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string;
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string;
  note?: string;
  actualHours?: string[];
}

export interface Achievement {
  id: string;
  text: string;
  date: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>;
  blockedDates: string[];
  createdAt: string;
  lastUpdated: string;
  completedDays: number[];
  dailySlots?: Record<number, string[]>;
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useEffect, useMemo } from 'react';
import { Project, BookingSlot, ViewMode, PlanningSession, Achievement, ThemeType } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { analyzeSchedule } from './services/geminiService';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Calendar,
  Paintbrush, 
  Sparkles, 
  X,
  Search,
  Copy,
  UserCircle2,
  LogOut,
  Fingerprint,
  Save,
  CheckCircle2,
  Clock,
  BrainCircuit,
  ListTodo,
  Lightbulb,
  MessageCircle,
  Coins,
  ChevronRight,
  History,
  Monitor,
  Palette
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [theme, setTheme] = useState<ThemeType>('modern');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);
  const [showAI, setShowAI] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>('');
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);
  const [achievements, setAchievements] = useState<Achievement[]>([]);

  // AI State
  const [aiQuery, setAiQuery] = useState('');
  const [aiResponse, setAiResponse] = useState('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', 
    description: '',
    amount: '',
    startDate: '',
    deadline: ''
  });

  // Initialization
  useEffect(() => {
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) {
      setConnectedArtistId(storedConnectedId);
    }

    const storedTheme = localStorage.getItem('artflow_theme') as ThemeType;
    if (storedTheme) setTheme(storedTheme);
  }, []);

  // Update root attribute when theme changes
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('artflow_theme', theme);
  }, [theme]);

  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      setAchievements([]);
      return;
    }
    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);
    const storedAchievements = localStorage.getItem(`artflow_data_${currentDataId}_achievements`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
    setAchievements(storedAchievements ? JSON.parse(storedAchievements) : []);
  }, [currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
    }
  }, [projects, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
    }
  }, [bookings, currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_achievements`, JSON.stringify(achievements));
    }
  }, [achievements, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;
    const targetProjects = localStorage.getItem(`artflow_data_${searchId}_projects`);
    if (targetProjects || searchId === myArtistId) {
      setConnectedArtistId(searchId);
      localStorage.setItem('artflow_connected_artist_id', searchId);
    } else {
      if(confirm(`未找到画手 ${searchId} 的本地记录。是否仍要连接？`)) {
         setConnectedArtistId(searchId);
         localStorage.setItem('artflow_connected_artist_id', searchId);
      }
    }
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;
    if (editingProjectId) {
      setProjects(projects.map(p => p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          amount: newProject.amount || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
      } : p));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || '无具体描述',
        amount: newProject.amount || '',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }
    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({ ...project });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', amount: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    if (viewMode === 'client') return;
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if (viewMode === 'client') return;
    if(confirm('确定要删除这个排单工单吗？相关规划数据也将一并清除。')) {
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));
    }
  };

  const handleAiAsk = async () => {
    if (!aiQuery.trim()) return;
    setIsAiLoading(true);
    setAiResponse('');
    const response = await analyzeSchedule(projects, bookings, aiQuery);
    setAiResponse(response);
    setIsAiLoading(false);
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制`);
  };

  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') handleDisconnect();
  };

  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen flex flex-col md:flex-row text-slate-800 transition-colors duration-500">

      {/* PC Side Navigation */}
      <aside className="hidden md:flex flex-col w-64 bg-white border-r border-slate-200 sticky top-0 h-screen z-40 transition-all">
        <div className="p-6 flex items-center gap-3">
          <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl shadow-lg shadow-indigo-100">
            <Paintbrush size={24} />
          </div>
          <h1 className="text-xl font-black tracking-tight">{theme === 'pixel' ? 'ART_FLOW' : 'ArtFlow'}</h1>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Layout size={20} /> 排单工单
          </button>
          <button onClick={() => setActiveTab('schedule')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <CalendarDays size={20} /> 排期日历
          </button>
          {viewMode === 'artist' && (
            <button onClick={() => setActiveTab('planning')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <BrainCircuit size={20} /> 辅助规划
            </button>
          )}
        </nav>

        {/* Theme Switcher in Sidebar */}
        <div className="px-6 py-4 border-t border-slate-100">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">主题选择 / Style</span>
          <div className="flex gap-2">
            <button 
              onClick={() => setTheme('modern')} 
              className={`flex-1 p-2 rounded-lg border-2 transition-all flex items-center justify-center ${theme === 'modern' ? 'border-indigo-600 bg-indigo-50 text-indigo-600' : 'border-slate-100 text-slate-400'}`}
              title="现代极简"
            >
              <Layout size={16} />
            </button>
            <button 
              onClick={() => setTheme('pixel')} 
              className={`flex-1 p-2 rounded-lg border-2 transition-all flex items-center justify-center ${theme === 'pixel' ? 'border-emerald-500 bg-emerald-900/10 text-emerald-500' : 'border-slate-100 text-slate-400'}`}
              title="复古像素"
            >
              <Monitor size={16} />
            </button>
            <button 
              onClick={() => setTheme('sketch')} 
              className={`flex-1 p-2 rounded-lg border-2 transition-all flex items-center justify-center ${theme === 'sketch' ? 'border-amber-600 bg-amber-50 text-amber-600' : 'border-slate-100 text-slate-400'}`}
              title="柔和手账"
            >
              <Palette size={16} />
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-100">
          <div className="bg-slate-50 rounded-2xl p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-black text-slate-400 uppercase">当前角色</span>
              <button onClick={toggleViewMode} className="text-[10px] font-black text-indigo-600 hover:underline">切换</button>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-indigo-100 flex items-center justify-center text-indigo-600">
                {viewMode === 'artist' ? <Paintbrush size={16} /> : <UserCircle2 size={16} />}
              </div>
              <div>
                <p className="text-xs font-bold">{viewMode === 'artist' ? '画手' : '单主'}</p>
                <p className="text-[10px] text-slate-400 font-mono truncate max-w-[120px]">{viewMode === 'artist' ? myArtistId : (connectedArtistId || '未连接')}</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Top Header */}
      <header className="md:hidden sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 shadow-sm flex justify-between items-center transition-all">
        <div className="flex items-center gap-2">
          <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-1.5 rounded-lg">
            <Paintbrush size={16} />
          </div>
          <h1 className="text-base font-bold text-slate-800">ArtFlow</h1>
        </div>
        <div className="flex items-center gap-2">
           <button onClick={() => setTheme(theme === 'modern' ? 'pixel' : theme === 'pixel' ? 'sketch' : 'modern')} className="p-2 bg-slate-100 rounded-full text-slate-600">
              <Palette size={16} />
           </button>
           <button onClick={toggleViewMode} className="text-xs font-black bg-slate-900 text-white px-3 py-1.5 rounded-full">
            {viewMode === 'artist' ? '画手' : '单主'}
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 min-h-screen overflow-x-hidden">
        {/* PC Top Dashboard Bar */}
        <div className="hidden md:flex items-center justify-between px-8 py-4 bg-white border-b border-slate-100 sticky top-0 z-30 transition-all">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2 bg-slate-50 border border-slate-100 rounded-full px-4 py-1.5 transition-all">
               <span className="text-[10px] font-bold text-slate-400 uppercase">My ID:</span>
               <span className="text-xs font-bold font-mono">{viewMode === 'artist' ? myArtistId : myClientId}</span>
               <button onClick={() => copyText(viewMode === 'artist' ? myArtistId : myClientId, 'ID')} className="text-slate-400 hover:text-indigo-600 ml-1"><Copy size={12}/></button>
            </div>
            {viewMode === 'client' && !connectedArtistId && (
              <div className="flex items-center gap-2">
                <input type="text" value={searchId} onChange={(e) => setSearchId(e.target.value)} placeholder="输入画手 ID" className="bg-slate-50 border border-slate-100 rounded-full px-4 py-1.5 text-xs outline-none focus:ring-1 focus:ring-indigo-500 w-48" />
                <button onClick={handleSearchArtist} className="bg-indigo-600 text-white px-4 py-1.5 rounded-full text-xs font-bold hover:bg-indigo-700">连接</button>
              </div>
            )}
            {connectedArtistId && (
              <div className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-indigo-50 px-4 py-1.5 rounded-full border border-indigo-100 transition-all">
                <span>已连接: {connectedArtistId}</span>
                <button onClick={handleDisconnect} className="hover:text-rose-600"><X size={14}/></button>
              </div>
            )}
          </div>

          <div className="flex items-center gap-4">
             {viewMode === 'artist' && (
                <button onClick={() => setShowAI(!showAI)} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-sm transition-all ${showAI ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}`}>
                  <Sparkles size={16} /> 智能助理
                </button>
             )}
             {viewMode === 'artist' && (
                <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-2 rounded-xl text-sm font-bold flex items-center gap-2 hover:bg-slate-800 transition-colors shadow-lg shadow-slate-200">
                  <Plus size={18} /> 新建排单
                </button>
             )}
          </div>
        </div>

        <div className="p-5 md:p-8 max-w-screen-2xl mx-auto">
          {/* AI Panel */}
          {showAI && viewMode === 'artist' && (
            <div className="mb-8 bg-indigo-600 rounded-[2rem] p-6 text-white shadow-xl shadow-indigo-100 animate-fade-in relative overflow-hidden transition-all">
              <div className="absolute top-0 right-0 w-64 h-64 bg-white/10 rounded-full -mr-32 -mt-32 blur-3xl"></div>
              <div className="relative z-10">
                <div className="flex justify-between items-center mb-4">
                  <h3 className="font-black flex items-center gap-2"><Sparkles size={20} /> AI 创作分析</h3>
                  <button onClick={() => setShowAI(false)} className="bg-white/10 hover:bg-white/20 p-1.5 rounded-lg"><X size={18} /></button>
                </div>
                <div className="bg-white/10 backdrop-blur-md rounded-2xl p-4 min-h-[80px] mb-4 text-sm font-medium leading-relaxed">
                  {isAiLoading ? <div className="flex items-center gap-2"><div className="w-2 h-2 bg-white rounded-full animate-bounce"></div><div className="w-2 h-2 bg-white rounded-full animate-bounce delay-75"></div><span>思考中...</span></div> : aiResponse || "你好！我可以帮你分析工期、预估急单可行性或优化排期建议。"}
                </div>
                <div className="flex gap-2">
                  <input type="text" value={aiQuery} onChange={(e) => setAiQuery(e.target.value)} placeholder="我的排期下周还能接急单吗？" className="flex-1 bg-white/10 border border-white/20 rounded-xl px-4 py-3 text-sm outline-none focus:bg-white/20 placeholder:text-white/50" onKeyDown={(e) => e.key === 'Enter' && handleAiAsk()} />
                  <button onClick={handleAiAsk} className="bg-white text-indigo-600 px-6 py-3 rounded-xl font-black text-sm hover:bg-indigo-50 active:scale-95 transition-all">发送</button>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'projects' && (
            <div className="space-y-6 animate-fade-in">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                  <h2 className="text-2xl font-black text-slate-800 tracking-tight transition-all">{viewMode === 'artist' ? '所有工单' : '我的约稿'}</h2>
                  <p className="text-slate-400 text-sm font-medium">共计 {displayedProjects.length} 个项目</p>
                </div>
                <div className="flex p-1 bg-slate-200/50 rounded-xl w-fit transition-all">
                  <button onClick={() => setProjectSubTab('active')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>进行中</button>
                  <button onClick={() => setProjectSubTab('completed')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>已完成</button>
                </div>
              </div>

              {displayedProjects.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[2.5rem] border border-dashed border-slate-200 transition-all">
                  <div className="bg-slate-50 p-6 rounded-full mb-4 text-slate-300"><ListTodo size={48} /></div>
                  <p className="text-slate-400 font-bold">暂无工单记录</p>
                  {viewMode === 'artist' && <button onClick={() => setShowAddModal(true)} className="mt-4 text-indigo-600 font-black hover:underline">点击创建第一个项目</button>}
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6 transition-all">
                  {displayedProjects
                    .sort((a, b) => new Date(a.deadline).getTime() - new Date(b.deadline).getTime())
                    .map(project => (
                      <ProjectCard 
                        key={project.id} 
                        project={project} 
                        onComplete={handleCompleteProject}
                        onDelete={handleDeleteProject}
                        onEdit={handleEditProject}
                        readOnly={viewMode === 'client'}
                      />
                    ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'schedule' && (
            <div className="animate-fade-in space-y-6">
               <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-100 border border-slate-100 overflow-hidden transition-all">
                  <ScheduleBoard 
                    bookings={bookings} 
                    projects={projects} 
                    achievements={achievements}
                    mode={viewMode} 
                    onUpdateBookings={setBookings} 
                    onUpdateAchievements={setAchievements}
                    currentClientId={viewMode === 'client' ? myClientId : undefined} 
                    currentClientName={viewMode === 'client' ? '我' : undefined} 
                  />
               </div>
            </div>
          )}

          {activeTab === 'planning' && viewMode === 'artist' && (
            <div className="animate-fade-in">
              <PTypePlanner onBack={() => setActiveTab('projects')} projects={projects} bookings={bookings} onUpdateBookings={setBookings} />
            </div>
          )}
        </div>
      </main>

      {/* Mobile Bottom Navigation */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-white border-t pb-[env(safe-area-inset-bottom)] z-40 shadow-lg flex justify-around items-center h-16 transition-all">
        <button onClick={() => setActiveTab('projects')} className={`flex flex-col items-center gap-1 ${activeTab === 'projects' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <Layout size={20} /> <span className="text-[10px] font-bold">工单</span>
        </button>
        <button onClick={() => setActiveTab('schedule')} className={`flex flex-col items-center gap-1 ${activeTab === 'schedule' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <CalendarDays size={20} /> <span className="text-[10px] font-bold">排期</span>
        </button>
        {viewMode === 'artist' && (
          <button onClick={() => setActiveTab('planning')} className={`flex flex-col items-center gap-1 ${activeTab === 'planning' ? 'text-indigo-600' : 'text-slate-400'}`}>
            <BrainCircuit size={20} /> <span className="text-[10px] font-bold">规划</span>
          </button>
        )}
      </nav>

      {/* Modal */}
      {showAddModal && viewMode === 'artist' && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
          <div className="absolute inset-0" onClick={handleCloseModal}></div>
          <div className="relative bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl animate-slide-up p-8 md:p-10 overflow-y-auto max-h-[90vh] custom-scrollbar transition-all">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-slate-800 transition-all">{editingProjectId ? '编辑排单项目' : '创建新排单'}</h3>
              <button onClick={handleCloseModal} className="text-slate-400 hover:text-slate-600 transition-colors"><X size={24}/></button>
            </div>

            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">单主老板名称</label>
                  <input type="text" value={newProject.clientName} onChange={e => setNewProject({...newProject, clientName: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="例如：老板 A" />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-1"><Coins size={12} className="text-amber-500" /> 报酬金额</label>
                  <div className="relative">
                    <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 font-bold">¥</span>
                    <input type="text" value={newProject.amount} onChange={e => setNewProject({...newProject, amount: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-10 pr-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="0.00" />
                  </div>
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-indigo-600 uppercase tracking-widest ml-1">单主专属 ID (必填，用于对方同步)</label>
                <div className="relative">
                  <UserCircle2 size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-indigo-400" />
                  <input type="text" value={newProject.targetClientId} onChange={e => setNewProject({...newProject, targetClientId: e.target.value})} className="w-full bg-indigo-50 border border-indigo-100 rounded-2xl pl-12 pr-5 py-4 text-sm font-bold text-indigo-900 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="CLI-xxxx" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                   <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">开始日期</label>
                   <input type="date" value={newProject.startDate} onChange={e => setNewProject({...newProject, startDate: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer" />
                </div>
                <div className="space-y-2">
                   <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">截稿日期</label>
                   <input type="date" value={newProject.deadline} onChange={e => setNewProject({...newProject, deadline: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer" />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">约稿需求 / 备注说明</label>
                <textarea 
                  rows={4}
                  value={newProject.description} 
                  onChange={e => setNewProject({...newProject, description: e.target.value})} 
                  className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all resize-none" 
                  placeholder="详细记录约稿说明、构图要求、加急项等..."
                />
              </div>

              <div className="pt-4 flex gap-4">
                <button onClick={handleCloseModal} className="flex-1 py-4 border border-slate-200 text-slate-600 font-bold rounded-2xl hover:bg-slate-50 transition-all">取消</button>
                <button onClick={handleSaveProject} className="flex-[2] py-4 bg-slate-900 text-white font-bold rounded-2xl shadow-xl shadow-slate-200 hover:bg-slate-800 active:scale-95 transition-all flex items-center justify-center gap-2">
                  <CheckCircle2 size={20} /> {editingProjectId ? '保存更改' : '确认创建任务'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export type ThemeType = 'modern' | 'pixel' | 'sketch';

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string;
  description: string;
  amount?: string;
  startDate: string;
  deadline: string;
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string;
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string;
  note?: string;
  actualHours?: string[];
}

export interface Achievement {
  id: string;
  text: string;
  date: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>;
  blockedDates: string[];
  createdAt: string;
  lastUpdated: string;
  completedDays: number[];
  dailySlots?: Record<number, string[]>;
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode, Achievement, ThemeType } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  X,
  Copy,
  UserCircle2,
  CheckCircle2,
  BrainCircuit,
  ListTodo,
  Coins,
  Palette,
  Monitor
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');
  const [theme, setTheme] = useState<ThemeType>('modern');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>('');
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);
  const [achievements, setAchievements] = useState<Achievement[]>([]);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', 
    description: '',
    amount: '',
    startDate: '',
    deadline: ''
  });

  // Initialization
  useEffect(() => {
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) setConnectedArtistId(storedConnectedId);

    const storedTheme = localStorage.getItem('artflow_theme') as ThemeType;
    if (storedTheme) setTheme(storedTheme);
  }, []);

  // Sync theme with HTML attribute
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('artflow_theme', theme);
  }, [theme]);

  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      setAchievements([]);
      return;
    }
    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);
    const storedAchievements = localStorage.getItem(`artflow_data_${currentDataId}_achievements`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
    setAchievements(storedAchievements ? JSON.parse(storedAchievements) : []);
  }, [currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
      localStorage.setItem(`artflow_data_${currentDataId}_achievements`, JSON.stringify(achievements));
    }
  }, [projects, bookings, achievements, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;
    setConnectedArtistId(searchId);
    localStorage.setItem('artflow_connected_artist_id', searchId);
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;
    if (editingProjectId) {
      setProjects(projects.map(p => p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          amount: newProject.amount || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
      } : p));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || '无具体描述',
        amount: newProject.amount || '',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }
    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({ ...project });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', amount: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if(confirm('确定要删除这个项目吗？')) {
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));
    }
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制`);
  };

  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') handleDisconnect();
  };

  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen flex flex-col md:flex-row transition-all duration-500">

      {/* PC Side Navigation */}
      <aside className="hidden md:flex flex-col w-64 bg-white border-r border-slate-200 sticky top-0 h-screen z-40 transition-colors">
        <div className="p-6 flex items-center gap-3">
          <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl">
            <Paintbrush size={24} />
          </div>
          <h1 className="text-xl font-black tracking-tight">{theme === 'pixel' ? 'ART_FLOW' : 'ArtFlow'}</h1>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Layout size={20} /> 排单工单
          </button>
          <button onClick={() => setActiveTab('schedule')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <CalendarDays size={20} /> 排期日历
          </button>
          {viewMode === 'artist' && (
            <button onClick={() => setActiveTab('planning')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <BrainCircuit size={20} /> 辅助规划
            </button>
          )}
        </nav>

        {/* Theme Picker */}
        <div className="px-6 py-4 border-t border-slate-100">
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">主题选择 / Styles</span>
          <div className="flex gap-2">
            <button onClick={() => setTheme('modern')} title="现代极简" className={`flex-1 p-2 rounded-lg border-2 transition-all ${theme === 'modern' ? 'border-indigo-600 bg-indigo-50 text-indigo-600' : 'border-slate-100 text-slate-400'}`}>
              <Layout size={16} className="mx-auto" />
            </button>
            <button onClick={() => setTheme('pixel')} title="复古像素" className={`flex-1 p-2 rounded-lg border-2 transition-all ${theme === 'pixel' ? 'border-emerald-500 bg-emerald-900/10 text-emerald-500' : 'border-slate-100 text-slate-400'}`}>
              <Monitor size={16} className="mx-auto" />
            </button>
            <button onClick={() => setTheme('sketch')} title="手账风格" className={`flex-1 p-2 rounded-lg border-2 transition-all ${theme === 'sketch' ? 'border-amber-600 bg-amber-50 text-amber-600' : 'border-slate-100 text-slate-400'}`}>
              <Palette size={16} className="mx-auto" />
            </button>
          </div>
        </div>

        <div className="p-4 border-t border-slate-100">
          <div className="bg-slate-50 rounded-2xl p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-black text-slate-400 uppercase">当前角色</span>
              <button onClick={toggleViewMode} className="text-[10px] font-black text-indigo-600 hover:underline">切换</button>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-indigo-100 flex items-center justify-center text-indigo-600">
                {viewMode === 'artist' ? <Paintbrush size={16} /> : <UserCircle2 size={16} />}
              </div>
              <div>
                <p className="text-xs font-bold">{viewMode === 'artist' ? '画手' : '单主'}</p>
                <p className="text-[10px] text-slate-400 font-mono truncate max-w-[120px]">{viewMode === 'artist' ? myArtistId : (connectedArtistId || '未连接')}</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Top Header */}
      <header className="md:hidden sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 flex justify-between items-center transition-colors">
        <div className="flex items-center gap-2">
          <Paintbrush size={20} className="text-indigo-600" />
          <h1 className="text-base font-bold">ArtFlow</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setTheme(theme === 'modern' ? 'pixel' : theme === 'pixel' ? 'sketch' : 'modern')} className="p-2 bg-slate-100 rounded-full text-slate-600">
            <Palette size={16} />
          </button>
          <button onClick={toggleViewMode} className="text-xs font-black bg-slate-900 text-white px-3 py-1.5 rounded-full">
            {viewMode === 'artist' ? '画手' : '单主'}
          </button>
        </div>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 min-h-screen overflow-x-hidden p-5 md:p-8">
        {activeTab === 'projects' && (
          <div className="space-y-6 animate-fade-in max-w-screen-2xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-black tracking-tight">{viewMode === 'artist' ? '所有工单' : '我的约稿'}</h2>
                <p className="text-slate-400 text-sm font-medium">共计 {displayedProjects.length} 个项目</p>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex p-1 bg-slate-200/50 rounded-xl w-fit">
                  <button onClick={() => setProjectSubTab('active')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600' : 'text-slate-400'}`}>进行中</button>
                  <button onClick={() => setProjectSubTab('completed')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600' : 'text-slate-400'}`}>已完成</button>
                </div>
                {viewMode === 'artist' && (
                  <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl text-sm font-bold flex items-center gap-2 hover:opacity-90">
                    <Plus size={18} /> 新建排单
                  </button>
                )}
              </div>
            </div>

            {displayedProjects.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                <ListTodo size={48} className="text-slate-200 mb-4" />
                <p className="text-slate-400 font-bold">暂无工单记录</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {displayedProjects.map(project => (
                  <ProjectCard key={project.id} project={project} onComplete={handleCompleteProject} onDelete={handleDeleteProject} onEdit={handleEditProject} readOnly={viewMode === 'client'} />
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'schedule' && (
          <div className="animate-fade-in max-w-screen-2xl mx-auto">
            <div className="bg-white rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden transition-all">
              <ScheduleBoard bookings={bookings} projects={projects} achievements={achievements} mode={viewMode} onUpdateBookings={setBookings} onUpdateAchievements={setAchievements} currentClientId={viewMode === 'client' ? myClientId : undefined} />
            </div>
          </div>
        )}

        {activeTab === 'planning' && viewMode === 'artist' && (
          <div className="animate-fade-in max-w-4xl mx-auto">
            <PTypePlanner onBack={() => setActiveTab('projects')} projects={projects} bookings={bookings} />
          </div>
        )}
      </main>

      {/* Mobile Bottom Navigation */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-white border-t pb-[env(safe-area-inset-bottom)] z-40 flex justify-around items-center h-16">
        <button onClick={() => setActiveTab('projects')} className={`flex flex-col items-center gap-1 ${activeTab === 'projects' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <Layout size={20} /> <span className="text-[10px] font-bold">工单</span>
        </button>
        <button onClick={() => setActiveTab('schedule')} className={`flex flex-col items-center gap-1 ${activeTab === 'schedule' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <CalendarDays size={20} /> <span className="text-[10px] font-bold">排期</span>
        </button>
        {viewMode === 'artist' && (
          <button onClick={() => setActiveTab('planning')} className={`flex flex-col items-center gap-1 ${activeTab === 'planning' ? 'text-indigo-600' : 'text-slate-400'}`}>
            <BrainCircuit size={20} /> <span className="text-[10px] font-bold">规划</span>
          </button>
        )}
      </nav>

      {/* New Project Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
          <div className="absolute inset-0" onClick={handleCloseModal}></div>
          <div className="relative bg-white w-full max-w-xl rounded-[2.5rem] p-8 md:p-10 shadow-2xl transition-all">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black">{editingProjectId ? '编辑项目' : '创建新项目'}</h3>
              <button onClick={handleCloseModal} className="text-slate-400"><X size={24}/></button>
            </div>
            <div className="space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <input type="text" value={newProject.clientName} onChange={e => setNewProject({...newProject, clientName: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none" placeholder="单主名称" />
                <input type="text" value={newProject.amount} onChange={e => setNewProject({...newProject, amount: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none" placeholder="金额 (可选)" />
              </div>
              <input type="text" value={newProject.targetClientId} onChange={e => setNewProject({...newProject, targetClientId: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none font-mono" placeholder="单主 ID (CLI-xxxx)" />
              <div className="grid grid-cols-2 gap-4">
                <input type="date" value={newProject.startDate} onChange={e => setNewProject({...newProject, startDate: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none" />
                <input type="date" value={newProject.deadline} onChange={e => setNewProject({...newProject, deadline: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none" />
              </div>
              <textarea rows={3} value={newProject.description} onChange={e => setNewProject({...newProject, description: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-sm outline-none resize-none" placeholder="需求备注..." />
              <button onClick={handleSaveProject} className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl hover:opacity-90 transition-all">确认保存</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export interface Project {
  id: string;
  clientName: string;
  targetClientId?: string;
  description: string;
  amount?: string;
  startDate: string;
  deadline: string;
  status: 'pending' | 'in_progress' | 'completed';
}

export interface BookingSlot {
  date: string;
  status: 'available' | 'booked' | 'blocked';
  bookedBy?: string;
  clientId?: string;
  note?: string;
  actualHours?: string[];
}

export interface Achievement {
  id: string;
  text: string;
  date: string;
}

export interface PlannerStage {
  id: string;
  title: string;
  isDeletable?: boolean;
}

export interface PlanningSession {
  id: string;
  projectId?: string;
  clientName: string;
  stages: PlannerStage[];
  estimates: Record<string, string>;
  blockedDates: string[];
  createdAt: string;
  lastUpdated: string;
  completedDays: number[];
  dailySlots?: Record<number, string[]>;
}

export type ViewMode = 'artist' | 'client';

import React, { useState, useEffect } from 'react';
import { Project, BookingSlot, ViewMode, Achievement } from './types';
import ProjectCard from './components/ProjectCard';
import ScheduleBoard from './components/ScheduleBoard';
import PTypePlanner from './components/PTypePlanner';
import { generateArtistId, generateClientId } from './utils';
import { 
  Layout, 
  Plus, 
  CalendarDays, 
  Paintbrush, 
  X,
  Copy,
  UserCircle2,
  CheckCircle2,
  BrainCircuit,
  ListTodo,
  Coins
} from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'projects' | 'schedule' | 'planning'>('projects');
  const [projectSubTab, setProjectSubTab] = useState<'active' | 'completed'>('active');

  const [viewMode, setViewMode] = useState<ViewMode>('artist');
  const [showAddModal, setShowAddModal] = useState(false);

  // Identity State
  const [myArtistId, setMyArtistId] = useState<string>('');
  const [myClientId, setMyClientId] = useState<string>('');
  const [searchId, setSearchId] = useState('');
  const [connectedArtistId, setConnectedArtistId] = useState<string | null>(null);

  // Data State
  const [projects, setProjects] = useState<Project[]>([]);
  const [bookings, setBookings] = useState<BookingSlot[]>([]);
  const [achievements, setAchievements] = useState<Achievement[]>([]);

  // New/Edit Project Form State
  const [editingProjectId, setEditingProjectId] = useState<string | null>(null);
  const [newProject, setNewProject] = useState<Partial<Project>>({
    clientName: '',
    targetClientId: '', 
    description: '',
    amount: '',
    startDate: '',
    deadline: ''
  });

  // Initialization
  useEffect(() => {
    const storedArtistId = localStorage.getItem('artflow_artist_id');
    if (storedArtistId) {
      setMyArtistId(storedArtistId);
    } else {
      const newId = generateArtistId();
      localStorage.setItem('artflow_artist_id', newId);
      setMyArtistId(newId);
    }

    const storedClientId = localStorage.getItem('artflow_client_id');
    if (storedClientId) {
      setMyClientId(storedClientId);
    } else {
      const newId = generateClientId();
      localStorage.setItem('artflow_client_id', newId);
      setMyClientId(newId);
    }

    const storedConnectedId = localStorage.getItem('artflow_connected_artist_id');
    if (storedConnectedId) setConnectedArtistId(storedConnectedId);
  }, []);

  const currentDataId = viewMode === 'artist' ? myArtistId : connectedArtistId;

  useEffect(() => {
    if (!currentDataId) {
      setProjects([]);
      setBookings([]);
      setAchievements([]);
      return;
    }
    const storedProjects = localStorage.getItem(`artflow_data_${currentDataId}_projects`);
    const storedBookings = localStorage.getItem(`artflow_data_${currentDataId}_bookings`);
    const storedAchievements = localStorage.getItem(`artflow_data_${currentDataId}_achievements`);

    setProjects(storedProjects ? JSON.parse(storedProjects) : []);
    setBookings(storedBookings ? JSON.parse(storedBookings) : []);
    setAchievements(storedAchievements ? JSON.parse(storedAchievements) : []);
  }, [currentDataId, viewMode]);

  useEffect(() => {
    if (currentDataId && viewMode === 'artist') {
      localStorage.setItem(`artflow_data_${currentDataId}_projects`, JSON.stringify(projects));
      localStorage.setItem(`artflow_data_${currentDataId}_bookings`, JSON.stringify(bookings));
      localStorage.setItem(`artflow_data_${currentDataId}_achievements`, JSON.stringify(achievements));
    }
  }, [projects, bookings, achievements, currentDataId, viewMode]);

  const handleSearchArtist = () => {
    if (!searchId.trim()) return;
    setConnectedArtistId(searchId);
    localStorage.setItem('artflow_connected_artist_id', searchId);
  };

  const handleDisconnect = () => {
    setConnectedArtistId(null);
    setSearchId('');
    localStorage.removeItem('artflow_connected_artist_id');
  };

  const handleSaveProject = () => {
    if (!newProject.clientName || !newProject.startDate || !newProject.deadline) return;
    if (editingProjectId) {
      setProjects(projects.map(p => p.id === editingProjectId ? {
          ...p,
          clientName: newProject.clientName!,
          targetClientId: newProject.targetClientId || '',
          description: newProject.description || '',
          amount: newProject.amount || '',
          startDate: newProject.startDate!,
          deadline: newProject.deadline!
      } : p));
    } else {
      const project: Project = {
        id: Date.now().toString(),
        clientName: newProject.clientName!,
        targetClientId: newProject.targetClientId || '', 
        description: newProject.description || '无具体描述',
        amount: newProject.amount || '',
        startDate: newProject.startDate!,
        deadline: newProject.deadline!,
        status: 'pending'
      };
      setProjects([...projects, project]);
    }
    handleCloseModal();
  };

  const handleEditProject = (project: Project) => {
    setNewProject({ ...project });
    setEditingProjectId(project.id);
    setShowAddModal(true);
  };

  const handleCloseModal = () => {
    setShowAddModal(false);
    setEditingProjectId(null);
    setNewProject({ clientName: '', targetClientId: '', description: '', amount: '', startDate: '', deadline: '' });
  };

  const handleCompleteProject = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, status: 'completed' } : p));
  };

  const handleDeleteProject = (id: string) => {
    if(confirm('确定要删除这个项目吗？')) {
        setProjects(prevProjects => prevProjects.filter(p => p.id !== id));
    }
  };

  const copyText = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    alert(`${label} 已复制`);
  };

  const toggleViewMode = () => {
    const newMode = viewMode === 'artist' ? 'client' : 'artist';
    setViewMode(newMode);
    if (newMode === 'artist') handleDisconnect();
  };

  const allVisibleProjects = viewMode === 'artist' 
    ? projects 
    : projects.filter(p => p.targetClientId === myClientId);

  const displayedProjects = allVisibleProjects.filter(p => {
    if (projectSubTab === 'active') return p.status !== 'completed';
    if (projectSubTab === 'completed') return p.status === 'completed';
    return true;
  });

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f8fafc] text-slate-800">

      {/* PC Side Navigation */}
      <aside className="hidden md:flex flex-col w-64 bg-white border-r border-slate-200 sticky top-0 h-screen z-40">
        <div className="p-6 flex items-center gap-3">
          <div className="bg-gradient-to-tr from-indigo-600 to-violet-600 text-white p-2 rounded-xl">
            <Paintbrush size={24} />
          </div>
          <h1 className="text-xl font-black tracking-tight text-slate-900">ArtFlow</h1>
        </div>

        <nav className="flex-1 px-4 space-y-1">
          <button onClick={() => setActiveTab('projects')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'projects' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Layout size={20} /> 排单工单
          </button>
          <button onClick={() => setActiveTab('schedule')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'schedule' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
            <CalendarDays size={20} /> 排期日历
          </button>
          {viewMode === 'artist' && (
            <button onClick={() => setActiveTab('planning')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${activeTab === 'planning' ? 'bg-indigo-50 text-indigo-600' : 'text-slate-500 hover:bg-slate-50'}`}>
              <BrainCircuit size={20} /> 辅助规划
            </button>
          )}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className="bg-slate-50 rounded-2xl p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-black text-slate-400 uppercase">当前角色</span>
              <button onClick={toggleViewMode} className="text-[10px] font-black text-indigo-600 hover:underline">切换</button>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-lg bg-indigo-100 flex items-center justify-center text-indigo-600">
                {viewMode === 'artist' ? <Paintbrush size={16} /> : <UserCircle2 size={16} />}
              </div>
              <div>
                <p className="text-xs font-bold">{viewMode === 'artist' ? '画手' : '单主'}</p>
                <p className="text-[10px] text-slate-400 font-mono truncate max-w-[120px]">{viewMode === 'artist' ? myArtistId : (connectedArtistId || '未连接')}</p>
              </div>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile Top Header */}
      <header className="md:hidden sticky top-0 z-30 bg-white/90 backdrop-blur-md border-b border-slate-100 px-5 py-3 flex justify-between items-center">
        <div className="flex items-center gap-2">
          <Paintbrush size={20} className="text-indigo-600" />
          <h1 className="text-base font-bold text-slate-900">ArtFlow</h1>
        </div>
        <button onClick={toggleViewMode} className="text-xs font-black bg-slate-900 text-white px-3 py-1.5 rounded-full">
          {viewMode === 'artist' ? '画手' : '单主'}
        </button>
      </header>

      {/* Main Content Area */}
      <main className="flex-1 min-h-screen overflow-x-hidden p-5 md:p-8">
        {activeTab === 'projects' && (
          <div className="space-y-6 animate-fade-in max-w-screen-2xl mx-auto">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h2 className="text-2xl font-black tracking-tight text-slate-800">{viewMode === 'artist' ? '所有工单' : '我的约稿'}</h2>
                <p className="text-slate-400 text-sm font-medium">共计 {displayedProjects.length} 个项目</p>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex p-1 bg-slate-200/50 rounded-xl w-fit">
                  <button onClick={() => setProjectSubTab('active')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'active' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>进行中</button>
                  <button onClick={() => setProjectSubTab('completed')} className={`px-6 py-2 rounded-lg text-sm font-bold transition-all ${projectSubTab === 'completed' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>已完成</button>
                </div>
                {viewMode === 'artist' && (
                  <button onClick={() => setShowAddModal(true)} className="bg-slate-900 text-white px-6 py-3 rounded-xl text-sm font-bold flex items-center gap-2 hover:opacity-90 shadow-lg">
                    <Plus size={18} /> 新建排单
                  </button>
                )}
              </div>
            </div>

            {displayedProjects.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-32 bg-white rounded-[2.5rem] border border-dashed border-slate-200">
                <ListTodo size={48} className="text-slate-200 mb-4" />
                <p className="text-slate-400 font-bold">暂无工单记录</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                {displayedProjects.map(project => (
                  <ProjectCard key={project.id} project={project} onComplete={handleCompleteProject} onDelete={handleDeleteProject} onEdit={handleEditProject} readOnly={viewMode === 'client'} />
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'schedule' && (
          <div className="animate-fade-in max-w-screen-2xl mx-auto">
            <div className="bg-white rounded-[2.5rem] shadow-xl border border-slate-100 overflow-hidden">
              <ScheduleBoard bookings={bookings} projects={projects} achievements={achievements} mode={viewMode} onUpdateBookings={setBookings} onUpdateAchievements={setAchievements} currentClientId={viewMode === 'client' ? myClientId : undefined} />
            </div>
          </div>
        )}

        {activeTab === 'planning' && viewMode === 'artist' && (
          <div className="animate-fade-in max-w-4xl mx-auto">
            <PTypePlanner onBack={() => setActiveTab('projects')} projects={projects} bookings={bookings} />
          </div>
        )}
      </main>

      {/* Mobile Bottom Navigation */}
      <nav className="md:hidden fixed bottom-0 left-0 w-full bg-white border-t pb-[env(safe-area-inset-bottom)] z-40 flex justify-around items-center h-16 shadow-lg">
        <button onClick={() => setActiveTab('projects')} className={`flex flex-col items-center gap-1 ${activeTab === 'projects' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <Layout size={20} /> <span className="text-[10px] font-bold">工单</span>
        </button>
        <button onClick={() => setActiveTab('schedule')} className={`flex flex-col items-center gap-1 ${activeTab === 'schedule' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <CalendarDays size={20} /> <span className="text-[10px] font-bold">排期</span>
        </button>
        {viewMode === 'artist' && (
          <button onClick={() => setActiveTab('planning')} className={`flex flex-col items-center gap-1 ${activeTab === 'planning' ? 'text-indigo-600' : 'text-slate-400'}`}>
            <BrainCircuit size={20} /> <span className="text-[10px] font-bold">规划</span>
          </button>
        )}
      </nav>

      {/* New Project Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fade-in">
          <div className="absolute inset-0" onClick={handleCloseModal}></div>
          <div className="relative bg-white w-full max-w-xl rounded-[2.5rem] p-8 md:p-10 shadow-2xl transition-all">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-black text-slate-800">{editingProjectId ? '编辑项目' : '创建新项目'}</h3>
              <button onClick={handleCloseModal} className="text-slate-400 hover:text-slate-600"><X size={24}/></button>
            </div>
            <div className="space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <input type="text" value={newProject.clientName} onChange={e => setNewProject({...newProject, clientName: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="单主名称" />
                <div className="relative">
                   <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm">¥</span>
                   <input type="text" value={newProject.amount} onChange={e => setNewProject({...newProject, amount: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl pl-8 pr-5 py-3.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="金额" />
                </div>
              </div>
              <input type="text" value={newProject.targetClientId} onChange={e => setNewProject({...newProject, targetClientId: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none font-mono focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="单主 ID (CLI-xxxx)" />
              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-bold text-slate-400 ml-2 uppercase">开始日期</label>
                  <input type="date" value={newProject.startDate} onChange={e => setNewProject({...newProject, startDate: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none" />
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-bold text-slate-400 ml-2 uppercase">截稿日期</label>
                  <input type="date" value={newProject.deadline} onChange={e => setNewProject({...newProject, deadline: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 text-sm outline-none" />
                </div>
              </div>
              <textarea rows={3} value={newProject.description} onChange={e => setNewProject({...newProject, description: e.target.value})} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-5 py-4 text-sm outline-none resize-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="需求备注..." />
              <button onClick={handleSaveProject} className="w-full py-4 bg-slate-900 text-white font-bold rounded-2xl hover:bg-slate-800 transition-all shadow-xl shadow-slate-200">确认保存</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
